async def _fetch_recent_actions(user_id: int, limit: int = 15) -> list:
    loss_patterns = ["- " + c for c in LOSS_CAUSES]
    win_patterns = ["+ " + c for c in WIN_CAUSES]
    all_patterns = loss_patterns + win_patterns
    query = """
        SELECT cause, "-" AS bet_amount, "+" AS win_amount, data
        FROM cutehistory 
        WHERE user_id = $1 AND cause = ANY($2::text[])
        ORDER BY data DESC
        LIMIT $3
    """
    try:
        async with db.pool.acquire() as conn:
            rows = await conn.fetch(query, user_id, all_patterns, limit)
            actions = []
            for row in rows:
                actions.append({
                    "cause": row["cause"],
                    "bet_amount": row["bet_amount"],
                    "win_amount": row["win_amount"],
                    "data": row["data"],
                    "is_loss": str(row["cause"]).startswith("-"),
                })
            return actions
    except Exception as e:
        print(f"[JERICHO] Ошибка получения истории: {e}")
        return []


def _evaluate_martingale(actions: list) -> float:
    if not actions: return 0.0
    chain = []
    for a in actions:
        if a["is_loss"]:
            chain.append(a["bet_amount"])
        else:
            break
    if len(chain) < MARTINGALE_CHAIN_MIN:
        return 0.0

    growth_count = 0
    for i in range(len(chain)-1):
        # ИСПРАВЛЕНО: проверяем, что следующая ставка выросла в 1.5+ раза
        if chain[i+1] > chain[i] * MARTINGALE_GROWTH_FACTOR:
            growth_count += 1

    base = (len(chain) - MARTINGALE_CHAIN_MIN + 1) * 0.25 + growth_count * 0.2
    return min(1.0, base) * random.uniform(0.9, 1.1)


def _analyze_bet_aggression(actions: list, current_bet: int) -> float:
    if not actions or current_bet <= 0:
        return 0.0
    stakes = [a["bet_amount"] for a in actions[:AGGRESSION_HISTORY_LIMIT]]
    if len(stakes) < 3:
        return 0.0
    avg = sum(stakes) / len(stakes)
    if avg <= 0:
        return 0.0
    ratio = current_bet / avg
    if ratio < AGGRESSION_MIN_RATIO:
        return 0.0
    return min(1.0, (ratio - AGGRESSION_MIN_RATIO + 1) / 7.0) * random.uniform(0.7, 1.3)


async def _modify_0demo(user_id: int, delta: int, debug: list):
    """
    Изменяет баланс 0demo на delta (может быть отрицательным).
    Не позволяет уйти в минус (обнуляет при попытке).
    """
    if delta == 0:
        return
    debug.append(f"Изменение 0demo на {delta}...")
    try:
        old_val = int(await db.get_user_0demo(user_id) or 0)
        # Гарантируем, что не станет ниже нуля
        new_val = max(0, old_val + delta)
        async with db.pool.acquire() as conn:
            await conn.execute(
                'UPDATE users SET "0demo" = GREATEST(0, COALESCE("0demo",0) + $1) WHERE user_id = $2',
                delta, user_id
            )
        actual_new = int(await db.get_user_0demo(user_id) or 0)
        debug.append(f"0demo: было {old_val}, стало {actual_new}")
    except Exception as e:
        debug.append(f"Ошибка изменения 0demo: {e}")


async def _reduce_debt(user_id: int, amount: int):
    """Уменьшает долг (newbie_total_demo_given) на сумму amount, но не ниже 0."""
    try:
        debt = int(await db.get_newbie_total_demo_given(user_id) or 0)
        if debt <= 0:
            return
        new_debt = max(0, debt - amount)
        await db.set_newbie_total_demo_given(user_id, new_debt)
        print(f"[JERICHO] Долг уменьшен: было {debt}, стало {new_debt}")
    except Exception as e:
        print(f"[JERICHO] Ошибка уменьшения долга: {e}")


async def force_repay_debt(user_id: int, amount: int):
    """
    Принудительное списание долга (вызывается из игр при реальном проигрыше).
    """
    try:
        debt = int(await db.get_newbie_total_demo_given(user_id) or 0)
        if debt <= 0:
            return
        new_debt = max(0, debt - amount)
        await db.set_newbie_total_demo_given(user_id, new_debt)
        print(f"[JERICHO] force_repay_debt: списано {amount}, было {debt}, стало {new_debt}")
    except Exception as e:
        print(f"[JERICHO] Ошибка force_repay_debt: {e}")


