def _clamp_float(value: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(value)))


def _jericho_debug(stage: str, msg: str) -> None:
    if not JERICHO_DEBUG_ENABLED:
        return
    try:
        print(f"[JERICHO][{stage}] {msg}", flush=True)
    except Exception:
        pass


async def _get_jericho_economy_pressure_snapshot() -> dict:
    """
    Кэшированная сводка давления экономики:
    - groups_total: сумма балансов всех групп
    - total_excess: суммарный избыток групп выше порога
    - global_pressure: сглаженное давление 0..1
    """
    now_mono = time.monotonic()
    try:
        if now_mono < float(_jericho_pressure_cache.get("expires_at", 0.0)):
            cached = _jericho_pressure_cache.get("snapshot")
            if isinstance(cached, dict):
                return cached

        raw = await db.get_group_economy_pressure_snapshot(JERICHO_GROUP_EXCESS_THRESHOLD)
        groups_total = int(raw.get("groups_total", 0) or 0)
        total_excess = int(raw.get("total_excess", 0) or 0)
        hot_groups = int(raw.get("hot_groups", 0) or 0)
        creator_excess_map = raw.get("creator_excess_map") or {}
        creator_hot_groups_map = raw.get("creator_hot_groups_map") or {}

        raw_global_pressure = 0.0
        if groups_total > JERICHO_GROUPS_TOTAL_SOFT_CAP:
            raw_global_pressure = (groups_total - JERICHO_GROUPS_TOTAL_SOFT_CAP) / max(1, JERICHO_GROUPS_TOTAL_SOFT_CAP)
        raw_global_pressure = _clamp_float(raw_global_pressure, 0.0, 1.0)

        prev_ema = float(_jericho_pressure_cache.get("ema_global_pressure", 0.0) or 0.0)
        initialized = bool(_jericho_pressure_cache.get("initialized"))
        if initialized:
            ema_global = prev_ema * (1.0 - JERICHO_PRESSURE_EMA_ALPHA) + raw_global_pressure * JERICHO_PRESSURE_EMA_ALPHA
        else:
            ema_global = raw_global_pressure
        ema_global = _clamp_float(ema_global, 0.0, 1.0)

        snapshot = {
            "groups_total": groups_total,
            "total_excess": total_excess,
            "hot_groups": hot_groups,
            "creator_excess_map": creator_excess_map,
            "creator_hot_groups_map": creator_hot_groups_map,
            "global_pressure": ema_global,
            "raw_global_pressure": raw_global_pressure,
        }

        _jericho_pressure_cache["initialized"] = True
        _jericho_pressure_cache["ema_global_pressure"] = ema_global
        _jericho_pressure_cache["snapshot"] = snapshot
        _jericho_pressure_cache["expires_at"] = now_mono + JERICHO_PRESSURE_CACHE_TTL_SEC
        return snapshot
    except Exception as e:
        print(f"[JERICHO] Ошибка pressure snapshot: {e}")
        fallback = _jericho_pressure_cache.get("snapshot")
        return fallback if isinstance(fallback, dict) else {
            "groups_total": 0,
            "total_excess": 0,
            "hot_groups": 0,
            "creator_excess_map": {},
            "creator_hot_groups_map": {},
            "global_pressure": 0.0,
            "raw_global_pressure": 0.0,
        }


def _get_creator_pressure_for_user(snapshot: dict, user_id: int) -> float:
    try:
        total_excess = int(snapshot.get("total_excess", 0) or 0)
        if total_excess <= 0:
            return 0.0

        creator_excess_map = snapshot.get("creator_excess_map") or {}
        creator_hot_groups_map = snapshot.get("creator_hot_groups_map") or {}
        creator_excess = int(creator_excess_map.get(user_id, creator_excess_map.get(str(user_id), 0)) or 0)
        if creator_excess <= 0:
            return 0.0

        creator_share = creator_excess / max(1, total_excess)
        creator_hot_groups = int(
            creator_hot_groups_map.get(user_id, creator_hot_groups_map.get(str(user_id), 0)) or 0
        )
        global_pressure = float(snapshot.get("global_pressure", 0.0) or 0.0)

        # Компонент 1: доля создателя в общем избытке при глобальном перегреве.
        shared_component = global_pressure * creator_share * JERICHO_CREATOR_PRESSURE_GAIN
        # Компонент 2: персональный избыток создателя, даже если общий перегрев ещё невысокий.
        direct_component = _clamp_float(
            creator_excess / max(1, JERICHO_CREATOR_EXCESS_SOFT_CAP), 0.0, 1.0
        ) * JERICHO_CREATOR_DIRECT_EXCESS_GAIN
        # Компонент 3: бонус за количество перегретых групп этого создателя.
        hot_groups_bonus = min(
            JERICHO_CREATOR_HOT_GROUP_MAX_BONUS,
            max(0, creator_hot_groups - 1) * JERICHO_CREATOR_HOT_GROUP_STEP,
        )

        pressure = shared_component + direct_component + hot_groups_bonus
        return _clamp_float(pressure, 0.0, JERICHO_MAX_CREATOR_PRESSURE)
    except Exception:
        return 0.0


def _get_creator_hot_groups_for_user(snapshot: dict, user_id: int) -> int:
    try:
        creator_hot_groups_map = snapshot.get("creator_hot_groups_map") or {}
        return int(creator_hot_groups_map.get(user_id, creator_hot_groups_map.get(str(user_id), 0)) or 0)
    except Exception:
        return 0


async def _fetch_recent_actions(user_id: int, limit: int = 15) -> list:
    loss_patterns = ["- " + c for c in LOSS_CAUSES]
    win_patterns = ["+ " + c for c in WIN_CAUSES]
    all_patterns = loss_patterns + win_patterns
    query = """
        SELECT cause, "-" AS bet_amount, "+" AS win_amount, data
        FROM cutehistory 
        WHERE user_id = $1 AND cause = ANY($2::text[])
        ORDER BY data DESC
        LIMIT $3
    """
    try:
        async with db.pool.acquire() as conn:
            rows = await conn.fetch(query, user_id, all_patterns, limit)
            actions = []
            for row in rows:
                actions.append({
                    "cause": row["cause"],
                    "bet_amount": row["bet_amount"],
                    "win_amount": row["win_amount"],
                    "data": row["data"],
                    "is_loss": str(row["cause"]).startswith("-"),
                })
            return actions
    except Exception as e:
        print(f"[JERICHO] Ошибка получения истории: {e}")
        return []


def _evaluate_martingale(actions: list) -> float:
    if not actions: return 0.0
    chain = []
    for a in actions:
        if a["is_loss"]:
            chain.append(a["bet_amount"])
        else:
            break
    if len(chain) < MARTINGALE_CHAIN_MIN:
        return 0.0

    growth_count = 0
    for i in range(len(chain)-1):
        if chain[i+1] > chain[i] * MARTINGALE_GROWTH_FACTOR:
            growth_count += 1

    base = (len(chain) - MARTINGALE_CHAIN_MIN + 1) * 0.25 + growth_count * 0.2
    return min(1.0, base) * random.uniform(0.9, 1.1)


def _analyze_bet_aggression(actions: list, current_bet: int) -> float:
    if not actions or current_bet <= 0:
        return 0.0
    stakes = [a["bet_amount"] for a in actions[:AGGRESSION_HISTORY_LIMIT]]
    if len(stakes) < 3:
        return 0.0
    avg = sum(stakes) / len(stakes)
    if avg <= 0:
        return 0.0
    ratio = current_bet / avg
    if ratio < AGGRESSION_MIN_RATIO:
        return 0.0
    return min(1.0, (ratio - AGGRESSION_MIN_RATIO + 1) / 7.0) * random.uniform(0.7, 1.3)


async def _modify_0demo(user_id: int, delta: int, debug: list):
    if delta == 0:
        return
    debug.append(f"Изменение 0demo на {delta}...")
    try:
        old_val = int(await db.get_user_0demo(user_id) or 0)
        async with db.pool.acquire() as conn:
            await conn.execute(
                'UPDATE users SET "0demo" = GREATEST(0, COALESCE("0demo",0) + $1) WHERE user_id = $2',
                delta, user_id
            )
        new_val = int(await db.get_user_0demo(user_id) or 0)
        debug.append(f"0demo: было {old_val}, стало {new_val}")
    except Exception as e:
        debug.append(f"Ошибка изменения 0demo: {e}")


async def _reduce_debt(user_id: int, amount: int):
    try:
        debt = int(await db.get_newbie_total_demo_given(user_id) or 0)
        if debt <= 0:
            return
        new_debt = max(0, debt - amount)
        await db.set_newbie_total_demo_given(user_id, new_debt)
        print(f"[JERICHO] Долг уменьшен: было {debt}, стало {new_debt}")
    except Exception as e:
        print(f"[JERICHO] Ошибка уменьшения долга: {e}")


