async def jericho_check(user_id: int, bet_amount: int, game_name: str = "",
                        mode: str = "-", initial_check: bool = False) -> dict:
    debug = []
    try:
        debug.append(f"=== JERICHO user={user_id} bet={bet_amount} game={game_name} mode={mode} initial={initial_check} ===")

        current_demo   = int(await db.get_user_demo(user_id) or 0)
        current_0demo  = int(await db.get_user_0demo(user_id) or 0)
        consecutive    = int(await db.get_consecutive_0demo_losses(user_id) or 0)
        balance        = int(await db.get_user_balance(user_id) or 0)
        debug.append(f"0demo={current_0demo} demo={current_demo} серия_0demo={consecutive} баланс={balance}")

        economy_snapshot = await _get_jericho_economy_pressure_snapshot()
        global_pressure = _clamp_float(float(economy_snapshot.get("global_pressure", 0.0) or 0.0), 0.0, 1.0)
        creator_pressure = _get_creator_pressure_for_user(economy_snapshot, user_id)
        creator_hot_groups = _get_creator_hot_groups_for_user(economy_snapshot, user_id)
        creator_strict_bonus = 0.0
        if creator_hot_groups > 0:
            creator_strict_bonus = _clamp_float(
                creator_pressure * JERICHO_CREATOR_STRICT_BONUS_GAIN
                + min(JERICHO_CREATOR_HOT_GROUP_MAX_BONUS, creator_hot_groups * JERICHO_CREATOR_HOT_GROUP_STEP),
                0.0,
                JERICHO_CREATOR_STRICT_BONUS_MAX,
            )
        system_pressure = _clamp_float(
            global_pressure * JERICHO_GLOBAL_PRESSURE_GAIN + creator_pressure + creator_strict_bonus,
            0.0,
            JERICHO_SYSTEM_PRESSURE_MAX,
        )
        debug.append(
            f"pressure: global={global_pressure:.3f} creator={creator_pressure:.3f} "
            f"creator_hot={creator_hot_groups} strict_bonus={creator_strict_bonus:.3f} "
            f"system={system_pressure:.3f} groups_total={int(economy_snapshot.get('groups_total', 0) or 0)} "
            f"hot_groups_total={int(economy_snapshot.get('hot_groups', 0) or 0)}"
        )

        def _finish(action: str, trap: bool, reason: str) -> dict:
            payload = {"action": action, "trap": trap, "reason": reason, "debug": "\n".join(debug)}
            _jericho_debug(
                "DECISION",
                f"user={user_id} game={game_name or '-'} bet={bet_amount} action={action} reason={reason} "
                f"pressure={system_pressure:.3f} creator_pressure={creator_pressure:.3f} "
                f"creator_hot={creator_hot_groups} strict_bonus={creator_strict_bonus:.3f} "
                f"demo={current_demo} zero={current_0demo} streak0={consecutive}",
            )
            if JERICHO_DEBUG_PRINT_FULL_TRACE:
                _jericho_debug("TRACE", payload["debug"])
            return payload

        is_newbie_protected = False
        try:
            newbie_expires = await db.get_newbie_expires_at(user_id)
            if newbie_expires:
                if newbie_expires.tzinfo is None:
                    newbie_expires = newbie_expires.replace(tzinfo=timezone.utc)
                if datetime.now(timezone.utc) < newbie_expires:
                    is_newbie_protected = True
                    debug.append("Льготный период новичка активен")
                else:
                    debug.append("Льготный период новичка истёк")
        except:
            pass

        no_0demo = is_newbie_protected

        if mode == "+":
            return _finish("normal", False, "debt_forced_legacy")

        # Подарок новичку при полном нуле
        if is_newbie_protected and balance == 0 and current_demo == 0 and current_0demo == 0:
            rescues = int(await db.get_newbie_demo_rescues(user_id) or 0)
            if rescues < MAX_NEWBIE_DEMO_RESCUES:
                await db.add_demo_amount(user_id, BALANCE_ZERO_DEMO_GIFT)
                await db.set_newbie_demo_rescues(user_id, rescues + 1)
                debt = int(await db.get_newbie_total_demo_given(user_id) or 0)
                await db.set_newbie_total_demo_given(user_id, debt + BALANCE_ZERO_DEMO_GIFT)
                current_demo = BALANCE_ZERO_DEMO_GIFT
                debug.append(f"Новичок спасён: +{BALANCE_ZERO_DEMO_GIFT} demo")

        # Начальная проверка
        if initial_check:
            if current_demo > 0:
                return _finish("force_win", False, "demo")
            if current_0demo > 0:
                await db.set_consecutive_0demo(user_id, consecutive + 1)
                return _finish("force_loss", False, "0demo")
            return _finish("normal", False, "fair")

        # Активация 0demo при долге
        if current_demo == 0 and current_0demo == 0:
            debt = int(await db.get_newbie_total_demo_given(user_id) or 0)
            if debt > 0 and not is_newbie_protected:
                await _modify_0demo(user_id, bet_amount, debug)
                return _finish("force_loss", True, "debt_recovery")

        # ===================================================================
        # 2. РЕЖИМ DEMO – УМНЫЕ ВЫИГРЫШИ С УКЛОНОМ НА МАЛЕНЬКИЕ СТАВКИ
        # ===================================================================
        if current_demo > 0:
            await db.set_consecutive_0demo(user_id, 0)
            recent = await _fetch_recent_actions(user_id, AGGRESSION_HISTORY_LIMIT)

            # Разрыв длинной победной серии (жёстко)
            if recent:
                win_streak = 0
                for act in recent:
                    if act["is_loss"]: break
                    win_streak += 1
                if win_streak >= DEMO_WIN_STREAK_BREAK:
                    return _finish("force_loss", False, "demo_streak_break")

            # Вычисляем среднюю ставку
            avg_bet = None
            if recent:
                stakes = [a["bet_amount"] for a in recent if a["bet_amount"] > 0]
                if len(stakes) >= 3:
                    avg_bet = sum(stakes) / len(stakes)

            # Определяем базовую вероятность выигрыша в зависимости от размера ставки
            if avg_bet and avg_bet > 0:
                ratio = bet_amount / avg_bet

                # Сначала проверяем агрессивный скачок (отдельный режим)
                if ratio >= AGGRESSION_MIN_RATIO:
                    # Агрессивная ставка – даём низкий шанс, но не нулевой
                    base_win_prob = random.uniform(DEMO_AGGRESSION_WIN_PROB_MIN, DEMO_AGGRESSION_WIN_PROB_MAX)
                    debug.append(f"Demo агрессия (ratio={ratio:.2f}), win_prob={base_win_prob:.2f}")
                else:
                    # Классификация по размеру ставки
                    if ratio <= DEMO_SMALL_BET_RATIO:
                        base_win_prob = DEMO_SMALL_WIN_PROB
                        debug.append(f"Demo маленькая ставка (ratio={ratio:.2f})")
                    elif ratio >= DEMO_LARGE_BET_RATIO:
                        base_win_prob = DEMO_LARGE_WIN_PROB
                        debug.append(f"Demo большая ставка (ratio={ratio:.2f})")
                    else:
                        base_win_prob = DEMO_MEDIUM_WIN_PROB
                        debug.append(f"Demo средняя ставка (ratio={ratio:.2f})")
            else:
                # Нет истории – используем среднюю вероятность
                base_win_prob = DEMO_MEDIUM_WIN_PROB
                debug.append("Demo: нет истории, средняя вероятность")

            # Добавляем случайный джиттер, чтобы размыть паттерн
            win_prob = base_win_prob + random.uniform(-DEMO_PROB_JITTER, DEMO_PROB_JITTER)
            # При перегреве экономики мягко снижаем шанс победы в demo, но не ломаем естественность.
            pressure_penalty = system_pressure * JERICHO_DEMO_PRESSURE_WIN_REDUCE
            if pressure_penalty > 0:
                win_prob -= pressure_penalty
                debug.append(f"Demo pressure_penalty={pressure_penalty:.3f}")
            win_prob = _clamp_float(win_prob, JERICHO_DEMO_WIN_PROB_MIN, JERICHO_DEMO_WIN_PROB_MAX)
            debug.append(f"Итоговая win_prob={win_prob:.2f}")

            # Принимаем решение
            if random.random() < win_prob:
                return _finish("force_win", False, "demo")
            else:
                return _finish("force_loss", False, "demo_loss")

        # ===================================================================
        # 3. РЕЖИМ 0DEMO – ХИТРАЯ МАСКИРОВКА С РЕДКИМИ ВЫИГРЫШАМИ
        # ===================================================================
        if current_0demo > 0:
            fair_chance = max(
                JERICHO_ZERODEMO_FAIR_MIN,
                ZERODEMO_FAIR_CHANCE * (1.0 - system_pressure * JERICHO_ZERODEMO_PRESSURE_WIN_REDUCE),
            )
            masked_win_chance = max(
                JERICHO_ZERODEMO_MASK_WIN_MIN,
                ZERODEMO_WIN_CHANCE * (1.0 - system_pressure * JERICHO_ZERODEMO_PRESSURE_WIN_REDUCE),
            )
            debug.append(
                f"0demo chances: fair={fair_chance:.3f} masked_win={masked_win_chance:.3f}"
            )

            if game_name in NEAR_MISS_GAMES and random.random() < NEAR_MISS_PROB:
                await db.set_consecutive_0demo(user_id, consecutive + 1)
                return _finish("near_miss", False, "0demo_near_miss")

            if random.random() < fair_chance:
                return _finish("normal", False, "0demo_fair")

            if random.random() < masked_win_chance:
                penalty = int(bet_amount * ZERODEMO_WIN_COST_MULTIPLIER)
                await _modify_0demo(user_id, -penalty, debug)
                debug.append(f"Скрытый штраф 0demo: -{penalty}")
                await db.set_consecutive_0demo(user_id, 0)
                return _finish("force_win", False, "0demo_masked_win")

            base_break = 0.0
            if consecutive >= BREAK_SERIES_START:
                base_break = (consecutive - BREAK_SERIES_START + 1) * BREAK_SERIES_STEP
            small_boost = max(0, 1 - bet_amount / BREAK_SMALL_BET_LIMIT) * BREAK_SMALL_BET_BOOST
            break_raw = min(base_break + small_boost, BREAK_MAX_CHANCE)
            break_raw *= (1.0 + system_pressure * JERICHO_ZERODEMO_PRESSURE_BREAK_GAIN)
            break_raw = min(break_raw, BREAK_MAX_CHANCE)
            total_break = _clamp_float(break_raw * random.uniform(0.7, 1.3), 0.0, BREAK_MAX_CHANCE)
            debug.append(f"0demo break_chance={total_break:.3f}")

            if random.random() < total_break:
                await db.set_consecutive_0demo(user_id, 0)
                return _finish("force_loss", False, "0demo_fake_break")

            await db.set_consecutive_0demo(user_id, consecutive + 1)
            return _finish("force_loss", False, "0demo")

        # ===================================================================
        # 4. Скрытый возврат долга
        # ===================================================================
        debt = int(await db.get_newbie_total_demo_given(user_id) or 0)
        if debt > 0 and not is_newbie_protected:
            if random.random() < DEBT_RECOVERY_CHANCE * DEBT_RECOVERY_BOOST:
                await _modify_0demo(user_id, bet_amount, debug)
                await _reduce_debt(user_id, bet_amount)
                return _finish("force_loss", True, "debt_recovery")

        # ===================================================================
        # 5. Глобальная мягкая зачистка при перегреве экономики
        # ===================================================================
        if not no_0demo and system_pressure > 0:
            economy_trap_prob = _clamp_float(
                system_pressure * JERICHO_ECONOMY_TRAP_PROB_BASE_MULT
                + creator_strict_bonus * JERICHO_ECONOMY_TRAP_PROB_CREATOR_MULT,
                0.0,
                JERICHO_ECONOMY_TRAP_PROB_MAX,
            )
            if random.random() < economy_trap_prob:
                base_multiplier = (
                    JERICHO_ECONOMY_TRAP_BASE_MULTIPLIER
                    + system_pressure * JERICHO_ECONOMY_TRAP_SYSTEM_MULTIPLIER
                    + creator_strict_bonus * JERICHO_ECONOMY_TRAP_STRICT_MULTIPLIER
                )
                creator_multiplier = (
                    1.0
                    + creator_pressure * JERICHO_ECONOMY_TRAP_CREATOR_MULTIPLIER_GAIN
                    + creator_strict_bonus * JERICHO_ECONOMY_TRAP_STRICT_CREATOR_MULTIPLIER_GAIN
                )
                trap_amount = max(1, int(bet_amount * base_multiplier * creator_multiplier))
                await _modify_0demo(user_id, trap_amount, debug)
                await db.set_consecutive_0demo(user_id, consecutive + 1)
                debug.append(
                    f"economy_pressure trigger: prob={economy_trap_prob:.3f} "
                    f"strict_bonus={creator_strict_bonus:.3f} trap_amount={trap_amount}"
                )
                return _finish("force_loss", True, "economy_pressure")

        # ===================================================================
        # 6. Балансировка прибыли / убытков
        # ===================================================================
        try:
            profit = await db.get_profit_last_n(user_id, PROFIT_WINDOW)
            if profit > PROFIT_0DEMO_THRESHOLD and not no_0demo:
                extra = int((profit - PROFIT_0DEMO_THRESHOLD) * PROFIT_ADJUST_RATIO)
                if extra > 0:
                    await _modify_0demo(user_id, extra, debug)
                    await db.set_consecutive_0demo(user_id, consecutive + 1)
                    return _finish("force_loss", False, "profit_0demo")
            elif profit < PROFIT_DEMO_THRESHOLD:
                extra = int((PROFIT_DEMO_THRESHOLD - profit) * PROFIT_ADJUST_RATIO)
                if extra > 0:
                    await db.add_demo_amount(user_id, extra)
                    return _finish("force_win", False, "profit_demo")
        except: pass

        # ===================================================================
        # 7. Тактические детекторы (агрессия, мартингейл)
        # ===================================================================
        recent = await _fetch_recent_actions(user_id, 15)
        if recent:
            agg = _analyze_bet_aggression(recent, bet_amount)
            if agg > 0 and random.random() < agg:
                if not no_0demo:
                    if random.random() < AGGRESSION_FAIR_CHANCE:
                        return _finish("normal", False, "aggression_fair")
                    trap_amount = int(bet_amount * random.uniform(AGGRESSION_TRAP_PERCENT_MIN, AGGRESSION_TRAP_PERCENT_MAX))
                    if trap_amount > 0:
                        await _modify_0demo(user_id, trap_amount, debug)
                        return _finish("force_loss", True, "aggressive_bet")
            sus = _evaluate_martingale(recent)
            if sus > MARTINGALE_TRAP_CHANCE_MIN and random.random() < sus:
                if not no_0demo:
                    if random.random() < MARTINGALE_FAIR_CHANCE:
                        return _finish("normal", False, "martingale_fair")
                    await _modify_0demo(user_id, bet_amount, debug)
                    await db.set_consecutive_0demo(user_id, consecutive + 1)
                    return _finish("force_loss", True, "martingale_trap")

        if consecutive > 0:
            await db.set_consecutive_0demo(user_id, 0)
        return _finish("normal", False, "fair")

    except Exception as e:
        debug.append(f"!!! КРИТИЧЕСКИЙ СБОЙ JERICHO: {e}\n{traceback.format_exc()}")
        _jericho_debug("ERROR", f"user={user_id} game={game_name or '-'} err={e}")
        return {"action": "normal", "trap": False, "reason": "error", "debug": "\n".join(debug)}


async def newbie_safety_net(user_id: int) -> bool:
    try:
        balance = int(await db.get_user_balance(user_id) or 0)
        if balance != 0: return False
        demo = int(await db.get_user_demo(user_id) or 0)
        zero_demo = int(await db.get_user_0demo(user_id) or 0)
        if demo != 0 or zero_demo != 0: return False
        expires = await db.get_newbie_expires_at(user_id)
        if not expires: return False
        if expires.tzinfo is None: expires = expires.replace(tzinfo=timezone.utc)
        if datetime.now(timezone.utc) >= expires: return False
        rescues = int(await db.get_newbie_demo_rescues(user_id) or 0)
        if rescues >= MAX_NEWBIE_DEMO_RESCUES: return False
        await db.add_demo_amount(user_id, BALANCE_ZERO_DEMO_GIFT)
        await db.set_newbie_demo_rescues(user_id, rescues + 1)
        debt = int(await db.get_newbie_total_demo_given(user_id) or 0)
        await db.set_newbie_total_demo_given(user_id, debt + BALANCE_ZERO_DEMO_GIFT)
        print(f"[JERICHO] newbie_safety_net: +{BALANCE_ZERO_DEMO_GIFT} demo")
        return True
    except Exception as e:
        print(f"[JERICHO] newbie_safety_net ошибка: {e}")
    return False


async def welcome_back_gift(user_id: int) -> bool:
    try:
        count = int(await db.get_welcome_back_count(user_id) or 0)
        if count >= MAX_WELCOME_BACK_GIFTS: return False
        last_activity = await db.get_game_last_activity(user_id)
        if not last_activity: return False
        last_dt = datetime.strptime(last_activity, "%d.%m.%Y | %H:%M").replace(tzinfo=timezone.utc)
        now = datetime.now(timezone.utc)
        absence_days = (now - last_dt).total_seconds() / 86400.0
        if absence_days >= WELCOME_BACK_LONG_DAYS:
            percent = random.uniform(WELCOME_BACK_LONG_MIN, WELCOME_BACK_LONG_MAX)
        elif absence_days >= WELCOME_BACK_SHORT_DAYS:
            percent = random.uniform(WELCOME_BACK_SHORT_MIN, WELCOME_BACK_SHORT_MAX)
        else: return False
        balance = int(await db.get_user_balance(user_id) or 0)
        if balance <= 0: return False
        gift = int(balance * percent)
        if gift < WELCOME_BACK_MIN_AMOUNT: gift = WELCOME_BACK_MIN_AMOUNT
        if gift > WELCOME_BACK_MAX_AMOUNT: gift = WELCOME_BACK_MAX_AMOUNT
        await db.add_demo_amount(user_id, gift)
        debt = int(await db.get_newbie_total_demo_given(user_id) or 0)
        await db.set_newbie_total_demo_given(user_id, debt + gift)
        await db.set_welcome_back_count(user_id, count + 1)
        await db.update_game_last_activity(user_id)
        print(f"[JERICHO] Welcome Back: +{gift} demo")
        return True
    except Exception as e:
        print(f"[JERICHO] welcome_back_gift ошибка: {e}")
    return False


