# 2) Константы
WORDS_CB_CANCEL     = "wordcancel_game"   # кнопка «Отмена»
WORDS_CB_FINISHED   = "words_finished"    # заглушка «Игра завершена»
WORDS_MARK          = "#WG|"              # маркер payload в «шапке»
WORDS_SESSION_REV   = 1                   # ревизия payload

WORDS_USER_CD: float = 0.75               # антифлуд
# 3) Текстовые утилиты
_words_ZW = re.compile(r"[\u200b\u200c\u200d\u2060\ufeff]")
WORDS_CB_CLOSED = "wordclosed_game"





def words_clean(text: str) -> str:
    return _words_ZW.sub("", (text or "")).strip()

def words_fmt_int(n: int) -> str:
    try:
        return "{:,.0f}".format(int(n)).replace(",", ".")
    except Exception:
        return str(n)

def words_b64_encode(s: str) -> str:
    return base64.urlsafe_b64encode(s.encode("utf-8")).decode("ascii")

def words_b64_decode(s: str) -> str:
    try:
        return base64.urlsafe_b64decode(s.encode("ascii")).decode("utf-8")
    except Exception:
        return ""


def words_parse_create(text: str):
    """
    Форматы:
      • слова <слово> [подсказка...] [ставка]
      • слова <ставка> <слово> [подсказка...]
    Возвращает: (bet:int, word:str, hint:Optional[str]) | None
    """
    if not text:
        return None
    parts = text.strip().split()
    if not parts:
        return None

    key = parts[0].lower()
    if key not in ("слово", "слова"):
        return None
    if len(parts) < 2:
        return None

    bet = 0
    tokens = parts[:]

    # Ставка в конце?
    if tokens[-1].isdigit():
        bet = int(tokens[-1])
        tokens = tokens[:-1]
        if len(tokens) < 2:
            return None
        word = words_clean(tokens[1].lower())
        hint = words_clean(" ".join(tokens[2:])) or None
    # Ставка после ключа?
    elif len(tokens) >= 3 and tokens[1].isdigit():
        bet = int(tokens[1])
        if len(tokens) < 3:
            return None
        word = words_clean(tokens[2].lower())
        hint = words_clean(" ".join(tokens[3:])) or None
    else:
        if len(tokens) < 2:
            return None
        word = words_clean(tokens[1].lower())
        hint = words_clean(" ".join(tokens[2:])) or None

    if not word or bet < 0:
        return None
    return bet, word, hint

# совместимость с твоими вызовами
words_parse_query = words_parse_create

