async def _words_force_close_previous_for_creator(chat_id: int, creator_id: int, exclude_game_id: Optional[str] = None):
    """
    Находит ЛЮБУЮ открытую игру того же автора в этом чате и закрывает её:
    - правит текст «Игра отменена создателем…»
    - ставит «✅ Игра завершена»
    - помечает в сторе closed=True
    Делает только через WORDS_STORE (единый словарь).
    """
    try:
        for gid, g in list(WORDS_STORE.items()):
            if gid == exclude_game_id:
                continue
            if g.get("chat_id") == chat_id and g.get("creator_id") == creator_id and not g.get("closed"):
                # UI
                try:
                    await bot1.edit_message_text(
                        "🌿",
                        chat_id=g["chat_id"],
                        message_id=g["message_id"],
                        parse_mode="HTML",
                        reply_markup=words_build_closed_kb()
                    )
                except Exception as e:
                    print(f"[WORDS][FORCE_CLOSE][UI_ERR] {e!r}")

                # Стор
                g["closed"] = True
                g["winner_id"] = None
                g["payout_done"] = True
                g["reason"] = "new_game_by_creator"
                print(f"[WORDS][FORCE_CLOSE] game_id={gid} closed by new game of same creator")
    except Exception as e:
        print(f"[WORDS][FORCE_CLOSE][ERR] {e!r}")
# ───────── FORCE CLOSE (единый) ─────────
def _words_force_close(game_id: str, reason: str = ""):
    g = WORDS_STORE.get(game_id)
    if not g:
        return False
    g["closed"] = True
    g["winner_id"] = None
    g["payout_done"] = True
    # UI
    try:
        if g.get("chat_id") and g.get("message_id"):
            bot1.loop.create_task(bot1.edit_message_text(
                "🌿",
                chat_id=g["chat_id"], message_id=g["message_id"], parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(text="Игра завершена", callback_data=WORDS_CB_CLOSED)]
                ])
            ))
        elif g.get("inline_message_id"):
            bot1.loop.create_task(bot1.edit_message_text(
                "🌿",
                inline_message_id=g["inline_message_id"], parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(text="Игра завершена", callback_data=WORDS_CB_CLOSED)]
                ])
            ))
    except Exception as e:
        print(f"[WORDS][FORCE_CLOSE][UI_ERR] {e!r}")
    return True


