def words_build_start_payload(game_id: str, creator_id: int, bet: int, word_to_guess: str,
                              hint: Optional[str], session_rev: int) -> str:
    payload = {
        "rev": session_rev,
        "game_id": game_id,
        "creator_id": int(creator_id),
        "bet": int(bet),
        "word": word_to_guess,
        "hint": hint or ""
    }
    return words_b64_encode(json.dumps(payload, ensure_ascii=False))

def _md_escape(s: str) -> str:
    if s is None:
        return ""
    return (
        str(s)
        .replace('\\', r'\\')
        .replace('*', r'\*')
        .replace('_', r'\_')
        .replace('`', r'\`')
        .replace('[', r'\[')
        .replace(']', r'\]')
        .replace('(', r'\(')
        .replace(')', r'\)')
    )

# --- формирование ТЕКСТА стартовой карточки (Markdown) ---
def _html(s: str) -> str:
    return html.escape(s or "", quote=True)

# --- формирование ТЕКСТА стартовой карточки (HTML, без entities) ---
async def words_build_start_plain_text(
    creator_id: int,
    creator_name: str,
    bet: int,
    hint: Optional[str],
    payload_b64: str
) -> tuple[str, list]:
    """
    Возвращает:
      text (HTML) и ПУСТОЙ список entities (НЕ используем их вместе с parse_mode).
    """
    first_name = await db.get_firstname_by_user_id(creator_id)
    username   = await db.get_username_by_user_id(creator_id)

    # твоя утилита делает корректную HTML-ссылку на пользователя
    # (если она уже экранирует - ок; если нет, подстрахуемся _html на входах)
    name_link = await create_user_link(creator_id, _html(first_name) or _html(creator_name) or "Игрок", username)

    title    = "⭐️ <b>Игра в слова началась!</b> ⭐️"
    bet_line = f"\n<b>💰 {words_fmt_int(bet)} кут</b>" if bet > 0 else ""
    hint_line = (
        f'\n\n<blockquote>🧠 <b>Подсказка :</b>\n🎀 <b>«{_html(hint)}»</b></blockquote>'
        if hint else ""
    )

    # невидимая ссылка с payload на ZW-символ
    ZW = "\u200b"
    payload_url = f"https://t.me/cg?d={WORDS_MARK}{payload_b64}"
    hidden_anchor = f'<a href="{_html(payload_url)}">{ZW}</a>'

    text = (
        f"{title}\n"
        f"🍹 <b><i>{name_link}</i></b>"
        f"{bet_line}{hint_line}"
        f"{hidden_anchor}"
    )

    return text, []  # entities НЕ возвращаем, работаем только через HTML

# ───────── EXTRACT payload ─────────

try:
    _MARK_RE = re.compile(rf"{re.escape(WORDS_MARK)}([A-Za-z0-9_\-]+=*)", flags=re.IGNORECASE)
except Exception:
    _MARK_RE = None

def _words_extract_payload_b64_safe(msg: Optional[Message]) -> str:
    if not msg:
        return ""
    try:
        for e in (msg.entities or []):
            if e.type == "text_link":
                url = getattr(e, "url", "") or ""
                if not url:
                    continue
                idx = url.find(WORDS_MARK)
                if idx != -1:
                    tail = url[idx + len(WORDS_MARK):]
                    for sep in ["&", "#", "?"]:
                        cut = tail.find(sep)
                        if cut != -1:
                            tail = tail[:cut]
                    return tail
    except Exception as e:
        print(f"[WORDS][EXTRACT_URL_ERR] {e!r}")
    return ""

# ───────── мягкий лок ─────────

def _try_soft_lock(game: Dict[str, Any], ttl: float = 3.0) -> bool:
    now = _now_mono()
    until = float(game.get("busy_until", 0.0))
    if now < until:
        return False
    game["busy_until"] = now + ttl
    return True

def _words_soft_unlock(g: dict) -> None:
    try:
        g["busy_until"] = 0.0
    except Exception:
        pass

def _soft_unlock(game: Dict[str, Any]) -> None:
    game["busy_until"] = 0.0

# ───────── bootstrap по via_bot + payload ─────────

WORDS_ALLOW_MULTIPLE_ACTIVE_PER_CREATOR: bool = False

# ───────── вспом: красивое закрытие предыдущих игр автора ─────────
async def _words_force_close_previous_for_creator(
    chat_id: int,
    creator_id: int,
    exclude_game_id: Optional[str] = None
) -> int:
    """
    Закрывает все открытые игры этого создателя в данном чате, кроме exclude_game_id.
    Возвращает число закрытых игр.
    """
    try:
        closed_count = 0
        # проходим копией items, чтобы безопасно редактировать
        for gid, g in list(WORDS_STORE.items()):
            if not g or g.get("closed"):
                continue
            if g.get("chat_id") != chat_id:
                continue
            if int(g.get("creator_id", 0)) != int(creator_id):
                continue
            if exclude_game_id and gid == exclude_game_id:
                continue

            g["closed"] = True
            g["winner_id"] = None
            g["payout_done"] = False
            g["closed_reason"] = "superseded_by_new_game"

            try:
                header_mid = int(g.get("message_id") or 0)
                if header_mid:
                    word_orig = words_clean(g.get("word_orig") or "")
                    end_text = (
                        "🪄 <b>Игра в слова завершена</b>\n"
                        "Причина: автор запустил новую игру.\n"
                        f"🎗 Слово: <b>«{word_orig}»</b>"
                    )
                    await bot1.edit_message_text(
                        end_text,
                        chat_id=chat_id,
                        message_id=header_mid,
                        parse_mode="HTML",
                        reply_markup=words_build_closed_kb(),
                        disable_web_page_preview=True,
                    )
            except Exception as e_edit:
                print(f"[WORDS][FORCE_CLOSE_EDIT_ERR] {e_edit!r}")

            closed_count += 1
            print(f"[WORDS][FORCE_CLOSE] game_id={gid} closed by new game of same creator")
        return closed_count
    except Exception as e:
        print(f"[WORDS][FORCE_CLOSE_ERR] {e!r}")
        return 0


# ───────── bootstrap: регистрация новой игры из инлайн-сообщения ─────────
async def _words_inline_bootstrap_if_needed(message: Message) -> bool:
    try:
        if not message or not message.chat or not getattr(message, "via_bot", None):
            return False

        me = await bot1.get_me()
        if not me or message.via_bot.id != me.id:
            return False

        payload_b64 = _words_extract_payload_b64_safe(message)
        if not payload_b64:
            print("[WORDS][BOOTSTRAP_SKIP] empty payload")
            return False

        try:
            data = json.loads(words_b64_decode(payload_b64))
        except Exception as e:
            print(f"[WORDS][BOOTSTRAP_DECODE_FAIL] {e!r}")
            return False

        game_id    = str(data.get("game_id") or "").strip()
        creator_id = int(data.get("creator_id", 0))
        bet        = int(data.get("bet", 0))

        word_original = str(data.get("word", "")).strip()
        word_cleaned  = words_clean(word_original).strip()
        word_norm     = word_cleaned.lower()

        hint_raw = str(data.get("hint", "")).strip()
        hint     = words_clean(hint_raw) or None

        if not game_id or not word_norm:
            print("[WORDS][BOOTSTRAP_EMPTY] game_id/word empty")
            return False

        chat_id = message.chat.id
        msg_id  = message.message_id

        if game_id in WORDS_STORE:
            return True  # уже есть

        # при необходимости - закрыть прошлую игру автора в этом чате
        if not WORDS_ALLOW_MULTIPLE_ACTIVE_PER_CREATOR:
            await _words_force_close_previous_for_creator(
                chat_id=chat_id,
                creator_id=creator_id,
                exclude_game_id=game_id
            )

        # регистрируем
        WORDS_STORE[game_id] = {
            "game_id": game_id,
            "chat_id": chat_id,
            "message_id": msg_id,
            "creator_id": creator_id,
            "bet": bet,
            "word_orig": word_original,
            "word_norm": word_norm,
            "hint": hint,  # уже очищенная, может быть None
            "closed": False,
            "winner_id": None,
            "payout_done": False,
            "created_ts": time.time(),
            "_lock": 0,
        }

        print(f"[WORDS][BOOTSTRAP_OK] chat={chat_id} msg={msg_id} creator={creator_id} bet={bet} word='{word_norm}'")
        return True

    except Exception as e:
        print(f"[WORDS][BOOTSTRAP_ERR] {e!r}")
        return False

# ───────── жёсткое закрытие (универсальный хелпер) ─────────

async def words_force_close_game(
    key: Tuple[int, int],
    *,
    reason: str = "finished",
    ui_text: Optional[str] = None,
    inline_id: Optional[str] = None
) -> bool:
    try:
        g = words_games.get(key)
        if not g:
            print(f"[WORDS][FORCE_CLOSE] key={key} → game not found")
            # если знаем inline_id - хотя бы UI поменяем
            if inline_id:
                try:
                    await bot1.edit_message_text(ui_text or "🎯 Игра завершена.", inline_message_id=inline_id, parse_mode="HTML")
                    await bot1.edit_message_reply_markup(inline_message_id=inline_id, reply_markup=words_build_finished_kb())
                except Exception as e:
                    print(f"[WORDS][FORCE_CLOSE][INLINE_ONLY_UI_ERR] {e!r}")
            return False

        if not g.get("closed"):
            g["closed"] = True
            g["winner_id"] = None
            g["payout_done"] = True

        chat_id, msg_id = key
        word = g.get("word_to_guess")
        creator_id = int(g.get("creator_id", 0))

        # чистка индексов (без await)
        try:
            words_open_by_chat.get(chat_id, set()).discard(key)
            if word:
                words_index_by_word.get((chat_id, word), set()).discard(key)
        except Exception as e:
            print(f"[WORDS][FORCE_CLOSE][IDX_ERR] {e!r}")

        # UI по chat/msg
        try:
            final_text = ui_text or "🎯 Игра завершена."
            await bot1.edit_message_text(final_text, chat_id=chat_id, message_id=msg_id, parse_mode="HTML")
            await bot1.edit_message_reply_markup(chat_id=chat_id, message_id=msg_id, reply_markup=words_build_finished_kb())
        except Exception as e:
            print(f"[WORDS][FORCE_CLOSE][UI_ERR] {e!r}")

        # чистка inline индексов
        try:
            for inl_id, k in list(words_inline_index.items()):
                if k == key:
                    words_inline_index.pop(inl_id, None)
            # мету тоже выкинем, если она есть и указывает на этот ключ (необяз.)
        except Exception as e:
            print(f"[WORDS][FORCE_CLOSE][INLINE_IDX_ERR] {e!r}")

        # снимаем индекс активной «шапки» у создателя
        try:
            idx_key = (chat_id, creator_id)
            prev_id = user_word_index.get(idx_key)
            if prev_id == msg_id:
                user_word_index.pop(idx_key, None)
        except Exception as e:
            print(f"[WORDS][FORCE_CLOSE][USER_IDX_ERR] {e!r}")

        # удаляем игру
        try:
            words_games.pop(key, None)
        except Exception as e:
            print(f"[WORDS][FORCE_CLOSE][STORE_DEL_ERR] {e!r}")

        print(f"[WORDS][FORCE_CLOSE] key={key} done, reason={reason}")
        return True

    except Exception as e:
        print(f"[WORDS][FORCE_CLOSE][FATAL] {e!r}")
        return False





