# ==================== ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ====================
def _fmt_int1(n: int) -> str:
    return f"{n:,}".replace(",", ".")

def _fmt_crypto_amount(x: Decimal) -> str:
    normalized = x.normalize()
    s = f"{normalized:f}"
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    return s

def _fmt_decimal_str(x: Decimal) -> str:
    i = int(x.to_integral_value(rounding=ROUND_HALF_UP))
    return _fmt_int1(i)

