# ==================== КЭШИРОВАНИЕ КУРСОВ ====================
_stars_usd_cache = {"rate": Decimal("0.015"), "last_update": 0}
STARS_USD_CACHE_TTL = 60

async def get_stars_usd_rate() -> Decimal:
    now = time.time()
    if now - _stars_usd_cache["last_update"] < STARS_USD_CACHE_TTL:
        return _stars_usd_cache["rate"]
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get("https://stars-price.com/api/price") as resp:
                if resp.status == 200:
                    data = await resp.json()
                    rate = Decimal(str(data.get("usd_per_star", "0.015")))
                    if rate > 0:
                        _stars_usd_cache["rate"] = rate
                        _stars_usd_cache["last_update"] = now
                        debug_print(f"Обновлён курс Stars: {rate} USD")
                        return rate
    except Exception as e:
        debug_print(f"Ошибка получения курса Stars: {e}")
    fallback = Decimal("0.015")
    debug_print(f"Используем резервный курс Stars: {fallback}")
    return fallback

_crypto_rates_cache = {"rates": {}, "last_update": 0}
CRYPTO_CACHE_TTL = 60

async def get_all_crypto_usd_rates(currencies: List[str]) -> Dict[str, Decimal]:
    now = time.time()
    if now - _crypto_rates_cache["last_update"] < CRYPTO_CACHE_TTL:
        cached = {c: _crypto_rates_cache["rates"].get(c) for c in currencies}
        if all(v is not None for v in cached.values()):
            debug_print("Используем кэшированные курсы криптовалют")
            return cached

    coin_map = {
        "BTC": "bitcoin", "ETH": "ethereum", "TON": "the-open-network",
        "BNB": "binancecoin", "LTC": "litecoin", "DOGE": "dogecoin",
        "TRX": "tron", "USDT": "tether"
    }
    ids = [coin_map.get(c, c.lower()) for c in currencies]
    ids_str = ",".join(ids)

    try:
        async with aiohttp.ClientSession() as session:
            url = f"https://api.coingecko.com/api/v3/simple/price?ids={ids_str}&vs_currencies=usd"
            async with session.get(url) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    rates = {}
                    for curr in currencies:
                        coin_id = coin_map.get(curr, curr.lower())
                        rate = Decimal(str(data.get(coin_id, {}).get("usd", 0)))
                        if rate > 0:
                            rates[curr] = rate
                        else:
                            fb = {"BTC": 65000, "ETH": 3200, "TON": 5.2, "BNB": 580,
                                  "LTC": 85, "DOGE": 0.12, "TRX": 0.17, "USDT": 1.0}
                            rates[curr] = Decimal(fb.get(curr, 1.0))
                    _crypto_rates_cache["rates"] = rates
                    _crypto_rates_cache["last_update"] = now
                    debug_print("Курсы криптовалют обновлены")
                    return rates
    except Exception as e:
        logging.error(f"Ошибка получения курсов криптовалют: {e}")

    fb = {"BTC": 65000, "ETH": 3200, "TON": 5.2, "BNB": 580, "LTC": 85, "DOGE": 0.12, "TRX": 0.17, "USDT": 1.0}
    return {c: Decimal(fb.get(c, 1.0)) for c in currencies}

async def get_crypto_usd_rate(currency: str) -> Decimal:
    rates = await get_all_crypto_usd_rates([currency])
    return rates.get(currency, Decimal("1.0"))

def calculate_crypto_amount(stars_whole: int, currency: str, crypto_usd_rate: Decimal) -> Decimal:
    stars_usd_rate = _stars_usd_cache["rate"]
    stars_usd = Decimal(stars_whole) * stars_usd_rate
    total_usd = stars_usd * (Decimal(1 + MARKUP_PERCENT / 100) * Decimal(1 + VOLATILITY_BUFFER_PERCENT / 100))
    crypto_amount = total_usd / crypto_usd_rate
    return crypto_amount.quantize(Decimal("0.000001"))

async def get_filtered_currencies_for_stars(stars_whole: int) -> List[str]:
    available = await get_available_currencies()
    if not available:
        return []
    rates = await get_all_crypto_usd_rates(available)
    filtered = []
    for curr in available:
        rate = rates.get(curr)
        if not rate or rate <= 0:
            continue
        crypto_amount = calculate_crypto_amount(stars_whole, curr, rate)
        min_crypto = MIN_CRYPTO_AMOUNTS.get(curr, Decimal("1.0"))
        if crypto_amount >= min_crypto:
            filtered.append(curr)
    debug_print(f"Для {stars_whole} Stars доступны валюты: {filtered}")
    return filtered

