# LRU кэш для готовых клавиатур с криптокнопками (ключ - сумма звёзд)
from functools import lru_cache

@lru_cache(maxsize=256)
def get_crypto_keyboard(
    stars_whole: int,
    is_buyback: bool = False,
    kut_amount: Optional[int] = None,
    gbl_chat_id: Optional[int] = None,
    gbl_level: Optional[int] = None,
) -> InlineKeyboardMarkup:
    """Клавиатура оплаты: Stars pay + сетка crypto (всегда), как в проде.

    Crypto-кнопки показываем всегда. CryptoPay-клиент поднимается лениво
    в ensure_cryptopay() при клике — иначе в local-test кнопки пропадали
    из-за cp is None.
    """
    crypto_buttons = []
    for curr, text, emoji_id, has_custom in _CRYPTO_BUTTON_TEMPLATES:
        if is_buyback and kut_amount is not None:
            cb_data = f"crypto_{curr}_{stars_whole}_buyback_{kut_amount}"
        elif gbl_chat_id is not None and gbl_level is not None:
            cb_data = f"crypto_{curr}_{stars_whole}_gblevel_{int(gbl_chat_id)}_{int(gbl_level)}"
        else:
            cb_data = f"crypto_{curr}_{stars_whole}"

        if has_custom:
            btn = InlineKeyboardButton(
                text=text,
                callback_data=cb_data,
                icon_custom_emoji_id=emoji_id
            )
        else:
            btn = InlineKeyboardButton(
                text=text,
                callback_data=cb_data
            )
        crypto_buttons.append(btn)

    crypto_rows = [crypto_buttons[i:i+2] for i in range(0, len(crypto_buttons), 2)]
    stars_view = format(stars_whole, ',d').replace(',', ' ')
    kb_rows = [[InlineKeyboardButton(text=f"Оплатить {stars_view} ⭐️", pay=True)]]
    if crypto_rows:
        kb_rows.extend(crypto_rows)
    kb_rows.append([
        InlineKeyboardButton(
            text="Закрыть",
            callback_data="9close_bonus_+",
            icon_custom_emoji_id="5960671702059848143"
        )
    ])
    return InlineKeyboardMarkup(inline_keyboard=kb_rows)


# ==================== БЫСТРАЯ ПРОВЕРКА RATE LIMIT (ДЛЯ CALLBACK) ====================
async def check_rate_limit_callback(callback: types.CallbackQuery) -> bool:
    """Возвращает True, если лимит не превышен, иначе отправляет alert и возвращает False."""
    user_id = callback.from_user.id
    now = time.time()
    async with _rate_limit_lock:
        last = _rate_limit_dict.get(user_id)
        if last and (now - last) < RATE_LIMIT_SECONDS:
            await callback.answer(
                f"⚠️ Подождите {RATE_LIMIT_SECONDS} сек.",
                show_alert=True
            )
            return False
        _rate_limit_dict[user_id] = now
        if len(_rate_limit_dict) > _CLEANUP_THRESHOLD:
            expired = [uid for uid, ts in _rate_limit_dict.items() if now - ts > 60]
            for uid in expired:
                del _rate_limit_dict[uid]
    return True


# ==================== ОТПРАВКА ИНВОЙСА (XTR) – МАКСИМАЛЬНО БЫСТРАЯ ====================
async def send_invoice_to_user(
    message: types.Message,
    stars_amount: Union[str, int, float],
    operation_type: str = "donate",      # "donate" или "buyback"
    kut_amount: int = None,              # для buyback – сколько кут получит пользователь
    nonce: str = None                    # для buyback – защитный nonce
) -> Optional[types.Message]:
    """
    Отправляет счёт на оплату Telegram Stars.
    Для доната: звёзды -> куты по курсу.
    Для выкупа: звёзды = сумма кут * скидка (мин. 1⭐), куты = полная сумма потерянных кут.
    """
    # 1. Приведение суммы звёзд к целому
    try:
        stars_whole = int(float(stars_amount))
    except (ValueError, TypeError):
        await message.answer("<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> Неверное значение суммы.", parse_mode="HTML")
        return None
    if stars_whole <= 0:
        await message.answer("<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> Сумма должна быть больше нуля.", parse_mode="HTML")
        return None

    # 2. Расчёт кутов
    if operation_type == "buyback":
        # Выкуп: количетво кут = переданное значение (полные потерянные куты)
        if kut_amount is None or kut_amount <= 0:
            await message.answer("<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> Некорректная сумма выкупа.", parse_mode="HTML")
            return None
        kut_int = kut_amount
        # Проверка согласованности: цена в звёздах должна быть = max(1, int(kut_int * 0.8))
        expected_stars = max(1, int(kut_int * MULTIPLIER_BUYBACK))
        if stars_whole != expected_stars:
            await message.answer("<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> Ошибка расчёта выкупа. Попробуйте ещё раз.", parse_mode="HTML")
            return None
    else:
        # Донат: стандартный расчёт по курсу
        if DONATE_BET_STARS_PER_KUT <= 0:
            await message.answer("<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> Внутренняя ошибка цены.", parse_mode="HTML")
            return None
        kut_int = (stars_whole * 2 + DONATE_BET_STARS_PER_KUT) // (DONATE_BET_STARS_PER_KUT * 2)
        if kut_int <= 0:
            await message.answer("<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> По данной сумме кут не начисляются. Увеличьте количество звёзд.", parse_mode="HTML")
            return None

    # 3. Форматирование
    stars_view = format(stars_whole, ',d').replace(',', ' ')
    kut_view = format(kut_int, ',d').replace(',', ' ')
    bet_view = format(DONATE_BET_STARS_PER_KUT, ',d').replace(',', ' ') if operation_type == "donate" else "🎟"

    # 4. Клавиатура
    if operation_type == "buyback":
        kb = get_crypto_keyboard(stars_whole , is_buyback=True , kut_amount=kut_amount)
    else:
        kb = get_crypto_keyboard(stars_whole)

    # 5. Prices и описание
    if operation_type == "buyback":
        title = f"🎩 Выкуп {kut_view} кут"
        description = f"🧸 Выкуп списанных кут. 💰 {kut_view} кут = {stars_view} ⭐️"
        payload = f"buyback_{kut_int}_{nonce}"
    else:
        title = f"🎩 Покупка {kut_view} кут"
        description = f"💰 1 кут = {bet_view} ⭐️"
        payload = f"buy_{stars_whole}_stars_{kut_int}"

    prices = [LabeledPrice(label=title[:32], amount=stars_whole)]

    # 6. Получатель
    user_id = message.from_user.id if message.from_user and not message.from_user.is_bot else None
    if user_id is None and message.chat.type == "private":
        user_id = message.chat.id
    if user_id is None:
        await message.answer("<tg-emoji emoji-id='5420323339723881652'>⚠️</tg-emoji> Не удалось определить получателя счёта.", parse_mode="HTML")
        return None

    # 7. Отправка инвойса
    try:
        invoice_msg = await bot1.send_invoice(
            chat_id=user_id,
            title=title[:32],
            description=description[:255],
            payload=payload[:128],
            currency="XTR",
            prices=prices,
            provider_token="",
            start_parameter="purchase",
            reply_markup=kb
        )
        # Доп. учёт для бонусов (можешь оставить свой)
        user_bonus_requests.setdefault(user_id, []).append(invoice_msg.message_id)
        message_state[user_id] = invoice_msg.message_id
        return invoice_msg
    except Exception as e:
        debug_print(f"Ошибка send_invoice: {e}")
        # Создаём клавиатуру с одной кнопкой
        tokernasd = await get_bot_username_by_token(TOKEN)
        keyboard = InlineKeyboardMarkup(
            inline_keyboard=[
                [ InlineKeyboardButton(text="Запустить бот" , url=f"https://t.me/{tokernasd}?start=start") ] ])

        await message.answer(
            "<tg-emoji emoji-id='5420323339723881652'>⚠️</tg-emoji> <b>Не удалось отправить счёт. Попробуйте зайти в ЛС с ботом и написать /start</b>" ,
            parse_mode="HTML" , reply_markup=keyboard)
        return None


