# ───────── ОБЩИЙ ХЕЛПЕР ЗАКРЫТИЯ ИГРЫ ─────────
async def words_force_close_game(
    key: Tuple[int, int],
    *,
    reason: str = "finished",
    ui_text: Optional[str] = None,
    inline_id: Optional[str] = None
) -> bool:
    """
    Закрывает игру по ключу (chat_id, msg_id):
      - помечает флаги closed=True, winner=None, payout_done=True
      - чистит индексы (words_open_by_chat, words_index_by_word, words_inline_index, user_word_index)
      - правит текст и клавиатуру в UI (на «Игра завершена»)
    Возвращает True при успехе (если игра была найдена).
    """
    try:
        g = words_games.get(key)
        if not g:
            print(f"[WORDS][FORCE_CLOSE] key={key} → game not found")
            return False

        if g.get("closed"):
            print(f"[WORDS][FORCE_CLOSE] key={key} → already closed")
        else:
            g["closed"] = True
            g["winner_id"] = None
            g["payout_done"] = True

        chat_id, msg_id = key
        word = g.get("word_to_guess")
        creator_id = int(g.get("creator_id", 0))

        # Чистим индексы (без await)
        try:
            words_open_by_chat.get(chat_id, set()).discard(key)
            if word:
                words_index_by_word.get((chat_id, word), set()).discard(key)
        except Exception as e:
            print(f"[WORDS][FORCE_CLOSE][IDX_ERR] {e!r}")

        # UI
        try:
            final_text = ui_text or "🎯 Игра завершена."
            await bot1.edit_message_text(final_text, chat_id=chat_id, message_id=msg_id, parse_mode="HTML")
            await bot1.edit_message_reply_markup(
                chat_id=chat_id, message_id=msg_id, reply_markup=words_build_finished_kb()
            )
        except Exception as e:
            print(f"[WORDS][FORCE_CLOSE][UI_ERR] {e!r}")

        # Убираем inline index, если есть
        try:
            for inl_id, k in list(words_inline_index.items()):
                if k == key:
                    words_inline_index.pop(inl_id, None)
        except Exception as e:
            print(f"[WORDS][FORCE_CLOSE][INLINE_IDX_ERR] {e!r}")

        # Снимаем user_word_index для этого создателя, если он указывал на msg_id
        try:
            idx_key = (chat_id, creator_id)
            prev_id = user_word_index.get(idx_key)
            if prev_id == msg_id:
                user_word_index.pop(idx_key, None)
        except Exception as e:
            print(f"[WORDS][FORCE_CLOSE][USER_IDX_ERR] {e!r}")

        # Удаляем саму игру из стора
        try:
            words_games.pop(key, None)
        except Exception as e:
            print(f"[WORDS][FORCE_CLOSE][STORE_DEL_ERR] {e!r}")

        print(f"[WORDS][FORCE_CLOSE] key={key} done, reason={reason}")
        return True

    except Exception as e:
        print(f"[WORDS][FORCE_CLOSE][FATAL] {e!r}")
        return False






# ---------------- утилиты ----------------
def _mask(s: str) -> str:
    if not s:
        return "(пусто)"
    n = len(s)
    return s if n <= 4 else (s[:2] + "*" * (n - 4) + s[-2:])

def _pick(env_name: str, fallback, src: str) -> Tuple[str, str]:
    v = os.getenv(env_name)
    return (v, f"ENV:{env_name}") if v not in (None, "") else (fallback, src)

def _pick_password(env_name: str, fallback, src: str) -> Tuple[str, str]:
    """
    Для пароля:
    - ENV пустой/'none'/'null' => без пароля ('')
    - иначе берём как есть
    """
    v = os.getenv(env_name)
    if v is None:
        return (fallback, src)
    if v.strip().lower() in ("", "none", "null"):
        return ("", f"ENV:{env_name}(empty)")
    return (v, f"ENV:{env_name}")

def _bool_env(name: str, default: bool) -> bool:
    v = os.getenv(name)
    if v is None:
        return default
    return v.strip().lower() not in ("0", "false", "no", "")

