# ---------- ожидание Redis ----------
def _make_pool(host: str, port: int, password: Optional[str]):
    return redis.ConnectionPool(
        host=host, port=int(port),
        password=(password or None),
        decode_responses=False,   # pickle-байты
        socket_timeout=1.5, socket_connect_timeout=1.5,
        health_check_interval=0,
    )

def _pipeline_smoke_test(client: "redis.Redis") -> bool:
    pipe = client.pipeline()
    pipe.ping()
    k = "boot:test:key"
    pipe.set(k, "ok", ex=30)
    pipe.get(k)
    pong, _, val = pipe.execute()
    return bool(pong and val == b"ok")

def _try_auth_then_noauth_fast(host: str, port: int, password: Optional[str]) -> Optional[Redis]:
    if password:
        try:
            cli_auth = redis.Redis(connection_pool=_make_pool(host, port, password))
            if _pipeline_smoke_test(cli_auth):
                if BOOT_VERBOSE:
                    print(f"[Redis] ✅ {host}:{port} AUTH ok")
                return cli_auth
        except (AuthenticationError, ResponseError) as e:
            msg = str(e).lower()
            if "called without any password configured" in msg:
                if BOOT_VERBOSE:
                    print(f"[Redis] ℹ️ {host}:{port} ignore AUTH → retry NOAUTH")
                cli_noauth = redis.Redis(connection_pool=_make_pool(host, port, None))
                if _pipeline_smoke_test(cli_noauth):
                    return cli_noauth
        except (ConnectionError, TimeoutError):
            pass
    try:
        cli_noauth = redis.Redis(connection_pool=_make_pool(host, port, None))
        if _pipeline_smoke_test(cli_noauth):
            if BOOT_VERBOSE:
                print(f"[Redis] ✅ {host}:{port} NOAUTH ok")
            return cli_noauth
    except (ConnectionError, TimeoutError):
        pass
    return None

def _redis_endpoint_reachable(host: str, ports, timeout: float = 0.35) -> bool:
    """Мгновенная TCP-проверка: открыт ли хоть один порт Redis.

    connection-refused на localhost возвращается за миллисекунды, поэтому
    не тратим драгоценные секунды на socket_connect_timeout, если Redis не поднят.
    """
    import socket

    for port in ports:
        try:
            with socket.create_connection((host, int(port)), timeout=max(0.05, float(timeout))):
                return True
        except OSError:
            continue
    return False


def _wait_for_redis_multi(
    preferred_host: str,
    preferred_port: int,
    timeout_total: float = 30.0,
    base_interval: float = 0.3,
    max_interval: float = 2.0,
) -> "redis.Redis":
    port_order = []
    for p in (preferred_port, 6379, 6380):
        if p not in port_order:
            port_order.append(p)

    start = time.time()
    attempt = 0
    while (time.time() - start) < timeout_total:
        attempt += 1
        for port in port_order:
            cli = _try_auth_then_noauth_fast(preferred_host, port, RAW_PASSWORD)
            if cli is not None:
                if BOOT_VERBOSE:
                    print(f"[Redis] 🔗 connected to {preferred_host}:{port}")
                return cli
        sleep_for = min(max_interval, base_interval * (2 ** (attempt - 1))) + random.uniform(0, 0.1)
        time.sleep(sleep_for)

    raise RuntimeError(f"Redis не поднялся за {timeout_total:.0f}s")

# --- подключаемся (Redis ОПЦИОНАЛЕН: бот обязан стартовать даже без него) ---
# REDIS_REQUIRED=true в .env заставит бота падать без Redis (для окружений,
# где кэш обязателен). По умолчанию Redis необязателен и включается автоматически,
# как только сервис поднят.
REDIS_REQUIRED = _bool_env("REDIS_REQUIRED", False)

_redis_ports = []
for _p in (SELECTED_PORT, 6379, 6380):
    if _p not in _redis_ports:
        _redis_ports.append(_p)


def _autostart_local_redis(host: str, port: int) -> bool:
    """Поднять локальный Redis без ручных действий — кроссплатформенно.

    ВАЖНО: запускаем ТОЛЬКО локальный Redis (host = localhost). Если в .env
    указан удалённый/managed Redis (REDIS_HOST=реальный хост или REDIS_URL),
    мы его НЕ поднимаем — просто подключаемся (см. проверку ниже). Это и есть
    правильное поведение на хостинге с managed Redis.

    Порядок попыток:
      • Windows: redis-server.exe / memurai.exe → Docker → WSL
      • Linux/macOS (VPS/Droplet): systemctl → service → redis-server --daemonize
        → Docker
    Пароль для поднимаемого Redis берётся из RAW_PASSWORD (REDIS_PASSWORD в .env),
    чтобы бот и сервер подключались с теми же кредами. Любой сбой = тихо
    продолжаем: Redis опционален, бот стартует и в fallback-режиме.
    """
    if host not in ("127.0.0.1", "localhost", "::1"):
        return False  # удалённый/managed Redis сами не поднимаем — только connect

    import shutil
    import subprocess

    is_windows = sys.platform == "win32"
    no_window = getattr(subprocess, "CREATE_NO_WINDOW", 0x08000000) if is_windows else 0

    def _run_quiet(cmd, timeout):
        try:
            return subprocess.run(
                cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                timeout=timeout, creationflags=no_window,
            ).returncode == 0
        except Exception:
            return False

    data_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), ".redis")

    def _start_docker() -> bool:
        """Общий фолбэк: Docker (только если демон реально отвечает быстро)."""
        if not (shutil.which("docker") and _run_quiet(["docker", "info"], timeout=2)):
            return False
        if _run_quiet(["docker", "start", "cute-redis"], timeout=6):
            return True
        docker_run = [
            "docker", "run", "-d", "--name", "cute-redis",
            "-p", f"{port}:6379", "--restart", "unless-stopped",
        ]
        if RAW_PASSWORD:
            docker_run += ["redis:8", "redis-server", "--requirepass", RAW_PASSWORD]
        else:
            docker_run.append("redis:7-alpine")
        return _run_quiet(docker_run, timeout=25)

    def _start_windows() -> bool:
        exe = shutil.which("redis-server") or shutil.which("memurai")
        for cand in (
            r"C:\Program Files\Redis\redis-server.exe",
            r"C:\Program Files\Memurai\memurai.exe",
        ):
            if not exe and os.path.isfile(cand):
                exe = cand
        if exe:
            os.makedirs(data_dir, exist_ok=True)
            cmd = [
                exe, "--port", str(port), "--bind", "127.0.0.1",
                "--save", "", "--appendonly", "no", "--dir", data_dir,
            ]
            if RAW_PASSWORD:
                cmd += ["--requirepass", RAW_PASSWORD]
            subprocess.Popen(
                cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                creationflags=no_window,
            )
            return True
        if _start_docker():
            return True
        if shutil.which("wsl"):
            pw = f" --requirepass {RAW_PASSWORD}" if RAW_PASSWORD else ""
            return _run_quiet(
                ["wsl", "-e", "sh", "-c",
                 f"command -v redis-server >/dev/null 2>&1 && "
                 f"redis-server --port {port} --daemonize yes{pw}"],
                timeout=6,
            )
        return False

    def _start_posix() -> bool:
        # 1) Штатный сервис (правильнее всего на сервере): systemctl → service.
        #    Пробуем без прав, затем через sudo -n (без интерактивного пароля).
        if shutil.which("systemctl"):
            for svc in ("redis-server", "redis"):
                if _run_quiet(["systemctl", "start", svc], timeout=8):
                    return True
                if _run_quiet(["sudo", "-n", "systemctl", "start", svc], timeout=8):
                    return True
        if shutil.which("service"):
            for svc in ("redis-server", "redis"):
                if _run_quiet(["service", svc, "start"], timeout=8):
                    return True
                if _run_quiet(["sudo", "-n", "service", svc, "start"], timeout=8):
                    return True
        # 2) Бинарь redis-server в daemonize-режиме (переживёт завершение бота).
        exe = shutil.which("redis-server")
        if exe:
            try:
                os.makedirs(data_dir, exist_ok=True)
            except Exception:
                pass
            cmd = [
                exe, "--port", str(port), "--bind", "127.0.0.1",
                "--daemonize", "yes", "--save", "", "--appendonly", "no",
                "--dir", data_dir,
                "--pidfile", os.path.join(data_dir, "redis.pid"),
                "--logfile", os.path.join(data_dir, "redis.log"),
            ]
            if RAW_PASSWORD:
                cmd += ["--requirepass", RAW_PASSWORD]
            if _run_quiet(cmd, timeout=8):
                return True
        # 3) Docker-фолбэк.
        return _start_docker()

    started = False
    try:
        started = _start_windows() if is_windows else _start_posix()
    except Exception as _e:
        print(f"[Redis][WARN] авто-запуск не удался: {type(_e).__name__}: {_e}")
        return False

    if not started:
        return False

    # Ждём, пока порт реально откроется (redis-server стартует за ~0.3-2s).
    _deadline = time.time() + 10.0
    while time.time() < _deadline:
        if _redis_endpoint_reachable(host, [port]):
            print(f"[Redis][OK] авто-запуск: сервис поднят на {host}:{port}")
            return True
        time.sleep(0.25)
    return False


# Если порт закрыт — один раз пытаемся поднять Redis сами (тихо, best-effort).
if not _redis_endpoint_reachable(SELECTED_HOST, _redis_ports):
    if _autostart_local_redis(SELECTED_HOST, SELECTED_PORT):
        if SELECTED_PORT not in _redis_ports:
            _redis_ports.insert(0, SELECTED_PORT)

rds = None
if _redis_endpoint_reachable(SELECTED_HOST, _redis_ports):
    try:
        # Порт открыт — ждём готовности недолго (PING), а не полные 30s.
        rds = _wait_for_redis_multi(SELECTED_HOST, SELECTED_PORT, timeout_total=8.0)
        print(f"[Redis][OK] connected {SELECTED_HOST}:{SELECTED_PORT}")
    except RuntimeError as _redis_err:
        rds = None
        print(f"[Redis][WARN] {_redis_err} - продолжаю без Redis (snapshot/кэш в fallback).")
else:
    print(
        f"[Redis][WARN] {SELECTED_HOST}:{_redis_ports} недоступен - "
        "бот стартует БЕЗ Redis (игровые снапшоты/кэш работают в fallback-режиме). "
        "Подними Redis и перезапусти бота, чтобы включить кэш."
    )

if REDIS_REQUIRED and rds is None:
    raise RuntimeError(
        "REDIS_REQUIRED=true, но Redis недоступен. "
        f"Проверь Redis на {SELECTED_HOST}:{SELECTED_PORT} (или сними REDIS_REQUIRED)."
    )

