def _format_hms(rem_sec: int) -> str:
    h , rem = divmod(rem_sec , 3600)
    m , s = divmod(rem , 60)
    return f"{h:02d}:{m:02d}:{s:02d}"


def _parse_dt_any(dt_val: Any) -> Optional [ datetime ]:
    if isinstance(dt_val , datetime):
        return dt_val
    if isinstance(dt_val , (int , float)):
        return datetime.fromtimestamp(dt_val)
    if isinstance(dt_val , str):
        try:
            return datetime.strptime(dt_val , "%Y-%m-%d %H:%M:%S")
        except ValueError:
            try:
                return datetime.fromisoformat(dt_val)
            except Exception:
                return None
    return None


async def _get_times_compat(db , u: int , v: int):
    # Поддержка обеих сигнатур: get_ref_times(u, v) и старой get_ref_times(u)
    try:
        return await db.get_ref_times(u , v)
    except TypeError:
        return await db.get_ref_times(u)


async def _pair_seconds_left(db , a: int , b: int , now: Optional [ datetime ] = None) -> int:
    """
    Возвращает, сколько секунд осталось до конца блокировки между пользователями a и b.
    Проверяет запись как (a,b), если нет - пробует (b,a). 0 => активной блокировки нет.
    """
    if now is None:
        now = datetime.now()

    # Сначала (a, b)
    _ , data_open = await _get_times_compat(db , a , b)
    if data_open is None:
        # Пробуем (b, a)
        _ , data_open = await _get_times_compat(db , b , a)
        if data_open is None:
            return 0

    data_open_dt = _parse_dt_any(data_open)
    if data_open_dt is None:
        return 0

    # Сравниваем во "временной зоне" data_open_dt (если она есть)
    now_local = datetime.now(data_open_dt.tzinfo) if data_open_dt.tzinfo else now

    if now_local < data_open_dt:
        return int((data_open_dt - now_local).total_seconds())
    return 0











