async def check_user_bio_for_bot(user_id: int, bio: Optional[str] = None) -> bool:
    """
    Проверяет, содержит ли BIO пользователя упоминание бота и фразу вида:
    «@CuteGamingBot – Элитный игровой бот на звезды/звёзды».

    Требования:
    - Упоминание бота (@cutegamingbot или t.me/cutegamingbot)
    - Фраза про «элитный игровой бот»
    - Наличие «на звезды/звёзды» (устойчиво к ё/е, тире, эмодзи, пробелам)
    """

    # 1. Берём BIO либо из аргумента, либо из БД
    if bio is None:
        bio = await db.get_user_bio(user_id)

    print("check_user_bio_for_bot: raw user_bio =", repr(bio))

    if not bio or not isinstance(bio, str):
        return False

    # 2. Нормализация юникода, регистра, ё→е
    normalized = unicodedata.normalize("NFKC", bio)
    normalized = normalized.lower().replace("ё", "е")

    # Приводим разные тире к одному виду и чистим пробелы
    normalized = normalized.replace("–", "-").replace("-", "-")
    normalized = re.sub(r"\s+", " ", normalized).strip()

    # Вариант без пробелов/знаков препинания/эмодзи:
    # "на звезды!" -> "назвезды", "на-звезды" -> "назвезды"
    compact = re.sub(r"[^a-zа-я0-9]+", "", normalized)

    print("check_user_bio_for_bot: normalized =", repr(normalized))
    print("check_user_bio_for_bot: compact    =", repr(compact))

    # 3. Упоминание бота (@ или ссылка)
    has_bot_handle = (
        "@cutegamingbot" in normalized
        or "t.me/cutegamingbot" in normalized
    )

    # 4. Фраза про «элитный игровой бот» (и точная, и по корням)
    has_elite_exact = "элитный игровой бот" in normalized
    has_elite_loose = (
        "элитн" in normalized and   # элитн…
        "игров" in normalized and   # игров…
        "бот" in normalized         # бот
    )
    has_elite_phrase = has_elite_exact or has_elite_loose

    # 5. Фраза «на звезды/звёзды»:
    #   normalized: ловим обычные фразы с пробелами
    #   compact:   ловим всё слепленное «назвезды», «назвезды!!!» и т.п.
    has_stars_normal = (
        "на звезд" in normalized or  # "на звезды", "на звезду", "на звезд!"
        "на звезды" in normalized    # явный полный вариант
    )

    has_stars_compact = (
        "назвезд" in compact or
        "назвезды" in compact
    )

    has_stars = has_stars_normal or has_stars_compact

    result = bool(has_bot_handle and has_elite_phrase and has_stars)
    print("check_user_bio_for_bot: result =", result)

    return result


NAMECHECK_DEBUG = True  # включи/выключи отдельно от BONUS_DEBUG


def _n_dbg(*args):
    if NAMECHECK_DEBUG:
        print("[NAMECHECK]", *args)


def _norm_text(s: str) -> str:
    # NFKC + lower
    return unicodedata.normalize("NFKC", s).lower().strip()


def _compact_text(s: str) -> str:
    # оставляем только буквы/цифры (лат/кирилл)
    s = _norm_text(s)
    return re.sub(r"[^a-zа-я0-9]+", "", s)


def _split_full_name(full: str) -> Tuple[Optional[str], Optional[str]]:
    """
    Аккуратно делим "Имя Фамилия" на две части.
    Если одно слово - считаем, что это first_name.
    """
    if not full:
        return None, None
    full = " ".join(full.split()).strip()
    if not full:
        return None, None
    parts = full.split(" ")
    if len(parts) == 1:
        return parts[0], None
    # если слов много - first = первое, last = остальное
    return parts[0], " ".join(parts[1:])


NAMECHECK_DEBUG = True  # включить/выключить print


def _n_dbg(msg: str) -> None:
    if NAMECHECK_DEBUG:
        print(f"[NAMECHECK] {msg}")


def _clean_part(x: Optional[str]) -> str:
    """Почистить часть имени: None -> '', убрать лишние пробелы."""
    if x is None:
        return ""
    s = str(x).strip()
    # иногда прилетают странные нулевые/пустые
    return s


def _split_full_name(full: str) -> Tuple[Optional[str], Optional[str]]:
    """
    Делит "Имя Фамилия ..." -> (first, last)
    - first: первое слово
    - last: всё остальное (или None)
    """
    s = _clean_part(full)
    if not s:
        return None, None
    parts = [p for p in s.split() if p]
    if not parts:
        return None, None
    if len(parts) == 1:
        return parts[0], None
    return parts[0], " ".join(parts[1:])


def _norm_text(s: str) -> str:
    """
    Нормализация для поиска:
    - NFKC
    - lower
    - схлопываем пробелы
    """
    s = _clean_part(s)
    if not s:
        return ""
    s = unicodedata.normalize("NFKC", s).lower()
    s = re.sub(r"\s+", " ", s).strip()
    return s


def _compact_text(s: str) -> str:
    """
    Компактная строка:
    - NFKC + lower
    - оставляем только буквы/цифры (лат/кириллица)
    """
    s = _clean_part(s)
    if not s:
        return ""
    s = unicodedata.normalize("NFKC", s).lower()
    # оставляем a-z, а-я, 0-9
    s = re.sub(r"[^a-zа-я0-9]+", "", s)
    return s


async def _get_names_from_db(uid: int) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    """
    Пытается достать из БД:
    - (first_name, last_name) через get_user_names_by_user_id
    - или full_name через get_name_by_user_id (fallback)
    Возвращает: (db_first, db_last, db_full)
    """
    db_first = None
    db_last = None
    db_full = None

    # 1) новый метод: (first,last) или Record
    try:
        res = await db.get_user_names_by_user_id(uid)

        if isinstance(res, (tuple, list)) and len(res) >= 2:
            db_first, db_last = res[0], res[1]
        else:
            # asyncpg.Record или объект с атрибутами
            if res is not None:
                db_first = getattr(res, "first_name", None) or getattr(res, "firstname", None)
                db_last = getattr(res, "last_name", None) or getattr(res, "lastname", None)

        return db_first, db_last, db_full

    except AttributeError:
        # 2) fallback: старый метод, одна строка
        try:
            db_full = await db.get_name_by_user_id(uid)
        except Exception as e:
            _n_dbg(f"DB fallback error uid={uid}: {type(e).__name__}: {e}")
            db_full = None

        f, l = _split_full_name(str(db_full) if db_full else "")
        return f, l, db_full

    except Exception as e:
        _n_dbg(f"DB error uid={uid}: {type(e).__name__}: {e}")
        return None, None, None


async def check_user_name_for_bot(
    user_id: int,
    first_name: Optional[str] = None,
    last_name: Optional[str] = None,
) -> bool:
    """
    ✅ Проверяет first_name + last_name (или берет из БД) на наличие ключевых слов.
    username НЕ используется.

    Возвращает True/False строго и предсказуемо.
    """
    uid = int(user_id)

    # 1) берём из аргументов, но только если реально не пустые
    fn = _clean_part(first_name)
    ln = _clean_part(last_name)

    parts = []
    if fn:
        parts.append(fn)
    if ln:
        parts.append(ln)

    db_first = db_last = db_full = None

    # 2) если в аргументах пусто - идём в БД
    if not parts:
        db_first, db_last, db_full = await _get_names_from_db(uid)

        db_first = _clean_part(db_first)
        db_last = _clean_part(db_last)

        if db_first:
            parts.append(db_first)
        if db_last:
            parts.append(db_last)

    raw_full_name = " ".join([p for p in parts if p]).strip()

    # 3) если всё равно пусто - False
    if not raw_full_name:
        _n_dbg(
            f"uid={uid} -> ПУСТОЕ ИМЯ | "
            f"args_first={first_name!r} args_last={last_name!r} | "
            f"db_first={db_first!r} db_last={db_last!r} db_full={db_full!r}"
        )
        return False

    normalized = _norm_text(raw_full_name)
    compact = _compact_text(raw_full_name)

    # 4) ключевые слова
    base_keywords = [
        "CuteGamingBot",
        "Cute",
        "Кут",
        "Кут топ",
        "Крутой кут",
        "Кут крутой",
    ]

    # 5) debug
    _n_dbg(f"uid={uid} raw_full_name={raw_full_name!r}")
    _n_dbg(f"uid={uid} normalized={normalized!r}")
    _n_dbg(f"uid={uid} compact={compact!r}")
    _n_dbg(f"uid={uid} db_first={db_first!r} db_last={db_last!r} db_full={db_full!r}")

    # 6) проверяем
    for kw in base_keywords:
        kw_norm = _norm_text(kw)
        kw_comp = _compact_text(kw)

        if kw_norm and kw_norm in normalized:
            _n_dbg(f"uid={uid} MATCH normalized kw={kw!r}")
            return True

        if kw_comp and kw_comp in compact:
            _n_dbg(f"uid={uid} MATCH compact kw={kw!r}")
            return True

    # 7) доп. подстроки
    for sub in ("cute", "кут"):
        if sub in normalized or sub in compact:
            _n_dbg(f"uid={uid} MATCH extra sub={sub!r}")
            return True

    _n_dbg(f"uid={uid} -> NO MATCH")
    return False




