def find_top_referrers(db):
    data = db.get_user_referrals()

    # Словарь с количеством приглашений
    user_referrals = {item [ 0 ]: item [ 1 ] for item in data if len(item) >= 2 and item [ 1 ] is not None}

    # Сортируем пользователей по количеству приглашений (убывание)
    sorted_users = sorted(user_referrals.items() , key=lambda x: x [ 1 ] , reverse=True)

    # Получаем идентификаторы пользователей на 1, 2 и 3 местах
    top_users = {}
    for rank , (user_id , referrals) in enumerate(sorted_users [ :3 ] , start=1):
        top_users [ rank ] = {'user_id': user_id , 'referrals': referrals ,
            'referrals_formatted': locale.format_string("%d" , referrals , grouping=True).replace("," , ".")}

    return top_users


