CHATHI_ON = 1

@dp.message(F.new_chat_members)
async def on_user_join_message(message: Message):
    # 0) только группы
    if message.chat.type not in (ChatType.GROUP, ChatType.SUPERGROUP):
        return

    chat_id = int(message.chat.id)

    # 1) заранее читаем флаг приветствия ОДИН раз на событие (а не на каждого юзера)
