def get_declension(number, form1, form2, form5):
    """Возвращает правильное склонение слова."""
    if 10 <= number % 100 <= 20:
        return form5
    elif number % 10 == 1:
        return form1
    elif 2 <= number % 10 <= 4:
        return form2
    else:
        return form5

