async def measure_time(coro, description):
    """Измеряет время выполнения асинхронной функции."""
    if not globals().get("DEBUG_VERBOSE", False):
        return await coro
    start = time.perf_counter()
    result = await coro
    elapsed = time.perf_counter() - start
    print(f"{description}: {elapsed:.4f} сек")
    return result


def _vdbg(*args, **kwargs):
    """Отладочный print, включается флагом DEBUG_VERBOSE в config.py."""
    if globals().get("DEBUG_VERBOSE", False):
        print(*args, **kwargs)


