async def inline_add_or_update_user_info(bot1, user_id, first_name, username, db, start_balance):
    """
    Добавляет или обновляет информацию о пользователе в словаре user_cache и базе данных.

    :param bot1: Экземпляр бота для взаимодействия с Telegram API
    :param user_id: ID пользователя
    :param first_name: Имя пользователя
    :param username: Username пользователя
    :param db: Экземпляр базы данных
    :param start_balance: Начальный баланс пользователя
    """
    # Очистка first_name от потенциально опасных символов
    first_name = re.sub(r'[<>/{}"]', '', first_name) if first_name else "Неизвестный"
    username = username or ""

    # ВАЖНО: раньше здесь был "if not user_cache: <полная синхронная загрузка
    # всех пользователей из БД одним циклом без await внутри>". user_cache -
    # обычный dict в памяти процесса, пустой после каждого рестарта бота.
    # Любой первый inline-колбэк (крестики-нолики, память и т.д.) после
    # рестарта попадал сюда и запускал for-цикл на 200 000+ строк БЕЗ единого
    # await внутри - это блокировало ЕДИНСТВЕННЫЙ event loop бота целиком на
    # несколько МИНУТ (см. инцидент 2026-07-16: "STALL" + "Уже загружено
    # N пользователей..." тянулось больше 4 минут, бот не отвечал никому).
    # Убрано целиком: код ниже (строки с db.add_data/user_cache[user_id]=...)
    # и так корректно добавляет/обновляет ОДНОГО конкретного user_id - кэш
    # просто наполняется постепенно, по одному пользователю за раз, вместо
    # одного катастрофического залпового реюда.

    # ВАЖНО (перф инлайн-кнопок): раньше здесь БЕЗУСЛОВНО вызывался
    # bot1.get_chat(user_id) - сетевой запрос к Telegram (73-380мс по логам
    # TG-API) на КАЖДЫЙ инлайн-колбэк, причём ДО callback_query.answer().
    # Эта функция дёргается из _sync_inline_user в начале всех инлайн-игр
    # (крестики-нолики, кнб, мины, память, шашки, дуэль, орёл) - отсюда и
    # тормоза кнопок в играх 1 на 1. Для команд ту же проблему уже починили
    # кэшем vgs_get_bio_safe (см. комментарий у _VGS_BIO_CACHE), инлайн-путь
    # просто забыли. Теперь:
    #   1) если юзер в кэше и имя/username не изменились - писать нечего,
    #      значит и bio запрашивать незачем → 0 сетевых вызовов, мгновенно;
    #   2) в остальных случаях bio берём через кэш с TTL, а не сырым get_chat.
    cached = user_cache.get(user_id)
    if (
        cached is not None
        and cached.get('first_name') == first_name
        and cached.get('username') == username
    ):
        return

    bio = await vgs_get_bio_safe(
        bot1, user_id, fallback=(cached or {}).get('bio') or "Пусто"
    )

    # Если пользователя нет в user_cache, добавляем его
    if cached is None:
        try:
            await db.add_data(user_id, first_name, username, bio, start_balance)
            user_cache[user_id] = {
                'first_name': first_name,
                'username': username,
                'bio': bio
            }
            if user_id not in user_cache_balance:
                print(f"💰 Инлайн Пользователь {user_id} не найден в кэше. Добавляем в кэш...")
                # Если пользователя нет в кэше, добавляем его
                user_cache_balance [ user_id ] = start_balance
                print(f"💰 Инлайн Информация о пользователе {user_id} добавлена в кэш с балансом {start_balance}.")
            print("✅ Пользователь добавлен в базу данных и user_cache.")
        except Exception as e:
            print(f"❌ Ошибка добавления пользователя: {e}")
            return
    else:
        # Проверяем необходимость обновления данных
        current_data = user_cache[user_id]
        updates = {}

        if current_data['first_name'] != first_name:
            updates['first_name'] = first_name
        if current_data['username'] != username:
            updates['username'] = username
        if current_data['bio'] != bio:
            updates['bio'] = bio

        if updates:
            try:
                await db.user_update_fields(user_id, updates)
                user_cache[user_id].update(updates)
                print(f"✅ Данные пользователя обновлены: {updates}")
            except Exception as e:
                print(f"❌ Ошибка при обновлении данных: {e}")
        else:
            print("✅ Обновление не требуется, данные совпадают.")

async def add_info_in_user_cache(message , db , start_balance):
    if not user_cache:
        try:
            print("😈 user_cache пуст - начинаю загрузку пользователей из базы...")

            start_time = time.time()
            users_from_db = await db.fetch_all(
                "SELECT user_id, first_name, username, bio FROM users")

            total = len(users_from_db)
            print(f"📥 Получено {total} пользователей из базы.")

            loaded = 0
            for user in users_from_db:
                user_cache [ user [ "user_id" ] ] = {"first_name": user.get("first_name") or "" ,
                    "username": user.get("username") or "" , "bio": user.get("bio") or "" , }
                loaded += 1

                if loaded % 10000 == 0:
                    print(f"➡️ Загружено {loaded} пользователей...")

            elapsed = time.time() - start_time
            print(
                f"✅ Загрузка завершена за {elapsed:.2f} сек. "
                f"Всего записей в user_cache: {len(user_cache)}")

            # Покажем примеры первых 3 записей
            for uid in list(user_cache.keys()) [ :3 ]:
                print(f"👤 user_id={uid}, данные={user_cache [ uid ]}")

        except Exception as e:
            print(f"❌ Ошибка при загрузке пользователей: {e}")

