# ============================================================
# НАСТРОЙКИ
# ============================================================
VGS_DEBUG = True
VGS_DEBUG_LEVEL = 0          # 0=off, 1=important, 2=details, 3=trace

VGS_DATE_FORMAT = "%Y-%m-%d %H:%M:%S.%f"

VGS_TG_TIMEOUT = 2.0          # Telegram API
VGS_DB_TIMEOUT = 2.5          # обычные запросы к БД
VGS_DB_BULK_TIMEOUT = 10.0    # для массовых выборок (прогрев)
VGS_SEND_TIMEOUT = 2.5

VGS_RETRIES = 2
VGS_RETRY_BASE_DELAY = 0.15

# ============================================================
# ГЛОБАЛЬНЫЕ КЭШИ
# ============================================================
VGS_USER_CACHE: Dict[int, Dict[str, Any]] = LazyGameStore("VGS_USER_CACHE")           # user_id -> {first_name, username, bio, reg_date}

VGS_PENDING_UPDATES: Dict[int, Dict[str, Any]] = LazyGameStore("VGS_PENDING_UPDATES")
VGS_PENDING_LOCK = asyncio.Lock()

# asyncio.Lock нельзя хранить в LazyGameStore/Redis: после рестарта или при
# десериализации лок может остаться «захваченным» и навсегда блокировать
# обработку сообщений конкретного пользователя (симптом: handler доходит до
# balance, но дальше «тишина»).
VGS_USER_LOCKS: Dict[int, asyncio.Lock] = {}
VGS_USER_LOCKS_LOCK = asyncio.Lock()
VGS_USER_LOCK_TIMEOUT_SEC = 20.0

VGS_META_KEY = "__vgs_meta__"
VGS_WARMUP_LOCK = asyncio.Lock()
# Прогрев кэша юзеров — ФОНОВЫЙ и низкоприоритетный. На 1 общем vCPU агрессивный
# прогрев (0.9с работы / 0.15с отдыха ≈ 86% ядра) захватывал CPU/GIL и подвешивал
# event-loop рябью ~0.6–0.9с. Делаем короткую работу и длинный отдых, чтобы почти
# всё ядро оставалось циклу — команды отвечают за десятки мс. Прогрев чуть дольше
# по времени, но пользователю незаметен. Тюнится через env.
VGS_WARMUP_BATCH = int(os.getenv("VGS_WARMUP_BATCH", "3000"))
VGS_WARMUP_SLEEP = float(os.getenv("VGS_WARMUP_SLEEP", "1.0"))
VGS_WARMUP_TIME_BUDGET = float(os.getenv("VGS_WARMUP_TIME_BUDGET", "0.2"))
# Фоновый прогрев всех 240k юзеров ВЫКЛЮЧЕН по умолчанию: кэш наполняется лениво
# по первому обращению каждого юзера. Это убирает фоновую CPU-нагрузку (особенно
# после каждого рестарта, т.к. Redis эфемерный). Включить: VGS_WARMUP_ENABLED=1.
VGS_WARMUP_ENABLED = bool(int(os.getenv("VGS_WARMUP_ENABLED", "0")))

# ============================================================
# ЛЁГКАЯ ОТЛАДКА (почти не тратит ресурсы при level=0)
# ============================================================
def _vgs_ts() -> str:
    return datetime.now().strftime("%d.%m.%Y %H:%M:%S") if VGS_DEBUG_LEVEL > 0 else ""

def _vgs_dbg(tag: str, msg: str, level: int = 1, uid: Optional[int] = None):
    if VGS_DEBUG and VGS_DEBUG_LEVEL >= level:
        prefix = f"[{_vgs_ts()}][VGS][{tag}]"
        if uid is not None:
            prefix += f"[uid={uid}]"
        print(f"{prefix} {msg}")

def _vgs_err(tag: str, msg: str, e: Exception, uid: Optional[int] = None, level: int = 1):
    if VGS_DEBUG and VGS_DEBUG_LEVEL >= level:
        _vgs_dbg(tag, f"❌ {msg} | {type(e).__name__}: {e}", level=level, uid=uid)
        if VGS_DEBUG_LEVEL >= 3:
            _vgs_dbg(tag, f"TRACEBACK:\n{traceback.format_exc()}", level=3, uid=uid)

# ============================================================
# ДАТЫ (быстрые, без отладки)
# ============================================================
def vgs_now_str() -> str:
    return datetime.now().strftime(VGS_DATE_FORMAT)

def vgs_parse_dt(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value
    if isinstance(value, str):
        try:
            return datetime.strptime(value, VGS_DATE_FORMAT)
        except Exception:
            pass
        try:
            return datetime.fromisoformat(value)
        except Exception:
            return None
    return None

def vgs_to_str(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.strftime(VGS_DATE_FORMAT)
    if isinstance(value, str):
        return value
    return None

# ============================================================
# META / WARMUP
# ============================================================
def _vgs_get_meta(user_cache: dict) -> dict:
    try:
        meta = user_cache.get(VGS_META_KEY)
        if not isinstance(meta, dict):
            meta = {}
            user_cache[VGS_META_KEY] = meta
        return meta
    except Exception:
        return {}

def _vgs_is_real_user_key(k) -> bool:
    return isinstance(k, int)

def _vgs_has_any_real_users(user_cache: dict) -> bool:
    return any(_vgs_is_real_user_key(k) for k in user_cache.keys())

# ============================================================
# НАДЁЖНЫЙ ВЫЗОВ (с таймаутом и ретраями, только когда нужно)
# ============================================================
def _vgs_is_transient(e: Exception) -> bool:
    if isinstance(e, (asyncio.TimeoutError, TimeoutError)):
        return True
    # если используется asyncpg
    try:
        import asyncpg
        if isinstance(e, asyncpg.InterfaceError):
            return True
    except ImportError:
        pass
    t = (str(e) or "").lower()
    return any(x in t for x in [
        "timeout", "timed out", "connection", "reset", "broken pipe",
        "server closed", "temporar", "try again", "pool"
    ])

async def vgs_call(coro_factory, *, timeout: float, tries: int = VGS_RETRIES, base_delay: float = VGS_RETRY_BASE_DELAY):
    """Вызов с таймаутом и автоматическим ретраем transient-ошибок."""
    last = None
    for attempt in range(1, tries + 1):
        try:
            return await asyncio.wait_for(coro_factory(), timeout=timeout)
        except asyncio.TimeoutError as e:
            last = e
            _vgs_dbg("CALL", f"attempt {attempt}/{tries} timed out", level=2)
        except Exception as e:
            last = e
            if not _vgs_is_transient(e):
                raise   # невременная ошибка – сразу наружу
            _vgs_dbg("CALL", f"attempt {attempt}/{tries} transient error: {type(e).__name__}", level=2)
        if attempt >= tries:
            break
        delay = base_delay * (2 ** (attempt - 1)) + random.random() * 0.05
        await asyncio.sleep(delay)
    raise last

# ============================================================
# DB WRAPPERS + PENDING QUEUE
# ============================================================
async def vgs_db_fetch_all(db, sql: str, params=None, *, timeout: float = VGS_DB_TIMEOUT, default=None, uid: Optional[int] = None):
    """Безопасная выборка с fallback-значением."""
    if default is None:
        default = []
    try:
        if params is None:
            return await vgs_call(lambda: db.fetch_all(sql), timeout=timeout)
        return await vgs_call(lambda: db.fetch_all(sql, params=params), timeout=timeout)
    except Exception as e:
        _vgs_err("DB", f"fetch_all failed → using default", e, uid=uid, level=2)
        return default

async def vgs_db_update_fields(db, user_id: int, fields: dict):
    """Прямая запись в БД, при неудаче – ставим в pending."""
    try:
        return await vgs_call(lambda: db.user_update_fields(user_id, fields), timeout=VGS_DB_TIMEOUT)
    except Exception as e:
        _vgs_err("DB", "update_fields failed → enqueue pending", e, uid=user_id, level=1)
        await vgs_enqueue_pending(user_id, fields)
        return None

async def vgs_enqueue_pending(user_id: int, fields: dict):
    """Добавляет изменения в отложенную очередь (план Б)."""
    async with VGS_PENDING_LOCK:
        cur = VGS_PENDING_UPDATES.get(user_id) or {}
        cur.update(fields)
        VGS_PENDING_UPDATES[user_id] = cur

async def vgs_pending_flusher(db, interval: float = 2.0):
    """Фоновый флешер очереди отложенных обновлений."""
    while True:
        await asyncio.sleep(interval)
        async with VGS_PENDING_LOCK:
            items = list(VGS_PENDING_UPDATES.items())
        for uid, fields in items:
            try:
                await vgs_call(lambda: db.user_update_fields(uid, fields), timeout=VGS_DB_TIMEOUT)
                async with VGS_PENDING_LOCK:
                    VGS_PENDING_UPDATES.pop(uid, None)
                _vgs_dbg("PENDING", f"flush OK uid={uid}", level=2, uid=uid)
            except Exception:
                pass   # останется в очереди до следующего цикла

# ============================================================
# TG wrappers
# ============================================================
# Кэш bio/get_chat по user_id. get_chat — сетевой вызов к Telegram (~150–330мс)
# и раньше делался на КАЖДУЮ команду (баланс/профиль). bio меняется редко,
# поэтому кэшируем на VGS_BIO_CACHE_TTL — команды перестают ждать Telegram.
_VGS_BIO_CACHE: Dict[int, tuple] = {}
VGS_BIO_CACHE_TTL = float(os.getenv("VGS_BIO_CACHE_TTL", "600"))  # сек

async def vgs_get_bio_safe(bot, user_id: int, fallback: str = "Пусто") -> str:
    now = time.time()
    hit = _VGS_BIO_CACHE.get(user_id)
    if hit is not None and (now - hit[1]) < VGS_BIO_CACHE_TTL:
        return hit[0] or fallback
    try:
        chat = await vgs_call(lambda: bot.get_chat(user_id), timeout=VGS_TG_TIMEOUT)
        bio = getattr(chat, "bio", None)
        _VGS_BIO_CACHE[user_id] = (bio, now)
        return bio or fallback
    except Exception as e:
        _vgs_err("BIO", "get_chat failed → fallback", e, uid=user_id, level=2)
        return fallback

async def vgs_send_safe(send_coro_factory, *, uid: Optional[int] = None):
    try:
        return await vgs_call(send_coro_factory, timeout=VGS_SEND_TIMEOUT)
    except Exception as e:
        _vgs_err("SEND", "send failed", e, uid=uid, level=1)
        return None

# ============================================================
# LOCKS PER USER
# ============================================================
async def vgs_get_user_lock(user_id: int) -> asyncio.Lock:
    async with VGS_USER_LOCKS_LOCK:
        lock = VGS_USER_LOCKS.get(user_id)
        if lock is None:
            lock = asyncio.Lock()
            VGS_USER_LOCKS[user_id] = lock
        return lock


async def vgs_acquire_user_lock(user_id: int, *, timeout: float = VGS_USER_LOCK_TIMEOUT_SEC) -> asyncio.Lock:
    """Захватывает per-user лок с таймаутом.

    Если предыдущая обработка зависла и не отпустила лок - создаём новый,
    чтобы бот не переставал отвечать на сообщения этого пользователя.
    """
    lock = await vgs_get_user_lock(user_id)
    try:
        await asyncio.wait_for(lock.acquire(), timeout=timeout)
        return lock
    except asyncio.TimeoutError:
        _vgs_err(
            "LOCK",
            f"user lock timeout ({timeout}s) - replacing stale lock",
            None,
            uid=int(user_id),
            level=1,
        )
        async with VGS_USER_LOCKS_LOCK:
            lock = asyncio.Lock()
            VGS_USER_LOCKS[int(user_id)] = lock
        await lock.acquire()
        return lock

# ============================================================
# WARMUP BACKGROUND (не блокирует обработку)
# ============================================================
async def _vgs_warmup_user_cache_background(db, user_cache: dict):
    _vgs_dbg("WARMUP", "🚀 background warmup start", level=1)
    meta = _vgs_get_meta(user_cache)
    try:
        last_uid = int(meta.get("warmup_last_uid") or 0)
    except Exception:
        last_uid = 0

    while True:
        if _vgs_has_any_real_users(user_cache):
            meta["warmup_done"] = True
            meta["warmup_started"] = True
            meta["warmup_last_uid"] = last_uid
            _vgs_dbg("WARMUP", f"stop: cache already has users ({len(user_cache)})", level=1)
            return

        start_tick = time.time()
        loaded_tick = 0

        while (time.time() - start_tick) < VGS_WARMUP_TIME_BUDGET:
            sql = (
                "SELECT user_id, first_name, username, bio, data "
                "FROM users "
                "WHERE user_id > $1 "
                "ORDER BY user_id "
                "LIMIT $2"
            )
            rows = await vgs_db_fetch_all(db, sql,
                                          params=[last_uid, VGS_WARMUP_BATCH],
                                          timeout=VGS_DB_BULK_TIMEOUT,
                                          default=[])
            if not rows:
                meta["warmup_done"] = True
                meta["warmup_started"] = True
                meta["warmup_last_uid"] = last_uid
                _vgs_dbg("WARMUP", f"done: cache={len(user_cache)}", level=1)
                return

            # Построение батча (strftime по тысячам строк — CPU) И запись в
            # pklcode-стор (синхронный Redis-I/O) выполняем ЦЕЛИКОМ в отдельном
            # потоке. Иначе даже чистый CPU-цикл strftime блокировал event-loop
            # на ~0.8с за батч (см. watchdog-стек vgs_to_str→strftime). В потоке
            # GIL переключается каждые ~5мс, и цикл остаётся отзывчивым.
            def _build_and_store(rows, start_last):
                local_last = start_last
                batch = {}
                for row in rows:
                    uid = row.get("user_id") if hasattr(row, "get") else row["user_id"]
                    reg_raw = row.get("data") if hasattr(row, "get") else row["data"]
                    reg_str = vgs_to_str(reg_raw)
                    batch[uid] = {
                        "first_name": (row.get("first_name") if hasattr(row, "get") else row["first_name"]) or "",
                        "username": (row.get("username") if hasattr(row, "get") else row["username"]) or "",
                        "bio": (row.get("bio") if hasattr(row, "get") else row["bio"]) or "",
                        "reg_date": reg_str,
                    }
                    local_last = uid
                if batch:
                    user_cache.bulk_load(batch)
                return local_last, len(batch)

            last_uid, added = await asyncio.to_thread(_build_and_store, rows, last_uid)
            loaded_tick += added
            meta["warmup_last_uid"] = last_uid

        if loaded_tick:
            _vgs_dbg("WARMUP", f"tick loaded={loaded_tick} cache={len(user_cache)}", level=2)
        await asyncio.sleep(VGS_WARMUP_SLEEP)

def vgs_ensure_warmup_started(db, user_cache: dict):
    meta = _vgs_get_meta(user_cache)
    if meta.get("warmup_started"):
        return

    async def _start():
        async with VGS_WARMUP_LOCK:
            meta2 = _vgs_get_meta(user_cache)
            if meta2.get("warmup_started"):
                return
            meta2["warmup_started"] = True
            asyncio.create_task(_vgs_warmup_user_cache_background(db, user_cache))

    asyncio.create_task(_start())

# ============================================================
# ОСНОВНАЯ ФУНКЦИЯ (с планом Б на каждом шагу)
# ============================================================
async def add_or_update_user_info(message, db, start_balance, *, bot):
    """
    Обрабатывает информацию о пользователе.
    План Б: при недоступности БД работаем через кэш и pending-очередь.
    """
    user_id = getattr(getattr(message, "from_user", None), "id", None)
    if not user_id:
        return
    user_id = int(user_id)
    lock = await vgs_acquire_user_lock(user_id)

    try:
        # ── TG data ──
        fu = message.from_user
        first_name_raw = getattr(fu, "first_name", "") or ""
        last_name_raw = getattr(fu, "last_name", "") or ""
        username = getattr(fu, "username", "") or ""

        try:
            first_name_clean = re.sub(r'[<>/{}\\"]', "", first_name_raw)
            last_name_clean = re.sub(r'[<>/{}\\"]', "", last_name_raw)
            first_name = f"{first_name_clean} {last_name_clean}".strip() if (first_name_clean or last_name_clean) else "Неизвестный"
        except Exception:
            first_name = (first_name_raw or "Неизвестный").strip() or "Неизвестный"

        # ── warmup (незаметно) ──
        if VGS_WARMUP_ENABLED:
            vgs_ensure_warmup_started(db, VGS_USER_CACHE)

        # ── bio ──
        fallback_bio = (VGS_USER_CACHE.get(user_id, {}) or {}).get("bio") or "Пусто"
        bio = await vgs_get_bio_safe(bot, user_id, fallback=fallback_bio)

        # ── Проверка существования (лёгкий запрос) ──
        exists_rows = await vgs_db_fetch_all(db,
            "SELECT 1 FROM users WHERE user_id = $1",
            params=[user_id],
            default=[]   # при ошибке БД считаем, что не существует → пойдём в создание
        )
        user_exists = bool(exists_rows)

        if not user_exists:
            # ---- НОВЫЙ ПОЛЬЗОВАТЕЛЬ ----
            reg_date_str = vgs_now_str()
            reg_date_dt = vgs_parse_dt(reg_date_str) or datetime.now()

            # План А: прямая вставка в БД
            try:
                await vgs_call(
                    lambda: db.add_data(user_id, first_name, username, bio, start_balance),
                    timeout=VGS_DB_TIMEOUT
                )
            except Exception as e:
                _vgs_err("NEW", "db.add_data failed → using cache+ pending", e, uid=user_id)
                # План Б: кладём в кэш и в pending (флешер попробует позже)
                pass

            # Обновляем кэш в любом случае
            current = {
                "first_name": first_name,
                "username": username,
                "bio": bio,
                "reg_date": reg_date_str,
            }
            VGS_USER_CACHE[user_id] = current

            # Пробуем записать точную data
            try:
                await vgs_db_update_fields(db, user_id, {"data": reg_date_dt})
            except Exception:
                # уже в pending через update_fields
                pass

            return

        # ---- СУЩЕСТВУЮЩИЙ ПОЛЬЗОВАТЕЛЬ ----
        current = VGS_USER_CACHE.get(user_id)
        if not isinstance(current, dict) or "first_name" not in current:
            # Загружаем из БД (или берём пустышку, если БД недоступна)
            fetch_rows = await vgs_db_fetch_all(db,
                "SELECT first_name, username, bio, data FROM users WHERE user_id = $1",
                params=[user_id],
                default=[]
            )
            if fetch_rows:
                row = fetch_rows[0]
                reg_raw = row.get("data") if hasattr(row, "get") else row["data"]
                current = {
                    "first_name": (row.get("first_name") if hasattr(row, "get") else row["first_name"]) or "",
                    "username": (row.get("username") if hasattr(row, "get") else row["username"]) or "",
                    "bio": (row.get("bio") if hasattr(row, "get") else row["bio"]) or "",
                    "reg_date": vgs_to_str(reg_raw),
                }
                VGS_USER_CACHE[user_id] = current
            else:
                # Защита от гонки: если в БД нет (а раньше было) – возможно, удалили; пробуем пересоздать
                return await add_or_update_user_info(message, db, start_balance, bot=bot)

        # ── Синхронизация reg_date ──
        try:
            data_row = await vgs_db_fetch_all(db,
                "SELECT data FROM users WHERE user_id = $1",
                params=[user_id],
                default=[]
            )
            if data_row:
                reg_raw = data_row[0].get("data") if hasattr(data_row[0], "get") else data_row[0]["data"]
                db_reg_dt = vgs_parse_dt(reg_raw)
                cache_reg_dt = vgs_parse_dt(current.get("reg_date"))

                final_dt = None
                need_update_db = False

                if cache_reg_dt and db_reg_dt:
                    final_dt = cache_reg_dt if cache_reg_dt <= db_reg_dt else db_reg_dt
                    if db_reg_dt != final_dt:
                        need_update_db = True
                elif cache_reg_dt and not db_reg_dt:
                    final_dt = cache_reg_dt
                    need_update_db = True
                elif db_reg_dt and not cache_reg_dt:
                    final_dt = db_reg_dt
                else:
                    final_dt = datetime.now()
                    need_update_db = True

                final_str = vgs_to_str(final_dt)
                if final_str and current.get("reg_date") != final_str:
                    current["reg_date"] = final_str
                    VGS_USER_CACHE[user_id] = current

                if need_update_db and final_dt:
                    await vgs_db_update_fields(db, user_id, {"data": final_dt})
        except Exception:
            pass   # не критично, в pending не пишем

        # ── Обновление изменившихся полей ──
        updates = {}
        if current.get("first_name") != first_name:
            updates["first_name"] = first_name
        if current.get("username") != username:
            updates["username"] = username
        if current.get("bio") != bio:
            updates["bio"] = bio

        if updates:
            await vgs_db_update_fields(db, user_id, updates)   # при неудаче сам добавит в pending
            current.update(updates)
            VGS_USER_CACHE[user_id] = current
    finally:
        lock.release()

