user_requests = {}

# Время ограничения и лимит запросов
REQUEST_LIMIT = 50
TIME_LIMIT = 30  # в секундах
def check_request_limit(user_id, user_requests):
    current_time = time.time()

    # Проверяем, существует ли пользователь в словаре
    if user_id not in user_requests:
        user_requests[user_id] = {'count': 0, 'first_request_time': current_time}

    first_request_time = user_requests[user_id]['first_request_time']

    # Проверяем, истек ли временной лимит
    if current_time - first_request_time > TIME_LIMIT:
        # Сбросить счетчик и обновить время первого запроса
        user_requests[user_id] = {'count': 1, 'first_request_time': current_time}
        return False  # Лимит не превышен
    else:
        # Увеличиваем счетчик запросов
        user_requests[user_id]['count'] += 1

        # Проверяем, превышает ли количество запросов лимит
        if user_requests[user_id]['count'] > REQUEST_LIMIT:
            return True  # Лимит превышен

    return False  # Лимит не превышен






# Функция для очистки текста от недопустимых символов
def clean_text(text):
    """Очищает текст от недопустимых символов для кодировки UTF-8."""
    if text is None:
        return "Неизвестно"
    #print("❤️ Очищаем текст: ", text)  # Отладочный вывод
    cleaned_text = text.encode("utf-8", errors="ignore").decode("utf-8").strip()
    return cleaned_text or "Неизвестно"  # Возвращаем дефолтное значение


# Асинхронная функция для обновления кэша групп
async def update_group_cache(db):
    """Инициализирует кэш данными из базы данных."""
    try:
        print("❤️ Начинаем обновление кэша групп из базы данных.")
        groups_from_db = await db.fetch_all(
            "SELECT chat_id, namechat, creator_id, creator_name, creator_username, chatbalance, dexbalance, usernamechat, chatlink FROM chat")
        print(f"❤️ Получено {len(groups_from_db)} групп из базы данных.")

        # Сначала собираем в обычный dict (без Redis/pklcode на каждый ключ),
        # затем одним bulk-блоком пишем в GameStore — один save вместо тысяч.
        fresh: Dict[int, Dict[str, Any]] = {}
        for _i, group in enumerate(groups_from_db):
            fresh[group["chat_id"]] = {
                "namechat": clean_text(group["namechat"]),
                "creator_id": group["creator_id"] or 0,
                "creator_name": clean_text(group["creator_name"]),
                "creator_username": clean_text(group["creator_username"]),
                "chatbalance": group["chatbalance"],
                "dexbalance": group["dexbalance"],
                "usernamechat": clean_text(group["usernamechat"]),
                "chatlink": clean_text(group["chatlink"]),
            }
            if (_i & 0x3FF) == 0x3FF:
                await asyncio.sleep(0)

        group_cache.bulk_load(fresh)

        print("✅ Кэш групп успешно обновлён из базы данных.")
    except Exception as e:
        print(f"❌ Ошибка при обновлении кэша групп из базы данных: {e}")


# Асинхронная функция для добавления или обновления информации о группе
# ✅ локи на чат, чтобы не было гонок (даже если db без локов)





def _r(tag: str, msg: str):
    print(f"🔴 [{tag}] {msg}")


# ============================================================
# 🔒 ЛОКИ НА ГРУППЫ
# ============================================================

_GROUP_LOCKS: Dict[int, asyncio.Lock] = {}

def _get_group_lock(chat_id: int) -> asyncio.Lock:
    if chat_id not in _GROUP_LOCKS:
        _GROUP_LOCKS[chat_id] = asyncio.Lock()
        _r("LOCK", f"Создан лок для chat_id={chat_id}")
    return _GROUP_LOCKS[chat_id]


# ============================================================
# 🗄️ FALLBACK ЧТЕНИЕ ИЗ БД
# ============================================================

async def _fetch_group_row_fallback(db, chat_id: int) -> Optional[Dict[str, Any]]:
    if not getattr(db, "pool", None):
        _r("DB", "❌ db.pool отсутствует")
        return None

    try:
        async with db.pool.acquire() as con:
            row = await asyncio.wait_for(
                con.fetchrow("SELECT * FROM chat WHERE chat_id = $1", int(chat_id)),
                timeout=5
            )
        return dict(row) if row else None
    except Exception as e:
        _r("DB", f"❌ fallback fetchrow ошибка: {e}")
        return None


# ============================================================
# 🧩 НОРМАЛИЗАЦИЯ СТРОКИ
# ============================================================

def _normalize_group_row(db_row: Dict[str, Any], chat_id: int) -> Dict[str, Any]:
    out = dict(db_row or {})
    out["chat_id"] = chat_id

    out.setdefault("namechat", "Без названия")
    out.setdefault("usernamechat", "username отсутствует")
    out.setdefault("chatlink", "Приватная ссылка не найдена")
    out.setdefault("creator_id", 0)
    out.setdefault("creator_name", "Неизвестно")
    out.setdefault("creator_username", "Неизвестно")

    try:
        out["chatbalance"] = int(out.get("chatbalance") or 0)
    except Exception:
        out["chatbalance"] = 0

    try:
        out["dexbalance"] = int(out.get("dexbalance") or 0)
    except Exception:
        out["dexbalance"] = 0

    return out


