# 🚀 ОСНОВНАЯ ФУНКЦИЯ
# ============================================================

async def add_or_update_group_info(bot1, chat_id, db) -> bool:
    try:
        chat_id = int(chat_id)
    except Exception:
        _r("GROUP", f"❌ chat_id некорректный: {chat_id!r}")
        return False

    if chat_id > 0:
        _r("GROUP", f"⚠️ chat_id={chat_id} - ЛС, пропуск")
        return False

    lock = _get_group_lock(chat_id)

    async with lock:
        _r("GROUP", f"▶️ Старт обработки chat_id={chat_id}")

        if not hasattr(db, "group_cache") or not isinstance(db.group_cache, dict):
            db.group_cache = {}
            _r("CACHE", "Создан db.group_cache")

        cache = db.group_cache

        try:
            exists = await asyncio.wait_for(db.check_group_exists(chat_id), timeout=5)
        except Exception as e:
            _r("DB", f"❌ check_group_exists ошибка: {e}")
            exists = False

        try:
            chat = await asyncio.wait_for(bot1.get_chat(chat_id), timeout=7)
        except Exception as e:
            _r("TG", f"❌ get_chat ошибка: {e}")
            return False

        if chat.type == ChatType.PRIVATE:
            _r("TG", "⚠️ Приватный чат")
            return False

        namechat = clean_text(chat.title) if chat.title else "Без названия"
        usernamechat = clean_text(chat.username) if chat.username else "username отсутствует"
        description = clean_text(chat.description) if chat.description else "Описание отсутствует"

        try:
            chatlink = clean_text(chat.invite_link) if chat.invite_link else "Приватная ссылка не найдена"
        except Exception:
            chatlink = "Приватная ссылка не найдена"

        creator_id = 0
        creator_name = "Неизвестно"
        creator_username = "Неизвестно"

        try:
            admins = await asyncio.wait_for(bot1.get_chat_administrators(chat_id), timeout=7)
            creator = next((a for a in admins if a.status == "creator"), None)
            if creator:
                creator_id = creator.user.id
                creator_name = clean_text(creator.user.full_name)
                creator_username = clean_text(creator.user.username) if creator.user.username else "username отсутствует"
        except Exception as e:
            _r("TG", f"⚠️ get_chat_administrators ошибка: {e}")

        if chat_id in cache:
            current = cache[chat_id]

            old_chatbalance = int(current.get("chatbalance") or 0)
            old_dexbalance = int(current.get("dexbalance") or 0)

            updates = {}
            if current.get("namechat") != namechat:
                updates["namechat"] = namechat
            if current.get("usernamechat") != usernamechat:
                updates["usernamechat"] = usernamechat
            if current.get("chatlink") != chatlink:
                updates["chatlink"] = chatlink
            if int(current.get("creator_id") or 0) != creator_id:
                updates["creator_id"] = creator_id
                updates["creator_name"] = creator_name
                updates["creator_username"] = creator_username

            if updates:
                try:
                    await asyncio.wait_for(db.update_chat_columns(chat_id, **updates), timeout=5)
                except Exception as e:
                    _r("DB", f"❌ update_chat_columns ошибка: {e}")
                current.update(updates)

            current["chatbalance"] = old_chatbalance
            current["dexbalance"] = old_dexbalance
            cache[chat_id] = current

            try:
                await asyncio.wait_for(db.update_group_member_count(chat_id, bot1), timeout=5)
            except Exception:
                pass

            _r("GROUP", f"✅ chat_id={chat_id} обновлён из кэша")
            return True

        if not exists:
            try:
                await asyncio.wait_for(
                    db.add_group(
                        chat_id=chat_id,
                        namechat=namechat,
                        usernamechat=usernamechat,
                        chatlink=chatlink,
                        description=description,
                        creator_id=creator_id,
                        creator_name=creator_name,
                        creator_username=creator_username
                    ),
                    timeout=5
                )
            except Exception as e:
                _r("DB", f"⚠️ add_group ошибка: {e}")

        try:
            if hasattr(db, "fetch_group_row"):
                row = await asyncio.wait_for(db.fetch_group_row(chat_id), timeout=5)
            else:
                row = await _fetch_group_row_fallback(db, chat_id)
        except Exception as e:
            _r("DB", f"❌ fetch_group_row ошибка: {e}")
            row = None

        if row:
            cache[chat_id] = _normalize_group_row(row, chat_id)
        else:
            cache[chat_id] = {
                "chat_id": chat_id,
                "namechat": namechat,
                "usernamechat": usernamechat,
                "chatlink": chatlink,
                "creator_id": creator_id,
                "creator_name": creator_name,
                "creator_username": creator_username,
                "chatbalance": 0,
                "dexbalance": 0,
            }

        try:
            await asyncio.wait_for(db.update_group_member_count(chat_id, bot1), timeout=5)
        except Exception:
            pass

        _r("GROUP", f"✅ chat_id={chat_id} добавлен и синхронизирован")
        return True


