async def check_and_add_user(message, db):
    user_id = message.from_user.id
    chat_id = message.chat.id
    chat_name = message.chat.title

    # Получение имени пользователя по user_id
    name = await db.get_firstname_by_user_id(user_id)
    if not name:
        name = message.from_user.first_name  # Если имя отсутствует в базе, используем имя из сообщения

    # Получение username пользователя по user_id
    username = await db.get_username_by_user_id(user_id)
    if not username:
        username = message.from_user.username if message.from_user.username else ""  # Получаем username из сообщения, если он есть

    # Проверка, существует ли пользователь в этой группе
    if not await db.user_exists_in_chat(user_id , chat_id):
        # Форматируем текущую дату и время
        current_date = datetime.now().strftime("%d.%m.%Y %H:%M")

        # Добавление пользователя в базу данных
        await db.add_user_to_chat(user_id , name , username , chat_id , chat_name , current_date)

    # Сообщение для отладки
    print(f"Пользователь с ID {user_id} ({name}, @{username}) находится в группе {chat_name} (ID: {chat_id})")
#функции в приватных сообщениях бота



group_info_updating = False

async def update_group_info_periodically(bot, chat_id, db):
    global group_info_updating

    print(f"🟡 Попытка запуска обновления группы. chat_id={chat_id}")

    if group_info_updating:
        print(f"⚠️ Обновление уже запущено, повторный старт отменён. chat_id={chat_id}")
        return

    group_info_updating = True
    print(f"✅ Цикл обновления группы ЗАПУЩЕН. chat_id={chat_id}")

    try:
        while True:
            print(f"\n🔄 Начинаем обновление информации о группе. chat_id={chat_id}")

            start_time = time.time()

            try:
                print("📤 Вызов add_or_update_group_info(...)")
                await add_or_update_group_info(bot, chat_id, db)
                print("📥 add_or_update_group_info(...) успешно завершён")

            except Exception as e:
                print("❌ ОШИБКА при обновлении информации о группе!")
                print(f"❌ chat_id={chat_id}")
                print(f"❌ Текст ошибки: {e}")
                print("❌ Traceback:")
                traceback.print_exc()

            end_time = time.time()
            elapsed_time = (end_time - start_time) * 1000  # миллисекунды

            print(
                f"🚀 Обновление завершено. "
                f"Время выполнения: {elapsed_time:.2f} мс. "
                f"chat_id={chat_id}"
            )

            print("⏳ Ожидание 900 секунд до следующего обновления...\n")
            await asyncio.sleep(900)

    finally:
        group_info_updating = False
        print(f"🛑 Цикл обновления ОСТАНОВЛЕН. chat_id={chat_id}")
