@dp.callback_query(F.data.startswith("starthowtoplay"))
async def process_game_buttons(call: types.CallbackQuery):
    # чтобы не было "часиков" на кнопке
    await call.answer()

    # ─────────────────────────────────────────────────────────────
    # Кнопки (без файлов, только UX)
