    button1 = InlineKeyboardButton(
        text="Играть в личке", switch_inline_query="игры", style="default" ,icon_custom_emoji_id="5936138290519349485"  # сразу подставит inline-запрос
    )
    button3 = InlineKeyboardButton(
        text="Играть в группе",
        url="https://t.me/CuteGamingChat", style="default" ,icon_custom_emoji_id="5264737672684907396"
    )
    button2 = InlineKeyboardButton(
        text="Закрыть",
        callback_data="twogreet_cut", style="default" ,icon_custom_emoji_id="5226660202035554522"
    )

    markup_start1 = InlineKeyboardMarkup(
        inline_keyboard=[
            [button1],
            [button3],
            [button2],
        ]
    )

    # ─────────────────────────────────────────────────────────────
    # Текст (коротко, элитно, понятно с первого раза)
    # ─────────────────────────────────────────────────────────────
    starttext2 = ("<tg-emoji emoji-id='5318959255385043017'>🎩</tg-emoji> <b>@CuteGamingBot - элитный игровой бот с валютой «Кут»</b>\n"
                  "<tg-emoji emoji-id='5924870095925942277'>⭐️</tg-emoji> <b>1 кут = 1 Telegram Star</b>\n\n"
                  "<tg-emoji emoji-id='5377336227533969892'>💱</tg-emoji> <b>Куты крутятся по кругу между игроками</b> <blockquote>кто-то выигрывает, кто-то проигрывает - это живая экономика.</blockquote>\n"
                  "<tg-emoji emoji-id='5318892863780579996'>🎩</tg-emoji> <b>Как начать :</b>\n"
                  "1) Перейдите в основную группу <b>@CuteGamingChat</b>\n"
                  "2) Напишите «<code>хелп игры</code>»\n"
                  "3) Выберите игру и следуйте подсказкам\n\n"
                  "<tg-emoji emoji-id='5470177992950946662'>👇</tg-emoji> Нажмите кнопку ниже, для навигации")

    # ─────────────────────────────────────────────────────────────
    # Редактируем текущее сообщение (без удаления и без новых сообщений)
    # ─────────────────────────────────────────────────────────────
    try:
        await call.message.edit_text(
            starttext2,
            reply_markup=markup_start1,
            parse_mode="HTML",
            disable_web_page_preview=True
        )
    except TelegramBadRequest as e:
        # Нельзя редактировать (например, сообщение слишком старое / не от бота / уже такое же)
        # По твоему требованию: НЕ шлём новое сообщение.
        await call.answer("Не удалось обновить сообщение. Откройте меню заново.", show_alert=True)




