@dp.message(CommandStart())
async def universal_start_handler(message: Message, command: Optional[CommandObject] = None):
    """
    Обрабатываем:
     - /start
     - /start@CuteGamingBot                    - (в группе/супергруппе) ответ "привет как дела ?"
     - /start <digits>                        - реферальная ссылка
     - /start withdraw                        - вывод
     - /start insert_<n>_+                    - инвойс на <n> кут (а также insert_<n>, insert_<n>%2B и т.п.)
     - /start gblevel_<chat>_<level>_<price>  - инвойс уровня баланса группы (из бч)
     - /start deep_conc_stars / deep_conc_stars+
    """

    # ─────────────────────────────────────────────────────────────────────────
    # A) БАЗОВЫЕ ДАННЫЕ
    # ─────────────────────────────────────────────────────────────────────────
    user_id = int(message.from_user.id)
    text_raw = (message.text or "").strip()
    text_lc = text_raw.lower()

    # ─────────────────────────────────────────────────────────────────────────
    # A.1) ПРОВЕРКА БЛОКИРОВКИ: заблокированный в проекте пользователь не проходит
    # дальше ни по одному из сценариев /start (рефералка, вывод, инвойс, меню).
    # Если не заблокирован - код работает как обычно.
    # ─────────────────────────────────────────────────────────────────────────
    try:
        if await _safe_is_user_banned(user_id):
            await message.answer(
                "<tg-emoji emoji-id='5249268768147792417'>🚫</tg-emoji> "
                "<b>Вы заблокированы в боте</b>",
                parse_mode="HTML",
                disable_web_page_preview=True,
            )
            return
    except Exception as e:
        print(f"[START][BAN][ERROR] is_user_banned: {type(e).__name__}: {e!r}")

    # ─────────────────────────────────────────────────────────────────────────
    # B) СПЕЦ-СЛУЧАЙ: /start@CuteGamingBot (обычно в группах)
    # ВАЖНО: CommandStart() может не отрабатывать в группах на /start@botname стабильно,
    # поэтому делаем эту проверку прямо по тексту и выходим early-return.
    # ─────────────────────────────────────────────────────────────────────────
    if text_lc == "/start@cutegamingbot" or text_lc.startswith("/start@cutegamingbot "):
        return await message.answer("привет как дела ? ")
    if command and isinstance(command.args, str):
        deep = command.args
    else:
        _parts = (message.text or "").strip().split(maxsplit=1)
        deep = _parts[1] if len(_parts) > 1 else ""

    deep = deep or ""
    user_id = int(message.from_user.id)

    # ─────────────────────────────────────────────────────────────────────────
    # 1) Нормализация deep-параметра (/start <deep>)
    # ─────────────────────────────────────────────────────────────────────────
    try:
        deep_raw = str(deep).strip()
    except Exception:
        deep_raw = ""

    # берём только первый токен (до пробела)
    deep_token = (deep_raw.split(maxsplit=1)[0] if deep_raw else "").strip()

    # ВАЖНО: unquote_plus - потому что '+' в URL часто превращается в пробел
    try:
        deep_token_decoded = urllib.parse.unquote_plus(deep_token)
    except Exception:
        deep_token_decoded = deep_token

    deep_token_decoded = (deep_token_decoded or "").strip()

    # ✅ КЛЮЧЕВОЕ: дальше ВСЮ маршрутизацию делаем по НОРМАЛИЗОВАННОМУ deep
    # чтобы одинаково работало и для новых пользователей, и при %2B / '+' / пробелах
    deep = deep_token_decoded

    print(f"🔎 [START][DEEP] raw={deep_raw!r} token={deep_token!r} decoded={deep!r} user_id={user_id}")

    # ─────────────────────────────────────────────────────────────────────────
    # 2) Инвойс (оставляем принцип if deep.startswith("insert_"))
    # ─────────────────────────────────────────────────────────────────────────
    # ─────────────────────────────────────────────────────────────
    # 2) Инвойс: автоматическое определение доната / выкупа
    # ─────────────────────────────────────────────────────────────
    # deep – уже нормализованная строка из start-параметра

    # ─────────────────────────────────────────────────────────────
    # Инвойс: автоматическое определение доната / выкупа
    # ─────────────────────────────────────────────────────────────
    if deep.startswith("insert_") or deep.startswith("buyback_") or deep.startswith("gblevel_"):
        # ---------- Извлечение данных ----------
        if deep.startswith("insert_"):
            operation = "donate"
            tail = deep [ len("insert_"): ].strip()
            digits = ''
            for ch in tail:
                if ch.isdigit():
                    digits += ch
                else:
                    break
            if not digits:
                return await message.answer("❌ Ошибка: некорректный формат ссылки." , parse_mode="HTML")
            stars_price_str = digits
            invoice_stars = int(stars_price_str)
            # Донат: количество кут будет рассчитано внутри send_invoice_to_user
            await send_invoice_to_user(message , stars_price_str , operation_type="donate")
        elif deep.startswith("buyback_"):
            operation = "buyback"
            # Формат: buyback_<bet>_<nonce>
            tail = deep [ len("buyback_"): ].strip()
            if not tail:
                return await message.answer("<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> Некорректная ссылка выкупа." , parse_mode="HTML")
            parts = tail.split("_" , 1)
            if len(parts) != 2:
                return await message.answer("<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> Некорректная ссылка выкупа." , parse_mode="HTML")
            bet_str , nonce = parts [ 0 ] , parts [ 1 ]
            if not bet_str.isdigit():
                return await message.answer("<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> Сумма выкупа должна быть числом." , parse_mode="HTML")
            bet = int(bet_str)
            if bet <= 0 or bet > 99999:
                return await message.answer("<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> Некорректная сумма выкупа." , parse_mode="HTML")

            # Проверка доступных потерянных кут
            user_home = await db.get_user_home(user_id)
            if bet > user_home:
                return await message.answer(
                    f"<tg-emoji emoji-id='5438449312893792440'>🎁</tg-emoji> <b>Недостаточно потерянных кут.</b>\nДоступно: {user_home} кут" , parse_mode="HTML")

            # Цена в звёздах со скидкой
            stars_price = max(1 , int(bet * MULTIPLIER_BUYBACK))
            stars_price_str = str(stars_price)

            # Отправка инвойса с явным указанием kut_amount и nonce
            await send_invoice_to_user(
                message , stars_price_str , operation_type="buyback" , kut_amount=bet , nonce=nonce)
        elif deep.startswith("gblevel_"):
            # Формат: gblevel_<chat_id>_<to_level>_<price>
            # Deep-link из группы → сразу счёт Stars + crypto в ЛС
            if message.chat.type != ChatType.PRIVATE:
                return await message.answer(
                    "<tg-emoji emoji-id='5420323339723881652'>⚠️</tg-emoji> "
                    "<b>Оплата уровня — только в личных сообщениях с ботом.</b>",
                    parse_mode="HTML",
                )
            tail = deep[len("gblevel_"):].strip()
            parts = tail.split("_")
            if len(parts) != 3 or not all(p.lstrip("-").isdigit() for p in parts):
                return await message.answer(
                    "<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> "
                    "<b>Некорректная ссылка оплаты уровня.</b>\n"
                    "Вернитесь в группу и откройте экран снова.",
                    parse_mode="HTML",
                )
            try:
                pay_chat_id = int(parts[0])
                to_level = int(parts[1])
                price = int(parts[2])
            except Exception:
                return await message.answer(
                    "<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> "
                    "<b>Некорректная ссылка оплаты уровня.</b>",
                    parse_mode="HTML",
                )
            if price <= 0 or to_level < 1 or to_level > 5:
                return await message.answer(
                    "<tg-emoji emoji-id='4958526153955476488'>❌</tg-emoji> "
                    "<b>Некорректные параметры уровня.</b>",
                    parse_mode="HTML",
                )

            from bot.funcs.group_balance_level import (
                get_settings,
                find_level_package,
                ensure_society_snapshot,
                stars_label,
                badge_title_for_level,
                stake_delta_for_step,
                social_proof_line,
                format_package_price_line,
                resolve_group_link_html,
                explain_package_plain,
            )

            cfg = get_settings()
            if not cfg.get("enabled", True):
                return await message.answer(
                    "<tg-emoji emoji-id='5420323339723881652'>⚠️</tg-emoji> "
                    "<b>Уровни баланса группы временно недоступны.</b>\n"
                    "Загляните чуть позже.",
                    parse_mode="HTML",
                )

            atmo = 0.0
            try:
                snap = await ensure_society_snapshot(pay_chat_id, db=db)
                atmo = float((snap or {}).get("pct") or 0)
            except Exception as _snap_e:
                print(f"⚠️ [START][GBL] society snapshot: {_snap_e!r}")

            pkg = find_level_package(pay_chat_id, to_level, price, cfg)
            if not pkg:
                return await message.answer(
                    "<tg-emoji emoji-id='5420323339723881652'>⚠️</tg-emoji> "
                    "<b>Этот пакет уже неактуален.</b>\n"
                    "Вернитесь в группу → баланс → повышение — и выберите пакет снова.",
                    parse_mode="HTML",
                )

            badge = str(pkg.get("badge_title") or badge_title_for_level(to_level, cfg))
            title = f"Статус {stars_label(to_level)}"
            description = (
                f"Уровень группы → {to_level} · {pkg.get('role', 'пакет')} · "
                f"{price} звёзд (−{int(pkg.get('save_pct') or 0)}%)"
            )
            prices = [LabeledPrice(label=title[:32], amount=int(price))]
            kb = get_crypto_keyboard(
                int(price), gbl_chat_id=int(pay_chat_id), gbl_level=int(to_level),
            )
            payload = f"gblevel_{pay_chat_id}_{to_level}_{price}"
            from_lvl = int(pkg.get("from_level") or max(0, int(to_level) - 1))
            gain = stake_delta_for_step(
                from_level=from_lvl,
                to_level=to_level,
                atmosphere_pct=atmo,
                cfg=cfg,
            )
            group_html_dm, chat_title_dm, _ = await resolve_group_link_html(
                bot1, pay_chat_id,
            )
            delta_line = (
                f"\nвсем станет можно ставить на <b>+{gain['delta']} кут</b> больше"
                if gain.get("delta") else ""
            )
            try:
                from bot.funcs.group_balance_level import gbl_tg as _gbl_tg
                await message.answer(
                    f"{_gbl_tg('⭐️')} "
                    f"<b>Оплата со скидкой</b>\n"
                    f"<i>счёт готов — ниже всё простыми словами</i>\n\n"
                    f"{_gbl_tg('💡')} <b>Что вы покупаете</b>\n"
                    f"{explain_package_plain(pkg)}\n"
                    f"группа: {group_html_dm}\n"
                    f"<i>нажмите на название — откроется группа</i>\n\n"
                    f"{_gbl_tg('⭐️')} <b>Что изменится</b>\n"
                    f"раньше: <b>{gain['old_lim']}</b>\n"
                    f"станет: <b>{gain['new_lim']}</b>{delta_line}\n"
                    f"подарок вам: метка «<b>{badge}</b>»\n\n"
                    f"{_gbl_tg('💰')} <b>Счёт</b>\n"
                    f"{format_package_price_line(pkg)}\n"
                    f"<i>{social_proof_line()}</i>\n"
                    f"<i>куты на личный баланс не придут — вы усиливаете общую игру</i>",
                    parse_mode="HTML",
                    disable_web_page_preview=True,
                )
            except Exception:
                pass
            try:
                await bot1.send_invoice(
                    chat_id=user_id,
                    title=title[:32],
                    description=description[:255],
                    payload=payload[:128],
                    currency="XTR",
                    prices=prices,
                    provider_token="",
                    start_parameter="gblevel",
                    reply_markup=kb,
                )
                try:
                    user_bonus_requests.setdefault(user_id, []).append(0)
                    message_state[user_id] = 0
                except Exception:
                    pass
            except Exception as e:
                print(f"❌ [START][GBL] invoice error: {e!r}")
                return await message.answer(
                    "<tg-emoji emoji-id='5420323339723881652'>⚠️</tg-emoji> "
                    "<b>Не удалось отправить счёт.</b>\n"
                    "Напишите /start и откройте оплату из группы ещё раз.",
                    parse_mode="HTML",
                )
        # ---------- Очистка pending_context (если был) ----------
        try:
            ctx = pending_context.get(user_id)
        except:
            ctx = None
        if ctx:
            msg_id = ctx.get("manual_message_id")
            if msg_id:
                try:
                    await message.bot.delete_message(chat_id=user_id , message_id=msg_id)
                except:
                    pass
            pending_context.pop(user_id , None)
        return  # <-- важно, чтобы не продолжалась обработка других start-команд
    # ─────────────────────────────────────────────────────────────────────────
    # deep_conc_stars / deep_conc_stars+
    # ─────────────────────────────────────────────────────────────────────────
    if deep_token_decoded in ("deep_conc_stars" , "deep_conc_stars+"):
        print(f"🔗 [WITHDRAW][DEEP][ENTER] deep={deep_token_decoded!r} user_id={user_id}")

        # 1) speed_flag
        if deep_token_decoded == "deep_conc_stars":
            # честный режим: проверяем TON
            try:
                speed_flag = await resolve_speed_flag_by_ton(SEED_PHRASE)  # noqa: F821
                print(f"🧮 [WITHDRAW][DEEP] Режим=AUTO_TON speed_flag={speed_flag!r}")
            except Exception as e:
                speed_flag = "-"
                print(
                    f"🟥 [WITHDRAW][DEEP][ОШИБКА] resolve_speed_flag_by_ton: "
                    f"{type(e).__name__}: {e} -> speed_flag='-'")
        else:
            # принудительно выключаем speed (TON не трогаем вообще)
            speed_flag = "-"
            print("⛔ [WITHDRAW][DEEP] Режим=FORCED_NO_SPEED speed_flag='-' (TON пропущена)")

        # 2) render (ВАЖНО: вызываем по именам, чтобы не зависеть от сигнатуры функции)
        try:
            await render_conc_stars_screen(
                message_obj=message , user_id=int(user_id) , speed_flag=str(speed_flag) , seed_phrase=SEED_PHRASE ,
                # noqa: F821
            )
            print(f"✅ [WITHDRAW][DEEP] Экран вывода показан user_id={user_id} speed_flag={speed_flag!r}")
        except TypeError as e:
            # если твоя версия render_conc_stars_screen ещё старая и не принимает speed_flag именем
            print(
                f"🟨 [WITHDRAW][DEEP][ВНИМАНИЕ] render_conc_stars_screen TypeError: {e} -> пробую старый вызов")
            try:
                await render_conc_stars_screen(message , int(user_id) , SEED_PHRASE)  # noqa: F821
                print(f"✅ [WITHDRAW][DEEP] Экран вывода показан через fallback user_id={user_id}")
            except Exception as e2:
                print(
                    f"🟥 [WITHDRAW][DEEP][ОШИБКА] render_conc_stars_screen fallback: "
                    f"{type(e2).__name__}: {e2}")
        except Exception as e:
            print(
                f"🟥 [WITHDRAW][DEEP][ОШИБКА] render_conc_stars_screen: "
                f"{type(e).__name__}: {e}")

        return
    if deep.startswith("withdraw"):

        user_id = message.from_user.id

        if not message.from_user.username:
            return await message.answer("❕ Установите username." , parse_mode="HTML")

        if message.chat.type != ChatType.PRIVATE:
            bot_username = None
            try:
                me = await message.bot.get_me()
                bot_username = me.username
            except Exception:
                pass

            if not bot_username:
                bot_username = {"7683193125:AAHasdML6dkryk2QaRps96rytsvv2ucXxqM": "CuteGamingBot" ,
                    "7357700583:AAHHA3jr6f38X6LwNvx9a2scXZHee3DJXTY": "Cute3TestBot"}.get(message.bot.token)

            if not bot_username:
                return await message.answer("❌ Ошибка: бот не определён.")

            btn = InlineKeyboardMarkup(
                inline_keyboard=[
                    [ InlineKeyboardButton("💭 Открыть в боте" , url=f"https://t.me/{bot_username}?start=withdraw") ] ,
                    [ InlineKeyboardButton("Назад" , callback_data="balanceashudjwqkdq") ] ])
            return await message.answer("💰" , reply_markup=btn , parse_mode="HTML")

        # PRIVATE: готовим сценарий ввода суммы
        # ✅ читаем pending (если deep-link пришёл из группы/баланса)
        try:
            pending = pending_withdraw.get(user_id)
        except Exception:
            pending = None

        pending_withdraw.pop(user_id , None)

        withdrawal_context [ user_id ] = {"awaiting_amount": True , "origin_chat_id": message.chat.id ,
            "origin_message_id": message.message_id , }

        # ✅ применяем back_flag/owner_id (если были в pending)
        try:
            _ctx_apply_back_meta(
                withdrawal_context [ user_id ] , back_flag=(pending or {}).get("back_flag" , WITHDRAW_BACK_STARS) ,
                owner_id_for_back=(pending or {}).get("owner_id_for_back") , )
        except Exception:
            pass

        prompt = await message.answer(
            "<tg-emoji emoji-id='5319130517205969202'>🌸</tg-emoji> <b>Введите количество кут для вывода</b>" , reply_markup=ForceReply(selective=True) ,
            message_effect_id="5107584321108051014" , parse_mode="HTML" , )
        withdrawal_context [ user_id ].update(
            prompt_chat_id=prompt.chat.id , prompt_message_id=prompt.message_id , )
        return


    # 3) Реферальная ссылка и ваш оригинальный блок (минимально тронут)
    start_time = time.time()
    first_name1 = message.from_user.first_name
    first_name = re.sub(r'[<>/{}"]', '', first_name1 or "")
    username = message.from_user.username

    print('🏉🏉🏉🏉🏉🏉 message_text : ', message.text)

    # Логика рефералок работает и для /START (мы уже пропустили через декоратор)
    # Доп. проверка чата:
    # В начале убедитесь, что user_id определён (если нет выше):
    user_id = message.from_user.id

    if message.chat.type == ChatType.PRIVATE:
        parts = message.text.split()
        if len(parts) == 2 and parts [ 1 ].isdigit():
            try:
                reffer_id = int(parts [ 1 ])

                # Получаем bio с защитой от ошибки
                try:
                    user_chat = await bot1.get_chat(user_id)
                    bio = user_chat.bio if getattr(user_chat , "bio" , None) else "Нет информации о био"
                except Exception:
                    bio = "Нет информации о био"

                # Создаём/обновляем основного пользователя
                await measure_time(
                    add_or_update_user_info(message=message , db=db , start_balance=start_balance , bot=message.bot) ,
                    "3Добавление / обновление информации о пользователе в базе")
                await db.add_data(user_id , first_name , username , bio , start_balance)

                # Проверяем, не было ли уже реферального перехода (таблица usersref)
                already_referred = await db.check_user_id_in_users(user_id)

                # Если записи о реферале ЕЩЁ НЕТ — обрабатываем ссылку
                if not already_referred:
                    if reffer_id != user_id:
                        # Фиксируем реферальную связь
                        await db.add_ref1(user_id , reffer_id)
                        await db.check_and_update_bio(user_id , bot1)

                        inviting_user_data = await db.get_user_data(reffer_id)
                        if inviting_user_data:
                            ref_first_name = await db.get_firstname_by_user_id(reffer_id)
                            first_name_hui = await db.get_firstname_by_user_id(user_id)
                            await db.insert_refcheck_entry(
                                user_id=user_id , ref_user_id=reffer_id , first_name=first_name_hui ,
                                ref_first_name=ref_first_name)

                            await db.remove_expired_refout()

                            current_time = time.time()
                            last_open_time , data_open = await db.get_ref_times(user_id , reffer_id)
                            if last_open_time is None or data_open is None:
                                last_open_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                                data_open_ts = current_time + timerefout
                                user_name = await db.get_firstname_by_user_id(user_id)
                                await db.add_refout(
                                    user_id , reffer_id , user_name , last_open_time ,
                                    datetime.fromtimestamp(data_open_ts).strftime("%Y-%m-%d %H:%M:%S"))

                            # Уведомление пригласившему
                            markup112132 = InlineKeyboardMarkup(
                                inline_keyboard=[ [ InlineKeyboardButton(
                                    text="Играть" , switch_inline_query="игры" ,
                                    icon_custom_emoji_id="5470088387048266598") ] ])
                            new_user_link = await create_user_link(user_id , first_name , username)
                            await bot1.send_message(
                                reffer_id , ("<tg-emoji emoji-id='5449850741667668411'>🌿</tg-emoji> <b>По вашей реф-ссылке перешёл новый пользователь!</b>\n"
                                             f"<tg-emoji emoji-id='5449885771420934013'>🌱</tg-emoji> <b>{new_user_link}</b>\n\n"
                                             f"<tg-emoji emoji-id='5278428495121248059'>🪴</tg-emoji> <b>Чтобы получить {ref_coin} кут за приглашение — "
                                             "приглашённый должен сыграть в любую игру | результат не важен.</b>\n\n"
                                             "<tg-emoji emoji-id='5224257782013769471'>💰</tg-emoji> <b>+ Вы будете зарабатывать 25% от его покупок в магазине!</b>") ,
                                reply_markup=markup112132 , parse_mode="HTML" , disable_web_page_preview=True)

                            # ===== НОВОЕ: приветствие для самого перешедшего пользователя =====
                            await bot1.send_message(
                                user_id , "<tg-emoji emoji-id='5449885771420934013'>🌱</tg-emoji> <b>Вы перешли по реферальной ссылке!</b>\n"
                                          f"<tg-emoji emoji-id='5317000922096769303'>🎁</tg-emoji> <b>Ваш друг получит {ref_coin} кут, когда вы сыграете в любую игру.</b>\n"
                                          "<tg-emoji emoji-id='5406683434124859552'>🛍</tg-emoji> <b>А вы будете получать 25% от его покупок в магазине!</b>" , parse_mode="HTML")
                            # =================================================================
                            print(f"🔋 Уведомление отправлено. Время: {time.time() - start_time:.3f} сек.")
                    else:
                        await bot1.send_message(
                            user_id , "<tg-emoji emoji-id='5213205860498549992'>⚠️</tg-emoji> <b>Нельзя регистрироваться по своей ссылке.</b>" , parse_mode="HTML" ,
                            disable_web_page_preview=True)
                else:
                    # Уже использовал реферальную ссылку ранее
                    await bot1.send_message(
                        user_id , "<tg-emoji emoji-id='5397718596132554015'>🤙</tg-emoji> <b>Вы уже использовали кут ранее, реферальная ссылка не засчитана</b>" ,
                        parse_mode="HTML" , disable_web_page_preview=True)
                    print('Пользователь уже использовал кут ранее.')
            except ValueError:
                await bot1.send_message(
                    user_id , "<tg-emoji emoji-id='5213205860498549992'>⚠️</tg-emoji> <b>Некорректный реферальный ID. Попробуйте ещё раз.</b>" , parse_mode="HTML" ,
                    disable_web_page_preview=True)

        # Обычное меню (отображается всегда после обработки рефералки)
        try:
            subscription_status = await db.get_user_subscription(user_id)
        except Exception as e:
            print(f"Ошибка при получении статуса подписки для пользователя {user_id}: {e}")
            subscription_status = 0

        # Экран 1 онбординга: одно сообщение вместо двух пустых эмодзи.
        # Верхняя кнопка зависит от того, есть ли чем играть: нет кут —
        # ведём к бесплатному заданию, есть — сразу к выбору игры.
        # Deep /start earn — сразу к списку бесплатных заданий.
        from bot.funcs.onboarding import start_screen, start_payload_screen

        # Дата первого /start — окно обучающих подсказок (2 суток).
        try:
            await db.ensure_bot_first_start(user_id)
        except Exception as e:
            print(f"[START] ensure_bot_first_start({user_id}): {e!r}")

        payload_screen = await start_payload_screen(user_id, deep)
        if payload_screen is not None:
            start_body, start_markup = payload_screen
        else:
            start_body, start_markup = await start_screen(user_id)

        # Сетевой обрыв до Telegram не должен ронять /start целиком.
        # 1) с effect → 2) без effect → 3) тихий выход (человек нажмёт /start снова).
        sent_message = None
        send_attempts = (
            dict(
                chat_id=message.chat.id,
                text=start_body,
                reply_markup=start_markup,
                message_effect_id="5107584321108051014",
                parse_mode="HTML",
                disable_web_page_preview=True,
            ),
            dict(
                chat_id=message.chat.id,
                text=start_body,
                reply_markup=start_markup,
                parse_mode="HTML",
                disable_web_page_preview=True,
            ),
        )
        for attempt_i, kwargs in enumerate(send_attempts, start=1):
            try:
                sent_message = await bot1(SendMessage(**kwargs))
                break
            except TelegramNetworkError as e:
                print(
                    f"[START][NET] uid={user_id} attempt={attempt_i}/{len(send_attempts)} "
                    f"{type(e).__name__}: {e}"
                )
                if attempt_i < len(send_attempts):
                    await asyncio.sleep(0.35 * attempt_i)
            except Exception as e:
                print(f"[START][SEND] uid={user_id} attempt={attempt_i}: {type(e).__name__}: {e!r}")
                if attempt_i < len(send_attempts):
                    await asyncio.sleep(0.2)
                else:
                    return

        if sent_message is None:
            print(f"[START][NET] uid={user_id}: не удалось отправить стартовый экран")
            return

        bns_add_request(user_id , sent_message.message_id , reason="print('🏉🏉🏉🏉🏉🏉 message_text : ', message.text)")
        message_state [ message.from_user.id ] = sent_message.message_id

        await measure_time(
            add_or_update_user_info(message=message , db=db , start_balance=start_balance , bot=message.bot) ,
            "2Добавление / обновление информации о пользователе в базе")
        return








