@dp.callback_query(lambda c: c.data.startswith("bonusstartbonus"))
async def callback_top(call: types.CallbackQuery):
    user_id = call.from_user.id
    chat = call.message.chat
    chat_id = chat.id
    chat_type = chat.type

    now_dt = datetime.now()

    # --- 0. Достаем историю игр (для допуска к бонусу) ---
    try:
        last_open_time, data_open = await db.get_historygames_times(user_id)
    except Exception as e:
        print(f"[Бонус старт] Ошибка при получении historygames_times для {user_id}: {e}")
        await call.answer("💭 Произошла ошибка при получении данных.", show_alert=True)
        return

    print(
        f"[Бонус старт] Пользователь {user_id} - "
        f"Время последнего открытия бонуса: {last_open_time}, Время окончания бонуса: {data_open}"
    )

    # --- 1. Проверка ника пользователя (приписка семьи) ---
    try:
        has_family_tag = await check_user_name_for_bot(user_id, first_name=call.from_user.first_name, last_name=call.from_user.last_name)
    except Exception as e:
        print(f"[Бонус старт] Ошибка в check_user_name_for_bot: {e}")
        has_family_tag = False

    if not has_family_tag:
        # Напоминание про приписку
        if chat_type == "private":
            await call.message.answer("❕")

        btn_open = InlineKeyboardButton(
            text="Открыть бонус",
            callback_data=f"{random.randint(1, bonusbet)}_+",
        )
        kb = InlineKeyboardMarkup(inline_keyboard=[[btn_open]])
        first_name = await db.get_user_first_name(user_id)
        text = (f"<b><tg-emoji emoji-id='5467519850576354798'>❕</tg-emoji> Ваш ник должен содержать приписку семьи бота <code>Cute</code>\n "
                f"[ {first_name} <code>Cute</code> ]</b>")

        try:
            sent = await call.message.reply(
                text,
                reply_markup=kb,
                parse_mode="HTML",
                disable_web_page_preview=True,
            )
        except TelegramBadRequest as e:
            print(f"[Бонус старт] TelegramBadRequest (ник): {e}")
            return

        user_bonus_requests.setdefault(user_id, []).append(sent.message_id)
        return

    # --- 2. Проверка: были ли победы в играх (допуск к бонусу) ---
    if last_open_time is None or data_open is None:
        print(f"[Бонус старт] Пользователь {user_id} не найден в historygames или нет побед.")

        btn_play = InlineKeyboardButton(
            text="Играть!",
            switch_inline_query="Игры",
            style="default",
            icon_custom_emoji_id="5408935401442267103"
        )
        btn_open = InlineKeyboardButton(
            text="Открыть бонус",
            callback_data=f"{random.randint(1, bonusbet)}_+",
        )
        kb = InlineKeyboardMarkup(inline_keyboard=[[btn_play], [btn_open]])

        if chat_type == "private":
            await call.message.answer("❕")

        try:
            sent = await call.message.reply(
                "<tg-emoji emoji-id='5895583431194054511'>🌟</tg-emoji> <b>Сначала победите противника в любой игре</b>",
                reply_markup=kb,
                parse_mode="HTML",
            )
        except TelegramBadRequest as e:
            print(f"[Бонус старт] TelegramBadRequest (нет побед): {e}")
            return

        user_bonus_requests.setdefault(user_id, []).append(sent.message_id)
        return

    # --- 3. Проверка активного окна бонуса (cooldown / таймер) ---
    try:
        bonus_last_open, bonus_data_open = await db.get_bonus_times(user_id)
    except Exception as e:
        print(f"[Бонус старт] Ошибка при получении bonus_times для {user_id}: {e}")
        bonus_last_open = bonus_data_open = None

    if bonus_last_open is not None and bonus_data_open is not None:
        # Переводим при необходимости в строки
        if isinstance(bonus_last_open, datetime):
            bonus_last_open = bonus_last_open.strftime("%Y-%m-%d %H:%M:%S")
        if isinstance(bonus_data_open, datetime):
            bonus_data_open = bonus_data_open.strftime("%Y-%m-%d %H:%M:%S")

        try:
            last_open_dt = datetime.strptime(bonus_last_open, "%Y-%m-%d %H:%M:%S")
            data_open_dt = datetime.strptime(bonus_data_open, "%Y-%m-%d %H:%M:%S")
        except (TypeError, ValueError) as e:
            print(f"[Бонус старт] Ошибка парсинга дат bonus_times для {user_id}: {e}")
            last_open_dt = data_open_dt = None

        now = datetime.now()
        if data_open_dt and now < data_open_dt:
            # уже есть активный таймер - показываем отсчёт
            rem_sec = int((data_open_dt - now).total_seconds())
            h, rem = divmod(rem_sec, 3600)
            m, s = divmod(rem, 60)
            ts = f"{h:02d}:{m:02d}:{s:02d}"

            kb = InlineKeyboardMarkup(
                inline_keyboard=[
                    [InlineKeyboardButton(text="Доступно через", callback_data="available_through")],
                    [InlineKeyboardButton(text=ts, callback_data=f"infowaitingbonus|{ts}")],
                    [InlineKeyboardButton(text="✖️", callback_data="waiting9close_bonus")]
                ]
            )

            try:
                msg = await call.message.edit_text("<tg-emoji emoji-id='5458581641381290671'>⏳</tg-emoji>", reply_markup=kb, parse_mode="HTML")
            except TelegramBadRequest as e:
                print(f"[Бонус старт] TelegramBadRequest (первый рендер таймера): {e}")
                return

            # флаг отмены таймера
            cancel_timers[msg.message_id] = False

            for _ in range(15):
                await asyncio.sleep(1)

                if cancel_timers.get(msg.message_id, False):
                    print(f"[Бонус старт] Таймер для сообщения {msg.message_id} отменён.")
                    break

                now = datetime.now()
                if now >= data_open_dt:
                    try:
                        await msg.edit_text("🎉 Бонус открыт!", reply_markup=None)
                    except TelegramBadRequest as e:
                        print(f"[Бонус старт] TelegramBadRequest (финал таймера): {e}")
                    break

                rem_sec = int((data_open_dt - now).total_seconds())
                h, rem = divmod(rem_sec, 3600)
                m, s = divmod(rem, 60)
                ts_new = f"{h:02d}:{m:02d}:{s:02d}"

                kb_new = InlineKeyboardMarkup(
                    inline_keyboard=[
                        [InlineKeyboardButton(text=ts_new, callback_data=f"infowaitingbonus|{ts_new}")],
                        [InlineKeyboardButton(text="✖️", callback_data="waiting9close_bonus")]
                    ]
                )

                try:
                    await msg.edit_reply_markup(reply_markup=kb_new)
                except TelegramRetryAfter as e:
                    # flood control: не долбим Telegram - прекращаем обновлять таймер
                    print(f"[Бонус старт] flood control, останавливаю таймер: retry_after={getattr(e, 'retry_after', '?')}")
                    break
                except TelegramBadRequest as e:
                    print(f"[Бонус старт] TelegramBadRequest (обновление таймера): {e}")
                    break

            cancel_timers.pop(msg.message_id, None)
            return

    # ========== 4. Пользователь может получить бонус - рисуем поле 3×3 с ПРЕМИУМ ЭМОДЗИ ==========
    random.shuffle(emojisbonus)

    # выбираем ровно 9 эмодзи
    if len(emojisbonus) >= 9:
        selected_emojis = emojisbonus[:9]
    else:
        selected_emojis = list(emojisbonus)
        while len(selected_emojis) < 9 and emojisbonus:
            selected_emojis.append(random.choice(emojisbonus))

    # создаём кнопки с использованием icon_custom_emoji_id
    buttons = []
    for emoji in selected_emojis:
        emoji_id = _extract_emoji_id123(emoji)
        if emoji_id:
            # Премиум-эмодзи: пустой текст, иконка по ID
            button = InlineKeyboardButton(
                text=" ",
                style="default",
                icon_custom_emoji_id=emoji_id,
                callback_data=str(random.randint(1, bonusbet))
            )
        else:
            # Fallback на обычный текст (если ID не найден)
            button = InlineKeyboardButton(
                text=emoji,
                callback_data=str(random.randint(1, bonusbet))
            )
        buttons.append(button)

    # разбиваем по 3 в ряд
    keyboard_layout = [buttons[i:i+3] for i in range(0, len(buttons), 3)]
    keyboard_layout = keyboard_layout[:3]  # ровно 3 строки

    # кнопка закрытия (только в личке) – уже с кастомной иконкой
    if chat_type == "private":
        keyboard_layout.append(
            [InlineKeyboardButton(
                text=" ",
                callback_data="9close_bonus",
                style="default",
                icon_custom_emoji_id="5226660202035554522"
            )]
        )

    keyboard = InlineKeyboardMarkup(inline_keyboard=keyboard_layout)

    randomtextfraza = random.choice(textfraza)

    try:
        send_message_bonus = await call.message.edit_text(
            randomtextfraza,
            parse_mode="HTML",
            reply_markup=keyboard,
        )
    except TelegramBadRequest as e:
        if "message is not modified" in str(e):
            return
        print(f"[Бонус старт] TelegramBadRequest (рендер поля бонуса): {e}")
        return

    # логируем message_id для последующей проверки
    user_bonus_requests.setdefault(user_id, []).append(send_message_bonus.message_id)


