async def infowaitingbonus_handler(callback_query: types.CallbackQuery):
    # распарсим callback_data
    _, ts = callback_query.data.split("|", 1)
    # отвечаем пользователю
    await callback_query.answer(
        f"🕊 Минуточку… бонус будет через {ts}",
        show_alert=False  # или True, если хотите модальным окном
    )



def _adm_safe_int(v, default: int = 0) -> int:
    try:
        return int(v)
    except Exception:
        return int(default)


def _adm_safe_str(v, default: str = "") -> str:
    try:
        if v is None:
            return default
        s = str(v).strip()
        return s if s else default
    except Exception:
        return default


async def _adm_safe_answer(call: types.CallbackQuery, text: str = "", show_alert: bool = False):
    try:
        await call.answer(text, show_alert=show_alert)
    except Exception:
        pass


async def _adm_safe_notify_user(user_id: int, text: str, *, effect_id: Optional[str] = None):


    try:
        await bot1(
            SendMessage(
                chat_id=user_id,
                text=text,
                message_effect_id=effect_id,
                parse_mode="HTML",disable_web_page_preview=True
            )
        )
    except Exception as e:
        print(f"[ADMIN][NOTIFY][WARN] uid={user_id} err={e!r}")


async def _adm_safe_edit_channel_message(call: types.CallbackQuery, text: str):
    try:
        await bot1.edit_message_text(
            text=text,
            chat_id=call.message.chat.id,
            message_id=call.message.message_id,
            parse_mode="HTML",
            disable_web_page_preview=True,
            reply_markup=None,
        )
        return True
    except Exception as e:
        print(f"[ADMIN][CHANNEL][EDIT][WARN] err={e!r}")
        try:
            await call.message.edit_text(
                text,
                parse_mode="HTML",
                disable_web_page_preview=True,
                reply_markup=None,
            )
            return True
        except Exception as e2:
            print(f"[ADMIN][CHANNEL][EDIT][WARN2] err={e2!r}")
            return False


def _salary_mark_all_tokens_done(prow: dict, admin_id: int, final_status: str) -> None:
    """Закрывает 👍/👎/🥂 одной зарплатной заявки — как у обычного вывода."""
    for key in ("approve_token", "reject_token", "refund_token"):
        t = _wd_safe_str(prow.get(key), "")
        if t:
            _mark_admin_withdraw_action_done(t, admin_id, final_status)


async def _salary_build_people_display(
    *,
    user_id: int,
    username: str,
    first_name: str,
) -> str:
    uname = _wd_normalize_username(username)
    disp = (first_name or uname or str(user_id)).strip()
    if user_id > 0:
        try:
            link = await create_user_link(user_id, disp, uname or None)
            if link:
                base = str(link)
            else:
                base = f'<a href="tg://user?id={user_id}">{escape(disp)}</a>'
        except Exception:
            base = f'<a href="tg://user?id={user_id}">{escape(disp)}</a>'
    else:
        base = escape(disp)
    if uname:
        return f"{base} (@{escape(uname)})"
    return base


