# =========================================================
# ADMIN ACTION REGISTRY
# =========================================================
# КРИТИЧЕСКОЕ ИЗМЕНЕНИЕ:
# pending-заявки НЕ удаляются по TTL.
# Они активны, пока админ не нажмёт кнопку.
#
# Чистим только:
# - done / completed / rejected / refunded / cancelled
# - очень старые мусорные записи
# =========================================================

ADMIN_WITHDRAW_ACTIONS: Dict[str, Dict[str, Any]] = LazyGameStore("admin_withdraw_actions")

# Через сколько можно чистить уже ЗАВЕРШЁННЫЕ заявки
ADMIN_ACTION_DONE_TTL = 60 * 60 * 24 * 14      # 14 дней
# Аварийная чистка совсем древнего мусора
ADMIN_ACTION_HARD_TTL = 60 * 60 * 24 * 60      # 60 дней


def _wd_now_ts() -> int:
    return int(time.time())


def _wd_safe_int(value, default: int = 0) -> int:
    try:
        return int(value)
    except Exception:
        return int(default)


def _wd_safe_float(value, default: float = 0.0) -> float:
    try:
        return float(value)
    except Exception:
        return float(default)


def _wd_safe_str(value, default: str = "") -> str:
    try:
        if value is None:
            return default
        s = str(value).strip()
        return s if s else default
    except Exception:
        return default


def _wd_fmt_amount(value: int) -> str:
    try:
        if "_fmt_int" in globals() and callable(globals().get("_fmt_int")):
            return _fmt_int(int(value))
    except Exception:
        pass

    try:
        return f"{int(value):,}".replace(",", ".")
    except Exception:
        return str(value)


def _wd_normalize_username(username: Optional[str]) -> str:
    raw = _wd_safe_str(username, "")
    if not raw:
        return ""
    raw = raw.lstrip("@").strip()
    if re.fullmatch(r"[A-Za-z0-9_]{5,32}", raw):
        return raw
    return ""


def _wd_build_username_tag(username: Optional[str], user_id: int) -> str:
    uname = _wd_normalize_username(username)
    if uname:
        return f"@{uname}"
    return f"user_id {user_id}"


def _cleanup_admin_withdraw_actions() -> None:
    now = _wd_now_ts()
    to_delete: List[str] = []

    for token, payload in list(ADMIN_WITHDRAW_ACTIONS.items()):
        try:
            if not isinstance(payload, dict):
                to_delete.append(token)
                continue

            created_at = _wd_safe_int(payload.get("created_at"), 0)
            updated_at = _wd_safe_int(payload.get("updated_at"), created_at)
            status = _wd_safe_str(payload.get("status"), "pending").lower()

            age_from_create = now - created_at if created_at > 0 else 10**9
            age_from_update = now - updated_at if updated_at > 0 else age_from_create

            # pending никогда не чистим по обычному TTL
            if status == "pending":
                # только очень древний мусор чистим аварийно
                if age_from_create > ADMIN_ACTION_HARD_TTL:
                    to_delete.append(token)
                continue

            # завершённые можно чистить через отдельный retention
            if status in {"done", "completed", "rejected", "refunded", "cancelled", "failed"}:
                if age_from_update > ADMIN_ACTION_DONE_TTL:
                    to_delete.append(token)
                continue

            # processing может зависнуть при редкой аварии.
            # В таком случае возвращаем токен в pending, чтобы кнопка снова работала.
            if status == "processing":
                if age_from_update > 20:
                    payload["status"] = "pending"
                    payload["updated_at"] = now
                    payload["pressed_at"] = 0
                    payload["pressed_by"] = 0
                    ADMIN_WITHDRAW_ACTIONS[token] = payload
                    print(
                        f"[WITHDRAW][REGISTRY] recover token={token!r} "
                        f"status='processing' -> 'pending'"
                    )
                continue

            # неизвестные статусы - аварийная чистка
            if age_from_create > ADMIN_ACTION_HARD_TTL:
                to_delete.append(token)

        except Exception as e:
            print(f"[WITHDRAW][REGISTRY][WARN] cleanup parse token={token!r} err={e!r}")
            to_delete.append(token)

    for token in to_delete:
        try:
            ADMIN_WITHDRAW_ACTIONS.pop(token, None)
        except Exception as e:
            print(f"[WITHDRAW][REGISTRY][WARN] cleanup pop token={token!r} err={e!r}")


def _register_admin_withdraw_action(payload: Dict[str, Any]) -> str:
    _cleanup_admin_withdraw_actions()

    token = uuid.uuid4().hex[:24]
    now = _wd_now_ts()

    ADMIN_WITHDRAW_ACTIONS[token] = {
        **dict(payload or {}),
        "token": token,
        "status": "pending",
        "created_at": now,
        "updated_at": now,
        "pressed_at": 0,
        "pressed_by": 0,
    }

    print(f"[WITHDRAW][REGISTRY] register token={token} status='pending'")
    return token


def _get_admin_withdraw_action(token: str) -> Optional[Dict[str, Any]]:
    _cleanup_admin_withdraw_actions()

    token = _wd_safe_str(token, "")
    if not token:
        return None

    payload = ADMIN_WITHDRAW_ACTIONS.get(token)
    if not isinstance(payload, dict):
        return None

    status = _wd_safe_str(payload.get("status"), "pending").lower()
    if status != "pending":
        print(f"[WITHDRAW][REGISTRY] token={token} ignored because status={status!r}")
        return None

    return payload


def _touch_admin_withdraw_action(token: str, **fields) -> None:
    token = _wd_safe_str(token, "")
    if not token:
        return

    payload = ADMIN_WITHDRAW_ACTIONS.get(token)
    if not isinstance(payload, dict):
        return

    payload.update(fields or {})
    payload["updated_at"] = _wd_now_ts()
    ADMIN_WITHDRAW_ACTIONS[token] = payload


def _mark_admin_withdraw_action_processing(token: str, admin_id: int) -> None:
    _touch_admin_withdraw_action(
        token,
        status="processing",
        pressed_at=_wd_now_ts(),
        pressed_by=_wd_safe_int(admin_id, 0),
    )


def _mark_admin_withdraw_action_done(token: str, admin_id: int, final_status: str) -> None:
    final_status = _wd_safe_str(final_status, "done").lower()
    if final_status not in {"done", "completed", "rejected", "refunded", "cancelled", "failed"}:
        final_status = "done"

    _touch_admin_withdraw_action(
        token,
        status=final_status,
        pressed_at=_wd_now_ts(),
        pressed_by=_wd_safe_int(admin_id, 0),
    )


def _pop_admin_withdraw_action(token: str) -> Optional[Dict[str, Any]]:
    # Мягкое удаление лучше не делать здесь сразу.
    # Но если тебе нужно мгновенное физическое удаление - оставляем возможность.
    token = _wd_safe_str(token, "")
    if not token:
        return None
    try:
        return ADMIN_WITHDRAW_ACTIONS.pop(token, None)
    except Exception:
        return None


# =========================================================
# SEND REQUEST ACTION REGISTRY
# Если используешь это для ДРУГИХ сценариев - тоже убираем TTL
# для pending-элементов.
# =========================================================
SEND_REQUEST_ACTIONS: Dict[str, Dict[str, Any]] = LazyGameStore("SEND_REQUEST_ACTIONS")
SEND_REQUEST_ACTION_DONE_TTL = 60 * 60 * 24 * 14
SEND_REQUEST_ACTION_HARD_TTL = 60 * 60 * 24 * 20


def _cleanup_send_request_actions() -> None:
    now = _wd_now_ts()
    expired = []

    for token, payload in list(SEND_REQUEST_ACTIONS.items()):
        try:
            if not isinstance(payload, dict):
                expired.append(token)
                continue

            status = _wd_safe_str(payload.get("status"), "pending").lower()
            created_at = _wd_safe_int(payload.get("created_at"), 0)
            updated_at = _wd_safe_int(payload.get("updated_at"), created_at)

            age_created = now - created_at if created_at > 0 else 10**9
            age_updated = now - updated_at if updated_at > 0 else age_created

            if status == "pending":
                if age_created > SEND_REQUEST_ACTION_HARD_TTL:
                    expired.append(token)
                continue

            if status in {"done", "completed", "cancelled", "failed"}:
                if age_updated > SEND_REQUEST_ACTION_DONE_TTL:
                    expired.append(token)
                continue

            if age_created > SEND_REQUEST_ACTION_HARD_TTL:
                expired.append(token)

        except Exception:
            expired.append(token)

    for token in expired:
        SEND_REQUEST_ACTIONS.pop(token, None)


def _register_send_request_action(payload: Dict[str, Any]) -> str:
    _cleanup_send_request_actions()
    token = uuid.uuid4().hex[:24]
    now = _wd_now_ts()
    row = {
        **dict(payload or {}),
        "token": token,
        "status": "pending",
        "created_at": now,
        "updated_at": now,
    }
    SEND_REQUEST_ACTIONS[token] = row
    try:
        from bot.runtime.button_lifecycle import bind_registered_token
        bind_registered_token(SEND_REQUEST_ACTIONS, token, row, prefix="srq")
    except Exception:
        pass
    return token


def _get_send_request_action(token: str) -> Optional[Dict[str, Any]]:
    _cleanup_send_request_actions()
    token = _wd_safe_str(token, "")
    if not token:
        return None

    payload = SEND_REQUEST_ACTIONS.get(token)
    if not isinstance(payload, dict):
        return None

    status = _wd_safe_str(payload.get("status"), "pending").lower()
    if status != "pending":
        return None

    return payload


def _mark_send_request_action_done(token: str, final_status: str = "done") -> None:
    token = _wd_safe_str(token, "")
    if not token:
        return

    payload = SEND_REQUEST_ACTIONS.get(token)
    if not isinstance(payload, dict):
        return

    payload["status"] = _wd_safe_str(final_status, "done").lower()
    payload["updated_at"] = _wd_now_ts()
    SEND_REQUEST_ACTIONS[token] = payload


def _pop_send_request_action(token: str) -> Optional[Dict[str, Any]]:
    _cleanup_send_request_actions()
    return SEND_REQUEST_ACTIONS.pop(_wd_safe_str(token, ""), None)


# =========================================================
# USERBOT REGISTRY
