async def _wd_resolve_person_display(
    *,
    user_id: int,
    username: Optional[str],
    first_name: Optional[str],
    fallback_text: str,
) -> str:
    uid = _wd_safe_int(user_id, 0)
    uname = _wd_safe_str(username, "")
    fname = _wd_safe_str(first_name, "")

    if not fname and uid > 0 and hasattr(db, "get_firstname_by_user_id"):
        try:
            fname = _wd_safe_str(await db.get_firstname_by_user_id(uid), "")
        except Exception as e:
            print(f"[WITHDRAW][DISPLAY][WARN] get_firstname_by_user_id err={e!r}")

    if not uname and uid > 0 and hasattr(db, "get_username_by_user_id"):
        try:
            uname = _wd_safe_str(await db.get_username_by_user_id(uid), "")
        except Exception as e:
            print(f"[WITHDRAW][DISPLAY][WARN] get_username_by_user_id err={e!r}")

    if uid > 0 and fname:
        try:
            link = await create_user_link(uid, fname, uname or None)
            if link:
                return str(link)
        except Exception as e:
            print(f"[WITHDRAW][DISPLAY][WARN] create_user_link err={e!r}")

    if uname and uname.lower() != "none":
        return uname if uname.startswith("@") else f"@{uname}"

    if fname:
        return fname

    if uid > 0:
        return f"{fallback_text} #{uid}"

    return fallback_text


async def _wd_build_recipient_name_link(recipient_user_id: int, fallback_display: str) -> str:
    recipient_name_link = fallback_display
    if recipient_user_id <= 0:
        return recipient_name_link

    first_name = ""
    username = ""

    try:
        if hasattr(db, "get_firstname_by_user_id"):
            first_name = _wd_safe_str(await db.get_firstname_by_user_id(recipient_user_id), "")
    except Exception as e:
        print(f"[WITHDRAW][WARN] get_firstname_by_user_id err={e!r}")

    try:
        if hasattr(db, "get_username_by_user_id"):
            username = _wd_safe_str(await db.get_username_by_user_id(recipient_user_id), "")
    except Exception as e:
        print(f"[WITHDRAW][WARN] get_username_by_user_id err={e!r}")

    try:
        link = await create_user_link(recipient_user_id, first_name, username or None)
        if link:
            recipient_name_link = link
    except Exception as e:
        print(f"[WITHDRAW][WARN] create_user_link err={e!r}")

    return recipient_name_link


async def _wd_render_final_channel_text(
    *,
    kind: str,
    result_flag: str,
    amount: int,
    sender_display: str,
    recipient_display: str,
    sender_user_id: int = 0,
    recipient_user_id: int = 0,
    is_friend: bool = False,
) -> str:
    amount_fmt = _wd_fmt_amount(amount)

    is_self_withdraw = (
        _wd_safe_int(sender_user_id, 0) > 0
        and _wd_safe_int(sender_user_id, 0) == _wd_safe_int(recipient_user_id, 0)
    )

    if _wd_safe_int(sender_user_id, 0) <= 0 or _wd_safe_int(recipient_user_id, 0) <= 0:
        if is_friend or str(result_flag) == "+":
            is_self_withdraw = False

    if is_self_withdraw:
        people_block = (
            f"<b><tg-emoji emoji-id='5294026527850132517'>🍬</tg-emoji> "
            f"Для {recipient_display}</b>"
        )
    else:
        people_block = (
            f"<b><tg-emoji emoji-id='5465143921912846619'>🛩</tg-emoji> "
            f"От {sender_display}</b>\n"
            f"<b><tg-emoji emoji-id='5294026527850132517'>🍬</tg-emoji> "
            f"Для {recipient_display}</b>"
        )

    if kind == "approve":
        title = "Подарок отправлен другу" if not is_self_withdraw else "Вывод выполнен"
        return (
            f"<tg-emoji emoji-id='5395325195542078574'>🍀</tg-emoji> <b>{title}</b>\n"
            f"<tg-emoji emoji-id='5449372007432985754'>🌴</tg-emoji> "
            f"<b>{amount_fmt} кут в stars "
            f"<tg-emoji emoji-id='5848259999763011021'>⭐️</tg-emoji></b>\n\n"
            f"{people_block}\n\n"
            f"<blockquote><b>@CuteGamingBot</b></blockquote>"
        )

    if kind == "refund":
        return (
            f"<tg-emoji emoji-id='5440911110838425969'>🌹</tg-emoji> "
            f"<b>Вывод отклонён, с возвратом средств</b>\n"
            f"<tg-emoji emoji-id='5449372007432985754'>🌴</tg-emoji> "
            f"<b>{amount_fmt} кут</b>\n\n"
            f"{people_block}\n\n"
            f"<blockquote><b>@CuteGamingBot</b></blockquote>"
        )

    if kind == "reject":
        return (
            f"<tg-emoji emoji-id='5420315771991497307'>🔥</tg-emoji> "
            f"<b>Вывод отклонён</b>\n"
            f"<tg-emoji emoji-id='5449372007432985754'>🌴</tg-emoji> "
            f"<b>{amount_fmt} кут</b>\n\n"
            f"{people_block}\n\n"
            f"<blockquote><b>@CuteGamingBot</b></blockquote>"
        )

    return f"<b>Неизвестное действие</b>\n{people_block}"


# =========================================================
# GIFT ERROR HELPERS
# =========================================================

def _gift_error_text(exc: Exception) -> str:
    try:
        return str(exc or "").strip()
    except Exception:
        return repr(exc)


def _gift_error_upper(exc_or_text: Any) -> str:
    try:
        if isinstance(exc_or_text, BaseException):
            s = _gift_error_text(exc_or_text)
        else:
            s = str(exc_or_text or "")
        return s.upper().strip()
    except Exception:
        return ""


def _gift_is_balance_too_low(exc_or_text: Any) -> bool:
    return "BALANCE_TOO_LOW" in _gift_error_upper(exc_or_text)


def _gift_is_usage_limited(exc_or_text: Any) -> bool:
    return "STARGIFT_USAGE_LIMITED" in _gift_error_upper(exc_or_text)


def _gift_is_invalid_recipient(exc_or_text: Any) -> bool:
    text = _gift_error_upper(exc_or_text)
    return (
        "USER_ID_INVALID" in text
        or "PEER_ID_INVALID" in text
        or "INPUT_USER_DEACTIVATED" in text
    )


def _gift_is_payment_form_issue(exc_or_text: Any) -> bool:
    text = _gift_error_upper(exc_or_text)
    return (
        "FORM_ID_INVALID" in text
        or "PAYMENT_FORM_INVALID" in text
        or "STARS_FORM" in text
        or "MESSAGE_EMPTY" in text
        or "MESSAGE_TOO_LONG" in text
        or "ENTITY_BOUNDS_INVALID" in text
        or "ENTITIES_TOO_LONG" in text
    )


def _gift_is_non_retryable_rpc(exc_or_text: Any) -> bool:
    return (
        _gift_is_balance_too_low(exc_or_text)
        or _gift_is_usage_limited(exc_or_text)
        or _gift_is_invalid_recipient(exc_or_text)
    )


def _gift_human_error(exc_or_text: Any) -> str:
    text = _gift_error_text(exc_or_text)

    if _gift_is_balance_too_low(text):
        return "На техническом юзерботе недостаточно Stars для отправки подарка"
    if _gift_is_usage_limited(text):
        return "Telegram ограничил отправку этого подарка"
    if _gift_is_invalid_recipient(text):
        return "Не удалось определить получателя подарка"
    if _gift_is_payment_form_issue(text):
        return "Telegram не принял описание подарка или форму оплаты"

    return text or "Неизвестная ошибка отправки подарка"


# =========================================================
# TELETHON CALL GUARD
# =========================================================

async def _gift_tl_call(tg_client, request_obj, *, label: str) -> Any:
    try:
        if not tg_client.is_connected():
            await tg_client.connect()
        return await tg_client(request_obj)

    except FloodWaitError:
        raise

    except RPCError as e:
        if _gift_is_non_retryable_rpc(e):
            print(f"[GIFT][TL][NONRETRY] {label} err={e!r}")
            raise

        print(f"[GIFT][TL][WARN] {label} first rpc err={e!r}")

        try:
            if not tg_client.is_connected():
                await tg_client.connect()
            return await tg_client(request_obj)
        except Exception as e2:
            print(f"[GIFT][TL][ERROR] {label} second err={e2!r}")
            raise

    except Exception as e:
        print(f"[GIFT][TL][WARN] {label} first err={e!r}")

        try:
            if not tg_client.is_connected():
                await tg_client.connect()
            return await tg_client(request_obj)
        except Exception as e2:
            print(f"[GIFT][TL][ERROR] {label} second err={e2!r}")
            raise


# =========================================================
# TELETHON / USERBOT DEBUG HELPERS
# =========================================================

def _extract_stars_balance_from_status(status_obj) -> Tuple[Optional[int], Dict[str, Any]]:
    debug: Dict[str, Any] = {
        "status_class": None,
        "balance_class": None,
        "raw_balance_repr": None,
        "parsed_from": None,
        "balance_int": None,
    }

    if status_obj is None:
        debug["error"] = "status_obj is None"
        return None, debug

    debug["status_class"] = status_obj.__class__.__name__

    balance_obj = getattr(status_obj, "balance", None)
    debug["balance_class"] = balance_obj.__class__.__name__ if balance_obj is not None else None
    debug["raw_balance_repr"] = repr(balance_obj)

    if balance_obj is None:
        debug["error"] = "balance field missing"
        return None, debug

    amount_attr = getattr(balance_obj, "amount", None)
    if amount_attr is not None:
        try:
            bal = int(amount_attr)
            debug["parsed_from"] = "balance.amount"
            debug["balance_int"] = bal
            return bal, debug
        except Exception:
            pass

    try:
        bal = int(balance_obj)
        debug["parsed_from"] = "int(balance)"
        debug["balance_int"] = bal
        return bal, debug
    except Exception:
        pass

    try:
        text = balance_obj.stringify() if hasattr(balance_obj, "stringify") else repr(balance_obj)
        m = re.search(r"amount[ =:]+(-?\d+)", text)
        if m:
            bal = int(m.group(1))
            debug["parsed_from"] = "regex(amount)"
            debug["balance_int"] = bal
            debug["raw_balance_repr"] = text
            return bal, debug
    except Exception:
        pass

    debug["error"] = "unable to parse balance"
    return None, debug


async def _gift_fetch_stars_status_safe(tg_client) -> Dict[str, Any]:
    try:
        status = await _gift_tl_call(
            tg_client,
            tl_functions.payments.GetStarsStatusRequest(peer="me"),
            label="GetStarsStatusRequest",
        )

        balance_stars, balance_debug = _extract_stars_balance_from_status(status)

        return {
            "ok": True,
            "status": status,
            "balance_stars": balance_stars,
            "debug": {
                "status_class": status.__class__.__name__,
                "status_stringify": status.stringify() if hasattr(status, "stringify") else str(status),
                "balance_debug": balance_debug,
            },
        }
    except Exception as e:
        print(f"[GIFT][STARS][WARN] get stars status err={e!r}")
        return {
            "ok": False,
            "status": None,
            "balance_stars": None,
            "debug": {"error": repr(e)},
        }


async def _gift_get_self_info_safe(tg_client) -> Dict[str, Any]:
    try:
        me = await tg_client.get_me()
        return {
            "ok": True,
            "id": _wd_safe_int(getattr(me, "id", 0), 0),
            "username": _wd_safe_str(getattr(me, "username", ""), ""),
            "first_name": _wd_safe_str(getattr(me, "first_name", ""), ""),
            "phone": _wd_safe_str(getattr(me, "phone", ""), ""),
            "raw": _wd_safe_str(repr(me), ""),
        }
    except Exception as e:
        return {"ok": False, "error": repr(e)}


