GIFT_WITHDRAW_DESCRIPTION_HTML = (
    "<tg-emoji emoji-id='5318959255385043017'>🎩</tg-emoji> "
    "<b>Элитный игровой бот на звёзды!</b> "
    "<tg-emoji emoji-id='5924870095925942277'>⭐️</tg-emoji>"
)


def _gift_is_available_for_send(gift_obj) -> bool:
    if not gift_obj:
        return False

    if bool(getattr(gift_obj, "sold_out", False)):
        return False

    limited_per_user = bool(getattr(gift_obj, "limited_per_user", False))
    per_user_remains = getattr(gift_obj, "per_user_remains", None)

    if limited_per_user and per_user_remains is not None:
        try:
            if int(per_user_remains) <= 0:
                return False
        except Exception:
            pass

    return True


def _gift_pick_by_id(gifts: List[Any], gift_id: int):
    gift_id = _wd_safe_int(gift_id, 0)
    if gift_id <= 0:
        return None

    for gift in gifts:
        gid = _wd_safe_int(getattr(gift, "id", 0), 0)
        if gid != gift_id:
            continue
        if not _gift_is_available_for_send(gift):
            return None
        return gift

    return None


def _gift_pick_exact_by_amount(gifts: List[Any], amount: int):
    amount = _wd_safe_int(amount, 0)
    if amount <= 0:
        return None

    candidates = []
    for gift in gifts:
        if not _gift_is_available_for_send(gift):
            continue

        stars = _wd_safe_int(getattr(gift, "stars", 0), 0)
        if stars == amount:
            candidates.append(gift)

    if not candidates:
        return None

    candidates.sort(
        key=lambda g: (
            bool(getattr(g, "limited_per_user", False)),
            bool(getattr(g, "require_premium", False)),
            _wd_safe_int(getattr(g, "id", 0), 0),
        )
    )
    return candidates[0]


def _gift_describe_obj(obj: Any) -> str:
    try:
        if obj is None:
            return "None"
        if hasattr(obj, "stringify"):
            return obj.stringify()
        return repr(obj)
    except Exception:
        return repr(obj)


async def _gift_get_available_gifts_safe(tg_client) -> Tuple[List[Any], Dict[str, Any]]:
    try:
        gifts_result = await _gift_tl_call(
            tg_client,
            tl_functions.payments.GetStarGiftsRequest(hash=0),
            label="GetStarGiftsRequest",
        )
        gifts = list(getattr(gifts_result, "gifts", []) or [])
        return gifts, {
            "ok": True,
            "result_class": gifts_result.__class__.__name__,
            "result_raw": _gift_describe_obj(gifts_result),
            "count": len(gifts),
        }
    except Exception as e:
        return [], {"ok": False, "error": repr(e)}


def _gift_build_message_with_entities_exact(tg_client, html_text: str):
    html_text = _wd_safe_str(html_text, "").strip()
    if not html_text:
        return None

    try:
        parser = getattr(tg_client, "parse_mode", None)
        if parser and hasattr(parser, "parse"):
            parsed_text, entities = parser.parse(html_text)
            return tl_types.TextWithEntities(
                text=parsed_text or "",
                entities=entities or [],
            )
    except Exception as e:
        print(f"[GIFT][MESSAGE][WARN] exact html parse err={e!r}")

    return None


def _gift_strip_html_to_plain_text(html_text: str) -> str:
    html_text = _wd_safe_str(html_text, "").strip()
    if not html_text:
        return ""

    try:
        text = re.sub(r"<tg-emoji\b[^>]*>(.*?)</tg-emoji>", r"\1", html_text, flags=re.IGNORECASE | re.DOTALL)
        text = re.sub(r"<[^>]+>", "", text)
        text = re.sub(r"\s+", " ", text).strip()
        return text
    except Exception as e:
        print(f"[GIFT][MESSAGE][WARN] strip html err={e!r}")
        return ""


def _gift_is_message_too_long(exc_or_text: Any) -> bool:
    text = _gift_error_upper(exc_or_text)
    return "MESSAGE_TOO_LONG" in text or "MESSAGE WAS TOO LONG" in text


async def _gift_send_via_tl_fallback(
    tg_client,
    *,
    recipient_peer: Any,
    real_gift_id: int,
    include_upgrade: bool = False,
    gift_message_html: str = "",
) -> Dict[str, Any]:

    async def _build_and_send(message_obj, *, message_mode: str, message_text_used: str = "") -> Dict[str, Any]:
        invoice_kwargs = {
            "peer": recipient_peer,
            "gift_id": real_gift_id,
        }

        if include_upgrade:
            invoice_kwargs["include_upgrade"] = True

        if message_obj is not None:
            invoice_kwargs["message"] = message_obj

        invoice = tl_types.InputInvoiceStarGift(**invoice_kwargs)

        payment_form = await _gift_tl_call(
            tg_client,
            tl_functions.payments.GetPaymentFormRequest(invoice=invoice),
            label=f"GetPaymentFormRequest[{message_mode}]",
        )

        form_id = getattr(payment_form, "form_id", None)
        if form_id is None:
            return {
                "ok": False,
                "stage": "get_payment_form",
                "payment_form_class": payment_form.__class__.__name__,
                "payment_form_raw": _gift_describe_obj(payment_form),
                "error": "Не удалось получить payment form для подарка",
                "message_used": bool(message_obj is not None),
                "message_mode": message_mode,
                "message_text_used": message_text_used,
            }

        payment_result = await _gift_tl_call(
            tg_client,
            tl_functions.payments.SendStarsFormRequest(
                form_id=form_id,
                invoice=invoice,
            ),
            label=f"SendStarsFormRequest[{message_mode}]",
        )

        return {
            "ok": True,
            "stage": "send_stars_form",
            "form_id": form_id,
            "message_used": bool(message_obj is not None),
            "message_mode": message_mode,
            "message_text_used": message_text_used,
            "payment_result_class": payment_result.__class__.__name__,
            "payment_result_raw": _gift_describe_obj(payment_result),
        }

    exact_message_obj = _gift_build_message_with_entities_exact(tg_client, gift_message_html)

    if exact_message_obj is not None:
        try:
            return await _build_and_send(
                exact_message_obj,
                message_mode="exact_html",
                message_text_used=gift_message_html,
            )
        except FloodWaitError:
            raise
        except RPCError as e:
            print(f"[GIFT][MESSAGE][WARN] exact invoice message rpc err={e!r}")
            if not (_gift_is_message_too_long(e) or _gift_is_payment_form_issue(e)):
                raise
        except Exception as e:
            print(f"[GIFT][MESSAGE][WARN] exact invoice message err={e!r}")

    plain_text = _gift_strip_html_to_plain_text(gift_message_html)
    if plain_text:
        plain_message_obj = tl_types.TextWithEntities(text=plain_text, entities=[])

        try:
            return await _build_and_send(
                plain_message_obj,
                message_mode="plain_text",
                message_text_used=plain_text,
            )
        except FloodWaitError:
            raise
        except RPCError as e:
            print(f"[GIFT][MESSAGE][WARN] plain invoice message rpc err={e!r}")
            if not (_gift_is_message_too_long(e) or _gift_is_payment_form_issue(e)):
                raise
        except Exception as e:
            print(f"[GIFT][MESSAGE][WARN] plain invoice message err={e!r}")

    return await _build_and_send(
        None,
        message_mode="without_message",
        message_text_used="",
    )


async def _gift_resolve_recipient_peer(
    tg_client,
    *,
    recipient_user_id: int,
    recipient_username: str,
) -> Tuple[Any, str]:
    last_error = None

    uid = _wd_safe_int(recipient_user_id, 0)
    uname = _wd_normalize_username(recipient_username)

    print(
        f"🟦 [GIFT][RESOLVE][START] "
        f"recipient_user_id={uid} "
        f"recipient_username_raw={recipient_username!r} "
        f"recipient_username_norm={uname!r}"
    )

    if uname:
        for candidate in (uname, f"@{uname}"):
            try:
                print(f"🟦 [GIFT][RESOLVE][TRY] get_input_entity({candidate!r})")
                entity = await tg_client.get_input_entity(candidate)
                print(f"🟩 [GIFT][RESOLVE][OK] by get_input_entity username={candidate!r}")
                return entity, f"@{uname}"
            except Exception as e:
                last_error = e
                print(f"🟨 [GIFT][RESOLVE][WARN] get_input_entity({candidate!r}) failed: {e!r}")

    if uname:
        for candidate in (uname, f"@{uname}"):
            try:
                print(f"🟦 [GIFT][RESOLVE][TRY] get_entity({candidate!r})")
                full_entity = await tg_client.get_entity(candidate)

                resolved_id = _wd_safe_int(getattr(full_entity, "id", 0), 0)
                resolved_username = _wd_normalize_username(getattr(full_entity, "username", ""))

                print(
                    f"🟦 [GIFT][RESOLVE][INFO] "
                    f"get_entity -> id={resolved_id} username={resolved_username!r}"
                )

                if uid > 0 and resolved_id > 0 and resolved_id != uid:
                    print(
                        f"🟨 [GIFT][RESOLVE][WARN] "
                        f"username resolved to another user: expected_uid={uid}, actual_uid={resolved_id}"
                    )

                entity = await tg_client.get_input_entity(full_entity)

                print(f"🟩 [GIFT][RESOLVE][OK] by get_entity username={candidate!r}")
                return entity, f"@{resolved_username or uname}"

            except Exception as e:
                last_error = e
                print(f"🟨 [GIFT][RESOLVE][WARN] get_entity({candidate!r}) failed: {e!r}")

    if uid > 0:
        try:
            print(f"🟦 [GIFT][RESOLVE][TRY] get_input_entity({uid}) by user_id")
            entity = await tg_client.get_input_entity(uid)
            print(f"🟩 [GIFT][RESOLVE][OK] by cached user_id={uid}")
            return entity, str(uid)
        except Exception as e:
            last_error = e
            print(f"🟨 [GIFT][RESOLVE][WARN] get_input_entity({uid}) failed: {e!r}")

    try:
        print("🟦 [GIFT][RESOLVE][TRY] iter_dialogs scan started")
        async for dialog in tg_client.iter_dialogs():
            ent = getattr(dialog, "entity", None)
            if not ent:
                continue

            ent_id = _wd_safe_int(getattr(ent, "id", 0), 0)
            ent_username = _wd_normalize_username(getattr(ent, "username", ""))

            if uid > 0 and ent_id == uid:
                try:
                    entity = await tg_client.get_input_entity(ent)
                    print(f"🟩 [GIFT][RESOLVE][OK] resolved from dialogs by id={uid}")
                    return entity, str(uid)
                except Exception as e:
                    last_error = e
                    print(f"🟨 [GIFT][RESOLVE][WARN] dialogs/id failed: {e!r}")

            if uname and ent_username and ent_username.lower() == uname.lower():
                try:
                    entity = await tg_client.get_input_entity(ent)
                    print(f"🟩 [GIFT][RESOLVE][OK] resolved from dialogs by username=@{uname}")
                    return entity, f"@{uname}"
                except Exception as e:
                    last_error = e
                    print(f"🟨 [GIFT][RESOLVE][WARN] dialogs/username failed: {e!r}")

    except Exception as e:
        print(f"🟨 [GIFT][RESOLVE][WARN] iter_dialogs failed: {e!r}")

    if uname:
        raise RuntimeError(
            "Не удалось определить получателя подарка через withdraw userbot. "
            f"Переданы данные: user_id={uid or 'unknown'}, username=@{uname}. "
            "Технический аккаунт не смог получить input entity этого пользователя."
        )

    raise RuntimeError(
        "Не удалось определить получателя подарка: "
        f"для user_id={uid} отсутствует доступный input entity. "
        "Желательно передавать корректный username получателя."
    )


def _gift_humanize_internal_exception(exc: Exception) -> str:
    text = str(exc or "").strip()

    if "Could not find the input entity" in text or "Не удалось определить получателя подарка" in text:
        return (
            "Технический аккаунт для выводов пока не смог определить получателя. "
            "Обычно это происходит, когда у получателя нет username, username передан некорректно "
            "или технический аккаунт ещё не встречал этого пользователя."
        )

    return f"Внутренняя ошибка gift executor: {exc}"


def _gift_result(
    *,
    ok: bool,
    provider: str = "userbot",
    error: str = "",
    provider_result: Optional[dict] = None,
    gift_title: str = "",
    recipient_resolved: str = "",
    gift_id: int = 0,
    gift_stars: int = 0,
    message_used: bool = False,
    message_mode: str = "",
    fallback_description_sent: bool = False,
) -> Dict[str, Any]:
    return {
        "ok": bool(ok),
        "provider": _wd_safe_str(provider, "userbot"),
        "error": _wd_safe_str(error, ""),
        "provider_result": provider_result or {},
        "gift_title": _wd_safe_str(gift_title, ""),
        "recipient_resolved": _wd_safe_str(recipient_resolved, ""),
        "gift_id": _wd_safe_int(gift_id, 0),
        "gift_stars": _wd_safe_int(gift_stars, 0),
        "message_used": bool(message_used),
        "message_mode": _wd_safe_str(message_mode, ""),
        "fallback_description_sent": bool(fallback_description_sent),
    }


_gift_send_global_lock = None


def _gift_get_send_global_lock() -> asyncio.Lock:
    """
    Ленивая инициализация lock, чтобы исключить NameError
    даже если порядок загрузки модулей/блоков изменится.
    """
    global _gift_send_global_lock

    lock = _gift_send_global_lock
    if lock is None or not hasattr(lock, "acquire"):
        lock = asyncio.Lock()
        _gift_send_global_lock = lock
    return lock


async def gift_executor_send(
    request_id: str,
    sender_user_id: int,
    sender_username: str,
    sender_first_name: str,
    recipient_user_id: int,
    recipient_username: str,
    recipient_first_name: str,
    amount: int,
    is_friend: bool,
    is_self_withdraw: bool,
    gift_id: int = 0,
    has_upgrade: int = 0,
):
    started_at = int(time.time())
    amount = _wd_safe_int(amount, 0)
    preferred_gift_id = _wd_safe_int(gift_id, 0)
    include_upgrade = True if _wd_safe_int(has_upgrade, 0) == 1 else False

    recipient_user_id = _wd_safe_int(recipient_user_id, 0)
    recipient_username = _wd_normalize_username(recipient_username)
    recipient_first_name = _wd_safe_str(recipient_first_name, "")

    print(
        f"🟦 [GIFT][EXEC][START] "
        f"request_id={request_id!r} "
        f"sender_user_id={sender_user_id} "
        f"recipient_user_id={recipient_user_id} "
        f"recipient_username={recipient_username!r} "
        f"amount={amount} "
        f"preferred_gift_id={preferred_gift_id} "
        f"include_upgrade={include_upgrade}"
    )

    if amount <= 0 and preferred_gift_id <= 0:
        return _gift_result(
            ok=False,
            error="Некорректные данные: пустая сумма и gift_id",
            provider_result={
                "stage": "validate",
                "request_id": request_id,
                "amount": amount,
                "preferred_gift_id": preferred_gift_id,
                "recipient_user_id": recipient_user_id,
                "recipient_username": recipient_username,
                "started_at": started_at,
            },
        )

    async with _gift_get_send_global_lock():
        try:
            tg_client = await get_withdraw_userbot_client()

            self_info = await _gift_get_self_info_safe(tg_client)
            print(f"🟦 [GIFT][SELF] {self_info!r}")

            if not recipient_username:
                print(
                    f"🟨 [GIFT][PRECHECK][WARN] recipient_username is empty for "
                    f"user_id={recipient_user_id}. "
                    f"Resolution by id may fail if user is not known to this withdraw-session."
                )

            recipient_peer, recipient_resolved = await _gift_resolve_recipient_peer(
                tg_client,
                recipient_user_id=recipient_user_id,
                recipient_username=recipient_username,
            )

            print(f"🟩 [GIFT][EXEC][RECIPIENT] resolved={recipient_resolved!r}")

            stars_info = await _gift_fetch_stars_status_safe(tg_client)
            stars_balance = _wd_safe_int(stars_info.get("balance_stars"), -1)
            print(f"🟦 [GIFT][STARS] {stars_info!r}")

            gifts, gifts_debug = await _gift_get_available_gifts_safe(tg_client)
            if not gifts:
                return _gift_result(
                    ok=False,
                    error="Telegram не вернул доступные подарки",
                    provider_result={
                        "stage": "get_gifts",
                        "request_id": request_id,
                        "self_info": self_info,
                        "recipient_resolved": recipient_resolved,
                        "preferred_gift_id": preferred_gift_id,
                        "stars_info": stars_info,
                        "gifts_debug": gifts_debug,
                        "recipient_user_id": recipient_user_id,
                        "recipient_username": recipient_username,
                        "started_at": started_at,
                        "finished_at": int(time.time()),
                    },
                )

            selected_gift = None
            selected_by = ""

            if preferred_gift_id > 0:
                selected_gift = _gift_pick_by_id(gifts, preferred_gift_id)
                selected_by = "gift_id"

            if selected_gift is None:
                selected_gift = _gift_pick_exact_by_amount(gifts, amount)
                selected_by = "amount"

            if not selected_gift:
                return _gift_result(
                    ok=False,
                    error="Не найден подходящий подарок для отправки",
                    provider_result={
                        "stage": "pick_gift",
                        "request_id": request_id,
                        "self_info": self_info,
                        "recipient_resolved": recipient_resolved,
                        "preferred_gift_id": preferred_gift_id,
                        "amount": amount,
                        "stars_info": stars_info,
                        "gifts_debug": gifts_debug,
                        "recipient_user_id": recipient_user_id,
                        "recipient_username": recipient_username,
                        "started_at": started_at,
                        "finished_at": int(time.time()),
                    },
                )

            real_gift_id = _wd_safe_int(getattr(selected_gift, "id", 0), 0)
            gift_stars = _wd_safe_int(getattr(selected_gift, "stars", 0), 0)
            gift_title = _wd_safe_str(getattr(selected_gift, "title", ""), "")
            upgrade_stars = _wd_safe_int(getattr(selected_gift, "upgrade_stars", 0), 0)
            total_expected_stars = gift_stars + (upgrade_stars if include_upgrade else 0)

            print(
                f"🟦 [GIFT][EXEC][SELECTED] "
                f"selected_by={selected_by!r} "
                f"gift_id={real_gift_id} "
                f"gift_title={gift_title!r} "
                f"gift_stars={gift_stars} "
                f"upgrade_stars={upgrade_stars} "
                f"total_expected_stars={total_expected_stars}"
            )

            if stars_balance >= 0 and total_expected_stars > 0 and stars_balance < total_expected_stars:
                return _gift_result(
                    ok=False,
                    error=(
                        f"На техническом юзерботе недостаточно Stars: "
                        f"есть {stars_balance}, нужно {total_expected_stars}"
                    ),
                    provider_result={
                        "stage": "precheck_balance_too_low",
                        "request_id": request_id,
                        "self_info": self_info,
                        "recipient_resolved": recipient_resolved,
                        "selected_by": selected_by,
                        "preferred_gift_id": preferred_gift_id,
                        "gift_id": real_gift_id,
                        "gift_title": gift_title,
                        "gift_stars": gift_stars,
                        "upgrade_stars": upgrade_stars,
                        "include_upgrade": include_upgrade,
                        "stars_info": stars_info,
                        "gifts_debug": gifts_debug,
                        "recipient_user_id": recipient_user_id,
                        "recipient_username": recipient_username,
                        "started_at": started_at,
                        "finished_at": int(time.time()),
                    },
                    gift_title=gift_title,
                    recipient_resolved=recipient_resolved,
                    gift_id=real_gift_id,
                    gift_stars=total_expected_stars if total_expected_stars > 0 else gift_stars,
                )

            tl_result = await _gift_send_via_tl_fallback(
                tg_client=tg_client,
                recipient_peer=recipient_peer,
                real_gift_id=real_gift_id,
                include_upgrade=include_upgrade,
                gift_message_html=GIFT_WITHDRAW_DESCRIPTION_HTML,
            )

            if not tl_result.get("ok"):
                return _gift_result(
                    ok=False,
                    error=_wd_safe_str(
                        tl_result.get("error"),
                        "Не удалось отправить подарок через TL fallback",
                    ),
                    provider_result={
                        "stage": "tl_fallback_fail",
                        "request_id": request_id,
                        "self_info": self_info,
                        "recipient_resolved": recipient_resolved,
                        "selected_by": selected_by,
                        "preferred_gift_id": preferred_gift_id,
                        "gift_id": real_gift_id,
                        "gift_stars": gift_stars,
                        "gift_title": gift_title,
                        "upgrade_stars": upgrade_stars,
                        "include_upgrade": include_upgrade,
                        "tl_result": tl_result,
                        "stars_info": stars_info,
                        "gifts_debug": gifts_debug,
                        "recipient_user_id": recipient_user_id,
                        "recipient_username": recipient_username,
                        "started_at": started_at,
                        "finished_at": int(time.time()),
                    },
                    gift_title=gift_title,
                    recipient_resolved=recipient_resolved,
                    gift_id=real_gift_id,
                    gift_stars=total_expected_stars if total_expected_stars > 0 else gift_stars,
                    message_used=bool(tl_result.get("message_used")),
                    message_mode=_wd_safe_str(tl_result.get("message_mode"), ""),
                )

            provider_payload = {
                "stage": "send_stars_form",
                "request_id": request_id,
                "self_info": self_info,
                "sender_user_id": sender_user_id,
                "recipient_user_id": recipient_user_id,
                "recipient_username": recipient_username,
                "recipient_resolved": recipient_resolved,
                "selected_by": selected_by,
                "preferred_gift_id": preferred_gift_id,
                "gift_id": real_gift_id,
                "gift_stars": gift_stars,
                "gift_title": gift_title,
                "upgrade_stars": upgrade_stars,
                "include_upgrade": include_upgrade,
                "message_used": bool(tl_result.get("message_used")),
                "message_mode": _wd_safe_str(tl_result.get("message_mode"), ""),
                "message_text_used": _wd_safe_str(tl_result.get("message_text_used"), ""),
                "tl_result": tl_result,
                "stars_info": stars_info,
                "gifts_debug": gifts_debug,
                "started_at": started_at,
                "finished_at": int(time.time()),
            }

            return _gift_result(
                ok=True,
                provider="userbot",
                provider_result=provider_payload,
                gift_title=gift_title or f"Gift #{real_gift_id}",
                recipient_resolved=recipient_resolved,
                gift_id=real_gift_id,
                gift_stars=total_expected_stars if total_expected_stars > 0 else gift_stars,
                message_used=bool(tl_result.get("message_used")),
                message_mode=_wd_safe_str(tl_result.get("message_mode"), ""),
            )

        except FloodWaitError as e:
            return _gift_result(
                ok=False,
                error=f"FloodWait: нужно подождать {int(getattr(e, 'seconds', 0) or 0)} сек.",
                provider_result={
                    "stage": "rpc_floodwait_outer",
                    "request_id": request_id,
                    "seconds": int(getattr(e, 'seconds', 0) or 0),
                    "preferred_gift_id": preferred_gift_id,
                    "recipient_user_id": recipient_user_id,
                    "recipient_username": recipient_username,
                    "started_at": started_at,
                    "finished_at": int(time.time()),
                },
            )

        except RPCError as e:
            return _gift_result(
                ok=False,
                error=_gift_human_error(e),
                provider_result={
                    "stage": "rpc_error_outer",
                    "request_id": request_id,
                    "error_type": e.__class__.__name__,
                    "error_text": str(e),
                    "preferred_gift_id": preferred_gift_id,
                    "recipient_user_id": recipient_user_id,
                    "recipient_username": recipient_username,
                    "started_at": started_at,
                    "finished_at": int(time.time()),
                },
            )

        except Exception as e:
            return _gift_result(
                ok=False,
                error=_gift_humanize_internal_exception(e),
                provider_result={
                    "stage": "exception",
                    "request_id": request_id,
                    "error_type": e.__class__.__name__,
                    "error_text": repr(e),
                    "preferred_gift_id": preferred_gift_id,
                    "recipient_user_id": recipient_user_id,
                    "recipient_username": recipient_username,
                    "started_at": started_at,
                    "finished_at": int(time.time()),
                },
            )


async def _execute_gift_delivery(
    *,
    request_id: str,
    sender_user_id: int,
    sender_username: str,
    sender_first_name: str,
    recipient_user_id: int,
    recipient_username: str,
    recipient_first_name: str,
    amount: int,
    is_friend: bool,
    is_self_withdraw: bool,
    gift_id: int = 0,
    has_upgrade: int = 0,
) -> Dict[str, Any]:
    try:
        result = await gift_executor_send(
            request_id=request_id,
            sender_user_id=sender_user_id,
            sender_username=sender_username,
            sender_first_name=sender_first_name,
            recipient_user_id=recipient_user_id,
            recipient_username=recipient_username,
            recipient_first_name=recipient_first_name,
            amount=amount,
            is_friend=is_friend,
            is_self_withdraw=is_self_withdraw,
            gift_id=gift_id,
            has_upgrade=has_upgrade,
        )

        if not isinstance(result, dict):
            return {
                "ok": False,
                "provider": "userbot",
                "provider_result": {"raw": str(result)},
                "error": "Исполнитель подарка вернул некорректный ответ",
                "gift_id": 0,
                "gift_stars": 0,
                "message_used": False,
                "message_mode": "",
                "fallback_description_sent": False,
            }

        return {
            "ok": bool(result.get("ok")),
            "provider": _wd_safe_str(result.get("provider"), "userbot"),
            "provider_result": result.get("provider_result") or {},
            "error": _wd_safe_str(result.get("error"), ""),
            "gift_title": _wd_safe_str(result.get("gift_title"), "Подарок"),
            "recipient_resolved": _wd_safe_str(result.get("recipient_resolved"), ""),
            "gift_id": _wd_safe_int(result.get("gift_id"), 0),
            "gift_stars": _wd_safe_int(result.get("gift_stars"), 0),
            "message_used": bool(result.get("message_used")),
            "message_mode": _wd_safe_str(result.get("message_mode"), ""),
            "fallback_description_sent": bool(result.get("fallback_description_sent")),
        }

    except Exception as e:
        print(f"[WITHDRAW][GIFT][ERROR] executor err={e!r}")
        return {
            "ok": False,
            "provider": "userbot",
            "provider_result": {"exception": repr(e)},
            "error": f"Ошибка отправки подарка: {e}",
            "gift_id": 0,
            "gift_stars": 0,
            "message_used": False,
            "message_mode": "",
            "fallback_description_sent": False,
        }


