@dp.message(F.sticker, F.chat.type == "private")
async def _debug_sticker_file_id(message: Message):
    if message.from_user.id not in ADMIN_IDS:
        return
    st = message.sticker
    await message.reply(
        f"file_id:\n<code>{st.file_id}</code>\n\n"
        f"file_unique_id: <code>{st.file_unique_id}</code>\n"
        f"emoji: {st.emoji or '-'}",
        parse_mode="HTML",
    )


# =========================================================
# MAIN CALLBACK HANDLER
# =========================================================

@dp.callback_query(lambda call: isinstance(call.data, str) and call.data.startswith("wdact:"))
async def admin_withdraw_action_handler(call: types.CallbackQuery):
    if call.from_user.id not in ADMIN_IDS:
        await _adm_safe_answer(call, "👎", show_alert=True)
        return

    inflight = _get_admin_inflight_store()
    inflight_key = f"wdact:{getattr(call, 'id', '') or call.data}"

    if inflight_key in inflight:
        await _adm_safe_answer(call, "⏳ Уже обрабатывается", show_alert=True)
        return

    inflight.add(inflight_key)

    try:
        await _adm_safe_answer(call)

        try:
            token = str(call.data.split(":", 1)[1]).strip()
        except Exception:
            await _adm_safe_answer(call, "Ошибка данных!", show_alert=True)
            return

        payload = _get_admin_withdraw_action(token)
        if not payload:
            # Зарплатные заявки из API: токены лежат в staff_star_payouts
            try:
                prow = await db.pool.fetchrow(
                    """
                    SELECT * FROM staff_star_payouts
                    WHERE approve_token = $1 OR reject_token = $1 OR refund_token = $1
                    LIMIT 1
                    """,
                    token,
                )
                if prow and prow["status"] not in ("completed", "cancelled", "refunded"):
                    if prow["approve_token"] == token:
                        kind_db = "approve"
                    elif prow["reject_token"] == token:
                        kind_db = "reject"
                    else:
                        kind_db = "refund"
                    uname = _wd_safe_str(prow["stars_username"], "").lstrip("@")
                    uid = _wd_safe_int(prow["user_id"], 0)
                    first_name_db = ""
                    try:
                        first_name_db = _wd_safe_str(
                            await db.pool.fetchval(
                                "SELECT first_name FROM admin_accounts WHERE user_id = $1",
                                uid,
                            ),
                            "",
                        )
                    except Exception:
                        pass
                    base_payload = {
                        "request_id": _wd_safe_str(prow["request_id"], f"salstar-{prow['id']}"),
                        "sender_user_id": uid,
                        "sender_username": uname,
                        "sender_first_name": first_name_db,
                        "recipient_user_id": uid,
                        "recipient_username": uname,
                        "recipient_first_name": first_name_db,
                        "amount": _wd_safe_int(prow["amount"], 0),
                        "result_flag": "-",
                        "is_friend": False,
                        "gift_id": _wd_safe_int(prow["gift_id"], 0),
                        "gift_emoji": _wd_safe_str(prow["gift_emoji"], "⭐"),
                        "has_upgrade": _wd_safe_int(prow["has_upgrade"], 0),
                        "is_salary": True,
                        "star_payout_id": _wd_safe_int(prow["id"], 0),
                        "salary_id": _wd_safe_int(prow["salary_id"], 0),
                        "bonus_id": _wd_safe_int(prow.get("bonus_id"), 0),
                        "salary_source": _wd_safe_str(prow["source"], "salary"),
                        "part_index": _wd_safe_int(prow.get("part_index"), 0),
                        "parts_total": _wd_safe_int(prow.get("parts_total"), 0),
                    }
                    now_ts = _wd_now_ts()
                    # Прогреваем все 3 токена — как registry у обычных выводов
                    for t_kind, t_key in (
                        ("approve", "approve_token"),
                        ("reject", "reject_token"),
                        ("refund", "refund_token"),
                    ):
                        t_val = _wd_safe_str(prow.get(t_key), "")
                        if not t_val:
                            continue
                        ADMIN_WITHDRAW_ACTIONS[t_val] = {
                            **base_payload,
                            "kind": t_kind,
                            "token": t_val,
                            "status": "pending",
                            "created_at": now_ts,
                            "updated_at": now_ts,
                            "pressed_at": 0,
                            "pressed_by": 0,
                        }
                    payload = dict(ADMIN_WITHDRAW_ACTIONS.get(token) or {})
                    print(
                        f"[ADMIN][WDACT] salary tokens hydrated from DB "
                        f"payout={prow['id']} pressed={kind_db}"
                    )
            except Exception as e:
                print(f"[ADMIN][WDACT][WARN] salary db lookup err={e!r}")
                payload = None
        if not payload:
            await _adm_safe_answer(
                call,
                "Заявка не найдена, уже обработана или повреждена",
                show_alert=True,
            )
            return

        kind = _wd_safe_str(payload.get("kind"), "")
        rid = _wd_safe_str(payload.get("request_id"), "")
        sender_user_id = _wd_safe_int(payload.get("sender_user_id"), 0)
        sender_username = _wd_safe_str(payload.get("sender_username"), "")
        sender_first_name = _wd_safe_str(payload.get("sender_first_name"), "")
        recipient_user_id = _wd_safe_int(payload.get("recipient_user_id"), 0)
        recipient_username = _wd_safe_str(payload.get("recipient_username"), "")
        recipient_first_name = _wd_safe_str(payload.get("recipient_first_name"), "")
        amount = _wd_safe_int(payload.get("amount"), 0)
        result_flag = _wd_safe_str(payload.get("result_flag"), "-")
        is_friend = bool(payload.get("is_friend"))

        gift_id = _wd_safe_int(payload.get("gift_id"), 0)
        gift_emoji = _wd_safe_str(payload.get("gift_emoji"), "")
        has_upgrade = _wd_safe_int(payload.get("has_upgrade"), 0)
        is_salary = bool(payload.get("is_salary"))
        star_payout_id = _wd_safe_int(payload.get("star_payout_id"), 0)

        if sender_user_id <= 0 or amount <= 0:
            await _adm_safe_answer(call, "Ошибка данных заявки!", show_alert=True)
            return

        # -----------------------------------------------------
        # Зарплата администратора (stars) — как обычный вывод:
        # lock → atomic claim → gift/userbot → edit канала → done
        # -----------------------------------------------------
        if is_salary and star_payout_id > 0:
            salary_lock = _get_withdraw_request_lock(f"salary:{star_payout_id}")
            async with salary_lock:
                try:
                    from bot.staff_star_worker import _complete_salary_payment, _mark as _star_mark

                    # Атомарно забираем заявку (защита от двойного 👍)
                    claimed = await db.pool.fetchrow(
                        """
                        UPDATE staff_star_payouts
                        SET status = 'processing', updated_at = NOW()
                        WHERE id = $1
                          AND (
                            status IN ('channel_pending', 'queued', 'failed')
                            OR (
                              status = 'processing'
                              AND updated_at < NOW() - INTERVAL '45 seconds'
                            )
                          )
                        RETURNING *
                        """,
                        star_payout_id,
                    )
                    if not claimed:
                        cur = await db.pool.fetchrow(
                            "SELECT status FROM staff_star_payouts WHERE id = $1",
                            star_payout_id,
                        )
                        st = _wd_safe_str(cur["status"] if cur else "", "missing")
                        if st in ("completed", "cancelled", "refunded"):
                            await _adm_safe_answer(call, "⛔ Эта заявка уже обработана", show_alert=True)
                        elif st == "processing":
                            await _adm_safe_answer(call, "⏳ Уже обрабатывается", show_alert=True)
                        else:
                            await _adm_safe_answer(call, "Зарплатная заявка не найдена", show_alert=True)
                        return

                    prow = dict(claimed)
                    _mark_admin_withdraw_action_processing(token, call.from_user.id)

                    # Подтянем имя для красивого «Для …» и резолва получателя
                    try:
                        fn = await db.pool.fetchval(
                            "SELECT first_name FROM admin_accounts WHERE user_id = $1",
                            sender_user_id,
                        )
                        if fn:
                            sender_first_name = _wd_safe_str(fn, sender_first_name)
                            recipient_first_name = _wd_safe_str(fn, recipient_first_name)
                    except Exception:
                        pass

                    if not recipient_username:
                        recipient_username = sender_username
                    if recipient_user_id <= 0:
                        recipient_user_id = sender_user_id

                    gift_id = gift_id or _wd_safe_int(prow.get("gift_id"), 0)
                    gift_emoji = gift_emoji or _wd_safe_str(prow.get("gift_emoji"), "⭐")
                    has_upgrade = has_upgrade or _wd_safe_int(prow.get("has_upgrade"), 0)
                    part_n = _wd_safe_int(prow.get("part_index"), 0)
                    parts_n = _wd_safe_int(prow.get("parts_total"), 0)

                    recipient_display = await _salary_build_people_display(
                        user_id=recipient_user_id or sender_user_id,
                        username=recipient_username or sender_username,
                        first_name=recipient_first_name or sender_first_name,
                    )

                    print(
                        f"[SALARY_STARS][WDACT] kind={kind!r} payout={star_payout_id} "
                        f"amount={amount} gift_id={gift_id} part={part_n}/{parts_n} "
                        f"user={sender_user_id} @{recipient_username}"
                    )

                    if kind == "approve":
                        # Лёгкий ping как у обычных выводов
                        try:
                            await _wd_send_html(
                                sender_user_id,
                                "<tg-emoji emoji-id='5924701179157156993'>⭐️</tg-emoji>",
                            )
                        except Exception:
                            pass

                        gift_result = await _execute_gift_delivery(
                            request_id=rid or token,
                            sender_user_id=sender_user_id,
                            sender_username=sender_username,
                            sender_first_name=sender_first_name,
                            recipient_user_id=recipient_user_id or sender_user_id,
                            recipient_username=recipient_username,
                            recipient_first_name=recipient_first_name,
                            amount=amount,
                            is_friend=False,
                            is_self_withdraw=True,
                            gift_id=gift_id,
                            has_upgrade=has_upgrade,
                        )

                        if not gift_result.get("ok"):
                            err = _wd_safe_str(gift_result.get("error"), "Не удалось отправить подарок")
                            # Вернём в channel_pending — кнопки снова можно нажать
                            await _star_mark(
                                db, star_payout_id, "channel_pending",
                                error=f"gift_fail: {err}"[:400],
                            )
                            _touch_admin_withdraw_action(
                                token,
                                status="pending",
                                pressed_at=0,
                                pressed_by=0,
                            )
                            fail_txt = _salary_render_channel_final(
                                kind="fail",
                                amount=amount,
                                recipient_display=recipient_display,
                                part=part_n,
                                parts=parts_n,
                                gift_error=err,
                            )
                            # Показать ошибку, но оставить кнопки (повтор 👍)
                            try:
                                kb = call.message.reply_markup
                                await bot1.edit_message_text(
                                    text=fail_txt,
                                    chat_id=call.message.chat.id,
                                    message_id=call.message.message_id,
                                    parse_mode="HTML",
                                    disable_web_page_preview=True,
                                    reply_markup=kb,
                                )
                            except Exception as e:
                                print(f"[SALARY_STARS][FAIL_EDIT][WARN] {e!r}")
                            await _adm_safe_answer(call, f"❌ {err}", show_alert=True)
                            return

                        await _complete_salary_payment(
                            db, prow, f"userbot-{rid or token}"
                        )
                        await _star_mark(
                            db, star_payout_id, "completed",
                            txid=f"userbot-{rid or token}",
                        )
                        _salary_mark_all_tokens_done(prow, call.from_user.id, "completed")

                        amount_fmt = _wd_fmt_amount(amount)
                        await _adm_safe_notify_user(
                            sender_user_id,
                            (
                                f"<b><tg-emoji emoji-id='5463289097336405244'>⭐️</tg-emoji> "
                                f"Ваша зарплата одобрена!\n"
                                f"<tg-emoji emoji-id='6028346797368283073'>✈️</tg-emoji> "
                                f"Подарок {amount_fmt}⭐ отправлен\n\n"
                                f"<blockquote>@CuteGamingBot</blockquote></b>"
                            ),
                            effect_id="5046509860389126442",
                        )

                        final_txt = _salary_render_channel_final(
                            kind="approve",
                            amount=amount,
                            recipient_display=recipient_display,
                            part=part_n,
                            parts=parts_n,
                        )
                        await _adm_safe_edit_channel_message(call, final_txt)
                        await _adm_safe_answer(call, "✅ Зарплата выплачена", show_alert=True)
                        return

                    if kind in ("refund", "reject"):
                        new_status = "refunded" if kind == "refund" else "cancelled"
                        await _star_mark(db, star_payout_id, new_status, error=f"admin_{kind}")
                        _salary_mark_all_tokens_done(prow, call.from_user.id, new_status)

                        # Мягкий ping + DM как у обычных выводов
                        try:
                            ping = (
                                "<tg-emoji emoji-id='5195369389599265575'>🦅</tg-emoji>"
                                if kind == "refund"
                                else "<tg-emoji emoji-id='5208923808169222461'>🥀</tg-emoji>"
                            )
                            await _wd_send_html(sender_user_id, ping)
                        except Exception:
                            pass

                        if kind == "refund":
                            staff_txt = (
                                f"<b><tg-emoji emoji-id='5469963154391833732'>🍓</tg-emoji> "
                                f"Заявка на зарплату возвращена. Начисление остаётся к выплате.\n\n"
                                f"<blockquote>@CuteGamingBot</blockquote></b>"
                            )
                            effect = "5159385139981059251"
                        else:
                            staff_txt = (
                                f"<b><tg-emoji emoji-id='5469913852462242978'>🧨</tg-emoji> "
                                f"Заявка на зарплату отклонена. Начисление остаётся к выплате.\n\n"
                                f"<blockquote>@CuteGamingBot</blockquote></b>"
                            )
                            effect = "5104841245755180586"

                        await _adm_safe_notify_user(sender_user_id, staff_txt, effect_id=effect)

                        final_txt = _salary_render_channel_final(
                            kind=kind,
                            amount=amount,
                            recipient_display=recipient_display,
                            part=part_n,
                            parts=parts_n,
                        )
                        await _adm_safe_edit_channel_message(call, final_txt)
                        label = "возвращена" if kind == "refund" else "отклонена"
                        await _adm_safe_answer(call, f"🍃 Заявка {label}", show_alert=True)
                        return

                    # Неизвестный kind — откат
                    await _star_mark(db, star_payout_id, "channel_pending", error="unknown_kind")
                    _touch_admin_withdraw_action(token, status="pending", pressed_at=0, pressed_by=0)
                    await _adm_safe_answer(call, "Неизвестное действие", show_alert=True)
                    return

                except Exception as e:
                    print(f"[SALARY_STARS][WDACT][ERROR] {e!r}")
                    print(traceback.format_exc())
                    try:
                        await db.pool.execute(
                            """
                            UPDATE staff_star_payouts
                            SET status = 'channel_pending',
                                error = $2,
                                updated_at = NOW()
                            WHERE id = $1 AND status = 'processing'
                            """,
                            star_payout_id,
                            f"handler_error: {e!r}"[:400],
                        )
                    except Exception:
                        pass
                    _touch_admin_withdraw_action(
                        token, status="pending", pressed_at=0, pressed_by=0,
                    )
                    await _adm_safe_answer(call, "❌ Ошибка обработки зарплаты", show_alert=True)
                    return

        if recipient_user_id <= 0:
            recipient_user_id = sender_user_id

        sender_display = (
            f"@{_wd_normalize_username(sender_username)}"
            if _wd_normalize_username(sender_username)
            else (_wd_safe_str(sender_first_name, "") or f"Отправитель #{sender_user_id}")
        )
        recipient_display = (
            f"@{_wd_normalize_username(recipient_username)}"
            if _wd_normalize_username(recipient_username)
            else (_wd_safe_str(recipient_first_name, "") or f"Получатель #{recipient_user_id}")
        )

        try:
            sender_display = await asyncio.wait_for(
                _wd_resolve_person_display(
                    user_id=sender_user_id,
                    username=sender_username,
                    first_name=sender_first_name,
                    fallback_text="Отправитель",
                ),
                timeout=2.5,
            )
        except Exception as e:
            print(f"[ADMIN][WDACT][WARN] sender display fallback err={e!r}")

        try:
            recipient_display = await asyncio.wait_for(
                _wd_resolve_person_display(
                    user_id=recipient_user_id,
                    username=recipient_username,
                    first_name=recipient_first_name,
                    fallback_text="Получатель",
                ),
                timeout=2.5,
            )
        except Exception as e:
            print(f"[ADMIN][WDACT][WARN] recipient display fallback err={e!r}")

        is_self_withdraw = int(sender_user_id) == int(recipient_user_id)
        lock_key = rid or token
        request_lock = _get_withdraw_request_lock(lock_key)

        print(
            f"[ADMIN][WDACT] kind={kind!r} rid={rid!r} "
            f"sender_user_id={sender_user_id} recipient_user_id={recipient_user_id} "
            f"amount={amount} gift_id={gift_id} gift_emoji={gift_emoji!r} "
            f"has_upgrade={has_upgrade} sender={sender_display!r} recipient={recipient_display!r} "
            f"result_flag={result_flag!r} is_friend={is_friend} is_self_withdraw={is_self_withdraw}"
        )

        async def _safe_ping_user(user_id: int, text: str) -> None:
            try:
                await _wd_send_html(user_id, text)
            except Exception as e:
                print(f"[WITHDRAW][PING][WARN] uid={user_id} err={e!r}")

        async def _safe_channel_ping() -> None:
            try:
                await _wd_send_html(
                    -1001612636292,
                    "<tg-emoji emoji-id='5924701179157156993'>⭐️</tg-emoji>",
                )
            except Exception as e:
                print(f"[WITHDRAW][CHANNEL][WARN] tech ping err={e!r}")

        async def _safe_public_log(text: str) -> None:
            try:
                await _wd_send_html(-1001612636292, text)
            except Exception as e:
                print(f"[WITHDRAW][PUBLIC][WARN] log err={e!r}")

        async def _safe_send_gift_description(uid: int) -> bool:
            try:
                return await _wd_send_gift_description_message_safe(uid)
            except Exception as e:
                print(f"[WITHDRAW][APPROVE][WARN] gift description send err={e!r}")
                return False

        async def _finalize_success_answer(text: str) -> None:
            await _adm_safe_answer(call, text, show_alert=True)

        async def _render_and_edit_final_channel(kind_value: str) -> None:
            channel_message = await _wd_render_final_channel_text(
                kind=kind_value,
                result_flag=result_flag,
                amount=amount,
                sender_display=sender_display,
                recipient_display=recipient_display,
                sender_user_id=sender_user_id,
                recipient_user_id=recipient_user_id,
                is_friend=is_friend,
            )
            await _adm_safe_edit_channel_message(call, channel_message)

        async with request_lock:
            # защита от повторного нажатия после старта обработки
            payload_fresh = ADMIN_WITHDRAW_ACTIONS.get(token) or {}
            current_status = _wd_safe_str(payload_fresh.get("status"), "pending").lower()
            if current_status == "processing":
                updated_at = _wd_safe_int(payload_fresh.get("updated_at"), 0)
                age = _wd_now_ts() - updated_at if updated_at > 0 else 10**9
                if age > 20:
                    _touch_admin_withdraw_action(
                        token,
                        status="pending",
                        pressed_at=0,
                        pressed_by=0,
                    )
                    current_status = "pending"
                    print(f"[ADMIN][WDACT] token={token!r} recovered from stale processing")
                else:
                    await _adm_safe_answer(call, "⏳ Эта кнопка уже обрабатывается", show_alert=True)
                    return

            if current_status in {"done", "completed", "rejected", "refunded", "cancelled", "failed"}:
                await _adm_safe_answer(call, "⛔ Эта кнопка уже была обработана", show_alert=True)
                return

            try:
                _mark_admin_withdraw_action_processing(token, call.from_user.id)

                # -----------------------------------------------------
                # APPROVE
                # -----------------------------------------------------
                if kind == "approve":
                    if rid and await _wd_is_already_completed_safe(rid):
                        _mark_admin_withdraw_action_done(token, call.from_user.id, "completed")
                        await _adm_safe_answer(call, "✅ Эта заявка уже была выполнена", show_alert=True)
                        return

                    await _wd_mark_request_processing_safe(
                        request_id=rid,
                        admin_id=call.from_user.id,
                    )

                    await _safe_ping_user(
                        sender_user_id,
                        "<tg-emoji emoji-id='5924701179157156993'>⭐️</tg-emoji>",
                    )

                    gift_result = await _execute_gift_delivery(
                        request_id=rid or token,
                        sender_user_id=sender_user_id,
                        sender_username=sender_username,
                        sender_first_name=sender_first_name,
                        recipient_user_id=recipient_user_id,
                        recipient_username=recipient_username,
                        recipient_first_name=recipient_first_name,
                        amount=amount,
                        is_friend=is_friend,
                        is_self_withdraw=is_self_withdraw,
                        gift_id=gift_id,
                        has_upgrade=has_upgrade,
                    )

                    gift_ok = bool(gift_result.get("ok"))
                    gift_provider = _wd_safe_str(gift_result.get("provider"), "userbot")
                    gift_provider_result = gift_result.get("provider_result") or {}
                    gift_error = _wd_safe_str(gift_result.get("error"), "Не удалось отправить подарок")
                    real_gift_id = _wd_safe_int(gift_result.get("gift_id"), gift_id)
                    real_gift_stars = _wd_safe_int(gift_result.get("gift_stars"), 0)
                    message_used = bool(gift_result.get("message_used"))
                    message_mode = _wd_safe_str(gift_result.get("message_mode"), "")

                    print(
                        f"[WITHDRAW][APPROVE] gift_ok={gift_ok} "
                        f"preferred_gift_id={gift_id} real_gift_id={real_gift_id} "
                        f"real_gift_stars={real_gift_stars} "
                        f"message_used={message_used} message_mode={message_mode!r}"
                    )

                    if not gift_ok:
                        await _wd_mark_request_failed_safe(
                            request_id=rid,
                            admin_id=call.from_user.id,
                            error_text=gift_error,
                            provider=gift_provider,
                            provider_result=gift_provider_result,
                        )

                        _mark_admin_withdraw_action_done(token, call.from_user.id, "failed")

                        try:
                            fail_text = (
                                "<tg-emoji emoji-id='5210952531676504517'>❌</tg-emoji> "
                                "<b>Подарок не был отправлен</b>\n\n"
                                f"<b>Причина :</b> <code>{gift_error}</code>\n\n"
                                "<blockquote>Заявка НЕ закрыта как успешная.</blockquote>"
                            )
                            await _adm_safe_edit_channel_message(call, fail_text)
                        except Exception as e:
                            print(f"[WITHDRAW][APPROVE][WARN] fail edit err={e!r}")

                        await _adm_safe_answer(
                            call,
                            f"❌ Ошибка отправки подарка: {gift_error}",
                            show_alert=True,
                        )
                        return

                    await _wd_mark_request_completed_safe(
                        request_id=rid,
                        admin_id=call.from_user.id,
                        provider=gift_provider,
                        provider_result=gift_provider_result,
                    )

                    fallback_description_sent = False
                    if not message_used:
                        fallback_description_sent = await _safe_send_gift_description(recipient_user_id)

                    print(
                        f"[WITHDRAW][APPROVE][DESCRIPTION] "
                        f"message_used={message_used} "
                        f"message_mode={message_mode!r} "
                        f"fallback_description_sent={fallback_description_sent}"
                    )

                    withdrawal_text = "🎁 Обычный вывод другу" if not is_self_withdraw else "Обычный вывод"

                    try:
                        if hasattr(db, "save_withdrawal_record"):
                            await db.save_withdrawal_record(
                                user_id=call.from_user.id,
                                amount=amount,
                                withdrawal_text=withdrawal_text,
                            )
                    except Exception as e:
                        print(f"[WITHDRAW][APPROVE][WARN] save_withdrawal_record err={e!r}")

                    emoj = "<tg-emoji emoji-id='5463289097336405244'>⭐️</tg-emoji>"
                    recipient_name_link = await _wd_build_recipient_name_link(
                        recipient_user_id=recipient_user_id,
                        fallback_display=recipient_display,
                    )

                    if is_self_withdraw:
                        notify_text = (
                            f"<b>{emoj} Ваша заявка на вывод кут одобрена!\n"
                            f"<tg-emoji emoji-id='6028346797368283073'>✈️</tg-emoji> "
                            f"Подарок отправлен\n\n"
                            f"<blockquote>@CuteGamingBot</blockquote></b>"
                        )
                    else:
                        notify_text = (
                            f"<b>{emoj} Ваша заявка на вывод кут одобрена!\n"
                            f"<tg-emoji emoji-id='6028346797368283073'>✈️</tg-emoji> "
                            f"{recipient_name_link} получил свой подарок!\n\n"
                            f"<blockquote>@CuteGamingBot</blockquote></b>"
                        )

                    await _adm_safe_notify_user(
                        sender_user_id,
                        notify_text,
                        effect_id="5046509860389126442",
                    )

                    await _safe_channel_ping()

                    recipient_tag = _wd_build_username_tag(recipient_username, recipient_user_id)
                    sender_tag = _wd_build_username_tag(sender_username, sender_user_id)
                    winf = "{:,.0f}".format(amount).replace(",", ".")

                    if is_self_withdraw:
                        public_text = (
                            f"<tg-emoji emoji-id='5319106486863947724'>🎩</tg-emoji> "
                            f"<b>{recipient_tag} вывел {winf} кут в TG Stars "
                            f"<tg-emoji emoji-id='6028338546736107668'>⭐️</tg-emoji></b>"
                        )
                    else:
                        public_text = (
                            f"<tg-emoji emoji-id='5319106486863947724'>🎩</tg-emoji> "
                            f"<b>{recipient_tag} вывел {winf} кут в TG Stars "
                            f"<tg-emoji emoji-id='6028338546736107668'>⭐️</tg-emoji></b>\n"
                            f"<tg-emoji emoji-id='5355132032592669254'>🍭</tg-emoji> "
                            f"<b>От {sender_tag}</b>"
                        )

                    await _safe_public_log(public_text)
                    await _render_and_edit_final_channel("approve")

                    _mark_admin_withdraw_action_done(token, call.from_user.id, "completed")
                    await _finalize_success_answer("✅ Подарок отправлен, заявка завершена!")
                    return

                # -----------------------------------------------------
                # REFUND
                # -----------------------------------------------------
                if kind == "refund":
                    rollback_done = False

                    if rid and hasattr(db, "rollback_withdraw_strict"):
                        try:
                            rb = await db.rollback_withdraw_strict(
                                user_id=sender_user_id,
                                request_id=rid,
                            )
                            print(f"[ADMIN][REFUND] rollback_withdraw_strict -> {rb!r}")
                            if isinstance(rb, dict) and rb.get("ok"):
                                rollback_done = True
                        except Exception as e:
                            print(f"[ADMIN][REFUND][WARN] rollback err={e!r}")

                    if not rollback_done:
                        try:
                            balance = int(await db.get_user_balance(sender_user_id) or 0)
                            await db.update_user_balance(sender_user_id, balance + amount)

                            if hasattr(db, "cutehistory_plus"):
                                await db.cutehistory_plus(
                                    sender_user_id,
                                    amount,
                                    "возврат кут с заявки на вывод (fallback)",
                                )

                            print(f"[ADMIN][REFUND][FALLBACK] uid={sender_user_id} amount={amount}")
                        except Exception as e:
                            print(f"[ADMIN][REFUND][ERROR] fallback refund err={e!r}")
                            _mark_admin_withdraw_action_done(token, call.from_user.id, "failed")
                            await _adm_safe_answer(call, "❌ Не удалось вернуть куты", show_alert=True)
                            return

                    await _wd_mark_request_failed_safe(
                        request_id=rid,
                        admin_id=call.from_user.id,
                        error_text="refunded_by_admin",
                        provider="manual",
                        provider_result={
                            "action": "refund",
                            "rollback_done": bool(rollback_done),
                        },
                    )

                    await _safe_ping_user(
                        sender_user_id,
                        "<tg-emoji emoji-id='5195369389599265575'>🦅</tg-emoji>",
                    )

                    emoj = "<tg-emoji emoji-id='5469963154391833732'>🍓</tg-emoji>"
                    await _adm_safe_notify_user(
                        sender_user_id,
                        f"<b>{emoj} Ваша заявка на вывод кут отклонена! Куты возвращены\n\n"
                        f"<blockquote>@CuteGamingBot</blockquote></b>",
                        effect_id="5159385139981059251",
                    )

                    await _render_and_edit_final_channel("refund")
                    _mark_admin_withdraw_action_done(token, call.from_user.id, "refunded")
                    await _finalize_success_answer("🍃 Заявка отклонена, куты возвращены")
                    return

                # -----------------------------------------------------
                # REJECT
                # -----------------------------------------------------
                if kind == "reject":
                    await _wd_mark_request_failed_safe(
                        request_id=rid,
                        admin_id=call.from_user.id,
                        error_text="rejected_by_admin",
                        provider="manual",
                        provider_result={"action": "reject"},
                    )

                    await _safe_ping_user(
                        sender_user_id,
                        "<tg-emoji emoji-id='5208923808169222461'>🥀</tg-emoji>",
                    )

                    emoj = "<tg-emoji emoji-id='5469913852462242978'>🧨</tg-emoji>"
                    await _adm_safe_notify_user(
                        sender_user_id,
                        f"<b>{emoj} Ваша заявка на вывод кут отклонена!\n\n"
                        f"<blockquote>@CuteGamingBot</blockquote></b>",
                        effect_id="5104841245755180586",
                    )

                    await _render_and_edit_final_channel("reject")
                    _mark_admin_withdraw_action_done(token, call.from_user.id, "rejected")
                    await _finalize_success_answer("🍃 Заявка отклонена")
                    return

                _mark_admin_withdraw_action_done(token, call.from_user.id, "failed")
                await _adm_safe_answer(call, "Неизвестное действие", show_alert=True)

            except Exception as e:
                _mark_admin_withdraw_action_done(token, call.from_user.id, "failed")
                print(
                    f"[ADMIN][WDACT][ERROR] token={token!r} kind={kind!r} "
                    f"rid={rid!r} err={type(e).__name__}: {e!r}"
                )
                print(traceback.format_exc())
                await _adm_safe_answer(call, "❌ Ошибка обработки кнопки", show_alert=True)
                return

    finally:
        inflight.discard(inflight_key)
@dp.callback_query(lambda c: c.data.startswith('9close_bonus'))
async def close_bonus_callback(callback_query: types.CallbackQuery):
    # Заблокированный пользователь не возвращается в стартовое меню.
    try:
        if await _safe_is_user_banned(callback_query.from_user.id):
            await callback_query.answer("❗️ Вы заблокированы в боте", show_alert=True)
            return
    except Exception as e:
        print(f"[START][BAN][ERROR] is_user_banned: {type(e).__name__}: {e!r}")

    await callback_query.answer()
    data = callback_query.data  # btninsert_{bet_amount}_+  или btninsert_{bet_amount}

    # Проверяем, есть ли "+"
    is_plus = data.endswith("_+")

    # Извлекаем сумму ставки (без "_+")

    user_id = callback_query.from_user.id

    # Закрыли бонус - возвращаем на тот же главный экран, что и /start.
    from bot.funcs.onboarding import show_home
    if is_plus:
        await callback_query.message.delete()
    if await show_home(callback_query.message, user_id, as_new=is_plus):
        message_state [ callback_query.message.from_user.id ] = callback_query.message.message_id
        return

    try:
        subscription_status = await db.get_user_subscription(user_id)
    except Exception as e:
        print(f"Ошибка при получении статуса подписки для пользователя {user_id}: {e}")
        subscription_status = 0  # Устанавливаем значение по умолчанию в случае ошибки

    # Запасной вариант: старое стартовое меню.
    markup_start = await create_start_inline_markup(subscription_status, user_id, db)
    if is_plus:
        sent_message = await callback_query.message.answer("<tg-emoji emoji-id='5318959255385043017'>🎩</tg-emoji>" , reply_markup=markup_start, parse_mode="HTML")
    else:
        try:
            sent_message = await callback_query.message.edit_text("<tg-emoji emoji-id='5318959255385043017'>🎩</tg-emoji>" , reply_markup=markup_start, parse_mode="HTML")
        except aiogram.exceptions.TelegramBadRequest as e:
            if "message is not modified" in str(e):
                # Игнорируем эту конкретную ошибку
                sent_message = callback_query.message
            else:
                raise  # Пробрасываем остальные ошибки


    # Сохраняем ID сообщения125121251
    message_id = sent_message.message_id

    bns_add_request(user_id , sent_message.message_id , reason="# Сохраняем ID сообщения125121251")
    message_state [ callback_query.message.from_user.id ] = sent_message.message_id

































