# CONFIG
BONUS_DEBUG = True

BONUS_REQ_TTL = 20 * 60              # whitelist message_id ttl
BONUS_DEBOUNCE_WINDOW = 0.9          # быстрые повторы - молча игнор
BONUS_AWARD_LOCK_TTL = 6.0           # lock ТОЛЬКО на начисление

MAX_CB_TOAST_PER_FLOW = 1            # максимум 1 toast в одном клике
MAX_CB_ALERT_PER_FLOW = 1            # максимум 1 alert в одном клике


def bns_dbg(msg: str) -> None:
    if BONUS_DEBUG:
        print(msg)


def bns_now_ts() -> float:
    return float(time.time())


# ─────────────────────────────────────────────────────────────
# STORES (LazyGameStore устойчив к перезапускам)
# user_id -> {message_id: ts}
_user_bonus_requests: Dict[int, Dict[int, float]] = LazyGameStore("_user_bonus_requests")

# debounce: "uid:mid" -> {"ts": float}
_bonus_last_click_by_key: Dict[str, Dict[str, float]] = LazyGameStore("_bonus_last_click_by_key")

# award lock: uid -> {"ts": float}
_bonus_award_lock: Dict[int, Dict[str, float]] = LazyGameStore("_bonus_award_lock")


def bns_mk_key(user_id: int, message_id: int) -> str:
    return f"{int(user_id)}:{int(message_id)}"


def bns_cleanup_ttl_store(store: Dict, ttl: float) -> None:
    try:
        now = bns_now_ts()
        to_del = []
        for k, meta in list(store.items()):
            try:
                ts = float(meta.get("ts", 0.0)) if isinstance(meta, dict) else float(meta)
            except Exception:
                ts = 0.0
            if (now - ts) > ttl:
                to_del.append(k)
        for k in to_del:
            store.pop(k, None)
    except Exception as e:
        bns_dbg(f"[BONUS][TTL][ERROR] cleanup err={e}")


def bns_is_debounced(user_id: int, message_id: int) -> bool:
    """
    True -> слишком быстрый повтор.
    Если на пользователе висит AWARD_LOCK - debounce не блокирует (иначе пользователь не может повторить клик).
    """
    try:
        uid = int(user_id)
        mid = int(message_id)

        # если лок активен - НЕ дебаунсим
        lock_meta = _bonus_award_lock.get(uid)
        if isinstance(lock_meta, dict) and lock_meta.get("ts"):
            return False

        key = bns_mk_key(uid, mid)
        bns_cleanup_ttl_store(_bonus_last_click_by_key, ttl=15.0)
        now = bns_now_ts()

        meta = _bonus_last_click_by_key.get(key)
        if meta:
            last_ts = float(meta.get("ts", 0.0)) if isinstance(meta, dict) else float(meta)
            if (now - last_ts) < BONUS_DEBOUNCE_WINDOW:
                bns_dbg(f"[BONUS][DEBOUNCE] ⏱ Повтор слишком быстрый -> debounce (uid={uid} mid={mid})")
                return True

        _bonus_last_click_by_key[key] = {"ts": now}
        return False
    except Exception as e:
        bns_dbg(f"[BONUS][DEBOUNCE][ERROR] {e}")
        return False


def bns_try_award_lock(user_id: int) -> bool:
    """
    Самолечение lock:
    - lock живёт в LazyGameStore и переживает рестарты
    - если "старый" -> снимаем и продолжаем
    """
    try:
        uid = int(user_id)
        now = bns_now_ts()

        bns_cleanup_ttl_store(_bonus_award_lock, ttl=BONUS_AWARD_LOCK_TTL)

        meta = _bonus_award_lock.get(uid)
        if meta:
            try:
                ts = float(meta.get("ts", 0.0)) if isinstance(meta, dict) else float(meta)
            except Exception:
                ts = 0.0

            age = now - ts
            heal_after = max(3.0, float(BONUS_AWARD_LOCK_TTL) * 1.2)

            if age >= heal_after:
                _bonus_award_lock.pop(uid, None)
                bns_dbg(f"[BONUS][AWARD_LOCK] 🧠 Самолечение: снял залипший lock (uid={uid}, age={age:.2f}s)")
            else:
                bns_dbg(f"[BONUS][AWARD_LOCK] 🔒 Уже идёт начисление (uid={uid}, age={age:.2f}s)")
                return False

        _bonus_award_lock[uid] = {"ts": now}
        bns_dbg(f"[BONUS][AWARD_LOCK] ✅ lock взят (uid={uid})")
        return True

    except Exception as e:
        bns_dbg(f"[BONUS][AWARD_LOCK][ERROR] {e}")
        return True


def bns_unlock_award_lock(user_id: int) -> None:
    try:
        uid = int(user_id)
        _bonus_award_lock.pop(uid, None)
        bns_dbg(f"[BONUS][AWARD_LOCK] 🔓 lock снят (uid={uid})")
    except Exception as e:
        bns_dbg(f"[BONUS][AWARD_LOCK][ERROR] unlock err={e}")


# ─────────────────────────────────────────────────────────────
# WHITELIST message_id helpers
def bns_add_request(user_id: int, message_id: int, reason: str = "") -> None:
    try:
        uid = int(user_id)
        mid = int(message_id)
        now = bns_now_ts()
        d = _user_bonus_requests.get(uid) or {}
        d[mid] = now
        _user_bonus_requests[uid] = d
        bns_dbg(f"[BONUS][STORE] ✅ add_request uid={uid} mid={mid} reason={reason} size={len(d)}")
    except Exception as e:
        bns_dbg(f"[BONUS][STORE][ERROR] add_request err={e}")


def bns_cleanup_user(user_id: int) -> None:
    try:
        uid = int(user_id)
        d = _user_bonus_requests.get(uid)
        if not d:
            return
        now = bns_now_ts()
        to_del: List[int] = []
        for mid, ts in list(d.items()):
            try:
                if (now - float(ts)) > BONUS_REQ_TTL:
                    to_del.append(int(mid))
            except Exception:
                to_del.append(int(mid))

        for mid in to_del:
            d.pop(mid, None)

        if not d:
            _user_bonus_requests.pop(uid, None)
        else:
            _user_bonus_requests[uid] = d

        if to_del:
            bns_dbg(f"[BONUS][STORE] 🧹 cleanup_user uid={uid} removed={len(to_del)} left={len(_user_bonus_requests.get(uid, {}))}")
    except Exception as e:
        bns_dbg(f"[BONUS][STORE][ERROR] cleanup_user err={e}")


def bns_is_allowed(user_id: int, message_id: int) -> bool:
    try:
        uid = int(user_id)
        mid = int(message_id)
        bns_cleanup_user(uid)
        d = _user_bonus_requests.get(uid)
        ok = bool(d and mid in d)
        bns_dbg(f"[BONUS][STORE] is_allowed uid={uid} mid={mid} -> {ok}")
        return ok
    except Exception as e:
        bns_dbg(f"[BONUS][STORE][ERROR] is_allowed err={e}")
        return False


def bns_remove_request(user_id: int, message_id: int, reason: str = "") -> None:
    try:
        uid = int(user_id)
        mid = int(message_id)
        d = _user_bonus_requests.get(uid)
        if not d:
            return
        d.pop(mid, None)
        if not d:
            _user_bonus_requests.pop(uid, None)
        else:
            _user_bonus_requests[uid] = d
        bns_dbg(f"[BONUS][STORE] 🧽 remove_request uid={uid} mid={mid} reason={reason}")
    except Exception as e:
        bns_dbg(f"[BONUS][STORE][ERROR] remove_request err={e}")


def bns_dump_user(user_id: int) -> None:
    if not BONUS_DEBUG:
        return
    try:
        uid = int(user_id)
        bns_cleanup_user(uid)
        bns_dbg(f"[BONUS][STORE][DUMP] uid={uid} requests={_user_bonus_requests.get(uid)}")
    except Exception as e:
        bns_dbg(f"[BONUS][STORE][ERROR] dump_user err={e}")


