# cb.answer budget (как ограничитель спама)
class CbAnswerBudget:
    def __init__(self) -> None:
        self.toast_left = MAX_CB_TOAST_PER_FLOW
        self.alert_left = MAX_CB_ALERT_PER_FLOW

    async def toast(self, cb: types.CallbackQuery, text: str) -> bool:
        if self.toast_left <= 0:
            return False
        try:
            await cb.answer(text, show_alert=False)
            self.toast_left -= 1
            bns_dbg(f"[BONUS][ANSWER] toast -> {text!r}")
            return True
        except Exception as e:
            bns_dbg(f"[BONUS][ANSWER][TOAST][ERROR] {e}")
            return False

    async def alert(self, cb: types.CallbackQuery, text: str) -> bool:
        if self.alert_left <= 0:
            return False
        try:
            await cb.answer(text, show_alert=True)
            self.alert_left -= 1
            bns_dbg(f"[BONUS][ANSWER] alert -> {text!r}")
            return True
        except Exception as e:
            bns_dbg(f"[BONUS][ANSWER][ALERT][ERROR] {e}")
            return False


# ─────────────────────────────────────────────────────────────
# render helpers
async def bns_safe_answer(cb: types.CallbackQuery, text: str, alert: bool = False) -> bool:
    try:
        await cb.answer(text, show_alert=alert)
        bns_dbg(f"[BONUS][ANSWER] {'ALERT' if alert else 'TOAST'} {text!r}")
        return True
    except Exception as e:
        bns_dbg(f"[BONUS][ANSWER][ERROR] {e}")
        return False


async def bns_render_to_message_or_fallback_reply(
    *,
    cb: types.CallbackQuery,
    message: types.Message,
    text: str,
    kb: Optional[InlineKeyboardMarkup],
    prefer_edit: bool,
) -> Optional[types.Message]:
    await bns_safe_answer(cb, "💭 Обновляю сообщение…", alert=False)

    if prefer_edit:
        try:
            return await message.edit_text(
                text,
                reply_markup=kb,
                parse_mode=ParseMode.HTML,
                disable_web_page_preview=True,
            )
        except TelegramBadRequest as e:
            if "message is not modified" in str(e).lower():
                bns_dbg("[BONUS][RENDER] message is not modified -> оставляю как есть")
                return message
            bns_dbg(f"[BONUS][RENDER][WARN] edit_text failed -> fallback reply: {e}")
        except Exception as e:
            bns_dbg(f"[BONUS][RENDER][WARN] edit_text err -> fallback reply: {e}")

    try:
        return await message.reply(
            text,
            reply_markup=kb,
            parse_mode=ParseMode.HTML,
            disable_web_page_preview=True,
        )
    except Exception as e:
        bns_dbg(f"[BONUS][RENDER][ERROR] reply failed: {e}")
        await bns_safe_answer(cb, "💭 Не удалось отправить сообщение. Попробуйте позже.", alert=True)
        return None


# ─────────────────────────────────────────────────────────────
# time parsing
def bns_to_unix_ts(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, datetime):
        try:
            return float(value.timestamp())
        except Exception:
            return None
    if isinstance(value, (int, float)):
        try:
            return float(value)
        except Exception:
            return None
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None
        try:
            return float(s)
        except ValueError:
            pass
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M:%S.%f"):
            try:
                return float(datetime.strptime(s, fmt).timestamp())
            except ValueError:
                continue
        try:
            return float(datetime.fromisoformat(s).timestamp())
        except Exception:
            return None
    return None


# ─────────────────────────────────────────────────────────────
# SUBS GATE
async def bns_subs_gate_bonus(
    *,
    callback_query: types.CallbackQuery,
    message: types.Message,
    user_id: int,
    required_chats: List[Union[int, str]],
    original_data: str,
) -> bool:
    bns_dbg("────────────────────────────────────────────")
    bns_dbg(f"[БОНУС][ПОДПИСКИ] ▶️ Проверка подписок | user_id={user_id} chats={required_chats!r}")

    subs = await check_user_subscriptions(bot1, user_id, required_chats)

    if subs is True:
        bns_dbg("[БОНУС][ПОДПИСКИ] ✅ subs=True (всё ок)")
        return True

    if not isinstance(subs, list):
        bns_dbg(f"[БОНУС][ПОДПИСКИ] ❌ subs неожиданный тип: {type(subs).__name__} -> {subs!r}")
        await bns_safe_answer(callback_query, "⚠️ Не удалось проверить подписки. Подробности в логах.", alert=True)
        return False

    bns_dbg(f"[БОНУС][ПОДПИСКИ] ❗ проблем={len(subs)}")
    for i, info in enumerate(subs, start=1):
        bns_dbg(
            f"  {i}) chat_id={info.get('chat_id')!r} title={info.get('title')!r} username={info.get('username')!r} "
            f"reason={info.get('reason')!r} status={info.get('status')!r} error={info.get('error')!r}"
        )

    joinable_infos = [info for info in subs if info.get("reason") == "not_member" and info.get("username")]
    unsub_ids = [info.get("chat_id") for info in joinable_infos]
    bns_dbg(f"[БОНУС][ПОДПИСКИ] joinable(not_member+username)={len(joinable_infos)} unsub_ids={unsub_ids!r}")

    if not unsub_ids:
        await bns_safe_answer(
            callback_query,
            "⚠️ Бот не может проверить подписку в одном из каналов/групп.\n"
            "Обычно нужно добавить бота админом или открыть список участников.\n"
            "Подробности в логах.",
            alert=True
        )
        return False

    await bns_safe_answer(callback_query, "Подпишитесь на каналы и нажмите «Проверить подписку».", alert=True)

    rows: List[List[InlineKeyboardButton]] = []
    temp: List[InlineKeyboardButton] = []
    for info in joinable_infos:
        title = str(info.get("title") or info.get("chat_id"))
        username = info.get("username")
        if not username:
            continue
        temp.append(InlineKeyboardButton(text=f"{title}", url=f"https://t.me/{username}", style="default",
                                         icon_custom_emoji_id="6028171274939797252"))
        if len(temp) == 2:
            rows.append(temp)
            temp = []
    if temp:
        rows.append(temp)

    rows.append([InlineKeyboardButton(text="Проверить подписку", callback_data=original_data, style="primary",
                                      icon_custom_emoji_id="5773677501825945508")])

    kb = InlineKeyboardMarkup(inline_keyboard=rows)
    text_subs_required = "<tg-emoji emoji-id='5237691237124820624'>🌥</tg-emoji> <b>Для получения бонуса подпишитесь на все указанные каналы/группы.</b>"

    try:
        await message.edit_text(
            text_subs_required,
            reply_markup=kb,
            parse_mode=ParseMode.HTML,
            disable_web_page_preview=True,
        )
        bns_dbg("[БОНУС][ПОДПИСКИ] ✅ edit_text успешен (экран подписок показан)")
    except TelegramBadRequest as e:
        if "message is not modified" in str(e).lower():
            bns_dbg("[БОНУС][ПОДПИСКИ] ⚠️ message is not modified -> значит пользователь ещё не подписался")
            await bns_safe_answer(callback_query, "⚠️ Вы всё ещё не подписались на необходимые каналы/группы", alert=True)
        else:
            bns_dbg(f"[БОНУС][ПОДПИСКИ][ERROR] edit_text badrequest: {e}")
            await bns_safe_answer(callback_query, "💥 Ошибка обновления сообщения. Подробности в логах.", alert=True)
    except Exception as e:
        bns_dbg(f"[БОНУС][ПОДПИСКИ][ERROR] edit_text: {type(e).__name__}: {e}")
        await bns_safe_answer(callback_query, "💥 Ошибка обновления сообщения. Подробности в логах.", alert=True)

    return False


# ─────────────────────────────────────────────────────────────
def _is_valid_bns_callback(data: str) -> bool:
    if not data:
        return False
    if data.isdigit():
        return True
    if "_+_" in data:
        return False
    if "_+" in data:
        return True
    return False


# ═════════════════════════════════════════════════════════════
# ХРАНИЛИЩЕ ВЛАДЕЛЬЦЕВ БОНУСНЫХ СООБЩЕНИЙ
# ═════════════════════════════════════════════════════════════
bonus_owner: Dict[int, int] = LazyGameStore("_bonus_owner")  # message_id -> user_id


def set_bonus_owner(message_id: int, user_id: int) -> None:
    """Запомнить, что сообщение с bonus_message принадлежит user_id."""
    bonus_owner[int(message_id)] = int(user_id)
    _log(f"[OWNER] set owner msg_id={message_id} user_id={user_id}")


def check_bonus_owner(callback: CallbackQuery) -> bool:
    """Проверка, что пользователь, нажавший кнопку, является владельцем бонусного сообщения."""
    msg = callback.message
    if msg is None:
        return False
    msg_id = msg.message_id
    owner_id = bonus_owner.get(msg_id)
    if owner_id is None:
        _log(f"[OWNER] no owner record for msg_id={msg_id}")
        return False
    if owner_id != callback.from_user.id:
        _log(f"[OWNER] access denied msg_id={msg_id} current_user={callback.from_user.id} owner={owner_id}")
        return False
    return True


def remove_bonus_owner(message_id: int) -> None:
    bonus_owner.pop(int(message_id), None)
    _log(f"[OWNER] removed owner msg_id={message_id}")


def check_bonus_owner_soft(callback: CallbackQuery) -> bool:
    """Мягкая проверка владельца (если владелец не задан – разрешаем)."""
    msg = callback.message
    if msg is None:
        return True
    owner_id = bonus_owner.get(msg.message_id)
    if owner_id is not None and owner_id != callback.from_user.id:
        return False
    return True


