# ═════════════════════════════════════════════════════════════
# ПРОВЕРКА ПРИПИСКИ Cute (прямо из Telegram, с кириллицей)
# ═════════════════════════════════════════════════════════════
def _has_family_tag(user: types.User) -> bool:
    """
    Проверяет, содержит ли имя пользователя 'Cute' (латиница/кириллица, любой регистр).
    Возвращает True, если приписка найдена.
    """
    first_name = user.first_name or ""
    last_name = user.last_name or ""
    full_name = f"{first_name} {last_name}".strip().lower()

    # Замена кириллических букв, похожих на латинские в слове "Cute"
    replacements = {'с': 'c', 'у': 'u', 'е': 'e', 'т': 't'}
    normalized = full_name
    for cyr, lat in replacements.items():
        normalized = normalized.replace(cyr, lat)

    result = "cute" in normalized
    bns_dbg(f"[FAMILY] name='{full_name}' normalized='{normalized}' has Cute: {result}")
    return result


# ═════════════════════════════════════════════════════════════
# ГЛАВНЫЙ ОБРАБОТЧИК БОНУСА (клик по ячейке доски)
# ═════════════════════════════════════════════════════════════
@dp.callback_query(lambda c: _is_valid_bns_callback(c.data))
async def bns_process_callback(callback_query: types.CallbackQuery):
    step = "START"
    user_id = callback_query.from_user.id
    message = callback_query.message
    raw_data = callback_query.data or ""

    if message is None:
        await callback_query.answer("💭 Сообщение недоступно.", show_alert=True)
        return

    message_id = message.message_id
    chat = message.chat
    chat_id = chat.id
    chat_name = getattr(chat, "full_name", None) or getattr(chat, "title", None) or str(chat_id)

    now_ts = bns_now_ts()
    now_dt = datetime.fromtimestamp(now_ts)

    is_update = "_+" in raw_data
    callback_data_clean = raw_data.replace("_+", "") if is_update else raw_data

    if BONUS_DEBUG:
        print("────────────────────────────────────────────")
        print(f"[БОНУС][КЛИК] user_id={user_id} chat_id={chat_id} message_id={message_id} raw_data={raw_data!r}")
        bns_dump_user(user_id)

    # Проверка владельца (мягкая)
    if not check_bonus_owner_soft(callback_query):
        await callback_query.answer("🤙 Это не ваш бонус.", show_alert=True)
        return

    # Дебаунс
    if bns_is_debounced(user_id, message_id):
        await callback_query.answer("⏳ Подождите секунду…", show_alert=False)
        return

    # Повторный клик по использованной ячейке
    if (user_id, message_id) in _bonus_requests:
        await callback_query.answer("✅ Вы уже получили бонус с этого сообщения.", show_alert=True)
        return

    # ══════════════════  ПРОВЕРКА ПРИПИСКИ Cute  ══════════════════
    if not _has_family_tag(callback_query.from_user):
        # ТОЛЬКО алерт, без изменения сообщения
        await bns_safe_answer(callback_query, "❕ Добавьте приписку Cute в ник и повторите.", alert=True)
        return

    # ══════════════════  ПОБЕДЫ  ══════════════════
    try:
        hist_res, new_first_name = await asyncio.gather(
            db.get_historygames_times(user_id),
            db.get_firstname_by_user_id(user_id),
        )
    except Exception as e:
        bns_dbg(f"[Бонус] Ошибка получения истории/имени: {type(e).__name__}: {e}")
        await callback_query.answer("💭 Ошибка получения данных. Попробуйте позже.", show_alert=True)
        return

    if hist_res is None:
        last_open_time = None
        data_open = None
    else:
        last_open_time, data_open = hist_res

    if last_open_time is None or data_open is None:
        bns_dbg("[БОНУС] WINS_GATE: пользователь не побеждал ни разу")
        # 1. Сначала показываем уведомление
        await bns_safe_answer(callback_query, "❕ Сначала победите противника в любой игре", alert=True)
        # 2. Затем заменяем сообщение на экран "нет победы" с кнопками
        await _show_no_win(user_id, chat_id, reply_to=message, edit_message=message)
        return

    # ══════════════════  ПОДПИСКИ  ══════════════════
    ok_subs = await bns_subs_gate_bonus(
        callback_query=callback_query,
        message=message,
        user_id=user_id,
        required_chats=required_chats_bonus,
        original_data=raw_data,
    )
    if not ok_subs:
        return

    # ══════════════════  ЛОК НАЧИСЛЕНИЯ  ══════════════════
    if not bns_try_award_lock(user_id):
        await callback_query.answer("⏳ Уже обрабатываю… нажмите ещё раз через секунду", show_alert=False)
        return

    try:
        # ══════════════════  КУЛДАУН  ══════════════════
        try:
            bonus_times = await db.get_bonus_times(user_id)
        except Exception as e:
            bns_dbg(f"[Бонус] Ошибка db.get_bonus_times: {type(e).__name__}: {e}")
            await callback_query.answer("💭 Ошибка получения времени бонуса.", show_alert=True)
            return

        if bonus_times is None:
            last_bonus_open = None
            next_open_ts = None
        else:
            last_bonus_open, next_open_ts = bonus_times

        next_open_ts_num = bns_to_unix_ts(next_open_ts)

        # Кулдаун активен → таймер
        if last_bonus_open is not None and next_open_ts_num is not None and now_ts < float(next_open_ts_num):
            _bonus_requests[(user_id, message_id)] = True
            rem_sec = int(float(next_open_ts_num) - now_ts)
            h, rem = divmod(rem_sec, 3600)
            m, s = divmod(rem, 60)
            ts = f"{h:02d}:{m:02d}:{s:02d}"

            kb_buttons = [
                [InlineKeyboardButton(text="Доступно через", callback_data="noop")],
                [InlineKeyboardButton(text=ts, callback_data=f"infowaitingbonus|{ts}")]
            ]
            if chat.id == user_id:
                kb_buttons.append([InlineKeyboardButton(text="✖️", callback_data="9close_bonus")])

            kb = InlineKeyboardMarkup(inline_keyboard=kb_buttons)
            try:
                msg = await message.edit_text(
                    "<tg-emoji emoji-id='5458581641381290671'>🤨</tg-emoji>",
                    reply_markup=kb, parse_mode="HTML"
                )
            except Exception:
                msg = await message.reply(
                    "<tg-emoji emoji-id='5458581641381290671'>🤨</tg-emoji>",
                    reply_markup=kb, parse_mode="HTML"
                )

            set_bonus_owner(msg.message_id, user_id)
            _bonus_requests[(user_id, msg.message_id)] = True
            cancel_timers[msg.message_id] = False
            _tick = 0

            try:
                while not cancel_timers.get(msg.message_id, False):
                    await asyncio.sleep(1)
                    now_ts_loop = bns_now_ts()
                    if now_ts_loop >= float(next_open_ts_num):
                        try:
                            await msg.edit_text("🎉 Бонус открыт! Нажмите снова.", reply_markup=None)
                        except Exception:
                            pass
                        break
                    rem_sec = int(float(next_open_ts_num) - now_ts_loop)
                    if rem_sec < 0:
                        break
                    h, rem = divmod(rem_sec, 3600)
                    m, s = divmod(rem, 60)
                    ts_new = f"{h:02d}:{m:02d}:{s:02d}"
                    new_kb_buttons = [
                        [InlineKeyboardButton(text="Доступно через", callback_data="noop")],
                        [InlineKeyboardButton(text=ts_new, callback_data=f"infowaitingbonus|{ts_new}")]
                    ]
                    if chat.id == user_id:
                        new_kb_buttons.append([InlineKeyboardButton(text="✖️", callback_data="9close_bonus")])
                    new_kb = InlineKeyboardMarkup(inline_keyboard=new_kb_buttons)
                    # Правим кнопку раз в 5 сек (и каждую секунду в последние 10),
                    # а при flood control ждём столько, сколько просит Telegram -
                    # раньше цикл долбил edit каждую секунду весь кулдаун.
                    _tick += 1
                    if rem_sec <= 10 or (_tick % 5 == 0):
                        try:
                            await msg.edit_reply_markup(reply_markup=new_kb)
                        except TelegramRetryAfter as _fe:
                            await asyncio.sleep(int(getattr(_fe, "retry_after", 5) or 5))
                        except Exception:
                            pass
            finally:
                cancel_timers.pop(msg.message_id, None)
            bns_unlock_award_lock(user_id)
            return

        # Кулдауна нет → начисляем бонус
        _bonus_requests[(user_id, message_id)] = True

        if last_bonus_open is None or next_open_ts_num is None:
            next_open_ts_num = now_ts + float(timebonus)
            try:
                await db.add_bonus(
                    chat_id, chat_name, user_id, new_first_name,
                    now_dt.strftime("%Y-%m-%d %H:%M:%S"),
                    datetime.fromtimestamp(next_open_ts_num).strftime("%Y-%m-%d %H:%M:%S"),
                )
            except Exception as e:
                bns_dbg(f"[Бонус] Ошибка db.add_bonus: {type(e).__name__}: {e}")
                await callback_query.answer("💭 Ошибка записи бонуса.", show_alert=True)
                return

        # Сумма бонуса
        try:
            bonus_amount = int(callback_data_clean)
        except Exception:
            await callback_query.answer("💭 Ошибка данных бонуса.", show_alert=True)
            return

        # ×2 проверка
        premium_ok = has_premium(callback_query.from_user)
        try:
            bio_ok = await check_bio_contains(user_id, '@CuteGamingBot')
        except Exception:
            bio_ok = False
        ref_count, ref_ok = await _get_ref_progress(user_id)
        has_full_x2 = premium_ok and bio_ok and ref_ok

        if has_full_x2:
            bonus_amount *= 2

        formatted_bonus_amount = "{:,.0f}".format(bonus_amount)

        # Начисление на баланс
        try:
            balance = await db.get_user_balance(user_id)
            await db.update_user_balance(user_id, balance + bonus_amount)
            await db.cutehistory_plus(user_id, bonus_amount, "бонус")
            await db.add_bonusbet(user_id, new_first_name, bonus_amount, chat_id, chat_name, now_dt)
            await callback_query.answer(f"✅ Бонус: {formatted_bonus_amount} кут", show_alert=False)
        except Exception as e:
            bns_dbg(f"[БОНУС][CREDIT][ERROR] {type(e).__name__}: {e}")
            await callback_query.answer("⚠️ Бонус обработан, но запись баланса временно недоступна.", show_alert=True)

        # Предмет при ×2
        if has_full_x2:
            try:
                item_name = await db.get_random_bonus_gift_item_by_chance()
                if item_name:
                    item_emoji = await db.find_emoji_by_item_name(item_name)
                    await db.set_items(user_id, item_name, 1)
                    item_text = f"<tg-emoji emoji-id='5787166284705699232'>🎁</tg-emoji> | <b>+<code>{item_emoji}</code> {item_name}</b>"
                    try:
                        await message.reply(item_text, parse_mode="HTML")
                    except Exception:
                        pass
                else:
                    no_item_msg = "<tg-emoji emoji-id='5280615440928758599'>🎁</tg-emoji> Доступных предметов пока нет, сообщите @JerichoCute."
                    try:
                        await message.reply(no_item_msg, parse_mode="HTML")
                    except Exception:
                        pass
            except Exception as e:
                bns_dbg(f"[БОНУС][ITEM][ERROR] Ошибка при выдаче предмета: {type(e).__name__}: {e}")

        # Финальный UI (доска результата)
        if has_full_x2:
            rows = [ [ InlineKeyboardButton(
                text=f"×2 | {formatted_bonus_amount} кут" , callback_data="bobnusdnusf") ] ]
        else:
            rows = [
                [ InlineKeyboardButton(text=f"{formatted_bonus_amount} кут" , callback_data="bobnusdnusf") ] ,
                [ InlineKeyboardButton(
                    text="×2 Бонус" , callback_data="info_x2" , icon_custom_emoji_id="5397674675796985688") ] ]

        if chat.id == user_id:
            rows.append(
                [ InlineKeyboardButton(
                    text=" " , callback_data="9close_bonus" , icon_custom_emoji_id="5226660202035554522") ])

        final_kb = InlineKeyboardMarkup(inline_keyboard=rows)
        final_text = "<tg-emoji emoji-id='5458612419116933783'>🏆</tg-emoji>"

        try:
            if is_update or chat.type == ChatType.PRIVATE:
                final_msg = await message.edit_text(final_text, reply_markup=final_kb, parse_mode="HTML")
            else:
                final_msg = await message.reply(final_text, reply_markup=final_kb, parse_mode="HTML")
            set_bonus_owner(final_msg.message_id, user_id)
            _bonus_requests[(user_id, final_msg.message_id)] = True
        except Exception as e:
            bns_dbg(f"[БОНУС][FINAL_UI][ERROR] {type(e).__name__}: {e}")

    finally:
        bns_unlock_award_lock(user_id)


