@dp.callback_query(lambda c: c.data == "closebonusdfsdfwe")
async def close_bonus_callback(callback_query: types.CallbackQuery):
    if not check_bonus_owner(callback_query):
        await callback_query.answer("🤙 Только владелец бонуса может закрыть это сообщение.", show_alert=True)
        return
    msg_id = callback_query.message.message_id
    try:
        await callback_query.message.delete()
    except Exception as e:
        print(f"Ошибка при удалении бонуса: {e}")
    remove_bonus_owner(msg_id)


@dp.callback_query(lambda c: c.data == "bobnusdnusf")
async def bobnusdnusf_cb(callback: CallbackQuery):
    if not check_bonus_owner(callback):
        await callback.answer("На эту кнопку может нажимать только тот кто открывает бонус", show_alert=True)
        return
    await callback.answer("Вознаграждение за открытие бонуса", show_alert=True)


# ─────────────────────────────────────────────────────────────
# ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
# ─────────────────────────────────────────────────────────────
def has_premium(user: types.User) -> bool:
    return getattr(user, 'is_premium', False) or False


async def check_bio_contains(user_id: int, target: str) -> bool:
    """Проверяет наличие строки target в описании профиля."""
    try:
        info = await bot1.get_chat(user_id)
        bio = getattr(info, 'bio', '') or ''
        result = target.lower() in bio.lower()
        _log(f"Bio check {user_id}: contains '{target}'? {result}")
        return result
    except Exception as e:
        _log(f"Bio check error {user_id}: {e}")
        return False


async def bns_edit(message: Message, text: str, kb: Optional[InlineKeyboardMarkup] = None):
    """Безопасное редактирование сообщения."""
    try:
        await message.edit_text(text, reply_markup=kb, parse_mode="HTML", disable_web_page_preview=True)
    except TelegramBadRequest as e:
        if "message is not modified" not in str(e):
            _log(f"bns_edit error: {e}")
    except Exception as e:
        _log(f"bns_edit unexpected: {e}")


def _log(*args):
    if BONUS_DEBUG:
        print("[BONUS]", *args)


async def _reply_or_send(chat_id: int, reply_to: Optional[types.Message], text: str, kb: InlineKeyboardMarkup) -> types.Message:
    """Отправляет сообщение либо ответом на reply_to, либо в чат."""
    if reply_to:
        return await reply_to.reply(text, reply_markup=kb, parse_mode="HTML")
    return await bot1.send_message(chat_id, text, reply_markup=kb, parse_mode="HTML")


def _random_stake() -> int:
    """Генерирует случайную ставку от 1 до bonusbet."""
    return random.randint(1, max(1, bonusbet))


def _extract_emoji_id123(emoji_text: str) -> str | None:
    """Извлекает ID кастомного эмодзи из строки вида <tg-emoji emoji-id='...'>...</tg-emoji>."""
    match = re.search(r"emoji-id=['\"]([0-9]+)['\"]", emoji_text)
    return match.group(1) if match else None


def bonus_board_keyboard(emojis: List[str], multiplier: int, show_x2_hint: bool = False) -> InlineKeyboardMarkup:
    """Создаёт клавиатуру с премиум-эмодзи (кастомными иконками) для игрового поля."""
    buttons = []
    for emoji in emojis:
        emoji_id = _extract_emoji_id123(emoji)
        if emoji_id is None:
            if emoji.isdigit():
                emoji_id = emoji
            else:
                emoji_id = None

        callback_data = f"{_random_stake()}_+"

        if emoji_id:
            button = InlineKeyboardButton(
                text=" ", style="default", icon_custom_emoji_id=emoji_id, callback_data=callback_data)
        else:
            button = InlineKeyboardButton(text=emoji, callback_data=callback_data)

        buttons.append(button)

    rows = [buttons[i:i + 3] for i in range(0, 9, 3)]

    if show_x2_hint and multiplier == 1:
        hint_button = InlineKeyboardButton(
            text="×2 Бонус", callback_data="info_x2", style="default",
            icon_custom_emoji_id="5420315771991497307"
        )
        rows.append([hint_button])

    return InlineKeyboardMarkup(inline_keyboard=rows)


