# ═════════════════════════════════════════════════════════════
async def _check_family_tag(user: types.User) -> bool:
    """Проверка через _has_family_tag (единая точка входа)."""
    return _has_family_tag(user)


async def _check_game_win(user_id: int) -> bool:
    try:
        last_win, _ = await db.get_historygames_times(user_id)
        return last_win is not None
    except Exception as e:
        _log(f"Game win check error: {e}")
        return False


async def _get_ref_progress(user_id: int, required_ref: int = min_required_ref) -> Tuple[int, bool]:
    try:
        ref_count = await db.get_refferals_count(user_id)
        ref_count = int(ref_count or 0)
        return ref_count, ref_count >= required_ref
    except Exception as e:
        _log(f"Ref check error: {e}")
        return 0, False


async def _check_cooldown(user_id: int, next_dt: datetime) -> bool:
    return next_dt and datetime.now() < next_dt


