@dp.callback_query(lambda c: c.data == "check_x2_again")
async def retry_x2_check(callback: CallbackQuery):
    if not check_bonus_owner(callback):
        await callback.answer("🤙 Вы не можете проверять чужой бонус.", show_alert=True)
        return

    user_id = callback.from_user.id
    now = datetime.now()
    last_time = x2_check_cooldown.get(user_id)
    if last_time and (now - last_time).total_seconds() < X2_CHECK_COOLDOWN_SEC:
        remaining = int(X2_CHECK_COOLDOWN_SEC - (now - last_time).total_seconds())
        await callback.answer(f"⏳ Повторная проверка через {remaining} сек.", show_alert=True)
        return
    x2_check_cooldown[user_id] = now

    try:
        premium_ok = has_premium(callback.from_user)
        bio_ok = await check_bio_contains(user_id, '@CuteGamingBot')
        if premium_ok and bio_ok:
            await callback.answer("✅ Условия выполнены! ×2 бонус доступен.")
        else:
            await callback.answer("❌ Условия не выполнены. Проверьте Premium и описание профиля.", show_alert=True)
            await render_x2_requirements(callback.from_user, callback.message)
    except Exception as e:
        _log(f"check_x2_again error: {e}")
        try:
            await callback.answer("⚠️ Ошибка проверки.", show_alert=True)
        except:
            pass


