chat_id_sub = [-1002314697460, -1002680844025]  # Указываем идентификаторы каналов

# Функция для проверки подписки на каналы
async def check_user_subscription(user_id):
    subscriptions = {}
    try:
        # Проверка подписки на каждый канал
        for chat_id in chat_id_sub:
            chat_member = await bot1.get_chat_member(chat_id, user_id)  # Получение информации о пользователе в канале
            is_subscribed = chat_member.status in [ChatMemberStatus.MEMBER,
                                                   ChatMemberStatus.ADMINISTRATOR,
                                                   ChatMemberStatus.CREATOR]
            subscriptions[chat_id] = is_subscribed  # Сохраняем информацию о подписке на канал
        return subscriptions  # Возвращаем словарь с состоянием подписок на каналы
    except Exception as e:
        print(f"Ошибка при проверке подписки для пользователя {user_id}: {str(e)}")
        return {chat_id: False for chat_id in chat_id_sub}  # Если ошибка, считаем, что на все каналы не подписан

async def sub(message: types.Message):
    """Команда «💰 бесплатные куты»: приглашение подписаться на каналы за 1 кут.

    Использует те же рабочие колбэки, что и меню (donesub / 9close_bonus).
    Раньше диспатч тянул `from bot.design.sub import sub`, но такой функции там
    не было (модуль — легаси на aiogram-2), поэтому команда падала.
    """
    user_id = message.from_user.id

    try:
        if await _safe_is_user_banned(user_id):
            await message.answer("❗️ Вы заблокированы в боте")
            return
    except Exception:
        pass

    user_sub = await db.get_user_subscription(user_id)
    if user_sub is None:
        await message.answer("Ошибка: не удалось получить информацию о подписке.")
        return

    if user_sub == 1:
        await message.answer(
            "🛠 <b>Вы уже получили бесплатные куты за подписку.</b>", parse_mode="HTML")
        return

    subscriptions = await check_user_subscription(user_id)
    not_subscribed_channels = [
        (chat_id, "𝐍𝐞𝐰𝐬 | 𝐂𝐮𝐭𝐞", "CuteGamingNews") if chat_id == -1002314697460 else
        (chat_id, "𝐂𝐮𝐭𝐞 | 𝐅𝐚𝐦𝐢𝐥𝐲", "JerichoCuteFamily")
        for chat_id, is_subscribed in subscriptions.items() if not is_subscribed
    ]

    if not_subscribed_channels:
        buttons = []
        for chat_id, channel_name, channel_username in not_subscribed_channels:
            buttons.append(
                [InlineKeyboardButton(text=channel_name, url=f"https://t.me/{channel_username}")])
        buttons.append([InlineKeyboardButton(text="☁️ Проверить ☁️", callback_data="donesub")])
        buttons.append([InlineKeyboardButton(text="✖️", callback_data="9close_bonus")])
        keyboard = InlineKeyboardMarkup(inline_keyboard=buttons)
        await message.answer(
            "💰 <b>Чтобы получить 1 бесплатный кут - присоединитесь в наши каналы!</b>",
            parse_mode="HTML", reply_markup=keyboard)
    else:
        # Уже подписан на все каналы — начисляем бонус разово.
        new_bonus = 1
        balance = await db.get_user_balance(user_id)
        win = balance + new_bonus
        await db.update_user_balance(user_id, win)
        await db.cutehistory_plus(user_id, win, "sub за подписку на наши каналы")
        await db.update_subscription(user_id)
        await message.answer(
            f"<b>✅ Готово! Вы получили {new_bonus} Кут за подписку!</b>", parse_mode="HTML")


