ADMIN_ID = 6801702632

@dp.message(Command("refund"))
async def cmd_refund(message: Message):
    # Проверка, что пользователь имеет право на возврат
    if message.from_user.id != ADMIN_ID:
        return

    # Разделяем сообщение и проверяем наличие аргумента
    parts = message.text.strip().split(maxsplit=1)
    if len(parts) < 2 or not parts[1].strip():
        await message.answer(
            "❗ <b>Пожалуйста, укажите ID транзакции.</b>",
            parse_mode="HTML"
        )
        return

    transaction_id = parts[1].strip()

    try:
        # Предполагается, что у bot1 есть метод refund_star_payment
        await bot1.refund_star_payment(user_id=message.from_user.id, telegram_payment_charge_id=transaction_id)
        await message.answer("<b>✅ Возврат звёзд выполнен успешно!</b>", parse_mode="HTML")
    except Exception as e:
        error_text = str(e)

        if "CHARGE_ALREADY_REFUNDED" in error_text:
            await message.answer("⚠️ <b>Этот платёж уже был возвращён ранее.</b>", parse_mode="HTML")
        elif "BAD_REQUEST" in error_text:
            await message.answer("⚠️ <b>Неверный ID транзакции или платёж не найден.</b>", parse_mode="HTML")
        else:
            print(f"❌ Ошибка при возврате: {error_text}")
            await message.answer(
                f"❌ <b>Произошла непредвиденная ошибка при возврате звёзд. Попробуйте позже.</b>\n<code>{error_text}</code>",
                parse_mode="HTML"
            )







