# ============================================================
# ✅ TON thresholds
# ============================================================
TON_INSTANT_MIN = 1.0        # показывать "⚡ моментальный вывод" если TON >= 1.0
TON_SPEED_MIN = 0.000001     # технический минимум "баланс есть" (если где-то надо)

# ============================================================
# ✅ TON cache/lock (единая точка истины)
# ============================================================
TON_BAL_TTL = 20.0
TON_TIMEOUT = 0.9
TON_FAIL_COOLDOWN = 60.0

_ton_cache_value: float = 0.0
_ton_cache_ts: float = 0.0
_ton_lock = asyncio.Lock()

_ton_fail_until_ts: float = 0.0
_ton_fail_count: int = 0


# ============================================================
# ✅ Утилита: корректно разобрать ответ fragment_client
# ============================================================
def _parse_fragment_balance_to_ton(res: dict) -> float:
    """
    Fragment может вернуть:
      - float TON (пример: 2.999646377)
      - int nanoTON
      - str
    Возвращаем TON(float) корректно.
    """
    try:
        raw = res.get("balance", 0)
    except Exception:
        raw = 0

    if raw is None:
        return 0.0

    # str
    if isinstance(raw, str):
        s = raw.strip().replace(",", ".")
        if not s:
            return 0.0
        if s.isdigit():
            try:
                return float(int(s)) / 1e9
            except Exception:
                return 0.0
        try:
            return float(s)
        except Exception:
            return 0.0

    # int
    if isinstance(raw, int):
        try:
            # nanoTON
            if raw >= 1_000_000_000:
                return float(raw) / 1e9
            # возможно уже TON
            return float(raw)
        except Exception:
            return 0.0

    # float
    if isinstance(raw, float):
        try:
            return float(raw)
        except Exception:
            return 0.0

    # fallback
    try:
        return float(raw)
    except Exception:
        return 0.0


# ✅ ЖЁСТКАЯ ИЗОЛЯЦИЯ КЛЮЧЕЙ
# Поменяй namespace на ещё более уникальный, если хочешь:
# например: "cute:test:bot123:ton"
REDIS_NAMESPACE = "cute:test:ton"
K_VALUE = f"{REDIS_NAMESPACE}:value"
K_LOCK = f"{REDIS_NAMESPACE}:lock"
K_FAIL = f"{REDIS_NAMESPACE}:fail"

TON_REFRESH_INTERVAL = 60.0
TON_REFRESH_JITTER = 8.0
TON_LOCK_TTL = 25
TON_OK_TTL = 90
TON_STALE_TTL = 10 * 60
TON_ERR_COOLDOWN = 5

TON_FETCH_ATTEMPTS = 3
TON_FETCH_BASE_SLEEP = 0.25
TON_FETCH_MAX_SLEEP = 1.20

# =============================================================================
# ✅ LOCAL RAM CACHE (для нагрузки в миллион пользователей)
# =============================================================================
_TON_LOCAL_TON: float = 0.0
_TON_LOCAL_TS_OK: float = 0.0

# мягкий анти-дребезг, если RAM кеш пуст и надо подтянуть из Redis
_TON_REDIS_PULL_INFLIGHT: Optional[asyncio.Task] = None
_TON_REDIS_PULL_LAST_TS: float = 0.0
_TON_REDIS_PULL_MIN_INTERVAL = 2.0

# =============================================================================
# ✅ UTILS
# =============================================================================
def _now() -> float:
    return time.time()


def _fmt_ts(ts: float) -> str:
    try:
        return time.strftime("%H:%M:%S", time.localtime(ts))
    except Exception:
        return "??:??:??"


def _pack_value(*, ton: float, ts_ok: float, err_ts: float, err_text: str) -> str:
    return json.dumps(
        {"ton": float(ton), "ts_ok": float(ts_ok), "err_ts": float(err_ts), "err_text": str(err_text or "")},
        ensure_ascii=False,
    )


def _unpack_json(raw: Any) -> Optional[dict]:
    if raw is None:
        return None

    if isinstance(raw, (bytes, bytearray)):
        try:
            raw = raw.decode("utf-8", "ignore")
        except Exception:
            return None

    if not isinstance(raw, str) or not raw.strip():
        return None

    try:
        return json.loads(raw)
    except Exception:
        return None


def _sleep_backoff(attempt: int) -> float:
    try:
        base = TON_FETCH_BASE_SLEEP * (2 ** max(0, attempt - 1))
        base = min(TON_FETCH_MAX_SLEEP, base)
        jitter = 0.85 + random.random() * 0.30
        return max(0.05, base * jitter)
    except Exception:
        return 0.30


def _calc_sleep_interval() -> float:
    try:
        return max(5.0, float(TON_REFRESH_INTERVAL) + random.uniform(-TON_REFRESH_JITTER, TON_REFRESH_JITTER))
    except Exception:
        return float(TON_REFRESH_INTERVAL)


def _dbg_refresh_line(*, old_ton: float, new_ton: float, ts_ok: float, dt_s: float) -> None:
    """Короткая строка на каждое успешное обновление кеша (только при debug=True)."""
    try:
        print(
            f"[ M.O.N.A.R.C.H ] 🍷 TON[CACHE] {old_ton:.9f} → {new_ton:.9f} | t={_fmt_ts(ts_ok)} | dt={dt_s:.3f}s"
        )
    except Exception:
        pass


def _get_sync_redis_client():
    """✅ Берём Redis клиента строго из pklcode. pklcode сам занимается autobind/health watcher."""
    try:
        return pklcode._client()  # noqa: SLF001
    except Exception:
        return None


async def _rds_call(fn, *args, debug: bool = False, **kwargs):
    """✅ Выполнить синхронный вызов redis-py в executor. Поддерживает kwargs через functools.partial."""
    loop = asyncio.get_running_loop()
    try:
        call = functools.partial(fn, *args, **kwargs)
        return await loop.run_in_executor(None, call)
    except Exception as e:
        if debug:
            print(f"[ M.O.N.A.R.C.H ] 🍺 TON[REDIS][EXEC] ошибка: {type(e).__name__}: {e}")
        return None


# =============================================================================
# ✅ ОСНОВНАЯ ФУНКЦИЯ (миллион пользователей)
# =============================================================================
async def get_balance_ton_raw(*, debug: bool = False) -> float:
    """
    🔥 Самый быстрый путь:
    - всегда отдаём RAM кеш (мгновенно)
    - НЕ дёргаем Fragment
    - НЕ дёргаем Redis на каждом чтении
    """
    global _TON_LOCAL_TON, _TON_LOCAL_TS_OK

    ton = float(_TON_LOCAL_TON or 0.0)
    ts_ok = float(_TON_LOCAL_TS_OK or 0.0)
    age = (_now() - ts_ok) if ts_ok > 0 else 1e9

    if debug:
        freshness = "OK" if age <= TON_OK_TTL else ("STALE" if age <= TON_STALE_TTL else "VERY_OLD")
        print(f"[ M.O.N.A.R.C.H ] 🥤 TON[READ][RAM]: ton={ton:.9f} age={age:.1f}s state={freshness}")

    # Если кеш ещё ни разу не заполнялся - мягко подтянем из Redis (редко, с анти-дребезгом)
    if ts_ok <= 0:
        await _maybe_soft_pull_from_redis(debug=debug)
        ton = float(_TON_LOCAL_TON or 0.0)
        ts_ok = float(_TON_LOCAL_TS_OK or 0.0)
        age = (_now() - ts_ok) if ts_ok > 0 else 1e9

        if debug:
            freshness = "OK" if age <= TON_OK_TTL else ("STALE" if age <= TON_STALE_TTL else "VERY_OLD")
            print(f"[ M.O.N.A.R.C.H ] 🍹 TON[READ][RAM-after-redis]: ton={ton:.9f} age={age:.1f}s state={freshness}")

    return float(_TON_LOCAL_TON or 0.0)


async def _maybe_soft_pull_from_redis(*, debug: bool = False) -> None:
    """Мягко подтянуть значение из Redis, если RAM кеш пуст. Делается редко, безопасно, не мешает."""
    global _TON_REDIS_PULL_INFLIGHT, _TON_REDIS_PULL_LAST_TS
    global _TON_LOCAL_TON, _TON_LOCAL_TS_OK

    now = _now()

    if (now - _TON_REDIS_PULL_LAST_TS) < _TON_REDIS_PULL_MIN_INTERVAL:
        if debug:
            print("[ M.O.N.A.R.C.H ] 🧃 TON[PULL]: throttled → пропуск")
        return

    if _TON_REDIS_PULL_INFLIGHT and not _TON_REDIS_PULL_INFLIGHT.done():
        if debug:
            print("[ M.O.N.A.R.C.H ] 🍸 TON[PULL]: inflight уже есть → жду")
        try:
            await _TON_REDIS_PULL_INFLIGHT
        except Exception:
            pass
        return

    async def _pull():
        global _TON_REDIS_PULL_LAST_TS, _TON_LOCAL_TON, _TON_LOCAL_TS_OK

        _TON_REDIS_PULL_LAST_TS = _now()

        cli = _get_sync_redis_client()
        if cli is None:
            if debug:
                print("[ M.O.N.A.R.C.H ] 🥃 TON[PULL]: Redis клиента нет (pklcode._client()=None)")
            return

        raw = await _rds_call(cli.get, K_VALUE, debug=debug)
        data = _unpack_json(raw)

        if not data:
            if debug:
                print("[ M.O.N.A.R.C.H ] 🧉 TON[PULL]: K_VALUE пуст/невалиден")
            return

        _TON_LOCAL_TON = float(data.get("ton") or 0.0)
        _TON_LOCAL_TS_OK = float(data.get("ts_ok") or 0.0)

        if debug:
            age = (_now() - _TON_LOCAL_TS_OK) if _TON_LOCAL_TS_OK > 0 else 1e9
            print(f"[ M.O.N.A.R.C.H ] 🍷 TON[PULL]: подтянул из Redis ton={_TON_LOCAL_TON:.9f} age={age:.1f}s")

    _TON_REDIS_PULL_INFLIGHT = asyncio.create_task(_pull())
    try:
        await _TON_REDIS_PULL_INFLIGHT
    except Exception:
        pass


# =============================================================================
# ✅ FRAGMENT FETCH (sync client -> executor)
# =============================================================================
async def _fetch_ton_from_fragment(*, debug: bool = True) -> Tuple[Optional[float], Optional[str]]:
    loop = asyncio.get_running_loop()

    def _sync_call():
        t0 = time.time()
        try:
            res = fragment_client.get_balance(seed=SEED_PHRASE)  # noqa: F821
        except Exception as e:
            dt = time.time() - t0
            return None, f"fragment_client.get_balance error (dt={dt:.3f}s): {e}"

        dt = time.time() - t0

        if debug:
            try:
                print(f"[ M.O.N.A.R.C.H ] 🥤 TON[FRAGMENT]: ответ (dt={dt:.3f}s): {res!r}")
            except Exception:
                print(f"[ M.O.N.A.R.C.H ] 🧃 TON[FRAGMENT]: ответ (dt={dt:.3f}s): <не удалось распечатать>")

        try:
            if not isinstance(res, dict):
                return None, "invalid fragment response type"

            ton = _parse_fragment_balance_to_ton(res)  # noqa: F821
            ton = float(ton or 0.0)

            if ton < 0:
                return None, f"invalid negative ton={ton}"

            return ton, None
        except Exception as e:
            return None, f"parse error: {e}"

    return await loop.run_in_executor(None, _sync_call)


# =============================================================================
# ✅ LEADER LOCK (Lua compare-and-del)
# =============================================================================
_LUA_UNLOCK = r"""
if redis.call("GET", KEYS[1]) == ARGV[1] then
  return redis.call("DEL", KEYS[1])
else
  return 0
end
"""


async def _acquire_lock(cli, token: str, *, debug: bool = True) -> bool:
    res = await _rds_call(cli.set, K_LOCK, token, nx=True, ex=int(TON_LOCK_TTL), debug=debug)
    ok = bool(res)  # redis-py обычно вернёт True / b'OK'
    if debug:
        print(f"[ M.O.N.A.R.C.H ] 🍸 TON[LOCK]: acquire={'OK' if ok else 'NO'} token={token}")
    return ok


async def _release_lock(cli, token: str, *, debug: bool = True) -> None:
    res = await _rds_call(cli.eval, _LUA_UNLOCK, 1, K_LOCK, token, debug=debug)
    if debug:
        print(f"[ M.O.N.A.R.C.H ] 🥃 TON[LOCK]: release res={res} token={token}")


# =============================================================================
# ✅ FAIL COOLDOWN (редко, только лидер)
# =============================================================================
async def _is_in_cooldown(cli, *, debug: bool = True) -> bool:
    raw = await _rds_call(cli.get, K_FAIL, debug=debug)
    data = _unpack_json(raw) or {}

    last_fail_ts = float(data.get("last_fail_ts") or 0.0)
    if last_fail_ts <= 0:
        return False

    age = _now() - last_fail_ts
    if age < TON_ERR_COOLDOWN:
        if debug:
            print(f"[ M.O.N.A.R.C.H ] 🧉 TON[FAIL]: cooldown активен age={age:.2f}s < {TON_ERR_COOLDOWN}s")
        return True

    return False


async def _record_fail(cli, err_text: str, *, debug: bool = True) -> None:
    fail_count = 1
    try:
        raw = await _rds_call(cli.get, K_FAIL, debug=debug)
        data = _unpack_json(raw) or {}
        fail_count = int(data.get("fail_count") or 0) + 1
    except Exception:
        pass

    payload = json.dumps(
        {
            "fail_count": int(fail_count),
            "last_fail_ts": float(_now()),
            "err_text": str(err_text or "")[:600],
        },
        ensure_ascii=False,
    )

    await _rds_call(cli.set, K_FAIL, payload, debug=debug)
    await _rds_call(cli.expire, K_FAIL, int(TON_STALE_TTL), debug=debug)

    if debug:
        print(f"[ M.O.N.A.R.C.H ] 🍷 TON[FAIL]: записал fail_count={fail_count} err={err_text}")


# =============================================================================
# ✅ REFRESH ONCE (лидер): обновляет Redis + RAM + короткий лог
# =============================================================================
async def _refresh_ton_cache_once(cli, *, debug: bool = True) -> bool:
    global _TON_LOCAL_TON, _TON_LOCAL_TS_OK

    t0 = _now()

    if await _is_in_cooldown(cli, debug=debug):
        if debug:
            print("[ M.O.N.A.R.C.H ] 🧃 TON[REFRESH]: cooldown → пропуск")
        return False

    old_ton = float(_TON_LOCAL_TON or 0.0)
    old_ts = float(_TON_LOCAL_TS_OK or 0.0)

    ton: Optional[float] = None
    last_err: Optional[str] = None

    for attempt in range(1, TON_FETCH_ATTEMPTS + 1):
        if debug:
            print(f"[ M.O.N.A.R.C.H ] 🍸 TON[REFRESH]: fetch {attempt}/{TON_FETCH_ATTEMPTS}")

        ton, last_err = await _fetch_ton_from_fragment(debug=debug)
        if ton is not None:
            break

        if attempt < TON_FETCH_ATTEMPTS:
            sleep_s = _sleep_backoff(attempt)
            if debug:
                print(f"[ M.O.N.A.R.C.H ] 🧉 TON[REFRESH]: fail: {last_err} → sleep {sleep_s:.2f}s")
            await asyncio.sleep(sleep_s)

    if ton is None:
        await _record_fail(cli, str(last_err or "unknown fetch error"), debug=debug)
        if debug:
            print("[ M.O.N.A.R.C.H ] 🥃 TON[REFRESH]: итог: не удалось обновить")
        return False

    ts_ok = _now()
    payload = _pack_value(ton=float(ton), ts_ok=float(ts_ok), err_ts=0.0, err_text="")

    try:
        await _rds_call(cli.set, K_VALUE, payload, debug=debug)
        await _rds_call(cli.expire, K_VALUE, int(TON_STALE_TTL), debug=debug)

        _TON_LOCAL_TON = float(ton)
        _TON_LOCAL_TS_OK = float(ts_ok)

        if debug:
            dt_s = _now() - t0
            _dbg_refresh_line(old_ton=old_ton, new_ton=float(ton), ts_ok=ts_ok, dt_s=dt_s)

            if old_ts > 0:
                print(f"[ M.O.N.A.R.C.H ] 🍷 TON[CACHE]: предыдущий кеш был {max(0.0, ts_ok - old_ts):.1f}s назад")

        return True

    except Exception as e:
        await _record_fail(cli, f"redis set/expire value error: {e}", debug=debug)
        if debug:
            print(f"[ M.O.N.A.R.C.H ] 🥤 TON[REFRESH]: redis ошибка: {type(e).__name__}: {e}")
        return False


# =============================================================================
# ✅ LOOP: первый тик сразу + затем каждые ~60 секунд
# =============================================================================
async def ton_balance_refresh_loop(*, debug: bool = True) -> None:
    token = f"ton-leader:{random.randint(1000, 9999)}:{int(_now())}"

    print("[ M.O.N.A.R.C.H ] 🍹 TON[LOOP]: цикл обновления запущен")

    cli = _get_sync_redis_client()
    if cli is None:
        print("[ M.O.N.A.R.C.H ] 🥃 TON[LOOP]: Redis клиента нет (pklcode._client()=None) → жду появления...")

    while cli is None:
        await asyncio.sleep(1.0)
        cli = _get_sync_redis_client()
        if debug and cli is None:
            print("[ M.O.N.A.R.C.H ] 🧉 TON[LOOP]: Redis всё ещё не поднялся...")

    # ✅ ПЕРВЫЙ ТИК СРАЗУ (заполняем кеш)
    try:
        got = await _acquire_lock(cli, token, debug=debug)
        if got:
            try:
                if debug:
                    print("[ M.O.N.A.R.C.H ] 🍸 TON[LOOP]: первый тик сразу → refresh кеша")
                await _refresh_ton_cache_once(cli, debug=debug)
            finally:
                await _release_lock(cli, token, debug=debug)
        else:
            if debug:
                print("[ M.O.N.A.R.C.H ] 🍹 TON[LOOP]: первый тик → лидер уже есть, пропуск")

            # всё равно подтянем K_VALUE в RAM, чтобы чтение сразу стало корректным
            await _maybe_soft_pull_from_redis(debug=debug)

    except Exception as e:
        if debug:
            print(f"[ M.O.N.A.R.C.H ] 🥤 TON[LOOP]: первый тик ошибка: {type(e).__name__}: {e}")

    # ✅ ДАЛЬШЕ ЦИКЛ
    while True:
        sleep_s = _calc_sleep_interval()
        if debug:
            print(f"[ M.O.N.A.R.C.H ] 🧃 TON[LOOP]: sleep {sleep_s:.2f}s")

        await asyncio.sleep(sleep_s)

        got = await _acquire_lock(cli, token, debug=debug)
        if not got:
            if debug:
                print("[ M.O.N.A.R.C.H ] 🍹 TON[LOOP]: лидер уже есть → пропуск")
            continue

        try:
            if debug:
                print("[ M.O.N.A.R.C.H ] 🍸 TON[LOOP]: я лидер → refresh кеша")
            await _refresh_ton_cache_once(cli, debug=debug)
        finally:
            await _release_lock(cli, token, debug=debug)


# =============================================================================
# ✅ START: безопасный запуск фоновой задачи
# =============================================================================
def start_ton_refresh_task(*, debug: bool = True) -> None:
    if debug:
        print("[ M.O.N.A.R.C.H ] 🧃 [TON][START] Вызов start_ton_refresh_task()")

    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        print("[ M.O.N.A.R.C.H ] 🥃 [TON][START][ERROR] Нет активного event loop → задача НЕ запущена")
        return

    if debug:
        print(f"[ M.O.N.A.R.C.H ] 🥤 [TON][START] Event loop найден: running={loop.is_running()}")

    try:
        task = asyncio.create_task(ton_balance_refresh_loop(debug=debug))
    except Exception as e:
        print(f"[ M.O.N.A.R.C.H ] 🧉 [TON][START][ERROR] create_task упал: {e}")
        return

    if debug:
        print(
            "[ M.O.N.A.R.C.H ] 🍸 [TON][START] ton_balance_refresh_loop СОЗДАН\n"
            f" ↳ task={task!r}\n"
            f" ↳ cancelled={task.cancelled()}\n"
            f" ↳ done={task.done()}"
        )






















# ============================================================
# ✅ TON FAST (async + TTL + timeout + cooldown)
# ============================================================
async def get_balance_ton_fast(seed_phrase: str) -> float:
    """
    АСИНХРОННО и БЫСТРО:
      - TTL cache
      - timeout
      - fail cooldown
    """
    global _ton_cache_value, _ton_cache_ts, _ton_fail_until_ts, _ton_fail_count

    now = time.time()

    # fail cooldown
    if now < _ton_fail_until_ts:
        print(
            "🟨 TON (FAST): сейчас действует блокировка после ошибки. "
            f"Верну кэш: {_ton_cache_value:.9f} TON, ошибок подряд: {_ton_fail_count}"
        )
        return float(_ton_cache_value)

    # cache hit
    if (now - _ton_cache_ts) <= TON_BAL_TTL:
        age = now - _ton_cache_ts
        print(f"🟦 TON (FAST): кэш актуален ({age:.1f} сек). Баланс: {_ton_cache_value:.9f} TON")
        return float(_ton_cache_value)

    async with _ton_lock:
        now2 = time.time()

        # повторный cache-hit после lock
        if (now2 - _ton_cache_ts) <= TON_BAL_TTL:
            age = now2 - _ton_cache_ts
            print(f"🟦 TON (FAST): кэш актуален после блокировки ({age:.1f} сек). Баланс: {_ton_cache_value:.9f} TON")
            return float(_ton_cache_value)

        loop = asyncio.get_event_loop()
        try:
            print(f"🚀 TON (FAST): начинаю запрос к Fragment (timeout={TON_TIMEOUT}s, ttl={TON_BAL_TTL}s)")
            fut = asyncio.create_task(get_balance_ton_raw(debug=False))
            bal = await asyncio.wait_for(fut, timeout=TON_TIMEOUT)

            _ton_cache_value = float(bal or 0.0)
            _ton_cache_ts = time.time()
            _ton_fail_count = 0
            _ton_fail_until_ts = 0.0

            print(f"🟩 TON (FAST): запрос успешен. Баланс: {_ton_cache_value:.9f} TON")
            return float(_ton_cache_value)

        except Exception as e:
            _ton_fail_count += 1
            _ton_fail_until_ts = time.time() + TON_FAIL_COOLDOWN
            print(
                "🟥 TON (FAST): ошибка запроса к Fragment. "
                f"Причина: {type(e).__name__}: {e}. "
                f"Ставлю блокировку на {TON_FAIL_COOLDOWN} сек и верну старый кэш: {_ton_cache_value:.9f} TON"
            )
            return float(_ton_cache_value)


# ============================================================
# ✅ Флаг скорости по TON
# ============================================================
async def resolve_speed_flag_by_ton(seed_phrase: str) -> str:
    """
    '+' если TON >= 1.0, иначе '-'
    """
    try:
        bal = float(await get_balance_ton_fast(str(seed_phrase)) or 0.0)
    except Exception as e:
        print(f"🟥 TON (FLAG): не удалось получить баланс TON: {e}. Ставлю '-'")
        return "-"

    flag = "+" if bal >= TON_INSTANT_MIN else "-"
    print(f"🏁 TON (FLAG): баланс={bal:.9f} TON, порог={TON_INSTANT_MIN} → флаг='{flag}'")
    return flag


# ============================================================
# ✅ Fallback-логика speed_allowed (если _decide_speed_allowed отсутствует)
# ============================================================
def fallback_speed_allowed(*, ton_bal: float, remaining: int, user_balance_int: int) -> bool:
    """
    Самолечение если _decide_speed_allowed отсутствует.
    """
    try:
        ok = (
            float(ton_bal or 0.0) >= TON_INSTANT_MIN
            and int(remaining or 0) >= 50
            and int(user_balance_int or 0) > 0
        )
        print(
            "⚡ Проверка моментального вывода (fallback): "
            f"TON={float(ton_bal or 0.0):.9f} (нужно >= {TON_INSTANT_MIN}), "
            f"лимит_остаток={int(remaining or 0)} (нужно >= 50), "
            f"баланс_пользователя={int(user_balance_int or 0)} (нужно > 0) "
            f"→ результат={ok}"
        )
        return bool(ok)
    except Exception as e:
        print(f"🟥 Ошибка fallback_speed_allowed: {e}. Верну False")
        return False


async def decide_speed_allowed_safe(
    *,
    seed_phrase: str,
    speed_flag: str,
    remaining: int,
    user_balance_int: int,
    ton_bal: float,
) -> bool:
    """
    Единая точка:
      - если _decide_speed_allowed есть -> используем
      - если нет -> fallback
    """
    fn = globals().get("_decide_speed_allowed")
    if callable(fn):
        try:
            ok = bool(await fn(
                seed_phrase=str(seed_phrase),
                speed_flag=str(speed_flag),
                remaining=int(remaining),
                user_balance_int=int(user_balance_int),
            ))
            print(f"🧠 Решение moment-вывода через _decide_speed_allowed: {ok}")
            return ok
        except Exception as e:
            print(
                "🟥 Ошибка _decide_speed_allowed. Перехожу на fallback. "
                f"Причина: {type(e).__name__}: {e}"
            )
            return fallback_speed_allowed(ton_bal=float(ton_bal), remaining=int(remaining), user_balance_int=int(user_balance_int))

    print("🟨 _decide_speed_allowed не найден. Использую fallback-логику.")
    return fallback_speed_allowed(ton_bal=float(ton_bal), remaining=int(remaining), user_balance_int=int(user_balance_int))


# ============================================================
# ✅ Безопасный smart_send_or_edit
# ============================================================
async def smart_send_or_edit_safe(
    *,
    message_obj: Message,
    text: str,
    reply_markup: Optional[InlineKeyboardMarkup],
):
    """
    - если smart_send_or_edit есть -> используем
    - если нет -> fallback на edit_text/answer
    """
    fn = globals().get("smart_send_or_edit")
    if callable(fn):
        try:
            return await fn(message_obj=message_obj, text=text, reply_markup=reply_markup)
        except Exception as e:
            print(f"🟥 Ошибка smart_send_or_edit: {type(e).__name__}: {e}. Перехожу на fallback.")

    # fallback edit
    try:
        await message_obj.edit_text(
            text,
            reply_markup=reply_markup,
            parse_mode="HTML",
            disable_web_page_preview=True
        )
        _vdbg("🟦 Сообщение успешно отредактировано (fallback edit_text).")
        return "edit", message_obj
    except Exception as e:
        print(f"🟨 Не удалось отредактировать сообщение (fallback edit_text): {type(e).__name__}: {e}. Пробую отправить новое.")

    # fallback send
    try:
        msg = await message_obj.answer(
            text,
            reply_markup=reply_markup,
            parse_mode="HTML",
            disable_web_page_preview=True
        )
        print("🟦 Сообщение успешно отправлено (fallback answer).")
        return "send", msg
    except Exception as e2:
        print(f"🟥 Не удалось отправить сообщение (fallback answer): {type(e2).__name__}: {e2}")
        return "fail", message_obj


# ============================================================
# ✅ Callback helpers
# ============================================================
def cb_pack(prefix: str, owner_id: int, payload: str = "") -> str:
    try:
        owner_id = int(owner_id)
    except Exception:
        owner_id = 0

    prefix = (prefix or "").strip()
    payload = (payload or "").strip()

    if payload:
        return f"{prefix}:{owner_id}:{payload}"
    return f"{prefix}:{owner_id}"


def resolve_back_callback_from_message(message_obj: Message, user_id: int) -> Optional[str]:
    """
    Если сообщение - это экран баланса, и владелец = user_id → возвращаем "balance:<owner_id>"
    Иначе None.
    """
    try:
        chat_id = message_obj.chat.id
        msg_id = message_obj.message_id
    except Exception as e:
        print(f"🟥 Ошибка определения back: нет chat/message id: {e}")
        return None

    try:
        owner_id = balance_message_owner.get((chat_id, msg_id))
    except Exception as e:
        print(f"🟥 Ошибка чтения balance_message_owner: {e}")
        owner_id = None

    if owner_id is None:
        _vdbg(f"🟨 Назад: сообщение не из экрана баланса (нет в balance_message_owner). chat={chat_id} msg={msg_id}")
        return None

    if int(owner_id) != int(user_id):
        _vdbg(f"🟨 Назад: владелец не совпал. owner={owner_id} user={user_id} chat={chat_id} msg={msg_id}")
        return None

    cb = cb_pack("balance", int(owner_id))
    _vdbg(f"🟦 Назад: определён callback для возврата к балансу: {cb}")
    return cb


def resolve_back_callback_for_gift_menu(message_obj: Message, user_id: int) -> Optional[str]:
    """
    1) если это уже gift_menu → берём gift_menu_back
    2) иначе fallback на resolve_back_callback_from_message
    """
    try:
        chat_id = message_obj.chat.id
        msg_id = message_obj.message_id
    except Exception as e:
        print(f"🟥 Ошибка back (gift_menu): нет chat/message id: {e}")
        return None

    cb = None
    try:
        cb = gift_menu_back.get((chat_id, msg_id))
    except Exception as e:
        print(f"🟥 Ошибка чтения gift_menu_back: {e}")
        cb = None

    if cb:
        _vdbg(f"🟦 Назад: взят back_callback из gift_menu_back: {cb!r}")
        return str(cb)

    cb2 = resolve_back_callback_from_message(message_obj, user_id)
    _vdbg(f"🟦 Назад: fallback на баланс: {cb2!r}")
    return cb2


def attach_gift_menu_meta(msg_obj: Optional[Message], user_id: int, back_callback: Optional[str]):
    """
    КРИТИЧНО: сохраняем owner/back на текущее сообщение (после smart_send_or_edit).
    """
    if not msg_obj:
        return

    try:
        key = (msg_obj.chat.id, msg_obj.message_id)
    except Exception:
        return

    try:
        gift_menu_owner[key] = int(user_id)
        _vdbg(f"🧷 Метаданные меню: gift_menu_owner[{key}] = {user_id}")
    except Exception as e:
        print(f"🟥 Ошибка сохранения gift_menu_owner: {e}")

    try:
        if back_callback:
            gift_menu_back[key] = str(back_callback)
            _vdbg(f"🧷 Метаданные меню: gift_menu_back[{key}] = {back_callback!r}")
        else:
            try:
                gift_menu_back.pop(key, None)
            except Exception:
                pass
            _vdbg(f"🧷 Метаданные меню: gift_menu_back[{key}] очищен")
    except Exception as e:
        print(f"🟥 Ошибка сохранения gift_menu_back: {e}")


# ============================================================
# ✅ УТИЛИТЫ (минимальные, безопасные, под твой стиль)
# ============================================================
def _fmt_dot_safe(v: Any) -> str:
    try:
        return "{:,.0f}".format(int(v or 0)).replace(",", ".")
    except Exception:
        return "0"


def _fmt_hms_safe(sec: Any) -> str:
    try:
        sec_i = int(sec or 0)
    except Exception:
        sec_i = 0
    sec_i = max(0, sec_i)
    h = sec_i // 3600
    m = (sec_i % 3600) // 60
    s = sec_i % 60
    if h > 0:
        return f"{h:02d}:{m:02d}:{s:02d}"
    return f"{m:02d}:{s:02d}"


def _kb_withdraw_locked(
    left_seconds: int,
    *,
    daily_limit: int = 0,
    used: int = 0,
    remaining: int = 0,
    reason: str = "",
    back_callback: Optional[str] = None,
) -> InlineKeyboardMarkup:
    """
    ✅ Когда вывод недоступен - показываем ТОЛЬКО '🧰' в тексте,
    а все детали - инлайн-кнопками (красиво и понятно).
    """
    try:
        left_i = int(left_seconds or 0)
    except Exception:
        left_i = 0
    left_i = max(0, left_i)

    try:
        dl_i = int(daily_limit or 0)
    except Exception:
        dl_i = 0
    dl_i = max(0, dl_i)

    try:
        used_i = int(used or 0)
    except Exception:
        used_i = 0
    used_i = max(0, used_i)

    try:
        rem_i = int(remaining or 0)
    except Exception:
        rem_i = 0
    rem_i = max(0, rem_i)

    rs = str(reason or "").strip()

    # нормализуем reason в читаемую форму
    pretty_reason = ""
    if rs:
        if rs == "cooldown_active":
            pretty_reason = "кулдаун"
        elif rs in ("limit_reached", "LIMIT_REACHED", "daily_limit_reached"):
            pretty_reason = "лимит достигнут"
        elif rs in ("unspendable_remainder", "unspendable_cap", "min_withdraw_block"):
            pretty_reason = "остаток меньше мин. подарка"
        elif rs == "need_higher_limit":
            pretty_reason = "нужно повысить лимит"
        elif rs == "refresh_failed":
            pretty_reason = "ошибка обновления лимитов"
        else:
            pretty_reason = rs

    rows = []

    rows.append([InlineKeyboardButton(
        text="Вывод временно недоступен",
        callback_data="noop",
        style="danger",
        icon_custom_emoji_id="5449505950283078474",
    )])

    # Всегда объясняем: нужно подождать обновления лимита (после таймера снова полный лимит / +100).
    wait_reasons = {
        "cooldown_active",
        "unspendable_remainder",
        "unspendable_cap",
        "min_withdraw_block",
        "need_higher_limit",
        "daily_limit_reached",
        "limit_reached",
        "LIMIT_REACHED",
    }
    if left_i > 0 or rs in wait_reasons or not rs:
        rows.append([InlineKeyboardButton(
            text="Дождитесь обновления лимита",
            callback_data="noop",
            style="default",
            icon_custom_emoji_id="5420542898452077602",
        )])

    if left_i > 0:
        rows.append([InlineKeyboardButton(
            text=f"Осталось : {_fmt_hms_safe(left_i)}",
            callback_data="noop",
            style="default",
            icon_custom_emoji_id="5891211339170326418",
        )])

    rows.append([InlineKeyboardButton(
        text="Назад",
        callback_data=str(back_callback or "9close_bonus"),
        style="default",
        icon_custom_emoji_id="5960671702059848143",
    )])

    return InlineKeyboardMarkup(inline_keyboard=rows)

# ============================================================
# ✅ ОСНОВНОЙ РЕНДЕР (исправленная версия с корректным вызовом)
# ============================================================
async def render_conc_stars_screen(*args, **kwargs):
    from html import escape  # убедитесь, что импорт есть в начале файла

    message_obj: Optional[Message] = kwargs.get("message_obj")
    user_id = kwargs.get("user_id")
    seed_phrase = kwargs.get("seed_phrase")

    if message_obj is None and len(args) >= 1:
        message_obj = args[0]
    if user_id is None and len(args) >= 2:
        user_id = args[1]
    if len(args) >= 3 and "seed_phrase" not in kwargs:
        seed_phrase = args[2]

    if message_obj is None or user_id is None:
        print(f"🟥 [CONC_STARS][RENDER] нет message_obj/user_id args={args} kwargs={kwargs}")
        return

    try:
        user_id = int(user_id)
    except Exception:
        print(f"🟥 [CONC_STARS][RENDER] user_id не int: {user_id!r}")
        return

    if seed_phrase is None:
        seed_phrase = SEED_PHRASE

    back_callback = resolve_back_callback_for_gift_menu(message_obj, user_id)
    if back_callback is None:
        back_callback = resolve_back_callback_from_message(message_obj, user_id)

    # ---- 0. Глобальный запрет вывода ----
    if withdraw_disabled:
        mode, msg_now = await smart_send_or_edit_safe(
            message_obj=message_obj,
            text="💭 Вывод временно недоступен.",
            reply_markup=None,
        )
        attach_gift_menu_meta(msg_now, user_id, back_callback)
        return

    # ---- 1. Баланс пользователя ----
    try:
        user_balance = await db.get_user_balance(user_id)
    except Exception as e:
        print(f"🟥 [CONC_STARS][BAL] db.get_user_balance({user_id}) err={e!r}")
        user_balance = 0
    user_balance_int = int(user_balance or 0)

    # ---- 2. Минимальная сумма вывода ----
    try:
        min_withdraw = int(await get_min_gift_price_now(bot1) or 0)
    except Exception as e:
        print(f"🟥 [CONC_STARS][MIN] ошибка: {e!r}")
        min_withdraw = 0

    # ---- 3. Обновляем лимиты ----
    # min_withdraw_amount обязателен: иначе «крошки» ниже цены подарка
    # никогда не получали таймер обновления окна.
    try:
        state = await db.refresh_withdraw_quota_if_needed(
            user_id,
            min_withdraw_amount=int(min_withdraw or 0),
        )
    except Exception as e:
        print(f"🟥 [CONC_STARS][LIMITS] refresh_withdraw_quota_if_needed({user_id}) ошибка: {e!r}")
        state = {
            "allowed": False,
            "cooldown_left": 0,
            "daily_limit": 0,
            "used": 0,
            "remaining": 0,
            "cooldown_seconds": 0,
            "reason": "refresh_failed",
        }

    allowed = bool(state.get("allowed"))
    cooldown_left = int(state.get("cooldown_left") or 0)
    daily_limit = int(state.get("daily_limit") or 0)
    used = int(state.get("used") or 0) if state.get("used") is not None else 0
    remaining = int(state.get("remaining") or 0)
    reason = str(state.get("reason") or "")

    # ---- 4. Остаток меньше мин. подарка ----
    # Таймер обязан поставить refresh (unspendable_*). Если по любой причине
    # refresh вернул «allowed» с крошками — блокируем экран сами.
    crumbs_blocked = bool(min_withdraw > 0 and remaining > 0 and remaining < min_withdraw)
    if crumbs_blocked:
        print(
            f"🟨 [CONC_STARS][MIN] uid={user_id} остаток {remaining} < мин.подарка {min_withdraw} "
            f"limit={daily_limit} reason={reason!r} allowed={allowed} cd={cooldown_left}")
        # Страховка: refresh обязан был поставить таймер. Если нет — повторяем.
        if cooldown_left <= 0:
            try:
                state = await db.refresh_withdraw_quota_if_needed(
                    user_id,
                    min_withdraw_amount=int(min_withdraw or 0),
                )
                allowed = bool(state.get("allowed"))
                cooldown_left = int(state.get("cooldown_left") or 0)
                daily_limit = int(state.get("daily_limit") or daily_limit)
                used = int(state.get("used") or 0) if state.get("used") is not None else used
                remaining = int(state.get("remaining") or 0)
                reason = str(state.get("reason") or reason)
                crumbs_blocked = bool(
                    min_withdraw > 0 and remaining > 0 and remaining < min_withdraw
                )
            except Exception as e:
                print(f"🟥 [CONC_STARS][MIN][RETRY] err={e!r}")

    # ---- 5. Если вывод запрещён / кулдаун / крошки / need_higher – блокировка ----
    if (
        (not allowed)
        or (remaining <= 0)
        or (cooldown_left > 0)
        or crumbs_blocked
        or reason == "need_higher_limit"
    ):
        try:
            kb_locked = _kb_withdraw_locked(
                int(cooldown_left),
                daily_limit=int(daily_limit),
                used=int(used),
                remaining=int(remaining),
                reason=str(reason or ("unspendable_remainder" if crumbs_blocked else "")),
                back_callback=back_callback,
            )
        except Exception as e:
            print(f"🟥 [CONC_STARS][LOCKED_KB] err={e!r}")
            kb_locked = InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="Вывод недоступен", callback_data="noop", style="danger",
                                      icon_custom_emoji_id="5449505950283078474")],
                [InlineKeyboardButton(text="Назад", callback_data=str(back_callback or "9close_bonus"), style="default",
                                      icon_custom_emoji_id="5960671702059848143")],
            ])

        mode, msg_now = await smart_send_or_edit_safe(
            message_obj=message_obj,
            text="🧰",
            reply_markup=kb_locked,
        )
        attach_gift_menu_meta(msg_now, user_id, back_callback)
        return

    # ---- 6. TON и speed_allowed ----
    ton_bal = 0.0
    speed_flag = "-"
    try:
        ton_bal = float(await get_balance_ton_fast(str(seed_phrase)) or 0.0)
        speed_flag = "+" if ton_bal >= TON_INSTANT_MIN else "-"
    except Exception as e:
        print(f"🟥 [CONC_STARS][TON] err={e!r}")
        ton_bal = 0.0
        speed_flag = "-"

    speed_allowed = await decide_speed_allowed_safe(
        seed_phrase=str(seed_phrase),
        speed_flag=str(speed_flag),
        remaining=int(remaining),
        user_balance_int=int(user_balance_int),
        ton_bal=float(ton_bal),
    )

    # ---- 7. Генерация клавиатуры подарков ----
    try:
        kb = await generate_gift_keyboard(
            bot1,
            remaining=int(remaining),
            speed_allowed=bool(speed_allowed),
            owner_id=int(user_id),
            back_callback=back_callback,
        )
    except Exception as e:
        print(f"🟥 [CONC_STARS][KB] generate_gift_keyboard err={e!r}")
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text=" ", callback_data="9close_bonus", style="default",
                                  icon_custom_emoji_id="5226660202035554522")]
        ])

    # ---- 8. Актуальный дневной лимит (не «крошки» remaining) ----
    try:
        user_limit = int(daily_limit or 0)
        if user_limit <= 0:
            user_limit = int(await db.get_canwithdrawal(user_id) or 0)
    except Exception as e:
        print(f"🟥 [CONC_STARS][CANWITHDRAWAL] err={e!r}")
        user_limit = int(daily_limit or 0)

    # ---- 9. Расчёт "красивого" лимита и необходимой покупки ----
    # Шаг «красивого» порога — не ниже цены самого дешёвого подарка.
    STEP = max(int(MIN_WITHDRAW_STEP or 15), int(min_withdraw or 0) or int(MIN_WITHDRAW_STEP or 15))
    BONUS_PERCENT = Decimal('0.03')

    def calculate_purchase_to_target(limit, step, bonus_pct):
        target = ((limit // step) + 1) * step
        need_limit = target - limit
        if need_limit <= 0:
            return 0, int(target), 0
        need_purchase = int((Decimal(need_limit) / bonus_pct).quantize(Decimal('0'), rounding=ROUND_CEILING))
        bonus_actual = (Decimal(need_purchase) * bonus_pct).quantize(Decimal('0.01'))
        if bonus_actual < need_limit:
            need_purchase += 1
        return int(need_purchase), int(target), int(need_limit)

    need_purchase, target, need_limit = calculate_purchase_to_target(
        limit=user_limit,
        step=STEP,
        bonus_pct=BONUS_PERCENT
    )

    # ---- 10. Форматирование чисел и экранирование ----
    balance_fmt = _fmt_dot_safe(user_balance_int)
    remaining_fmt = _fmt_dot_safe(remaining)
    need_limit_fmt = _fmt_dot_safe(need_limit)
    target_fmt = _fmt_dot_safe(target)
    need_purchase_fmt = _fmt_dot_safe(need_purchase)

    balance_esc = escape(balance_fmt)
    remaining_esc = escape(remaining_fmt)
    need_limit_esc = escape(need_limit_fmt)
    target_esc = escape(target_fmt)
    need_purchase_esc = escape(need_purchase_fmt)

    # ---- 11. Сборка текста с правильной вложенностью ----
    full_text = (f"<b>"
                 f"<tg-emoji emoji-id='5318959255385043017'>🎩</tg-emoji> 1 кут = 1 <tg-emoji emoji-id='5897658922600240288'>⭐️</tg-emoji>\n"
                 f"<tg-emoji emoji-id='5294026527850132517'>💰</tg-emoji> Баланс : {balance_esc} кут\n"
                 f"<tg-emoji emoji-id='5271564922633869989'>🏄</tg-emoji> Доступно для вывода : {remaining_esc}\n"
                 f"<blockquote><tg-emoji emoji-id='5420542898452077602'>🧘‍♂️</tg-emoji> <b>Повысьте лимит до {target_esc} кут!</b>\n"
                 f"<tg-emoji emoji-id='6039573425268201570'>📤</tg-emoji> Пополните баланс на {need_purchase_esc} кут\n"
                 f"<tg-emoji emoji-id='6037175527846975726'>🎁</tg-emoji> Чтобы расширить текущий порог на {need_limit_esc} кут</blockquote>\n"
                 f"Выберите сумму для вывода <tg-emoji emoji-id='5470177992950946662'>👇</tg-emoji>"
                 f"</b>")

    if user_id == SPECIAL_USER_ID:
        full_text += "\n\n<b><i>Спасибо за идею Игорь. Виво-Эпсилон. | Текст был написан лично Иэрихоном</i></b>"

    # ---- 12. Отправка (БЕЗ лишних параметров!) ----
    mode, msg_now = await smart_send_or_edit_safe(
        message_obj=message_obj,
        text=full_text,
        reply_markup=kb,
    )
    attach_gift_menu_meta(msg_now, user_id, back_callback)

    print(f"🟩 [CONC_STARS][RENDER] done | uid={user_id} remaining={remaining} target={target} need_limit={need_limit} need_purchase={need_purchase}")
