@dp.callback_query(lambda c: c.data and (c.data == "conc_stars" or c.data.startswith("conc_stars:")))  # noqa: F821
async def conc_stars_callback(callback_query: types.CallbackQuery):
    try:
        await callback_query.answer()
    except Exception:
        pass

    if withdraw_disabled:  # noqa: F821
        try:
            await send_withdraw_disabled_message(callback_query)  # noqa: F821
        except Exception as e:
            print(f"🟥 Ошибка send_withdraw_disabled_message: {e}")
        return

    user_id = callback_query.from_user.id

    # speed_flag строго по TON >= 1
    speed_flag = "-"
    try:
        speed_flag = await resolve_speed_flag_by_ton(SEED_PHRASE)  # noqa: F821
    except Exception as e:
        print(f"🟥 Ошибка resolve_speed_flag_by_ton: {e}")
        speed_flag = "-"

    print(f"🟦 Нажатие conc_stars: user_id={user_id}, speed_flag='{speed_flag}'")

    # PRIVATE
    if callback_query.message.chat.type == "private":
        try:
            await render_conc_stars_screen(callback_query.message, int(user_id), SEED_PHRASE)
        except Exception as e:
            print(f"🟥 Ошибка render_conc_stars_screen из callback: {e}")
        return

    # GROUP / CHANNEL
    try:
        chat_id = callback_query.message.chat.id
        msg_id = callback_query.message.message_id
        owner_id_for_back = balance_message_owner.get((chat_id, msg_id), user_id)
    except Exception:
        owner_id_for_back = user_id

    try:
        bot_username = await get_bot_username_by_token(TOKEN)  # noqa: F821
    except Exception as e:
        print(f"🟥 Ошибка определения имени бота: {e}")
        bot_username = None

    if not bot_username:
        try:
            await callback_query.answer("Ошибка определения бота.", show_alert=True)
        except Exception:
            pass
        return

    group_rows = [
        [InlineKeyboardButton(text="Открыть вывод в боте", url=f"https://t.me/{bot_username}?start=deep_conc_stars", style="default" ,
                            icon_custom_emoji_id="6028338546736107668")],
        [InlineKeyboardButton(text="Назад к балансу", callback_data=cb_pack("balance", int(owner_id_for_back), style="default" ,
                            icon_custom_emoji_id="5960671702059848143"))],
    ]

    if speed_flag == "+":
        group_rows.insert(
            1,
            [InlineKeyboardButton(text="⚡️ Моментальный вывод возможен", url=f"https://t.me/{bot_username}?start=deep_conc_stars+")]
        )

    kb = InlineKeyboardMarkup(inline_keyboard=group_rows)

    try:
        emoji_id = get_random_emoji_id()
        await callback_query.message.edit_text(f"<tg-emoji emoji-id='{emoji_id}'>💰</tg-emoji>", reply_markup=kb, parse_mode="HTML")
    except Exception as e:
        print(f"🟥 Ошибка edit_text в группе: {e}")
        try:
            await callback_query.message.edit_reply_markup(reply_markup=kb)
        except Exception as e2:
            print(f"🟥 Ошибка edit_reply_markup в группе: {e2}")




