# ============================================================
# 0) HELPERS: длина callback + безопасный хвост +/owner
# ============================================================

def _cb_len(s: str) -> int:
    try:
        return len(s.encode("utf-8"))
    except Exception:
        return len(s)


def _append_sig_owner_safe(base_cb: str, back_signal: str, owner_id_for_back: int) -> str:
    """
    Аккуратно дописывает хвост:
      _+_{owner}  или  _-
    и следит за лимитом callback_data.
    """
    sig = "+" if str(back_signal or "") == "+" else "-"
    owner = int(owner_id_for_back or 0)

    if sig == "+":
        cb = f"{str(base_cb or '')}_+_{owner}"
    else:
        cb = f"{str(base_cb or '')}_-"

    _ensure_cb_len(cb, "prep_callback_with_suffix")
    return cb


def _make_back_button_from_signal(*, back_signal: str, owner_id_for_back: int, user_id: int) -> InlineKeyboardButton:
    """
    ✅ ЕДИНЫЙ способ строить кнопку "Назад" везде.
    """
    if back_signal == "+":
        safe_owner = int(owner_id_for_back or user_id)
        return InlineKeyboardButton(text="Назад к балансу", callback_data=f"balance:{safe_owner}", style="default" ,
                            icon_custom_emoji_id="5960671702059848143")
    return InlineKeyboardButton(text="Назад", callback_data="back_to_stars_choice", style="default" ,
                            icon_custom_emoji_id="5960671702059848143")


def _get_back_from_user_gift(user_id: int, default_owner: int = 0) -> Tuple[str, int]:
    """
    ✅ Для будущего: достаём back_signal/owner из user_gift.
    Если вдруг нет - вернём дефолты.
    """
    try:
        d = user_gift.get(user_id) or {}
        sig = str(d.get("back_signal") or "-")
        own = int(d.get("owner_id_for_back") or default_owner or 0)
        if sig not in ("+", "-"):
            sig = "-"
        return sig, own
    except Exception:
        return "-", int(default_owner or 0)


# ============================================================
# 1) BTNSTARS PARSE + TOGGLE BUILD
# ============================================================

def _parse_btnstars_underscore(raw: str):
    """
    Поддержка:
      btnstars_{gid}_{base}_{upg}_{nft}
      btnstars_{gid}_{base}_{upg}_{nft}_+_{owner}
      btnstars_{gid}_{base}_{upg}_{nft}_-
    """
    parts = raw.split("_")
    if len(parts) < 5:
        raise ValueError(f"too short btnstars: {parts}")

    gift_id = parts[1]
    base_amount = int(parts[2])
    upgrade_price = int(parts[3]) if parts[3] != "None" else 0
    nft_enabled = int(parts[4])

    back_signal = "-"
    owner_id_for_back = 0

    if len(parts) >= 6 and parts[5] in ("+", "-"):
        back_signal = parts[5]
        if back_signal == "+" and len(parts) >= 7:
            try:
                owner_id_for_back = int(parts[6])
            except Exception:
                owner_id_for_back = 0

    return gift_id, base_amount, upgrade_price, nft_enabled, back_signal, owner_id_for_back


def _parse_btnstars_sts(raw: str):
    """
    sts:g:{gift_id}:{base}:{upgrade}:{nft}:{sig}:{owner?}
    """
    parts = raw.split(":")
    if len(parts) < 6:
        raise ValueError(f"too short sts:g: {parts}")

    gift_id = str(parts[2]).strip()
    base_amount = int(parts[3])
    upgrade_price = int(parts[4]) if parts[4] != "None" else 0
    nft_enabled = int(parts[5])

    back_signal = "-"
    owner_id_for_back = 0

    if len(parts) >= 7 and parts[6] in ("+", "-"):
        back_signal = parts[6]
    if back_signal == "+" and len(parts) >= 8:
        try:
            owner_id_for_back = int(parts[7])
        except Exception:
            owner_id_for_back = 0

    return gift_id, base_amount, upgrade_price, nft_enabled, back_signal, owner_id_for_back


def _build_toggle_callback(
    *,
    gift_id: str,
    base_amount: int,
    upgrade_price: int,
    new_nft_enabled: int,
    back_signal: str,
    owner_id_for_back: int,
) -> str:
    """
    БАЗА: btnstars_{gid}_{base}_{upg}_{new}
    + хвост _+_{owner} или _- (если влезает)
    """
    base = f"btnstars_{gift_id}_{int(base_amount)}_{int(upgrade_price)}_{int(new_nft_enabled)}"
    return _append_sig_owner_safe(base, back_signal, int(owner_id_for_back or 0))


# ============================================================
# 2) PREPARATIONSEND PARSE (underscore + sts) ✅ ДОБАВЛЕНО
# ============================================================

def _parse_preparationsend_underscore(raw: str):
    """
    Поддержка (устойчиво к "_" в gift_name):
      preparationsend_{hu}_{gift_name}_{base}_{upg}_{gift_id}
      preparationsend_{hu}_{gift_name}_{base}_{upg}_{gift_id}_-
      preparationsend_{hu}_{gift_name}_{base}_{upg}_{gift_id}_+_{owner}

    Парсим с конца, потому что gift_name может содержать "_".
    """
    parts = raw.split("_")
    if len(parts) < 6:
        raise ValueError(f"too short preparationsend: {parts}")

    if parts[0] != "preparationsend":
        raise ValueError(f"wrong prefix preparationsend: {parts[:1]}")

    has_upgrade = int(parts[1])

    back_signal = "-"
    owner_id_for_back = 0

    core = parts

    # хвост
    if parts[-1] in ("+", "-"):
        back_signal = parts[-1]
        core = parts[:-1]
    elif len(parts) >= 2 and parts[-2] in ("+", "-"):
        back_signal = parts[-2]
        if back_signal == "+":
            try:
                owner_id_for_back = int(parts[-1])
            except Exception:
                owner_id_for_back = 0
        core = parts[:-2]

    if len(core) < 6:
        raise ValueError(f"too short core preparationsend: {core}")

    gift_id = int(core[-1])
    upgrade_price = int(core[-2]) if core[-2] != "None" else 0
    base_amount = int(core[-3])

    gift_name = "_".join(core[2:-3])  # всё между has_upgrade и base_amount

    return has_upgrade, gift_name, base_amount, upgrade_price, gift_id, back_signal, owner_id_for_back


def _parse_preparationsend_sts(raw: str):
    """
    Поддержка 2 вариантов (чтобы не ломалось):
    A) sts:ps:{hu}:{gift_name}:{base}:{upg}:{gift_id}:{sig}:{owner?}
    B) sts:ps:{hu}:{base}:{upg}:{gift_id}:{sig}:{owner?}   (если захотишь без gift_name)

    Мы определяем по тому, что на позиции base должно быть число.
    """
    parts = raw.split(":")
    if len(parts) < 6:
        raise ValueError(f"too short sts:ps: {parts}")

    if parts[0] != "sts" or parts[1] != "ps":
        raise ValueError(f"wrong prefix sts:ps: {parts[:2]}")

    has_upgrade = int(parts[2])

    # Определяем, где base:
    # если parts[3] - число => формат B (без gift_name)
    # иначе => формат A (с gift_name)
    gift_name = ""
    idx = 3
    try:
        _ = int(parts[3])
        # формат B
        gift_name = ""
        base_amount = int(parts[3])
        upgrade_price = int(parts[4]) if parts[4] != "None" else 0
        gift_id = int(parts[5])
        sig_idx = 6
    except Exception:
        # формат A
        gift_name = parts[3]
        base_amount = int(parts[4])
        upgrade_price = int(parts[5]) if parts[5] != "None" else 0
        gift_id = int(parts[6])
        sig_idx = 7

    back_signal = "-"
    owner_id_for_back = 0

    if len(parts) > sig_idx and parts[sig_idx] in ("+", "-"):
        back_signal = parts[sig_idx]
    if back_signal == "+" and len(parts) > sig_idx + 1:
        try:
            owner_id_for_back = int(parts[sig_idx + 1])
        except Exception:
            owner_id_for_back = 0

    return has_upgrade, gift_name, base_amount, upgrade_price, gift_id, back_signal, owner_id_for_back


def _build_preparationsend_callback_smart(
    *,
    has_upgrade: int,
    gift_name: str,
    base_amount: int,
    upgrade_price: int,
    gift_id: int,
    back_signal: str,
    owner_id_for_back: int,
) -> str:
    """
    ✅ ЛОГИКА (как у тебя):
    - Если back_signal == "+" -> пробуем sts:ps (обход лимита)
    - иначе preparationsend_... + хвост _+_{owner} / _-
    """
    if back_signal not in ("+", "-"):
        back_signal = "-"

    owner = int(owner_id_for_back or 0)

    if back_signal == "+":
        sts_cb = f"sts:ps:{int(has_upgrade)}:{gift_name}:{int(base_amount)}:{int(upgrade_price)}:{int(gift_id)}:+:{owner}"
        if _cb_len(sts_cb) <= 64:
            return sts_cb

    base_old = f"preparationsend_{int(has_upgrade)}_{gift_name}_{int(base_amount)}_{int(upgrade_price)}_{int(gift_id)}"
    return _append_sig_owner_safe(base_old, back_signal, owner)


# ============================================================
# 3) GIFT_SEND_REQUEST (underscore + sts) + skip tools ✅
# ============================================================

def _parse_gift_send_request_underscore(raw: str):
    """
    Поддержка (устойчиво к "_" в gift_name):
      gift_send_request_{nft}_{gift_name}_{base}_{upg}_{amount}_{gift_id}
      gift_send_request_{nft}_{gift_name}_{base}_{upg}_{amount}_{gift_id}_-
      gift_send_request_{nft}_{gift_name}_{base}_{upg}_{amount}_{gift_id}_+_{owner}

    Парсим с конца.
    """
    parts = raw.split("_")
    if len(parts) < 8:
        raise ValueError(f"too short gift_send_request: {parts}")

    if parts[0] != "gift" or parts[1] != "send" or parts[2] != "request":
        raise ValueError(f"wrong prefix gift_send_request: {parts[:3]}")

    back_signal = "-"
    owner_id_for_back = 0

    core = parts

    if parts[-1] in ("+", "-"):
        back_signal = parts[-1]
        core = parts[:-1]
    elif len(parts) >= 2 and parts[-2] in ("+", "-"):
        back_signal = parts[-2]
        if back_signal == "+":
            try:
                owner_id_for_back = int(parts[-1])
            except Exception:
                owner_id_for_back = 0
        core = parts[:-2]

    if len(core) < 8:
        raise ValueError(f"too short core gift_send_request: {core}")

    nft_enabled = int(core[3])

    gift_id = int(core[-1])
    amount = int(core[-2])
    upgrade_price = int(core[-3]) if core[-3] != "None" else 0
    base_amount = int(core[-4])

    gift_name = "_".join(core[4:-4])

    return nft_enabled, gift_name, base_amount, upgrade_price, amount, gift_id, back_signal, owner_id_for_back


def _parse_gift_send_request_sts(raw: str):
    """
    sts:gr:{nft}:{base}:{upg}:{amount}:{gift_id}:{sig}:{owner?}
    """
    parts = raw.split(":")
    if len(parts) < 7:
        raise ValueError(f"too short sts:gr: {parts}")

    if parts[0] != "sts" or parts[1] != "gr":
        raise ValueError(f"wrong prefix sts:gr: {parts[:2]}")

    nft_enabled = int(parts[2])
    base_amount = int(parts[3])
    upgrade_price = int(parts[4]) if parts[4] != "None" else 0
    amount = int(parts[5])
    gift_id = int(parts[6])

    back_signal = "-"
    owner_id_for_back = 0

    if len(parts) >= 8 and parts[7] in ("+", "-"):
        back_signal = parts[7]
    if back_signal == "+" and len(parts) >= 9:
        try:
            owner_id_for_back = int(parts[8])
        except Exception:
            owner_id_for_back = 0

    gift_name = ""  # в STS не передаём
    return nft_enabled, gift_name, base_amount, upgrade_price, amount, gift_id, back_signal, owner_id_for_back


def _is_skip_flag(original_data: str) -> Tuple[bool, str]:
    if original_data.endswith("_skip"):
        return True, original_data[:-5]
    if original_data.endswith(":skip"):
        return True, original_data[:-5]
    return False, original_data


def _build_skip_cb(original_data: str) -> str:
    if original_data.startswith("sts:gr:"):
        if original_data.endswith(":skip"):
            return original_data
        return f"{original_data}:skip"
    else:
        if original_data.endswith("_skip"):
            return original_data
        return f"{original_data}_skip"


def _build_gift_send_request_callback_smart(
    *,
    nft_enabled: int,
    gift_name: str,
    base_amount: int,
    upgrade_price: int,
    amount: int,
    gift_id: int,
    back_signal: str,
    owner_id_for_back: int,
) -> str:
    """
    ✅ Умный callback для "🎁 Другу":
    - сначала пробуем старый формат + хвост _+_{owner}/_-
    - если не влезает -> sts:gr:...
    """
    if back_signal not in ("+", "-"):
        back_signal = "-"

    owner = int(owner_id_for_back or 0)

    base_old = (
        f"gift_send_request_{int(nft_enabled)}_{str(gift_name)}_"
        f"{int(base_amount)}_{int(upgrade_price)}_{int(amount)}_{int(gift_id)}"
    )
    cb_old = f"{base_old}_+_{owner}" if back_signal == "+" else f"{base_old}_-"
    if _cb_len(cb_old) <= 64:
        return cb_old

    cb_sts = (
        f"sts:gr:{int(nft_enabled)}:{int(base_amount)}:{int(upgrade_price)}:"
        f"{int(amount)}:{int(gift_id)}:{back_signal}"
    )
    if back_signal == "+":
        cb_sts = f"{cb_sts}:{owner}"

    if _cb_len(cb_sts) <= 64:
        return cb_sts

    # fallback: старый без хвоста
    if _cb_len(base_old) <= 64:
        return base_old

    # крайний fallback: sts без owner
    return f"sts:gr:{int(nft_enabled)}:{int(base_amount)}:{int(upgrade_price)}:{int(amount)}:{int(gift_id)}:{back_signal}"


