async def get_gift_details_fast(bot1, gift_id: str) -> Tuple[Optional[str], Optional[str]]:
    """
    ✅ FAST: Возвращает (emoji, limit_text) без лишнего запроса.
    limit_text = "used / total" (если total_count/remaining_count доступны)
    """
    try:
        print(f"🔵🧾 [GIFTS][DETAILS_FAST] start gift_id={gift_id}")
        gifts = await get_available_gifts_fast(bot1)
        print(f"🟦🧾 [GIFTS][DETAILS_FAST] gifts_cached={len(gifts)}")
    except Exception as e:
        print(f"🟥🧾 [GIFTS][DETAILS_FAST][ERROR] get_available_gifts_fast: {type(e).__name__}: {e}")
        return None, None

    for gift in gifts:
        try:
            current_id = str(getattr(gift, "id", ""))
            if current_id != str(gift_id):
                continue

            emoji = getattr(getattr(gift, "sticker", None), "emoji", "🎁")

            total = getattr(gift, "total_count", None)
            remaining_count = getattr(gift, "remaining_count", None)

            limit_text = None
            if total is not None and remaining_count is not None:
                try:
                    total_i = int(total)
                    rem_i = int(remaining_count)
                    used_i = max(0, total_i - rem_i)

                    used_fmt = "{:,.0f}".format(used_i).replace(",", ".")
                    total_fmt = "{:,.0f}".format(total_i).replace(",", ".")
                    limit_text = f"{used_fmt} / {total_fmt}"
                except Exception as e:
                    print(f"🟨🧾 [GIFTS][DETAILS_FAST][WARN] format counts: {e}")
                    limit_text = None

            print(f"🟩🧾 [GIFTS][DETAILS_FAST] OK gift_id={gift_id} emoji={emoji} limit={limit_text!r}")
            return str(emoji), limit_text

        except Exception as e:
            print(f"🟥🧾 [GIFTS][DETAILS_FAST][ERROR] gift_id={gift_id}: {type(e).__name__}: {e}")

    print(f"🟨🧾 [GIFTS][DETAILS_FAST] not found gift_id={gift_id}")
    return None, None


async def extract_gift_counts_fast(bot1, gift_id: str) -> Tuple[Optional[int], Optional[int], Optional[int]]:
    """
    ✅ FAST: Возвращает (used, remaining, total) без лишнего запроса.
    """
    try:
        print(f"🔵📦 [GIFTS][COUNTS_FAST] start gift_id={gift_id}")
        gifts = await get_available_gifts_fast(bot1)
        print(f"🟦📦 [GIFTS][COUNTS_FAST] gifts_cached={len(gifts)}")
    except Exception as e:
        print(f"🟥📦 [GIFTS][COUNTS_FAST][ERROR] get_available_gifts_fast: {type(e).__name__}: {e}")
        return None, None, None

    for gift in gifts:
        try:
            current_id = str(getattr(gift, "id", ""))
            if current_id != str(gift_id):
                continue

            total = getattr(gift, "total_count", None)
            remaining = getattr(gift, "remaining_count", None)

            if total is None or remaining is None:
                print(f"🟨📦 [GIFTS][COUNTS_FAST] no counts for gift_id={gift_id}")
                return None, None, None

            total_i = int(total)
            rem_i = int(remaining)
            used_i = max(0, total_i - rem_i)

            print(f"🟩📦 [GIFTS][COUNTS_FAST] OK gift_id={gift_id} used={used_i} rem={rem_i} total={total_i}")
            return used_i, rem_i, total_i

        except Exception as e:
            print(f"🟥📦 [GIFTS][COUNTS_FAST][ERROR] gift_id={gift_id}: {type(e).__name__}: {e}")

    print(f"🟨📦 [GIFTS][COUNTS_FAST] not found gift_id={gift_id}")
    return None, None, None


async def get_gift_details_fast_safe(bot1, gift_id: str) -> Tuple[str, Optional[str]]:
    """
    ✅ SAFE wrapper (если хочешь вызывать в любом месте без None):
    - emoji всегда будет строкой (по умолчанию 🎁)
    - limit_text может быть None
    """
    emoji, limit_text = await get_gift_details_fast(bot1, gift_id)
    return (emoji or "🎁"), limit_text













