USE_PREMIUM_TG_EMOJI_IN_TEXT = True

def _norm_emoji(e: str) -> str:
    return (e or "").replace("\ufe0f", "")

def _tg_emoji_tag(unicode_emoji: str, emoji_id: str) -> str:
    return f"<tg-emoji emoji-id='{_escape(str(emoji_id))}'>{_escape(str(unicode_emoji))}</tg-emoji>"

def _gift_name_to_html(gift_name: str) -> str:
    s = str(gift_name or "").strip()
    if not s:
        return ""

    if not USE_PREMIUM_TG_EMOJI_IN_TEXT:
        return _escape(s)

    ceid = PREMIUM_ICON_MAP.get(s)
    if not ceid:
        ceid = PREMIUM_ICON_MAP.get(_norm_emoji(s))

    if ceid:
        return _tg_emoji_tag(s, ceid)

    return _escape(s)

def _gift_name_to_code_html(gift_name: str) -> str:
    s = str(gift_name or "").strip()
    if not s:
        return "<code></code>"

    html_gift = _gift_name_to_html(s)

    if html_gift.startswith("<tg-emoji"):
        return html_gift

    return f"<code>{html_gift}</code>"


