# GENERIC SAFE HELPERS
# =========================================================
def _to_int_safe(v, default: int = 0) -> int:
    try:
        if v is None:
            return default
        if isinstance(v, str):
            vv = v.strip().replace(" ", "").replace(".", "")
            if not vv:
                return default
            return int(float(vv))
        return int(v)
    except Exception:
        return default

def _to_int(v, default: int = 0) -> int:
    return _to_int_safe(v, default)

def _fmt_dot(x) -> str:
    try:
        return "{:,.0f}".format(int(_to_int_safe(x, 0))).replace(",", ".")
    except Exception:
        return "0"

def _bonus_safe_int(v: Any, default: int = 0) -> int:
    try:
        return int(v)
    except Exception:
        return int(default)

def _bonus_safe_str(v: Any, default: str = "") -> str:
    try:
        if v is None:
            return default
        s = str(v).strip()
        return s if s else default
    except Exception:
        return default


# =========================================================
# CALLBACK TOKEN STORES
# =========================================================
# App-level cleanup. GameStore TTL for these stores must be >= this
# (see STORE_EXPIRY_OVERRIDES in bot/db_create/pklcode.py).
CALLBACK_TOKEN_MAX_AGE = 24 * 60 * 60  # 24 hours

GIFT_CALLBACK_ACTIONS: Dict[str, Dict[str, Any]] = LazyGameStore("GIFT_CALLBACK_ACTIONS")
PREP_CALLBACK_ACTIONS: Dict[str, Dict[str, Any]] = LazyGameStore("PREP_CALLBACK_ACTIONS")
SKIP_CALLBACK_ACTIONS: Dict[str, Dict[str, Any]] = LazyGameStore("SKIP_CALLBACK_ACTIONS")
SPEEDCONC_CALLBACK_ACTIONS: Dict[str, Dict[str, Any]] = LazyGameStore("SPEEDCONC_CALLBACK_ACTIONS")

try:
    from bot.db_create.pklcode import register_store_expiry as _register_cb_store_expiry
    for _cb_store_name in (
        "PREP_CALLBACK_ACTIONS",
        "GIFT_CALLBACK_ACTIONS",
        "SKIP_CALLBACK_ACTIONS",
        "SPEEDCONC_CALLBACK_ACTIONS",
        "SEND_REQUEST_ACTIONS",
    ):
        _register_cb_store_expiry(_cb_store_name, 7 * 24 * 3600.0)
except Exception as _cb_ttl_exc:
    print(f"🟨[CALLBACK][TTL][WARN] register_store_expiry failed: {_cb_ttl_exc!r}")


def _cleanup_callback_store(store: Dict[str, Dict[str, Any]], max_age_sec: int = CALLBACK_TOKEN_MAX_AGE) -> None:
    now = time.time()
    to_delete = []

    for token, payload in list(store.items()):
        ts = float(payload.get("ts", 0) or 0)
        if ts <= 0 or (now - ts) > max_age_sec:
            to_delete.append(token)

    for token in to_delete:
        store.pop(token, None)


def _register_callback_payload(store: Dict[str, Dict[str, Any]], payload: Dict[str, Any]) -> str:
    _cleanup_callback_store(store)
    token = uuid.uuid4().hex[:16]
    row = {
        **dict(payload or {}),
        "ts": time.time(),
    }
    store[token] = row
    # BLC: durable копия токена + write-through в Redis
    try:
        from bot.runtime.button_lifecycle import bind_registered_token
        bind_registered_token(store, token, row)
    except Exception:
        try:
            from bot.runtime.button_survival import persist_callback_store
            persist_callback_store(store)
        except Exception:
            try:
                if hasattr(store, "save"):
                    store.save()
            except Exception:
                pass
    return token


def _get_callback_payload(store: Dict[str, Dict[str, Any]], token: str) -> Optional[Dict[str, Any]]:
    _cleanup_callback_store(store)
    row = store.get(str(token or "").strip())
    return dict(row) if row else None


def _pop_callback_payload(store: Dict[str, Dict[str, Any]], token: str) -> Optional[Dict[str, Any]]:
    _cleanup_callback_store(store)
    row = store.pop(str(token or "").strip(), None)
    return dict(row) if row else None


def _cb_len(cb: str) -> int:
    try:
        return len(str(cb or "").encode("utf-8"))
    except Exception:
        return 9999


def _ensure_cb_len(cb: str, label: str = "callback_data") -> None:
    ln = _cb_len(cb)
    if ln > 64:
        raise ValueError(f"{label} too long: {ln} bytes")


