async def _safe_edit_or_alert(cb: types.CallbackQuery, text: str, *, kb: Optional[InlineKeyboardMarkup] = None) -> bool:
    try:
        await cb.message.edit_text(
            text,
            parse_mode="HTML",
            reply_markup=kb,
            disable_web_page_preview=True
        )
        return True
    except TelegramBadRequest as e:
        s = str(e)
        if "message is not modified" in s:
            try:
                await cb.answer("⚠️ Ничего не изменилось. Проверьте условия.", show_alert=True)
                return True
            except Exception:
                return False
        try:
            await cb.message.answer(
                text,
                parse_mode="HTML",
                reply_markup=kb,
                disable_web_page_preview=True
            )
            return True
        except Exception as e2:
            print(f"[GIFT][UI][ERROR] edit_text failed={e!r}, answer failed={e2!r}")
            return False
    except Exception as e:
        print(f"[GIFT][UI][ERROR] unknown edit error: {e!r}")
        try:
            await cb.message.answer(
                text,
                parse_mode="HTML",
                reply_markup=kb,
                disable_web_page_preview=True
            )
            return True
        except Exception:
            return False


async def _safe_edit_or_answer(cb: types.CallbackQuery, text: str, kb: Optional[InlineKeyboardMarkup] = None) -> None:
    try:
        await cb.message.edit_text(text, parse_mode="HTML", reply_markup=kb, disable_web_page_preview=True)
        return
    except TelegramBadRequest as e:
        s = str(e)
        if "message is not modified" in s:
            try:
                await cb.answer("⚠️ Ничего не изменилось.", show_alert=True)
            except Exception:
                pass
            return
        try:
            await cb.message.answer(text, parse_mode="HTML", reply_markup=kb, disable_web_page_preview=True)
            return
        except Exception as e2:
            print(f"[PREP][UI][ERROR] edit failed={e!r} answer failed={e2!r}")
            return
    except Exception as e:
        print(f"[PREP][UI][ERROR] unknown edit error: {e!r}")
        try:
            await cb.message.answer(text, parse_mode="HTML", reply_markup=kb, disable_web_page_preview=True)
        except Exception:
            pass


