SUBS_DEBUG = False

def _dbg(msg: str):
    if SUBS_DEBUG:
        print(f"[SUBS] {msg}")

def _normalize_chat_ref(chat: Union[int, str]) -> Union[int, str]:
    if isinstance(chat, int):
        return chat
    chat = chat.strip()
    if chat and not chat.startswith("@"):
        return "@" + chat
    return chat

async def _get_chat_meta(bot: Bot, chat_ref: Union[int, str]) -> Dict[str, Optional[Union[int, str]]]:
    try:
        chat_obj = await bot.get_chat(chat_ref)
        title = (
            getattr(chat_obj, "title", None)
            or getattr(chat_obj, "first_name", None)
            or getattr(chat_obj, "username", None)
            or str(getattr(chat_obj, "id", chat_ref))
        )
        username = getattr(chat_obj, "username", None)
        chat_id = getattr(chat_obj, "id", None)
        return {"chat_id": chat_id if chat_id is not None else chat_ref, "title": title, "username": username}
    except Exception as e:
        _dbg(f"meta fail for {chat_ref}: {e}")
        return {"chat_id": chat_ref, "title": str(chat_ref), "username": None}

def _interpret_member_status(member) -> Dict[str, Union[bool, str]]:
    status = getattr(member, "status", None) or "unknown"
    is_member = getattr(member, "is_member", None)

    if status in ("creator", "administrator", "member"):
        return {"ok": True, "reason": "ok", "status": status}

    if status == "restricted":
        if is_member is None:
            return {"ok": True, "reason": "ok", "status": status}
        return {"ok": bool(is_member), "reason": "not_member" if not is_member else "ok", "status": status}

    if status == "left":
        return {"ok": False, "reason": "not_member", "status": status}

    if status == "kicked":
        return {"ok": False, "reason": "blocked", "status": status}

    return {"ok": False, "reason": f"unknown_status:{status}", "status": status}

async def check_user_subscriptions(
    bot: Bot,
    user_id: int,
    chats: List[Union[int, str]],
    *,
    max_concurrency: int = 5,
) -> Union[bool, List[Dict[str, Union[int, str]]]]:
    if not chats:
        return True

    sem = asyncio.Semaphore(max_concurrency)
    problems: List[Dict[str, Union[int, str]]] = []

    async def check_one(raw_chat):
        chat_ref = _normalize_chat_ref(raw_chat)
        async with sem:
            try:
                member = await bot.get_chat_member(chat_ref, user_id)
                interp = _interpret_member_status(member)
                if interp["ok"]:
                    return None
                meta = await _get_chat_meta(bot, chat_ref)
                meta.update({"reason": interp["reason"], "status": interp["status"]})
                return meta

            except TelegramForbiddenError as e:
                meta = await _get_chat_meta(bot, chat_ref)
                meta.update({"reason": "forbidden", "status": "unknown", "error": str(e)})
                return meta

            except TelegramBadRequest as e:
                text = str(e)
                reason = "not_member" if "USER_NOT_PARTICIPANT" in text else (
                    "forbidden" if "CHAT_ADMIN_REQUIRED" in text else "bad_request"
                )
                meta = await _get_chat_meta(bot, chat_ref)
                meta.update({"reason": reason, "status": "unknown", "error": text})
                return meta

            except Exception as e:
                meta = await _get_chat_meta(bot, chat_ref)
                meta.update({"reason": "error", "status": "unknown", "error": str(e)})
                return meta

    tasks = [asyncio.create_task(check_one(c)) for c in chats]
    for res in await asyncio.gather(*tasks):
        if res is not None:
            problems.append(res)

    return True if not problems else problems

