async def _get_gift_menu_override_icon_id_safe(gift_id: Any) -> Optional[str]:
    try:
        return await resolve_gift_menu_icon_override(gift_id)
    except Exception as e:
        print(f"[GIFT_MENU_OVERRIDE][GET][ERROR] gift_id={gift_id!r} err={e!r}")
        return None

def _gift_local_escape(text: Any) -> str:
    try:
        return html.escape(str(text or ""))
    except Exception:
        return ""
def _gift_local_norm_emoji(e: str) -> str:
    try:
        return (e or "").replace("\ufe0f", "")
    except Exception:
        return str(e or "")
def _gift_local_name_to_html(gift_name: str) -> str:
    s = str(gift_name or "").strip()
    if not s:
        return ""

    try:
        use_premium = bool(globals().get("USE_PREMIUM_TG_EMOJI_IN_TEXT", True))
    except Exception:
        use_premium = True

    if not use_premium:
        return _gift_local_escape(s)

    try:
        premium_map = globals().get("PREMIUM_ICON_MAP", {}) or {}
        ceid = premium_map.get(s)
        if not ceid:
            ceid = premium_map.get(_gift_local_norm_emoji(s))

        if ceid:
            return _gift_local_tg_emoji_tag(s, str(ceid))
    except Exception:
        pass

    return _gift_local_escape(s)
def _gift_local_tg_emoji_tag(unicode_emoji: str, emoji_id: str) -> str:
    try:
        return f"<tg-emoji emoji-id='{_gift_local_escape(str(emoji_id))}'>{_gift_local_escape(str(unicode_emoji))}</tg-emoji>"
    except Exception:
        return _gift_local_escape(unicode_emoji)
def _gift_name_to_html_with_override(gift_name: str, override_icon_id: Optional[str]) -> str:
    s = str(gift_name or "").strip()
    if not s:
        return ""

    try:
        ceid = str(override_icon_id or "").strip()
        if ceid:
            return _gift_local_tg_emoji_tag("🎁", ceid)
    except Exception as e:
        print(f"[GIFT_MENU_OVERRIDE][HTML][ERROR] gift_name={gift_name!r} override_icon_id={override_icon_id!r} err={e!r}")

    return _gift_local_name_to_html(s)


def _gift_name_to_code_html_with_override(gift_name: str, override_icon_id: Optional[str]) -> str:
    s = str(gift_name or "").strip()
    if not s:
        return "<code></code>"

    html_gift = _gift_name_to_html_with_override(s, override_icon_id)

    if html_gift.startswith("<tg-emoji"):
        return html_gift

    return f"<code>{html_gift}</code>"




async def _render_gift_title_html_for_menu(
    *,
    gift_id: Any,
    gift_name: str,
) -> Tuple[str, Optional[str], bool]:
    override_icon_id = await _get_gift_menu_override_icon_id_safe(gift_id)

    try:
        is_animated = await is_animated_emoji(gift_name)
    except Exception as e:
        print(f"[GIFT_MENU_OVERRIDE][ANIM][ERROR] gift_name={gift_name!r} err={e!r}")
        is_animated = True

    html_plain = _gift_name_to_html_with_override(gift_name, override_icon_id)
    html_code = _gift_name_to_code_html_with_override(gift_name, override_icon_id)

    text = html_plain if is_animated else html_code
    return text, override_icon_id, is_animated
