def _gift_local_to_int_safe(v: Any, default: int = 0) -> int:
    try:
        if v is None:
            return default
        if isinstance(v, str):
            vv = v.strip().replace(" ", "").replace(".", "")
            if not vv:
                return default
            return int(float(vv))
        return int(v)
    except Exception:
        return default
async def _resolve_manual_gift_data(gift_id: Any) -> Optional[Dict[str, Any]]:
    """
    Ищет подарок в ручном реестре buttons.py.
    Возвращает данные в том же стиле, который нужен UI/btnstars.
    """
    try:
        from bot.design.buttons import get_all_manual_gifts
    except Exception as e:
        print(f"[MANUAL_GIFT][IMPORT][ERROR] err={e!r}")
        return None

    try:
        gid = str(gift_id or "").strip()
        if not gid:
            return None

        manual_map = await get_all_manual_gifts()
        payload = (manual_map or {}).get(gid)
        if not payload:
            return None

        emoji = str(payload.get("emoji") or "🎁")
        price = int(_gift_local_to_int_safe(payload.get("price"), 0))
        upgrade_price = int(_gift_local_to_int_safe(payload.get("upgrade_price"), 0))
        has_upgrade = 1 if int(_gift_local_to_int_safe(payload.get("has_upgrade"), 0)) == 1 else 0
        custom_emoji_id = str(payload.get("custom_emoji_id") or "").strip()

        return {
            "gift_id": gid,
            "gift_name": emoji,
            "emoji": emoji,
            "price": price,
            "upgrade_price": upgrade_price,
            "has_upgrade": has_upgrade,
            "custom_emoji_id": custom_emoji_id,
            "limit_text": "",
            "used": None,
            "remaining": None,
            "total": None,
            "is_manual": True,
        }
    except Exception as e:
        print(f"[MANUAL_GIFT][RESOLVE][ERROR] gift_id={gift_id!r} err={e!r}")
        return None


async def _resolve_runtime_gift_data(bot1, gift_id: Any) -> Dict[str, Any]:
    """
    Унифицированный источник данных о подарке.
    Сначала проверяем ручной подарок.
    Если нет - используем Telegram.
    """
    gid = str(gift_id or "").strip()

    manual_data = await _resolve_manual_gift_data(gid)
    if manual_data:
        return manual_data

    gift_name = gid
    limit_text = None
    used, remaining, total = None, None, None
    upgrade_price = 0
    has_upgrade = 0
    price = 0
    emoji = "🎁"

    try:
        gifts = await get_available_gifts_fast(bot1)
        for g in (gifts or []):
            live_gid = str(getattr(g, "id", "") or "").strip()
            if live_gid != gid:
                continue

            emoji = str(getattr(getattr(g, "sticker", None), "emoji", "🎁") or "🎁")
            gift_name = emoji
            price = int(_gift_local_to_int_safe(getattr(g, "star_count", 0), 0))
            upgrade_raw = getattr(g, "upgrade_star_count", None)
            upgrade_price = int(_gift_local_to_int_safe(upgrade_raw, 0))
            has_upgrade = 1 if upgrade_raw is not None else 0
            break
    except Exception as e:
        print(f"[RUNTIME_GIFT][LIVE_SCAN][ERROR] gift_id={gid} err={e!r}")

    try:
        gift_name_from_api, limit_text = await get_gift_details_fast(bot1, gid)
        if gift_name_from_api:
            gift_name = str(gift_name_from_api)
    except Exception as e:
        print(f"[RUNTIME_GIFT][DETAILS][ERROR] gift_id={gid} err={e!r}")

    try:
        used, remaining, total = await extract_gift_counts_fast(bot1, gid)
    except Exception as e:
        print(f"[RUNTIME_GIFT][COUNTS][ERROR] gift_id={gid} err={e!r}")

    return {
        "gift_id": gid,
        "gift_name": gift_name,
        "emoji": emoji,
        "price": price,
        "upgrade_price": upgrade_price,
        "has_upgrade": has_upgrade,
        "custom_emoji_id": "",
        "limit_text": limit_text,
        "used": used,
        "remaining": remaining,
        "total": total,
        "is_manual": False,
    }
def _gift_local_name_to_code_html(gift_name: str) -> str:
    s = str(gift_name or "").strip()
    if not s:
        return "<code></code>"

    html_gift = _gift_local_name_to_html(s)

    if html_gift.startswith("<tg-emoji"):
        return html_gift

    return f"<code>{html_gift}</code>"
@dp.callback_query(lambda c: c.data.startswith(("btnstars_", "sts:g:")))
async def btnstars_callback(callback_query: types.CallbackQuery):
    raw = callback_query.data

    gift_id = None
    base_amount = 0
    upgrade_price = 0
    nft_enabled = 0
    back_signal = "-"
    owner_id_for_back = 0

    # ----- НАЧАЛО ИСПРАВЛЕНИЯ -----
    try:
        if raw.startswith("sts:g:"):
            # Формат: sts:g:<gift_id>:<price>:<upgrade>:<nft>:<back_signal>:<owner_id>
            parts = raw.split(":")
            if len(parts) != 8:
                raise ValueError("Invalid sts:g format")
            gift_id = parts[2]
            base_amount = int(parts[3])
            upgrade_price = int(parts[4])
            nft_enabled = int(parts[5])
            back_signal = parts[6]                          # ← остаётся строкой
            owner_id_for_back = int(parts[7]) if parts[7].lstrip('-').isdigit() else 0
        else:
            # Формат: btnstars_<gift_id>_<price>_<upgrade>_<nft>_<back_signal>_<owner_id>
            data = raw[len("btnstars_"):]
            parts = data.split("_")
            if len(parts) != 6:
                raise ValueError("Invalid btnstars_ format")
            gift_id = parts[0]
            base_amount = int(parts[1])
            upgrade_price = int(parts[2])
            nft_enabled = int(parts[3])
            back_signal = parts[4]                           # ← остаётся строкой
            owner_id_for_back = int(parts[5]) if parts[5].lstrip('-').isdigit() else 0
    except (ValueError, IndexError) as e:
        print(f"[btnstars_callback][PARSE][ERROR] raw={raw} err={e}")
        return await callback_query.answer("Ошибка данных кнопки", show_alert=True)
    # ----- КОНЕЦ ИСПРАВЛЕНИЯ -----

    user_id = callback_query.from_user.id

    if not callback_query.from_user.username:
        return await callback_query.answer("⚠️ Установите юзернейм для получения подарка", show_alert=True)

    base_amount = _to_int_safe(base_amount, 0)
    upgrade_price = _to_int_safe(upgrade_price, 0)
    nft_enabled = _to_int_safe(nft_enabled, 0)
    owner_id_for_back = _to_int_safe(owner_id_for_back, 0)

    try:
        if raw.startswith("sts:g:"):
            gift_id, base_amount, upgrade_price, nft_enabled, back_signal, owner_id_for_back = _parse_btnstars_sts(raw)
        else:
            gift_id, base_amount, upgrade_price, nft_enabled, back_signal, owner_id_for_back = _parse_btnstars_underscore(raw)
    except Exception as e:
        print(f"[btnstars_callback][PARSE][ERROR] raw={raw} err={e}")
        return await callback_query.answer("Ошибка данных кнопки", show_alert=True)

    user_id = callback_query.from_user.id

    if not callback_query.from_user.username:
        return await callback_query.answer("⚠️ Установите юзернейм для получения подарка", show_alert=True)

    base_amount = _to_int_safe(base_amount, 0)
    upgrade_price = _to_int_safe(upgrade_price, 0)
    nft_enabled = _to_int_safe(nft_enabled, 0)
    owner_id_for_back = _to_int_safe(owner_id_for_back, 0)

    amount = int(base_amount) + (int(upgrade_price) if int(nft_enabled) == 1 else 0)

    try:
        user_balance = await db.get_user_balance(user_id)
    except Exception as e:
        print(f"[btnstars_callback][ERROR] get_user_balance user_id={user_id} err={e}")
        user_balance = 0

    if _to_int_safe(user_balance, 0) < amount:
        formatted = _fmt_dot(user_balance)
        return await callback_query.answer(f"💭 Недостаточно кут.\nВаш баланс: {formatted}", show_alert=True)

    try:
        runtime_gift = await _resolve_runtime_gift_data(bot1 , gift_id)
    except Exception as e:
        print(f"[btnstars_callback][RUNTIME_GIFT][ERROR] gift_id={gift_id} err={e!r}")
        runtime_gift = {"gift_id": str(gift_id) , "gift_name": str(gift_id) , "emoji": "🎁" ,
            "price": int(base_amount or 0) , "upgrade_price": int(upgrade_price or 0) ,
            "has_upgrade": int(nft_enabled or 0) , "custom_emoji_id": "" , "limit_text": None , "used": None ,
            "remaining": None , "total": None , "is_manual": False , }

    gift_name = str(runtime_gift.get("gift_name") or gift_id)
    limit_text = runtime_gift.get("limit_text")
    used = runtime_gift.get("used")
    remaining = runtime_gift.get("remaining")
    total = runtime_gift.get("total")

    # =========================================================
    # GIFT TITLE / OVERRIDE ICON
    # =========================================================
    try:
        manual_custom_emoji_id = str(runtime_gift.get("custom_emoji_id") or "").strip()
        if manual_custom_emoji_id:
            override_icon_id = manual_custom_emoji_id
            try:
                is_animated = await is_animated_emoji(gift_name)
            except Exception:
                is_animated = True

            gift_html_plain = _gift_local_tg_emoji_tag("🎁" , manual_custom_emoji_id)
            gift_html_code_or_premium = gift_html_plain
            gift_title_html = gift_html_plain if is_animated else gift_html_code_or_premium
        else:
            gift_title_html , override_icon_id , is_animated = await _render_gift_title_html_for_menu(
                gift_id=gift_id , gift_name=str(gift_name or "") , )
    except Exception as e:
        print(f"[btnstars_callback][OVERRIDE_RENDER][ERROR] gift_id={gift_id} err={e!r}")

        override_icon_id = None
        try:
            is_animated = await is_animated_emoji(gift_name)
        except Exception as e2:
            print(f"[btnstars_callback][ERROR] is_animated_emoji gift_name={gift_name!r} err={e2}")
            is_animated = True

        gift_html_plain = _gift_local_name_to_html(str(gift_name))
        gift_html_code_or_premium = _gift_local_name_to_code_html(str(gift_name))
        gift_title_html = gift_html_plain if is_animated else gift_html_code_or_premium

    amount1 = _fmt_dot(amount)
    upgrade_note = " [ NFT ]" if int(nft_enabled) == 1 else ""

    try:
        prep_cd = _build_prep_short_cb(
            has_upgrade=int(nft_enabled),
            gift_name=str(gift_name),
            base_amount=int(base_amount),
            upgrade_price=int(upgrade_price),
            gift_id=int(gift_id),
            back_signal=str(back_signal),
            owner_id_for_back=int(owner_id_for_back or user_id),
        )

        friend_cd = _build_gift_request_short_cb(
            nft_enabled=int(nft_enabled),
            gift_name=str(gift_name),
            base_amount=int(base_amount),
            upgrade_price=int(upgrade_price),
            amount=int(amount),
            gift_id=int(gift_id),
            back_signal=str(back_signal),
            owner_id_for_back=int(owner_id_for_back or user_id),
        )

        speedconc_cd = _build_speedconc_short_cb(
            has_upgrade=int(nft_enabled),
            gift_name=str(gift_name),
            used_base=int(base_amount),
            upgrade_price=int(upgrade_price),
            gift_id=int(gift_id),
        )
    except Exception as e:
        print(f"[btnstars_callback][CALLBACK_BUILD][ERROR] user_id={user_id} gift_id={gift_id} err={e!r}")
        return await callback_query.answer("⚠️ Ошибка подготовки кнопок", show_alert=True)

    buttons = []

    # =========================================================
    # TOP INFO BUTTON
    # Если для gift_id есть override -> показываем нужный custom emoji
    # =========================================================
    try:
        top_kwargs = {
            "text": f"Выводим {amount1} кут {_escape(upgrade_note)}",
            "callback_data": "ajdfiasjoaskdokasdqwqkp",
        }

        if override_icon_id:
            top_kwargs["style"] = "default"
            top_kwargs["icon_custom_emoji_id"] = str(override_icon_id)

        buttons.append([InlineKeyboardButton(**top_kwargs)])
    except Exception as e:
        print(f"[btnstars_callback][TOP_BTN][ERROR] gift_id={gift_id} err={e!r}")
        buttons.append([
            InlineKeyboardButton(
                text=f"Выводим {amount1} кут {_escape(upgrade_note)}",
                callback_data="ajdfiasjoaskdokasdqwqkp"
            )
        ])

    if remaining is not None and total is not None:
        buttons.append([
            InlineKeyboardButton(
                text=f"{remaining}/{total}",
                callback_data="ajdfiasjoaskdokasdqwqkpфыафывйц"
            )
        ])

    buttons.append([
        InlineKeyboardButton(
            text="Другу",
            callback_data=friend_cd,
            style="default",
            icon_custom_emoji_id="6028346797368283073"
        ),
        InlineKeyboardButton(
            text="Себе",
            callback_data=prep_cd,
            style="default",
            icon_custom_emoji_id="6028338546736107668"
        ),
    ])

    if int(upgrade_price) > 0:
        try:
            nft_enabled_int = 1 if int(nft_enabled) == 1 else 0
        except Exception:
            nft_enabled_int = 0

        is_disabled = (nft_enabled_int == 0)

        toggle_text = "Улучшить до NFT" if is_disabled else "Отключить NFT"
        new_nft_enabled = 1 if is_disabled else 0
        toggle_icon_id = "5440911110838425969" if is_disabled else "5208923808169222461"

        toggle_cb = _build_toggle_callback(
            gift_id=str(gift_id),
            base_amount=int(base_amount),
            upgrade_price=int(upgrade_price),
            new_nft_enabled=int(new_nft_enabled),
            back_signal=str(back_signal),
            owner_id_for_back=int(owner_id_for_back or 0),
        )

        buttons.append([
            InlineKeyboardButton(
                text=toggle_text,
                callback_data=toggle_cb,
                style="default",
                icon_custom_emoji_id=toggle_icon_id,
            )
        ])

    buttons.append([
        _make_back_button_from_signal(
            back_signal=back_signal,
            owner_id_for_back=int(owner_id_for_back or 0),
            user_id=user_id
        )
    ])

    markup = InlineKeyboardMarkup(inline_keyboard=buttons)

    text = str(gift_title_html)



    if limit_text:
        text += f"\n<b>{_gift_local_escape(str(limit_text))}</b>"

    try:
        await callback_query.message.edit_text(
            text,
            reply_markup=markup,
            parse_mode="HTML"
        )
    except TelegramBadRequest as e:
        print(
            f"[btnstars_callback][EDIT][BAD_REQUEST] user_id={user_id} gift_id={gift_id} err={e} "
            f"raw={raw} friend_len={_cb_len(friend_cd)} prep_len={_cb_len(prep_cd)} speed_len={_cb_len(speedconc_cd)}"
        )
        if "message is not modified" in str(e):
            await callback_query.answer("⚠️ Уже актуально", show_alert=False)
            return
        await callback_query.answer("⚠️ Ошибка обновления сообщения", show_alert=True)
    except Exception as e:
        print(f"[btnstars_callback][EDIT][ERROR] user_id={user_id} gift_id={gift_id} err={e} raw={raw}")
        await callback_query.answer("⚠️ Ошибка", show_alert=True)


# =========================================================
# GIFT SEND REQUEST HANDLER
# =========================================================
@dp.callback_query(_cb_is_gift_request)
async def gift_send_request(callback_query: types.CallbackQuery):
    user_id = int(getattr(callback_query.from_user, "id", 0) or 0)
    original_data = str(getattr(callback_query, "data", "") or "")
    now = time.time()

    print(f"🎁[GIFT][REQ] uid={user_id} data={original_data[:80]!r}")

    try:
        last_ts = float(last_click_time.get(user_id, 0.0)) if isinstance(last_click_time, dict) else 0.0
    except Exception:
        last_ts = 0.0

    if last_ts > 0:
        elapsed = now - last_ts
        if elapsed < float(timeoutourbot):
            left = float(timeoutourbot) - elapsed
            minutes = int(left // 60)
            seconds = int(left % 60)
            print(f"⏳[GIFT][ANTISPAM] uid={user_id} left={minutes}m{seconds}s")
            await callback_query.answer(f"⌚️ Подождите {minutes} мин. {seconds} сек", show_alert=True)
            return

    username = getattr(callback_query.from_user, "username", None)
    if not username:
        print(f"⚠️[GIFT][BLOCK] uid={user_id} no_username")
        await callback_query.answer("⚠️ Установите username для получения подарка", show_alert=True)
        return

    try:
        resolved = _resolve_gift_request_data(original_data)
    except Exception as e:
        print(f"🟥[GIFT][PARSE][ERROR] uid={user_id} raw={original_data!r} err={e!r}")
        err_text = str(e).lower()
        if "expired" in err_text or "not found" in err_text:
            await callback_query.answer(
                "⏳ Кнопка устарела после перезапуска бота.\n"
                "Откройте вывод заново из меню баланса.",
                show_alert=True,
            )
        else:
            await callback_query.answer("❌ Ошибка данных", show_alert=True)
        return

    src = str(resolved.get("src") or "")
    skip_subscription = bool(resolved.get("skip_subscription"))
    nft_enabled = int(resolved.get("nft_enabled") or 0)
    gift_name = str(resolved.get("gift_name") or "")
    base_amount = int(resolved.get("base_amount") or 0)
    upgrade_price = int(resolved.get("upgrade_price") or 0)
    amount = int(resolved.get("amount") or 0)
    gift_id = int(resolved.get("gift_id") or 0)
    back_signal = str(resolved.get("back_signal") or "")
    owner_id_for_back = int(resolved.get("owner_id_for_back") or 0)

    base_amount_i = _to_int_safe(base_amount, 0)
    upgrade_price_i = _to_int_safe(upgrade_price, 0)
    gift_id_i = _to_int_safe(gift_id, 0)
    has_upgrade = 1 if _to_int_safe(nft_enabled, 0) == 1 else 0
    back_signal_s = str(back_signal or "")
    owner_id_back_i = _to_int_safe(owner_id_for_back, 0)

    if base_amount_i <= 0 or gift_id_i <= 0:
        print(f"🟥[GIFT][PARSE][BAD] uid={user_id} base={base_amount_i} gift_id={gift_id_i} src={src}")
        await callback_query.answer("❌ Некорректные данные подарка", show_alert=True)
        return

    print(
        f"🧾[GIFT][PARSED] uid={user_id} src={src} gift_id={gift_id_i} "
        f"base={base_amount_i} upg={upgrade_price_i} has_upg={has_upgrade} "
        f"skip={skip_subscription} back_sig={back_signal_s!r}"
    )

    try:
        back_btn = _make_back_button_from_signal(
            back_signal=back_signal_s,
            owner_id_for_back=int(owner_id_back_i or 0),
            user_id=int(user_id)
        )
    except Exception as e:
        print(f"🟨[GIFT][BACKBTN][WARN] uid={user_id} err={e!r}")
        back_btn = InlineKeyboardButton(
            text="Назад",
            callback_data="9close_bonus",
            style="default",
            icon_custom_emoji_id="5960671702059848143"
        )

    gift_name_s = str(gift_name or "").strip()
    if not gift_name_s:
        try:
            gift_name_s, _limit_text = await get_gift_details_fast(bot1, str(gift_id_i))
            gift_name_s = str(gift_name_s or "").strip() or str(gift_id_i)
            print(f"🟦[GIFT][NAME] resolved gift_name={gift_name_s!r} gift_id={gift_id_i}")
        except Exception as e:
            print(f"🟨[GIFT][NAME][WARN] uid={user_id} gift_id={gift_id_i} err={e!r}")
            gift_name_s = str(gift_id_i)

    effective_base = int(base_amount_i)
    commission_i = 0
    if skip_subscription:
        try:
            commission_i = int(round(int(base_amount_i) * float(commissionsubscribe)))
        except Exception:
            commission_i = 0
        effective_base += int(commission_i)

    used_base = int(effective_base)
    total_amount = used_base + int(upgrade_price_i) if has_upgrade == 1 else used_base

    print(
        f"💸[GIFT][PRICE] uid={user_id} base={base_amount_i} commission={commission_i} "
        f"used_base={used_base} upgrade={upgrade_price_i} total={total_amount}"
    )

    try:
        ok_ref = await ensure_has_referrals(callback_query, user_id, min_required=min_required_ref)
    except Exception as e:
        print(f"🟥[GIFT][REFCHECK][ERROR] uid={user_id} err={e!r}")
        await callback_query.answer("⚠️ Ошибка проверки рефералов", show_alert=True)
        return
    if not ok_ref:
        print(f"⛔[GIFT][REFCHECK] uid={user_id} blocked")
        return

    try:
        ok_lim = await ensure_can_withdraw(callback_query, user_id, amount=int(base_amount_i))
    except Exception as e:
        print(f"🟥[GIFT][LIMITS][ERROR] uid={user_id} err={e!r}")
        await callback_query.answer("⚠️ Ошибка лимитов", show_alert=True)
        return
    if not ok_lim:
        print(f"⛔[GIFT][LIMITS] uid={user_id} blocked")
        return

    try:
        ok_msgs = await ensure_daily_messages(callback_query, user_id, back_btn=back_btn)
    except Exception as e:
        print(f"🟥[GIFT][MSGCHK][ERROR] uid={user_id} err={e!r}")
        await callback_query.answer("⚠️ Ошибка проверки активности", show_alert=True)
        return
    if not ok_msgs:
        print(f"⛔[GIFT][MSGCHK] uid={user_id} blocked")
        return

    if not skip_subscription:
        try:
            subs = await check_user_subscriptions(bot1, user_id, required_chats)
        except Exception as e:
            print(f"🟥[GIFT][SUBS][ERROR] uid={user_id} err={e!r}")
            await callback_query.answer("⚠️ Ошибка проверки подписок", show_alert=True)
            return

        if subs is False:
            try:
                subs2 = await check_user_subscriptions(bot1, user_id, required_chats)
                subs = [] if subs2 is True else subs2
            except Exception:
                pass

        if subs is not True:
            infos = subs or []
            joinable_infos = [i for i in infos if i.get("reason") == "not_member" and i.get("username")]

            if joinable_infos:
                seen = set()
                not_subscribed: List[Tuple[int, str, str]] = []

                for info in joinable_infos:
                    try:
                        cid = int(info.get("chat_id"))
                    except Exception:
                        cid = 0
                    if not cid or cid in seen:
                        continue
                    seen.add(cid)

                    title = str(info.get("title") or cid)
                    uname = str(info.get("username") or "").strip()
                    if uname:
                        not_subscribed.append((cid, title, uname))

                commission = 0
                try:
                    commission = int(round(int(base_amount_i) * float(commissionsubscribe)))
                except Exception:
                    commission = 0

                skip_total = int(base_amount_i) + int(commission)
                commission_percent = int(round((commission / base_amount_i) * 100)) if base_amount_i > 0 else 0

                text = (
                    f"<tg-emoji emoji-id='5192951739623447936'>🏜</tg-emoji> <b>Для вывода {_fmt_dot(base_amount_i)} кут подпишитесь на все указанные каналы/группы.</b>\n"
                    f"<blockquote><b><i>Не хотите подписываться? Пропустите проверку, "
                    f"но к сумме добавится комиссия {commission_percent}% (+{_fmt_dot(commission)} кут).</i></b></blockquote>"
                )

                rows: List[List[InlineKeyboardButton]] = []
                temp: List[InlineKeyboardButton] = []
                for _, title, uname in not_subscribed:
                    temp.append(InlineKeyboardButton(text=f"💭 {title}", url=f"https://t.me/{uname}"))
                    if len(temp) == 2:
                        rows.append(temp)
                        temp = []
                if temp:
                    rows.append(temp)

                try:
                    retry_cb = _build_gift_request_short_cb(
                        nft_enabled=int(has_upgrade),
                        gift_name=str(gift_name_s),
                        base_amount=int(base_amount_i),
                        upgrade_price=int(upgrade_price_i),
                        amount=int(total_amount),
                        gift_id=int(gift_id_i),
                        back_signal=str(back_signal_s),
                        owner_id_for_back=int(owner_id_back_i or user_id),
                    )
                    skip_cb = _build_skip_short_cb(retry_cb)
                except Exception as e:
                    print(f"🟥[GIFT][SUBS][CB_BUILD][ERROR] uid={user_id} err={e!r}")
                    await callback_query.answer("⚠️ Ошибка подготовки кнопок", show_alert=True)
                    return

                rows.append([InlineKeyboardButton(text="⛵️ Проверить подписку", callback_data=retry_cb)])
                rows.append([InlineKeyboardButton(text=f"🍹 Пропустить за {_fmt_dot(skip_total)} кут", callback_data=skip_cb)])
                rows.append([back_btn])

                kb = InlineKeyboardMarkup(inline_keyboard=rows)
                await _safe_edit_or_alert(callback_query, text, kb=kb)
                return

    try:
        user_balance = await db.get_user_balance(user_id)
        user_balance_i = _to_int_safe(user_balance, 0)
    except Exception as e:
        print(f"🟥[GIFT][BALANCE][ERROR] uid={user_id} err={e!r}")
        await callback_query.answer("⚠️ Ошибка получения баланса", show_alert=True)
        return

    if user_balance_i < int(total_amount):
        print(f"⛔[GIFT][NOFUNDS] uid={user_id} bal={user_balance_i} need={total_amount}")
        await callback_query.answer(f"💭 Недостаточно кут. Баланс: {user_balance_i}", show_alert=True)
        return

    try:
        user_gift[user_id] = {
            "gift_amount": int(used_base),
            "gift_emoji": str(gift_name_s),
            "is_nft": bool(has_upgrade == 1),
            "has_upgrade": int(has_upgrade),
            "gift_id": int(gift_id_i),
            "base_amount": int(base_amount_i),
            "upgrade_price": int(upgrade_price_i),

            "back_signal": str(back_signal_s),
            "owner_id_for_back": int(owner_id_back_i or 0),

            "awaiting_recipient": True,
            "prompt_chat_id": None,
            "prompt_message_id": None,
        }
    except Exception as e:
        print(f"🟥[GIFT][STATE][ERROR] uid={user_id} err={e!r}")
        await callback_query.answer("⚠️ Ошибка состояния", show_alert=True)
        return

    try:
        last_click_time[user_id] = now
    except Exception:
        pass

    try:
        await callback_query.message.delete()
    except TelegramBadRequest:
        pass
    except Exception as e:
        print(f"🟨[GIFT][DELETE][WARN] uid={user_id} err={e!r}")

    try:
        prompt = await bot1.send_message(
            chat_id=callback_query.message.chat.id,
            text="<tg-emoji emoji-id='6021551862753270008'>🎁</tg-emoji> <b>Введите @username, ID или ссылку получателя.\n<tg-emoji emoji-id='6023971862076200111'>🔥</tg-emoji> Напишите «<code>Завершить</code>» для отмены.</b>",
            reply_markup=ForceReply(selective=True),
            parse_mode="HTML",
            message_effect_id="5104841245755180586",
            disable_web_page_preview=True
        )
    except Exception as e:
        print(f"🟥[GIFT][PROMPT][ERROR] uid={user_id} err={e!r}")
        try:
            user_gift.pop(user_id, None)
        except Exception:
            pass
        await callback_query.answer("⚠️ Не удалось открыть ввод получателя", show_alert=True)
        return

    try:
        user_gift[user_id]["prompt_chat_id"] = int(prompt.chat.id)
        user_gift[user_id]["prompt_message_id"] = int(prompt.message_id)
    except Exception as e:
        print(f"🟨[GIFT][PROMPT_META][WARN] uid={user_id} err={e!r}")

    try:
        await callback_query.answer()
    except Exception:
        pass

    print(f"✅[GIFT][READY] uid={user_id} prompt_mid={getattr(prompt, 'message_id', None)} gift_id={gift_id_i}")


