# =========================================================
# SPEEDCONC DIRECT CALLBACK BUILDER
# =========================================================
def _build_speedconc_direct_callback(
    *,
    has_upgrade: int,
    gift_name: str,
    used_base: int,
    upgrade_price: int,
    gift_id: int,
    target_user_id: int = 0,
) -> str:
    """
    Формат строго под обработчик:
    speedconc_{has_upgrade}_{gift_name}_{used_base}_{upgrade_price}_{gift_id}_{target_user_id}
    """
    gift_name_s = str(gift_name or "🎁").strip() or "🎁"

    cb = (
        f"speedconc_"
        f"{int(has_upgrade)}_"
        f"{gift_name_s}_"
        f"{int(used_base)}_"
        f"{int(upgrade_price)}_"
        f"{int(gift_id)}_"
        f"{int(target_user_id or 0)}"
    )

    ln = len(cb.encode("utf-8"))
    if ln > 64:
        raise ValueError(f"speedconc callback too long: {ln} bytes")

    return cb



