WITHDRAW_HELP_CALLBACK_DEFAULT = "otherrrrrrrrhelpeeeeeerrrssss"
WITHDRAW_HELP_CALLBACK_REMOVED = "withdraw_removed_gift_help_v2"


async def get_manual_gift_ids_set() -> Set[str]:
    try:
        manual_map = await get_all_manual_gifts()
        return set((manual_map or {}).keys())
    except Exception as e:
        print(f"🟥 [GIFT_MENU_MANUAL][IDS][ERROR] {e!r}")
        return set()

def _normalize_gift_id(value: Any) -> str:
    try:
        return str(value or "").strip()
    except Exception:
        return ""
async def is_manual_gift_id(gift_id: Any) -> bool:
    gid = _normalize_gift_id(gift_id)
    if not gid:
        return False

    try:
        manual_ids = await get_manual_gift_ids_set()
        is_manual = gid in manual_ids

        if GIFTS_DEBUG:
            print(f"🟦 [GIFT_MENU_MANUAL][CHECK] gift_id={gid!r} is_manual={is_manual}")

        return bool(is_manual)
    except Exception as e:
        print(f"🟥 [GIFT_MENU_MANUAL][CHECK][ERROR] gift_id={gift_id!r} err={e!r}")
        return False


def _build_removed_help_button(
    *,
    style: str,
    icon_custom_emoji_id: Optional[str],
) -> InlineKeyboardButton:
    kwargs = {
        "text": "Важно знать!",
        "callback_data": WITHDRAW_HELP_CALLBACK_REMOVED,
    }

    if style:
        kwargs["style"] = style

    if icon_custom_emoji_id:
        kwargs["icon_custom_emoji_id"] = icon_custom_emoji_id

    return InlineKeyboardButton(**kwargs)


def _build_default_help_button(
    *,
    style: str,
    icon_custom_emoji_id: Optional[str],
) -> InlineKeyboardButton:
    kwargs = {
        "text": "Важно знать!",
        "callback_data": WITHDRAW_HELP_CALLBACK_DEFAULT,
    }

    if style:
        kwargs["style"] = style

    if icon_custom_emoji_id:
        kwargs["icon_custom_emoji_id"] = icon_custom_emoji_id

    return InlineKeyboardButton(**kwargs)


async def build_withdraw_choice_keyboard_by_gift_id(
    *,
    gift_id: Any,
    speedconc_callback: str,
    back_button: InlineKeyboardButton,
    ordinary_callback: Optional[str] = None,
    help_style: str = "primary",
    help_icon_custom_emoji_id: Optional[str] = None,
) -> Tuple[InlineKeyboardMarkup, bool]:
    is_manual = await is_manual_gift_id(gift_id)

    rows: List[List[InlineKeyboardButton]] = []

    if is_manual:
        rows.append([
            _build_removed_help_button(
                style=help_style,
                icon_custom_emoji_id=help_icon_custom_emoji_id,
            )
        ])
        rows.append([
            InlineKeyboardButton(
                text="От бота",
                callback_data=str(speedconc_callback),
                style="default",
                icon_custom_emoji_id="6028346797368283073",
            )
        ])
    else:
        rows.append([
            _build_default_help_button(
                style=help_style,
                icon_custom_emoji_id=help_icon_custom_emoji_id,
            )
        ])
        rows.append([
            InlineKeyboardButton(
                text="От бота",
                callback_data=str(speedconc_callback),
                style="default",
                icon_custom_emoji_id="6028346797368283073",
            ),
            InlineKeyboardButton(
                text="Обычный",
                callback_data=str(ordinary_callback or ""),
                style="default",
                icon_custom_emoji_id="6028338546736107668",
            )
        ])

    rows.append([back_button])

    return InlineKeyboardMarkup(inline_keyboard=rows), bool(is_manual)


