# ---------- Render / keyboards for subscription tasks ----------

async def _render_sub_task_text(
    chat_ref: str, task_row: Dict[str, Any], idx: int, total: int, queb: Decimal
) -> str:
    try:
        reward = D(task_row.get("reward") or task_row.get("reward_amount") or 0)
        created = task_row.get("created_at") or "-"
        cap = task_row.get("total_cap")
        ttl = task_row.get("ttl_expires_at")
        cap_line = f"\n• Кап: <b>{int(cap)}</b> чел." if cap is not None else ""
        ttl_line = f"\n• Действует до: <b>{html.escape(str(ttl))}</b>" if ttl else ""
        title = html.escape(str(task_row.get("chat_ref") or chat_ref or "-"))

        try:
            queb = D(queb)
        except Exception:
            queb = D(0)
        queb_s = _fmt_dot(floor_int(queb))

        lines = [
            f"<b>Задание на подписку #{idx}/{total}</b>",
            "",
            f"⭐️ <b>{title}</b>",
            f"• Награда: <b>{fmt_amt(reward)}</b> кут{cap_line}{ttl_line}",
            "",
            f"🍹 Ваша Virtual balance : <b>{queb_s} кут</b>",
            "",
            f"• Создано: <b>{html.escape(str(created))}</b>",
            "",
            "Нажмите «Проверить подписку», если вы уже являетесь участником, "
            "или «Пропустить», чтобы потратить Virtual balance и пометить как пропущенное.",
        ]
        return gc_html_replace_known("\n".join(lines))
    except Exception as e:
        _qdbg_exc("_render_sub_task_text fail", e)
        return "<b>Задание</b>\n\nОписание временно недоступно."


# ----------------- Улучшенная сборка клавиатуры списка заданий -----------------

async def _build_sub_list_kb(
    tasks: List[Dict[str, Any]], page: int, queb: Decimal
) -> types.InlineKeyboardMarkup:
    try:
        total = len(tasks or [])
        pages = max(1, math.ceil(total / SUBS_PAGE_SIZE)) if total > 0 else 1
    except Exception:
        total = len(tasks or [])
        pages = 1

    try:
        page = int(page)
    except Exception:
        page = 0
    if page < 0:
        page = 0
    if page >= pages:
        page = max(0, pages - 1)

    start = page * SUBS_PAGE_SIZE
    visible = tasks[start : start + SUBS_PAGE_SIZE]

    rows: List[List[types.InlineKeyboardButton]] = []

    header_label = f"Задания с подпиской - {page+1}/{pages} стр."
    rows.append([InlineKeyboardButton(text=header_label, callback_data="noop", style="default", icon_custom_emoji_id="5362063083311214432")])

    try:
        queb = D(queb)
    except Exception:
        queb = D(0)



    # верхний разделитель
    rows.append([InlineKeyboardButton(text="⎺⎺" * 19, callback_data="noop")])

    for t in visible:
        try:
            if isinstance(t, dict):
                meta = t.get("meta") or {}
                cref_raw = t.get("chat_ref") or t.get("target_chat_ref") or ""
                display_cref = meta.get("title") or str(cref_raw or "")
                reward = t.get("reward")
                if reward is None:
                    reward = t.get("reward_amount") or 0
            else:
                meta = {}
                cref_raw = str(t)
                display_cref = cref_raw
                reward = 0

            reward_dec = D(reward)
            broken = _is_broken_meta(meta)

            if broken:
                # Явно показываем, что задание проблемное
                label = f"⚠️ {display_cref} - проблема [+{fmt_amt(reward_dec)}]"
            else:
                label = f"{display_cref} [+{fmt_amt(reward_dec)}]"

            cb = _task_cb("sub_show", cref_raw)
            rows.append([gc_btn(label, callback_data=cb)])
        except Exception as e:
            _qdbg_exc("_build_sub_list_kb: add group button failed", e)
            rows.append(
                [gc_btn("⚠️ Неизвестная задача", callback_data="noop")]
            )

    # нижний разделитель
    rows.append([InlineKeyboardButton(text="⎽⎽" * 19, callback_data="noop")])

    # навигация
    try:
        nav_row: List[InlineKeyboardButton] = []
        if page > 0:
            nav_row.append(
                gc_btn("🔙 Назад", callback_data=f"qst:sub_page:{page-1}")
            )
        if start + SUBS_PAGE_SIZE < total:
            nav_row.append(
                gc_btn("🔜 Вперёд", callback_data=f"qst:sub_page:{page+1}")
            )
        if nav_row:
            rows.append(nav_row)
    except Exception as e:
        _qdbg_exc("_build_sub_list_kb: build nav row failed", e)
    bal_label = f"💰 Virtual balance : {fmt_amt(queb)} кут"
    rows.append([gc_btn(bal_label, callback_data="qst:bal_info")])

    # Кнопка вывода, если есть >= 1 кут
    try:
        if queb >= D(1):
            can_int = floor_int(queb)
            btn_text = f"⛵️ Вывести {can_int} кут"
            cb = _withdraw_cb(can_int)
            rows.append([gc_btn(btn_text, callback_data=cb)])
    except Exception as e:
        _qdbg_exc("_build_sub_list_kb: withdraw button failed", e)
    rows.append(
        [gc_btn("♻️ Обновить список", callback_data="qst:sub_refresh")]
    )
    rows.append(
        [gc_btn("🏝 В главное меню", callback_data="qst:menu_back")]
    )

    try:
        return types.InlineKeyboardMarkup(inline_keyboard=rows)
    except Exception as e:
        _qdbg_exc("_build_sub_list_kb: InlineKeyboardMarkup build failed", e)
        return types.InlineKeyboardMarkup(
            inline_keyboard=[
                [gc_btn("🔙 Назад в меню", callback_data="qst:menu_back")]
            ]
        )


_refresh_locks: Dict[Tuple[int, int], asyncio.Lock] = {}  # lock per (chat_id, message_id)
_user_short_cache: Dict[int, Tuple[float, List[Dict[str, Any]], Decimal]] = {}
_CACHE_TTL = 2.0  # секунды - короткий TTL для защиты от спама кнопки
_LOCKS_DICT_LOCK = asyncio.Lock()  # защита создания замков
# user_id -> (chat_id, message_id) последнего сообщения со списком заданий
_USER_SUB_MSG: Dict[int, Tuple[int, int]] = {}

# user_id -> asyncio.Lock, чтобы сериализовать быстрый спам по кнопке
_USER_SUB_LOCKS: Dict[int, asyncio.Lock] = {}
# кеш для отображения последней награды по подписке
_last_sub_reward: Dict[int, Decimal] = {}
def _get_user_sub_lock(user_id: int) -> asyncio.Lock:
    lock = _USER_SUB_LOCKS.get(user_id)
    if lock is None:
        lock = asyncio.Lock()
        _USER_SUB_LOCKS[user_id] = lock
    return lock

# ================== ОБРАБОТЧИК КНОПКИ "ОБНОВИТЬ ЗАДАНИЯ" ==================
@dp.callback_query(lambda c: c.data == "qst:sub_refresh")
async def qst_sub_refresh(callback_query: types.CallbackQuery):
    user_id = callback_query.from_user.id
    _qdbg(f"qst_sub_refresh called by user={user_id}")

    # гасим "часики" на кнопке
    try:
        await callback_query.answer()
    except Exception:
        pass

    # откуда пришёл клик (fallback - в ЛС)
    cur_chat_id = (
        callback_query.message.chat.id
        if callback_query.message
        else callback_query.from_user.id
    )
    cur_msg_id = callback_query.message.message_id if callback_query.message else 0

    now = time.time()
    queb: Decimal = D(0)
    pending: List[Dict[str, Any]] = []

    # --------- баланс + задания (с учётом короткого кэша) ----------
    try:
        cached = _user_short_cache.get(user_id)
        if cached and (now - cached[0]) < _CACHE_TTL:
            _, pending, queb = cached
            _qdbg(f"qst_sub_refresh: used short-cache for user={user_id}")
        else:
            balance_coro = _try_db_call(
                ["get_que_balance", "get_virtual_balance"], user_id, default=D(0)
            )
            pending_coro = get_pending_sub_tasks(user_id)
            queb_raw, pending_raw = await asyncio.gather(balance_coro, pending_coro)

            queb = D(queb_raw)
            pending = pending_raw or []

            _user_short_cache[user_id] = (now, pending, queb)
            _qdbg(
                f"qst_sub_refresh: DB loaded for user={user_id}, "
                f"tasks={len(pending)}, queb={queb}"
            )
    except Exception as e:
        _qdbg_exc("qst_sub_refresh: DB gather failed", e)
        try:
            await callback_query.answer(
                "Не удалось обновить задания - попробуйте ещё раз.",
                show_alert=True,
            )
        except Exception:
            pass
        return

    # --------- заранее собираем только КЛАВИАТУРУ (никакого текста) ----------
    no_tasks = not pending
    try:
        if no_tasks:
            # клавиатура для экрана "заданий нет" (кнопка баланса, вывод, назад)
            kb = await _empty_kb(queb)
        else:
            # клавиатура со списком доступных заданий
            kb = await _build_sub_list_kb(pending, page=0, queb=queb)
    except Exception as e:
        _qdbg_exc("qst_sub_refresh: build_kb failed", e)
        # если клавиатура вообще не собралась - честно говорим и выходим
        try:
            await callback_query.answer(
                "Ошибка при сборке интерфейса. Попробуйте позже.",
                show_alert=True,
            )
        except Exception:
            pass
        return

    # ================== КРИТИЧЕСКИЙ УЧАСТОК: ВСЕГДА ОДНО СООБЩЕНИЕ НА ЮЗЕРА ==================
    lock = _get_user_sub_lock(user_id)
    async with lock:
        try:
            # 1) Удаляем предыдущее "активное" сообщение для этого пользователя (если оно есть)
            prev = _USER_SUB_MSG.get(user_id)
            if prev is not None:
                prev_chat_id, prev_msg_id = prev
                await _safe_delete_message(prev_chat_id, prev_msg_id)

            # 2) Удаляем сообщение, по которому нажали (кнопка), чтобы не оставалось старых UI
            if cur_msg_id:
                await _safe_delete_message(cur_chat_id, cur_msg_id)

            # 3) Выбираем стикер в зависимости от наличия заданий

            sticker_id = "CAACAgIAAxkBAnnkimkkxMC5_fsg-96x8mjz21p-o7DtAAIeiQAC6FMoSb1sUOpoXdxiNgQ"


            # 4) Отправляем НОВЫЙ СТИКЕР + inline-клавиатура
            try:
                msg = await bot1.send_sticker(
                    chat_id=cur_chat_id,
                    sticker=sticker_id,
                    reply_markup=kb,
                )
                _qdbg(
                    f"qst_sub_refresh: sticker UI sent "
                    f"chat={cur_chat_id} msg={msg.message_id} no_tasks={no_tasks}"
                )
            except Exception as e_st:
                # Теоретически может упасть send_sticker (битый file_id, бан и т.д.)
                _qdbg_exc(
                    "qst_sub_refresh: send_sticker failed, fallback to text message",
                    e_st,
                )
                # Фоллбек: всё-таки отправим текст, чтобы не оставить пользователя без UI
                fallback_text = (
                    "Заданий больше нет."
                    if no_tasks
                    else "📋 Обновлён список заданий с подпиской."
                )
                msg = await bot1.send_message(
                    chat_id=cur_chat_id,
                    text=fallback_text,
                    parse_mode="HTML",
                    disable_web_page_preview=True,
                    reply_markup=kb,
                )

            # 5) Запоминаем новое сообщение как единственное актуальное для этого пользователя
            _USER_SUB_MSG[user_id] = (msg.chat.id, msg.message_id)

        except Exception as e:
            _qdbg_exc("qst_sub_refresh: UI update failed", e)
            try:
                await callback_query.answer(
                    "Ошибка при обновлении интерфейса.",
                    show_alert=True,
                )
            except Exception:
                pass

    # --------- лёгкая периодическая чистка словарей (опционально) ----------
    try:
        if len(_USER_SUB_LOCKS) > 5000:
            for uid in list(_USER_SUB_LOCKS.keys())[:1000]:
                if not _USER_SUB_LOCKS[uid].locked():
                    _USER_SUB_LOCKS.pop(uid, None)

        if len(_USER_SUB_MSG) > 5000:
            for uid in list(_USER_SUB_MSG.keys())[:1000]:
                _USER_SUB_MSG.pop(uid, None)
    except Exception:
        pass


@dp.callback_query(lambda c: c.data and c.data.startswith("qst:broken_details:"))
async def qst_broken_details(callback_query: types.CallbackQuery):
    """
    Коротко сообщает причину поломки и кому писать.
    Полный текст уходит в ЛС (HTML). В show_alert - краткая однострочная заметка.
    """
    try:
        parts = callback_query.data.split(":", 2)
        try:
            page = int(parts[2])
        except Exception:
            page = 0

        user = callback_query.from_user
        user_id = user.id

        pending = await get_pending_sub_tasks(user_id)
        if not pending:
            await callback_query.answer("🏜 Нет активных заданий.", show_alert=True)
            return

        start = page * SUBS_PAGE_SIZE
        visible = pending[start : start + SUBS_PAGE_SIZE]
        if not visible:
            await callback_query.answer(
                "🔍 На этой странице заданий нет.", show_alert=True
            )
            return

        admins = "@JerichoCute"

        # Build a short single-line summary
        summary_items = []
        for t in visible:
            try:
                cref = str(t.get("chat_ref") or t.get("target_chat_ref") or "")
                meta = t.get("meta") or {}
                bot_missing = bool(meta.get("bot_missing"))
                err_raw = str(meta.get("error") or "").strip()
                if bot_missing and any(
                    k in err_raw.lower()
                    for k in ("forbidden", "kicked", "removed")
                ):
                    short = f"⚠️ {cref}: бот удалён/заблокирован."
                elif bot_missing:
                    short = f"⚠️ {cref}: бот не имеет доступа."
                elif not meta.get("username"):
                    short = f"🔒 {cref}: нет публичного @username."
                elif err_raw:
                    short = f"❗ {cref}: ошибка ({err_raw[:80]}…)."
                else:
                    short = f"❗ {cref}: непредвиденная проблема."
                summary_items.append(short)
            except Exception:
                summary_items.append(f"⚠️ {str(t)} - проблема (см. в ЛС).")

        alert_text = ";\n".join(summary_items)
        if len(alert_text) > 700:
            alert_text = alert_text[:690].rstrip() + "…"

        try:
            await callback_query.answer(
                "ℹ️ Кратко: подробности отправлены в ЛС (если доступно).",
                show_alert=True,
            )
        except Exception:
            pass

        # попытка отправить подробности в ЛС
        try:
            full_lines = ["<b>🔧 Проблемы с заданиями - детали</b>\n"]
            for t in visible:
                cref = str(
                    t.get("chat_ref") or t.get("target_chat_ref") or ""
                )
                meta = t.get("meta") or {}
                bot_missing = bool(meta.get("bot_missing"))
                err_raw = str(meta.get("error") or "").strip()
                if bot_missing and any(
                    k in err_raw.lower()
                    for k in ("forbidden", "kicked", "removed")
                ):
                    reason = "Бот удалён/заблокирован"
                    action = (
                        "Напишите админам, укажите название/username чата и эту ошибку."
                    )
                elif bot_missing:
                    reason = "Бот не имеет доступа"
                    action = (
                        "Прикрепите ссылку/username чата и текст ошибки."
                    )
                elif not meta.get("username"):
                    reason = "Нет публичного @username"
                    action = (
                        "Попросите владельца добавить username или пришлите chat_id админам."
                    )
                elif err_raw:
                    reason = f"Ошибка: {html.escape(err_raw[:200])}"
                    action = (
                        "Скопируйте текст ошибки и отправьте админам."
                    )
                else:
                    reason = "Непредвиденная проблема"
                    action = (
                        "Опишите кратко, что видите, и отправьте админам."
                    )

                full_lines.append(f"<b>• {html.escape(cref)}</b>")
                full_lines.append(f"  • Причина: {html.escape(reason)}")
                full_lines.append(f"  • Действие: {html.escape(action)}\n")

            sample_chat = html.escape(
                str(
                    visible[0].get("chat_ref")
                    or visible[0].get("target_chat_ref")
                    or ""
                )
            )
            sample_template = (
                f"Здравствуйте, заметил(а) проблему с заданием {sample_chat}. "
                f"При попытке выполнить вижу: [кратко]. Мой @username/ID: {user_id}"
            )
            full_lines.append(
                "<b>📩 Шаблон для администратора (скопируйте):</b>"
            )
            full_lines.append(f"<code>{html.escape(sample_template)}</code>")
            full_text = gc_html_replace_known("\n".join(full_lines))
            if len(full_text) > 3800:
                full_text = (
                    full_text[:3790].rstrip()
                    + "\n\n… (текст обрезан)"
                )
            await bot1.send_message(
                chat_id=user_id,
                text=full_text,
                parse_mode="HTML",
                disable_web_page_preview=True,
            )
            _qdbg("qst_broken_details: full details sent via PM")
        except Exception as e:
            _qdbg_exc("qst_broken_details: send_message to user failed", e)

    except Exception as e:
        _qdbg_exc("qst_broken_details failed", e)
        try:
            await callback_query.answer(
                "Ошибка при получении подробностей. Попробуйте позже. ⚠️",
                show_alert=True,
            )
        except Exception:
            pass


# ---------- Safe edit (delete+send sticker/text fallback) ----------

async def _safe_edit_message_text(
    chat_id: int,
    message_id: int,
    text: str,
    reply_markup=None,
    replacement_sticker: Optional[str] = None,
) -> Optional[types.Message]:
    """
    Safe replacement: удаляем старое сообщение (best-effort), затем отправляем стикер (если задан)
    или текст с клавиатурой.
    Возвращаем новый message или None.
    """
    try:
        if message_id:
            try:
                await bot1.delete_message(chat_id=chat_id, message_id=message_id)
                _qdbg("delete_message: OK")
            except Exception as e_del:
                msg = str(e_del).lower()
                if "message to delete not found" in msg or (
                    "message to delete" in msg and "not found" in msg
                ):
                    _qdbg(
                        "delete_message: message already gone (ignored, continue)"
                    )
                else:
                    _qdbg_exc("delete_message failed (continuing)", e_del)

        # выбираем стикер (replacement или любой из массивов)
        stickers_pool = []
        if REPLACEMENT_STICKERS:
            stickers_pool.extend(REPLACEMENT_STICKERS)
        if STICKERS:
            stickers_pool.extend(STICKERS)

        sticker_to_send = replacement_sticker or (
            random.choice(stickers_pool) if stickers_pool else None
        )

        if sticker_to_send:
            try:
                new_msg = await bot1.send_sticker(
                    chat_id=chat_id,
                    sticker=sticker_to_send,
                    reply_markup=reply_markup,
                )
                _qdbg("replacement sticker send: OK")
                return new_msg
            except Exception as e_send:
                _qdbg_exc(
                    "replacement sticker send failed (fall back to text)", e_send
                )

        try:
            new_msg = await bot1.send_message(
                chat_id=chat_id,
                text=text,
                parse_mode="HTML",
                disable_web_page_preview=True,
                reply_markup=reply_markup,
            )
            _qdbg("send_message (fallback): OK")
            return new_msg
        except Exception as e_msg:
            _qdbg_exc("send_message failed", e_msg)
            return None
    except Exception as e_outer:
        _qdbg_exc("_safe_edit_message_text outer", e_outer)
        return None


# ---------- Empty render ----------

async def _render_empty_text(queb: Decimal) -> str:
    """
    Текст, когда активных заданий не осталось.
    Всегда показывает актуальный Virtual balance.
    """
    try:
        queb = D(queb)
    except Exception:
        queb = D(0)

    return gc_html_replace_known(
        "<b>🏜 Активных заданий нет.</b>\n\n"
        f"🍹 <b>Virtual balance : {fmt_amt(queb)} кут</b>\n\n"
        "Вы можете вывести накопленные куты или вернуться в меню с помощью кнопок ниже."
    )


async def _empty_kb(queb: Decimal) -> types.InlineKeyboardMarkup:
    """
    Клавиатура для экрана, когда заданий нет:
    - информационная кнопка (noop)
    - кнопка с текущим Virtual balance (qst:bal_info)
    - кнопка вывода (если есть >= 1 кут)
    - кнопка 'Назад в меню'
    """
    try:
        queb = D(queb)
    except Exception:
        queb = D(0)

    can_int = floor_int(queb)
    rows: List[List[InlineKeyboardButton]] = [
        [gc_btn("🏜 Заданий больше нет…", callback_data="noop")],
        [gc_btn(f"💰 Virtual balance : {fmt_amt(queb)} кут", callback_data="qst:bal_info")],
    ]
    if can_int > 0:
        rows.append([
            gc_btn(
                f"⛵️ Вывести {can_int} кут",
                callback_data=f"qst:withdraw:{can_int}",
            )
        ])
    rows.append([gc_btn("🔙 Назад в меню", callback_data="qst:menu_back")])
    return types.InlineKeyboardMarkup(inline_keyboard=rows)


@dp.callback_query(lambda c: c.data == "qst:menu_back")
async def qst_menu_back(callback_query: types.CallbackQuery):
    try:
        # гасим "часики"
        try:
            await callback_query.answer()
        except Exception:
            pass

        # аккуратно удаляем старое сообщение
        try:
            if callback_query.message:
                await _safe_delete_message(
                    chat_id=callback_query.message.chat.id,
                    message_id=callback_query.message.message_id,
                )
        except Exception as e:
            _qdbg_exc("qst_menu_back: checking/deleting message failed", e)

        # пробуем открыть нормальное меню
        try:
            await questions_stars_menu(callback_query)
            return
        except Exception as e_menu:
            _qdbg_exc("qst_menu_back: questions_stars_menu failed (falling back)", e_menu)

        # fallback-меню вручную, если основной хэндлер сломался
        try:
            kb = InlineKeyboardBuilder()
            kb.button(text="Задания с подпиской", callback_data="qst:show_subs", style="default", icon_custom_emoji_id="5362063083311214432")
            kb.button(text="Челленджи", callback_data="qst:show_gc", style="default", icon_custom_emoji_id="5445096582238181549")
            kb.button(text="Закрыть", callback_data="9close_bonus_+")
            kb.adjust(1)
            compact_kb = kb.as_markup()

            sticker_id = None
            try:
                if isinstance(STICKERS, (list, tuple)) and STICKERS:
                    sticker_id = random.choice(STICKERS)
            except Exception as e:
                _qdbg_exc("qst_menu_back: choose sticker failed", e)

            target = (
                callback_query.message.chat.id
                if callback_query.message
                else callback_query.from_user.id
            )

            if sticker_id:
                try:
                    await bot1.send_sticker(
                        chat_id=target,
                        sticker=sticker_id,
                        reply_markup=compact_kb,
                    )
                    _qdbg("qst_menu_back: fallback sticker menu sent")
                except Exception as e_st:
                    _qdbg_exc(
                        "qst_menu_back: fallback send_sticker failed, sending message",
                        e_st,
                    )
                    try:
                        await bot1.send_message(
                            chat_id=target,
                            text="Меню временно недоступно. Попробуйте позже.",
                            reply_markup=compact_kb,
                        )
                    except Exception as e_msg:
                        _qdbg_exc(
                            "qst_menu_back: fallback send_message failed",
                            e_msg,
                        )
            else:
                try:
                    await bot1.send_message(
                        chat_id=target,
                        text="Меню временно недоступно. Попробуйте позже.",
                        reply_markup=compact_kb,
                    )
                    _qdbg("qst_menu_back: fallback text menu sent")
                except Exception as e_msg2:
                    _qdbg_exc(
                        "qst_menu_back: send_message fallback failed",
                        e_msg2,
                    )

        except Exception as e_send:
            _qdbg_exc("qst_menu_back: final fallback failed", e_send)
            try:
                await callback_query.answer(
                    "Не удалось открыть меню. Попробуйте ещё.",
                    show_alert=True,
                )
            except Exception:
                pass

    except Exception as e:
        _qdbg_exc("qst_menu_back unexpected", e)
        try:
            await callback_query.answer(
                "Не удалось вернуться в меню. Попробуйте ещё.",
                show_alert=True,
            )
        except Exception:
            pass


@dp.callback_query(lambda c: c.data == "qst:show_subs_normal")
async def qst_show_subs_normal(callback_query: types.CallbackQuery):
    """
    Показывает только НОРМАЛЬНЫЕ задания (без проблем с ботом/username).
    Если нормальных заданий нет - экран «заданий больше нет» + баланс + вывод.
    """
    user_id = callback_query.from_user.id
    _qdbg(f"qst_show_subs_normal user={user_id}")

    # аккуратно гасим «часы» у callback
    try:
        await callback_query.answer()
    except Exception:
        pass

    target_chat = callback_query.message.chat.id if callback_query.message else user_id
    target_msg_id = callback_query.message.message_id if callback_query.message else None

    now = time.time()
    queb: Decimal = D(0)
    pending: List[Dict[str, Any]] = []

    # --------- грузим баланс + список заданий (с коротким кэшем, как в qst_sub_refresh) ----------
    try:
        cached = _user_short_cache.get(user_id)
        if cached and (now - cached[0]) < _CACHE_TTL:
            _, pending, queb = cached
            _qdbg(f"qst_show_subs_normal: used short-cache for user={user_id}")
        else:
            balance_coro = _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
            pending_coro = get_pending_sub_tasks(user_id)
            queb_raw, pending_raw = await asyncio.gather(balance_coro, pending_coro)

            queb = D(queb_raw)
            pending = pending_raw or []

            _user_short_cache[user_id] = (now, pending, queb)
            _qdbg(f"qst_show_subs_normal: DB loaded for user={user_id}, tasks={len(pending)}, queb={queb}")
    except Exception as e:
        _qdbg_exc("qst_show_subs_normal: load balance/tasks failed", e)
        try:
            await callback_query.answer("Ошибка при загрузке заданий.", show_alert=True)
        except Exception:
            pass
        return

    # --------- фильтруем только нормальные задания (НЕ сломанные) ----------
    try:
        normal_tasks = [t for t in (pending or []) if not _is_broken_task(t)]
        _qdbg(f"qst_show_subs_normal: normal_tasks={len(normal_tasks)}, pending_total={len(pending)}")
    except Exception as e:
        _qdbg_exc("qst_show_subs_normal: filter normal_tasks failed", e)
        normal_tasks = []

    # --------- если нормальных заданий нет -> экран "заданий больше нет" с балансом и выводом ----------
    if not normal_tasks:
        try:
            text = await _render_empty_text(queb)
            kb = await _empty_kb(queb)

            await _safe_edit_message_text(
                chat_id=target_chat,
                message_id=target_msg_id or 0,
                text=text,
                reply_markup=kb,
                replacement_sticker=EMPTY_TASKS_STICKER,  # "заданий больше нет" стикер
            )
            _qdbg(f"qst_show_subs_normal: no normal tasks -> no-tasks UI for user={user_id}")
        except Exception as e:
            _qdbg_exc("qst_show_subs_normal: show no-normal-tasks UI failed", e)
            try:
                await callback_query.answer("Не удалось показать список заданий.", show_alert=True)
            except Exception:
                pass
        return

    # --------- есть нормальные задания -> показываем список только из них ----------
    try:
        page = 0
        header_text = gc_html_replace_known(
            "<b>📋 Обычные задания (без проблем с ботом)</b>\n\n"
            "Нажмите на любую кнопку ниже, чтобы открыть задание."
        )
        kb = await _build_sub_list_kb(normal_tasks, page, queb)

        await _safe_edit_message_text(
            chat_id=target_chat,
            message_id=target_msg_id or 0,
            text=header_text,
            reply_markup=kb,
        )
        _qdbg(f"qst_show_subs_normal: normal list shown for user={user_id}")
    except Exception as e:
        _qdbg_exc("qst_show_subs_normal: render/send normal list failed", e)
        try:
            await callback_query.answer("Ошибка. Попробуй позже.", show_alert=True)
        except Exception:
            pass
async def _safe_delete_message(chat_id: int, message_id: int) -> bool:
    """
    Best-effort удаление сообщения. Возвращает True если удаление выполнено успешно,
    False в остальных случаях. НИКОГДА не бросает.
    """
    try:
        if chat_id is None or message_id is None:
            _qdbg("_safe_delete_message: no chat_id/message_id provided -> skipping")
            return False
        try:
            await bot1.delete_message(chat_id=chat_id, message_id=message_id)
            _qdbg(f"_safe_delete_message: deleted chat={chat_id} msg={message_id}")
            return True
        except Exception as e:
            msg = str(e).lower() if e is not None else ""
            if "message to delete not found" in msg or ("message to delete" in msg and "not found" in msg):
                _qdbg(f"_safe_delete_message: message not found chat={chat_id} msg={message_id} (ignored)")
                return False
            _qdbg_exc(f"_safe_delete_message: delete failed chat={chat_id} msg={message_id}", e)
            return False
    except Exception as e_outer:
        _qdbg_exc("_safe_delete_message outer", e_outer)
        return False

