async def qst_withdraw_ok(callback_query: types.CallbackQuery):
    try:
        await callback_query.answer("Вывод выполнен успешно. Деньги зачислены на основной баланс.", show_alert=True)
        try:
            await questions_stars_menu(callback_query)
        except Exception:
            pass
    except Exception as e:
        _qdbg_exc("qst_withdraw_ok fail", e)
        try:
            await callback_query.answer("OK", show_alert=True)
        except Exception:
            pass

async def get_pending_sub_tasks(user_id: int) -> List[Dict[str, Any]]:
    """
    Возвращает список активных задач с полями 'meta' и т.д.
    Дополнение: если пользователь уже является участником целевого чата,
    то задание помечается как выполненное (автоматически) и не попадает в результат.
    По флагу AUTOCREDIT_IF_ALREADY_MEMBER решаем - начислять награду или только пометить.
    """
    try:
        tasks = await _try_db_call(["list_tasks", "list_subscription_tasks", "list_quests"], active_only=True, default=[])
        _qdbg_list("get_pending_sub_tasks -> all tasks", tasks, max_items=20)

        refs = []
        row_by_ref = {}
        for t in tasks or []:
            if isinstance(t, dict):
                cref = str(t.get("chat_ref") or t.get("target_chat_ref") or t.get("ref") or "")
            else:
                cref = str(t)
            if not cref:
                continue
            cref_norm = _norm_chat_ref(cref)
            refs.append(cref_norm)
            row_by_ref[cref_norm] = t

        # done refs from DB (унифицировано)
        done_refs_raw = []
        if refs:
            done_refs_raw = await _try_db_call(
                ["get_done_refs_for_user", "get_done_tasks_for_user", "list_done_task_refs", "get_user_done_tasks"],
                user_id,
                refs,
                default=[]
            )
        else:
            done_refs_raw = []

        done_set = set()
        for it in done_refs_raw or []:
            if isinstance(it, dict):
                ref = it.get("chat_ref") or it.get("ref") or it.get("target") or it.get("canonical_ref") or None
                if ref:
                    done_set.add(_norm_chat_ref(ref))
            else:
                done_set.add(_norm_chat_ref(str(it)))

        _qdbg_list("get_pending_sub_tasks -> done_refs", list(done_set), max_items=50)

        # candidates = refs \ done_set
        candidates = [r for r in refs if r not in done_set]
        _qdbg_list("get_pending_sub_tasks -> candidates pre-membership-check", candidates, max_items=50)
        if not candidates:
            return []

        # concurrency control
        CONCURRENCY = 6
        sem = asyncio.Semaphore(CONCURRENCY)

        # 1) try bulk check_user_subscriptions if available
        membership_map = {}  # normalized cref -> bool
        use_check_fn = globals().get("check_user_subscriptions") is not None
        if use_check_fn:
            try:
                api_refs = [_as_api_ref(r) for r in candidates]
                _qdbg(f"get_pending_sub_tasks: calling check_user_subscriptions for {len(api_refs)} refs")
                raw_res = await check_user_subscriptions(bot1, user_id, api_refs)
                _qdbg(f"check_user_subscriptions returned: {type(raw_res)}")
                # interpret various shapes
                if isinstance(raw_res, dict):
                    for api_ref, info in raw_res.items():
                        key = str(api_ref)
                        if str(key).lstrip("-").isdigit():
                            membership_map[str(key)] = bool(info)
                        else:
                            membership_map[_norm_chat_ref(key)] = bool(info)
                elif isinstance(raw_res, list):
                    for item in raw_res:
                        if isinstance(item, dict):
                            key = None
                            for k in ("chat_id", "chat", "ref", "target", "chat_ref", "id"):
                                if k in item:
                                    key = str(item[k])
                                    break
                            is_mem = False
                            for mf in ("is_member", "member", "joined", "exists"):
                                if mf in item:
                                    is_mem = bool(item[mf])
                                    break
                            if key is not None:
                                norm_key = _norm_chat_ref(key) if not str(key).lstrip("-").isdigit() else str(key)
                                membership_map[norm_key] = bool(is_mem)
                elif raw_res is True:
                    _qdbg("check_user_subscriptions returned True (ambiguous) - ignoring bulk mapping")
                else:
                    _qdbg("check_user_subscriptions returned unknown shape - ignoring")
            except Exception as e:
                _qdbg_exc("get_pending_sub_tasks: check_user_subscriptions failed", e)

        # normalize keys in membership_map
        normalized_membership = {}
        for k, v in membership_map.items():
            try:
                if str(k).lstrip("-").isdigit():
                    normalized_membership[str(k)] = bool(v)
                else:
                    normalized_membership[_norm_chat_ref(k)] = bool(v)
            except Exception:
                normalized_membership[str(k)] = bool(v)
        membership_map = normalized_membership

        # 2) For remaining candidates not known as member -> do get_chat_member checks
        to_check_via_getchat = []
        for cref in candidates:
            if membership_map.get(cref) or membership_map.get(str(_as_api_ref(cref))):
                continue
            to_check_via_getchat.append(cref)

        _qdbg_list("get_pending_sub_tasks -> to_check_via_getchat", to_check_via_getchat, max_items=50)

        async def _create_member_task(cref):
            api_ref = _as_api_ref(cref)
            is_mem = await _check_member_getchatmember(api_ref, user_id, sem)
            return cref, is_mem

        coros = [_create_member_task(c) for c in to_check_via_getchat]
        if coros:
            try:
                results = await asyncio.gather(*coros, return_exceptions=True)
                for r in results:
                    if isinstance(r, Exception):
                        _qdbg_exc("get_pending_sub_tasks: member check item failed", r)
                        continue
                    cref, is_mem = r
                    membership_map[cref] = bool(is_mem)
            except Exception as e:
                _qdbg_exc("get_pending_sub_tasks: member check gather failed", e)

        # --- NEW: автозакрытие (autoclose) для тех, кто уже является участником ---
        # Собираем список refs, которые membership_map пометил как True (т.е. user is member)
        auto_close = [cref for cref, v in membership_map.items() if bool(v)]
        if auto_close:
            _qdbg_list("get_pending_sub_tasks -> auto_close (members found)", auto_close, max_items=100)

            # создаём задачи для автозакрытия; limit concurrency
            sem_ac = asyncio.Semaphore(CONCURRENCY)

            async def _autoclose_one(cref_local):
                async with sem_ac:
                    try:
                        # выбираем row и reward для возможного автозачёта
                        row = row_by_ref.get(cref_local) or {}
                        reward = D(row.get("reward") or row.get("reward_amount") or 0)
                        # если в БД есть метод с капами - используем prefer claim_task_reward_once_capped_expiry
                        if AUTOCREDIT_IF_ALREADY_MEMBER:
                            # попробуем сначала метод с капами
                            res = await _try_db_call(["claim_task_reward_once_capped_expiry", "claim_task_reward_once_capped", "claim_task_reward_once"], user_id, cref_local, reward, default=(False, "error"))
                            # claim_task_reward_once_capped_expiry возвращает (ok, code) в твоей реализации - обработаем
                            if isinstance(res, tuple):
                                ok = bool(res[0])
                                return (cref_local, ok)
                            else:
                                # некоторые реализации могут возвращать True/False
                                return (cref_local, bool(res))
                        else:
                            # пометить как сделанное без начисления награды - вызываем skip_task_once с cost=0
                            res = await _try_db_call(["skip_task_once", "mark_task_skipped", "mark_task_as_done_without_reward"], user_id, cref_local, D(0), default=False)
                            return (cref_local, bool(res))
                    except Exception as e:
                        _qdbg_exc("_autoclose_one failed", e)
                        return (cref_local, False)

            # запустим автозакрытие (best-effort)
            ac_coros = [_autoclose_one(c) for c in auto_close]
            try:
                ac_results = await asyncio.gather(*ac_coros, return_exceptions=True)
                for item in ac_results:
                    if isinstance(item, Exception):
                        _qdbg_exc("get_pending_sub_tasks: autoclose item exception", item)
                        continue
                    cref_done, ok_flag = item
                    if ok_flag:
                        # внесём в done_set, чтобы не показывать
                        done_set.add(cref_done)
                        # если в row_by_ref - можно пометить row meta/чтобы логика выше учла
                        if cref_done in row_by_ref:
                            r = row_by_ref[cref_done]
                            if isinstance(r, dict):
                                r.setdefault("meta", {}).setdefault("auto_closed", True)
                _qdbg("get_pending_sub_tasks: autoclose finished (best-effort)")
            except Exception as e:
                _qdbg_exc("get_pending_sub_tasks: autoclose gather failed", e)

            # обновляем candidates: убираем закрытые
            candidates = [r for r in candidates if r not in done_set]
            _qdbg_list("get_pending_sub_tasks -> candidates after autoclose", candidates, max_items=50)
            if not candidates:
                return []

        # 3) Build pending_candidates = those candidates where membership_map says False or unknown (treat unknown as not member)
        pending_candidates = []
        for cref in candidates:
            if membership_map.get(cref) or membership_map.get(str(_as_api_ref(cref))):
                _qdbg(f"get_pending_sub_tasks: skipping {cref} because membership_map=True (post-autoclose)")
                continue
            row = row_by_ref.get(cref)
            row_copy = dict(row) if isinstance(row, dict) else {"chat_ref": cref, "reward": 0}
            pending_candidates.append((cref, row_copy))

        _qdbg_list("get_pending_sub_tasks -> pending_candidates after membership filter", [c for c,_ in pending_candidates], max_items=50)
        if not pending_candidates:
            return []

        # 4) Fetch meta for pending candidates (parallel with Semaphore)
        async def _fetch_meta(cref, sem_local):
            try:
                async with sem_local:
                    m = await _meta_for_ref(cref)
                    return cref, m
            except Exception as e:
                _qdbg_exc("get_pending_sub_tasks: _meta_for_ref single failed", e)
                return cref, {"chat_id": cref, "title": cref, "username": None, "bot_missing": False, "error": str(e)}

        sem_meta = asyncio.Semaphore(CONCURRENCY)
        meta_coros = [_fetch_meta(cref, sem_meta) for (cref, _) in pending_candidates]
        meta_results = []
        try:
            meta_results = await asyncio.gather(*meta_coros, return_exceptions=True)
        except Exception as e:
            _qdbg_exc("get_pending_sub_tasks: gather meta failed", e)
            # fallback sequential
            meta_results = []
            for cref, _ in pending_candidates:
                try:
                    meta_results.append(await _fetch_meta(cref, sem_meta))
                except Exception as e2:
                    meta_results.append((cref, {"chat_id": cref, "title": cref, "username": None, "bot_missing": False, "error": str(e2)}))

        meta_by_cref = {}
        for r in meta_results:
            if isinstance(r, Exception):
                _qdbg_exc("get_pending_sub_tasks: meta item is Exception", r)
                continue
            try:
                cref, meta = r
                meta_by_cref[cref] = meta or {"chat_id": cref, "title": cref, "username": None, "bot_missing": False, "error": None}
            except Exception as e:
                _qdbg_exc("get_pending_sub_tasks: meta item unpack failed", e)

        # 5) Compose pending_with_meta
        pending_with_meta = []
        for cref, row_copy in pending_candidates:
            meta = meta_by_cref.get(cref) or {"chat_id": cref, "title": cref, "username": None, "bot_missing": False, "error": None}
            row_copy["meta"] = meta
            pending_with_meta.append(row_copy)

        _qdbg_list("get_pending_sub_tasks -> pending_with_meta (unsorted)", pending_with_meta, max_items=50)

        # 6) sort: normal tasks first by reward desc, broken tasks last
        def sort_key(r):
            meta = r.get("meta") or {}
            broken = _is_broken_meta(meta)
            reward = r.get("reward") or r.get("reward_amount") or 0
            try:
                reward_val = float(reward)
            except Exception:
                try:
                    reward_val = float(str(reward))
                except Exception:
                    reward_val = 0.0
            # хотим: нормальные (broken=False) сначала, потом сломанные (broken=True),
            # внутри группы - по награде по убыванию
            return (1 if broken else 0 , -reward_val)

        pending_with_meta.sort(key=sort_key)
        _qdbg_list("get_pending_sub_tasks -> pending_sorted", pending_with_meta, max_items=50)
        return pending_with_meta

    except Exception as e:
        _qdbg_exc("get_pending_sub_tasks failed", e)
        return []

async def _check_member_getchatmember(api_ref, user_id, sem: asyncio.Semaphore, timeout: float = 5.0) -> bool:
    """
    Best-effort check via bot1.get_chat_member. Возвращает True если user является member/admin/creator.
    """
    try:
        _qdbg(f"_check_member_getchatmember: check api_ref={api_ref} for user={user_id}")
        async with sem:
            try:
                cm = await bot1.get_chat_member(chat_id=api_ref, user_id=user_id)
                status = getattr(cm, "status", "") or ""
                is_member = status.lower() in ("member", "creator", "administrator")
                _qdbg(f"_check_member_getchatmember: api_ref={api_ref} status={status} -> {is_member}")
                return bool(is_member)
            except Exception as e_cm:
                _qdbg_exc(f"_check_member_getchatmember: get_chat_member failed for {api_ref}", e_cm)
                return False
    except Exception as e:
        _qdbg_exc("_check_member_getchatmember unexpected", e)
        return False

# ---------- Show next task helpers ----------
# ---------- Show next task helpers ----------
async def _show_next_task(message: types.Message, user_id: int):
    """
    Показывает:
    - список заданий с подпиской (если есть)
    - или (позже) игровые задания
    - или единый экран 'заданий больше нет', если ни обычных, ни проблемных заданий не осталось.
    Работает по конкретному message (его и заменяет через _safe_edit_message_text).
    """
    if not message:
        _qdbg(f"_show_next_task: no message provided for user_id={user_id}")
        return

    chat_id = message.chat.id
    msg_id = message.message_id

    try:
        _qdbg(f"_show_next_task: user_id={user_id}, chat_id={chat_id}, msg_id={msg_id}")

        # баланс
        queb = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
        queb = D(queb)

        # подписочные задания (и нормальные, и проблемные - get_pending_sub_tasks уже сортирует)
        pending_subs = await get_pending_sub_tasks(user_id)
        sub_cands = list(pending_subs or [])
        sub_available = len(sub_cands)

        # TODO: сюда позже можно добавить GC
        gc_cands: List[Dict[str, Any]] = []
        gc_available = len(gc_cands)

        # --- вообще НЕТ заданий ни подписочных, ни игровых ---
        if sub_available == 0 and gc_available == 0:
            _qdbg(f"_show_next_task: no subs and no gc for user={user_id} -> no-tasks screen")
            await _show_no_tasks_screen(chat_id=chat_id, message_id=msg_id, queb=queb)
            return

        # --- есть задания с подпиской ---
        if sub_available > 0:
            txt = gc_html_replace_known(
                "<b>📋 Доступные задания с подпиской</b>\n\n"
                "Выберите задание из списка ниже."
            )
            kb = await _build_sub_list_kb(sub_cands, page=0, queb=queb)
            await _safe_edit_message_text(
                chat_id=chat_id,
                message_id=msg_id,
                text=txt,
                reply_markup=kb,
            )
            _qdbg(f"_show_next_task: subs list shown for user={user_id}, subs={sub_available}")
            return

        # --- (заглушка) есть только игровые задания ---
        if gc_available > 0:
            _qdbg(f"_show_next_task: no subs but gc_available={gc_available} for user={user_id}")
            await _safe_edit_message_text(
                chat_id=chat_id,
                message_id=msg_id,
                text="<b>Игровые задания</b>",
                reply_markup=await _build_after_take_kb(None),
            )
            return

    except Exception as e:
        _qdbg_exc("_show_next_task unexpected fail", e)
        try:
            queb = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
            queb = D(queb)
            await _show_no_tasks_screen(chat_id=chat_id, message_id=msg_id, queb=queb)
        except Exception as e2:
            _qdbg_exc("_show_next_task fallback edit failed", e2)

# ---------- Show "best" (max reward) pending subscription task ----------
async def _show_best_task_for_user(message: types.Message, user_id: int):
    """
    Показывает лучшее (с максимальной наградой) НОРМАЛЬНОЕ задание на подписку.
    Сломанные задания никогда не выбираются как «лучшее» - они остаются внизу общего списка.
    Если нормальных заданий не осталось, показываем общий список (_show_next_task),
    где сломанные уже отсортированы в конце и помечены ⚠️.
    """
    try:
        # 1) Баланс виртуальных кут
        queb = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))

        # 2) Непросмотренные/не выполненные задания
        pending = await get_pending_sub_tasks(user_id)

        if not pending:
            # Вообще нет заданий - отдаём в общий обработчик
            await _show_next_task(message, user_id)
            return

        normal: List[Tuple[str, Decimal, Dict[str, Any]]] = []
        broken: List[Tuple[str, Decimal, Dict[str, Any]]] = []

        for t in pending:
            if isinstance(t, dict):
                cref = str(t.get("chat_ref") or t.get("target_chat_ref") or "")
                reward = D(t.get("reward") or 0)
                if _is_broken_task(t):
                    broken.append((cref, reward, t))
                else:
                    normal.append((cref, reward, t))
            else:
                cref = str(t)
                # простая обёртка: считаем такие задания нормальными с нулевой наградой
                normal.append((cref, D(0), {"chat_ref": cref, "reward": 0}))

        # Если нормальных заданий нет, но есть сломанные - показываем общий список,
        # где они уже стоят внизу и помечены как ⚠️ + ведут к админам.
        if not normal:
            await _show_next_task(message, user_id)
            return

        # 3) Выбираем задание с максимальной наградой ИЗ НОРМАЛЬНЫХ
        max_reward = max(r for (_, r, _) in normal)
        top = [c for c in normal if c[1] == max_reward]
        chosen = random.choice(top)
        cref, reward, meta = chosen

        # 4) Рендер текста задания
        # total можно считать по всем pending или только по normal - не критично
        txt = await _render_sub_task_text(cref, meta, 1, len(normal), queb)

        # 5) Клавиатура
        kb = InlineKeyboardBuilder()

        # 5.1. Если есть последняя награда - показываем "+ N кут" вверху
        last_reward = _last_sub_reward.get(user_id)
        try:
            if last_reward is not None and D(last_reward) > 0:
                kb.button(text=f"+ {fmt_amt(last_reward)} кут", callback_data="qst:bal_info")
        except Exception as e:
            _qdbg_exc("_show_best_task_for_user: last_reward button failed", e)

        # 5.2. Кнопка "подписаться / открыть группу"
        meta_ref = str(meta.get("chat_ref") or meta.get("target_chat_ref") or cref)
        try:
            mmeta = meta.get("meta") or meta  # meta может уже содержать 'meta', пробуем оба варианта
            if isinstance(mmeta, dict) and "chat_id" in mmeta:
                # это уже meta
                url, title = await _chat_link_and_title(mmeta)
            else:
                mmeta2 = await _meta_for_ref(meta_ref)
                url, title = await _chat_link_and_title(mmeta2)

            if url:
                kb.button(text="Перейти в канал / группу", url=url)
            else:
                kb.button(text=f"Инфо: {meta_ref}", callback_data=f"qst:group_info:{meta_ref}")
        except Exception:
            kb.button(text=f"Инфо: {meta_ref}", callback_data=f"qst:group_info:{meta_ref}")

        # 5.3. Проверить подписку / Пропустить / Назад
        kb.row(gc_btn("✅ Проверить подписку", callback_data=_task_cb("check", cref)))
        if D(queb) >= SKIP_COST:
            kb.row(gc_btn(
                f"🕊 Пропустить за {fmt_amt(SKIP_COST)}",
                callback_data=_task_cb("skip", cref),
            ))
        kb.row(gc_btn("🏕 Назад к списку", callback_data="qst:show_subs"))
        kb.adjust(1)

        await _safe_edit_message_text(
            chat_id=message.chat.id,
            message_id=message.message_id,
            text=txt,
            reply_markup=kb.as_markup()
        )
    except Exception as e:
        _qdbg_exc("_show_best_task_for_user fail", e)
        try:
            await _show_next_task(message, user_id)
        except Exception as e2:
            _qdbg_exc("_show_best_task_for_user fallback fail", e2)

# ---------- Show subs list / pagination / show single sub task ----------
@dp.callback_query(lambda c: c.data == "qst:show_subs")
async def qst_show_subs(callback_query: types.CallbackQuery):
    user_id = callback_query.from_user.id
    _qdbg(f"qst_show_subs user={user_id}")
    try:
        queb = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
        tasks = await get_pending_sub_tasks(user_id)
        if not tasks:
            try:
                await callback_query.answer()
            except Exception:
                pass
            await _show_no_tasks_screen(
                chat_id=callback_query.message.chat.id,
                message_id=callback_query.message.message_id,
                queb=D(queb),
            )
            return
        page = 0
        header_text = gc_html_replace_known(
            "<b>📋 Доступные задания с подпиской</b>\n\n"
            "Нажмите на любую кнопку ниже, чтобы открыть задание."
        )
        kb = await _build_sub_list_kb(tasks, page, queb)
        try:
            await callback_query.answer()
        except Exception:
            pass
        await _safe_edit_message_text(chat_id=callback_query.message.chat.id, message_id=callback_query.message.message_id, text=header_text, reply_markup=kb)
    except Exception as e:
        _qdbg_exc("qst_show_subs fail", e)
        try:
            await callback_query.answer("Ошибка. Попробуй позже.", show_alert=True)
        except Exception:
            pass

@dp.callback_query(lambda c: c.data and c.data.startswith("qst:sub_page:"))
async def qst_sub_page(callback_query: types.CallbackQuery):
    user_id = callback_query.from_user.id
    parts = callback_query.data.split(":")
    try:
        page = int(parts[2])
    except Exception:
        page = 0
    _qdbg(f"qst_sub_page user={user_id} requested page={page}")
    try:
        queb = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
        tasks = await get_pending_sub_tasks(user_id)
        if not tasks:
            try:
                await callback_query.answer()
            except Exception:
                pass
            await _show_no_tasks_screen(
                chat_id=callback_query.message.chat.id,
                message_id=callback_query.message.message_id,
                queb=D(queb),
            )
            return
        total = len(tasks)
        max_pages = max(1, math.ceil(total / SUBS_PAGE_SIZE))
        if page < 0:
            page = 0
        if page >= max_pages:
            page = max_pages - 1
        header_text = gc_html_replace_known(
            "<b>📋 Доступные задания с подпиской</b>\n\n"
            "Нажмите на любую кнопку ниже, чтобы открыть задание."
        )
        kb = await _build_sub_list_kb(tasks, page, queb)
        try:
            await callback_query.answer()
        except Exception:
            pass
        await _safe_edit_message_text(chat_id=callback_query.message.chat.id, message_id=callback_query.message.message_id, text=header_text, reply_markup=kb)
    except Exception as e:
        _qdbg_exc("qst_sub_page fail", e)
        try:
            await callback_query.answer("Ошибка.", show_alert=True)
        except Exception:
            pass

@dp.callback_query(lambda c: c.data and c.data.startswith("qst:sub_show:"))
async def qst_sub_show(callback_query: types.CallbackQuery):
    user_id = callback_query.from_user.id
    parts = callback_query.data.split(":", 2)
    raw_enc = parts[2] if len(parts) > 2 else ""
    try:
        raw_decoded = _decode_cb_ref(raw_enc)
        cref_norm = _norm_chat_ref(raw_decoded)
    except Exception:
        cref_norm = _decode_and_norm_ref(raw_enc)

    _qdbg(f"qst_sub_show user={user_id} cref={cref_norm} (patched)")

    try:
        pending = await get_pending_sub_tasks(user_id)
        task = None
        for t in pending:
            try:
                if isinstance(t, dict):
                    cand = _norm_chat_ref(str(t.get("chat_ref") or t.get("target_chat_ref") or ""))
                    if cand and cand == cref_norm:
                        task = t
                        break
                else:
                    if _norm_chat_ref(str(t)) == cref_norm:
                        task = {"chat_ref": str(t)}
                        break
            except Exception:
                continue

        if not task:
            try:
                await callback_query.answer(
                    "Это задание недоступно (возможно, вы уже выполнили/пропустили его).",
                    show_alert=True
                )
            except Exception:
                pass
            return await qst_show_subs(callback_query)

        queb = await _try_db_call(["get_que_balance"], user_id, default=D(0))

        meta = task.get("meta") or {}
        display_ref = meta.get("title") or str(task.get("chat_ref") or cref_norm)
        broken = _is_broken_task(task)

        # ---------- СЛОМАННОЕ ЗАДАНИЕ ----------
        if broken:
            txt = gc_html_replace_known("\n".join([
                "⚠️ <b>Проблема с заданием</b>",
                "",
                f"Мы не можем корректно обработать задание: <b>{html.escape(display_ref)}</b>.",
                "Ничего страшного - ниже есть быстрые шаги, чтобы сообщить об этом администрации.",
            ]))

            broken_kb = types.InlineKeyboardMarkup(inline_keyboard=[
                [gc_btn("⚠️ Ошибка", callback_data="noop")],
                [InlineKeyboardButton(
                    text="Подробно",
                    callback_data=f"qst:broken_details_ref:{_encode_cb_ref(str(task.get('chat_ref') or cref_norm))}",
                )],
                [gc_btn("🔙 Показать обычные задания", callback_data="qst:show_subs_normal")],
                [gc_btn("🔙 Назад", callback_data="qst:show_subs")],
            ])

            replacement_sticker = "CAACAgIAAxkBAnnkmGkkxNhXY0BXJn7aZ8Q6M3Yh5iyhAAIbkwACOm0hSewZ8PtUH6P-NgQ"
            try:
                await callback_query.answer()
            except Exception:
                pass

            try:
                await _safe_edit_message_text(
                    chat_id=callback_query.message.chat.id,
                    message_id=callback_query.message.message_id,
                    text=txt,
                    reply_markup=broken_kb,
                    replacement_sticker=replacement_sticker
                )
            except Exception as e:
                _qdbg_exc("qst_sub_show: failed to show broken UI with sticker", e)
                try:
                    await _safe_edit_message_text(
                        chat_id=callback_query.message.chat.id,
                        message_id=callback_query.message.message_id,
                        text=txt,
                        reply_markup=broken_kb
                    )
                except Exception as e2:
                    _qdbg_exc("qst_sub_show: fallback edit failed", e2)
            return

        # ---------- НОРМАЛЬНОЕ ЗАДАНИЕ ----------
        txt = await _render_sub_task_text(cref_norm, task, 1, 1, queb)
        kb = InlineKeyboardBuilder()

        meta_ref = str(task.get("chat_ref") or task.get("target_chat_ref") or cref_norm)
        try:
            mmeta = meta or await _meta_for_ref(meta_ref)
            url, title_link = await _chat_link_and_title(mmeta)

            if url:
                kb.button(text=f"Подписаться", url=url)
            else:
                kb.button(
                    text=f"Инфо: {display_ref}",
                    callback_data=f"qst:group_info:{meta_ref}"
                )
        except Exception as e:
            _qdbg_exc("qst_sub_show: build open-chat button failed", e)
            kb.button(
                text=f"Инфо: {display_ref}",
                callback_data=f"qst:group_info:{meta_ref}"
            )

        kb.row(gc_btn(
            "✅ Проверить подписку",
            callback_data=_task_cb("check", str(task.get("chat_ref") or cref_norm)),
        ))

        if D(queb) >= SKIP_COST:
            kb.row(gc_btn(
                f"🕊 Пропустить за {fmt_amt(SKIP_COST)}",
                callback_data=_task_cb("skip", str(task.get("chat_ref") or cref_norm)),
            ))

        kb.row(gc_btn("🏕 Назад к списку", callback_data="qst:show_subs"))
        kb.adjust(1)

        try:
            await callback_query.answer()
        except Exception:
            pass

        await _safe_edit_message_text(
            chat_id=callback_query.message.chat.id,
            message_id=callback_query.message.message_id,
            text=txt,
            reply_markup=kb.as_markup()
        )

    except Exception as e:
        _qdbg_exc("qst_sub_show (patched) fail", e)
        try:
            await callback_query.answer("Ошибка.", show_alert=True)
        except Exception:
            pass


@dp.callback_query(lambda c: c.data and c.data.startswith("qst:broken_details_ref:"))
async def qst_broken_details_ref(callback_query: types.CallbackQuery):
    """
    Компактный обработчик: отправляет PM с деталями и в чате - только стикер + кнопки.
    Удаляет исходное сообщение (best-effort).
    """
    try:
        # Сначала снимаем «часики»: ниже несколько запросов подряд, и без
        # раннего ответа нажатие успевает просрочиться.
        try:
            await callback_query.answer()
        except Exception:
            pass

        parts = callback_query.data.split(":", 2)
        raw_enc = parts[2] if len(parts) > 2 else ""
        try:
            cref_decoded = _decode_cb_ref(raw_enc)
            cref_norm = _norm_chat_ref(cref_decoded)
        except Exception:
            try:
                cref_norm = _norm_chat_ref(_decode_cb_ref(raw_enc))
            except Exception:
                cref_norm = raw_enc or ""

        user = callback_query.from_user
        user_id = user.id

        task = None
        try:
            pending = await get_pending_sub_tasks(user_id)
        except Exception as e:
            _qdbg_exc("qst_broken_details_ref: get_pending_sub_tasks failed", e)
            pending = []
        if pending:
            for t in pending:
                try:
                    if isinstance(t, dict):
                        cand = _norm_chat_ref(str(t.get("chat_ref") or t.get("target_chat_ref") or ""))
                        if cand and cand == cref_norm:
                            task = t
                            break
                    else:
                        if _norm_chat_ref(str(t)) == cref_norm:
                            task = {"chat_ref": str(t)}
                            break
                except Exception:
                    continue

        try:
            if task and isinstance(task, dict) and task.get("meta"):
                meta = task.get("meta") or {}
            else:
                meta = await _meta_for_ref(cref_norm)
        except Exception as e:
            _qdbg_exc("qst_broken_details_ref: _meta_for_ref failed", e)
            meta = {"chat_id": cref_norm, "title": cref_norm, "username": None, "bot_missing": False, "error": None}

        chat_ref = str(task.get("chat_ref")) if (task and isinstance(task, dict) and task.get("chat_ref")) else cref_norm
        chat_id = meta.get("chat_id") or chat_ref
        title = meta.get("title") or chat_ref
        username = meta.get("username")
        err_raw = str(meta.get("error") or "").strip()
        created_at = task.get("created_at") if (task and isinstance(task, dict)) else None
        reward = task.get("reward") if (task and isinstance(task, dict)) else None

        def _short(s: str, n: int):
            s = str(s or "").strip()
            return s if len(s) <= n else s[: n - 1].rstrip() + "…"

        err_display = _short(err_raw, 700)
        title_display = _short(title, 120)
        low_err = err_raw.lower() if err_raw else ""
        if any(k in low_err for k in ("forbidden", "kicked", "removed", "bot was kicked", "bot was removed")):
            short_reason = "Бот удалён/заблокирован в этом чате."
        elif err_raw:
            short_reason = "Бот не имеет доступа / ошибка."
        elif not username:
            short_reason = "У чата нет публичного @username."
        else:
            short_reason = "Непредвиденная проблема."

        # Build plain template (keeps spaces, not + encoded)
        lines = []
        lines.append("Здравствуйте! Нашёл(ла) проблему с заданием.")
        lines.append("")
        lines.append(f"🔧 Проблема с заданием: {chat_ref}")
        lines.append(f"• chat_id: {chat_id}")
        lines.append(f"• Название: {title_display}")
        if username:
            lines.append(f"• Username: @{username}")
        if reward is not None:
            try:
                lines.append(f"• Награда: {fmt_amt(reward)} кут")
            except Exception:
                pass
        if created_at:
            lines.append(f"• Создано: {str(created_at)}")
        if err_display:
            lines.append("")
            lines.append("Текст ошибки:")
            lines.append(err_display)
        lines.append("")
        lines.append(f"Коротко: {short_reason}")
        lines.append("")
        lines.append(f"Мой @username/ID: {user_id}")

        sample_template_plain = "\n".join(lines)
        if len(sample_template_plain) > 1200:
            sample_template_plain = sample_template_plain[:1196].rstrip() + "…"

        preview = _short(sample_template_plain, 800)
        pm_lines = [
            "<b>🔧 Подробности по заданию</b>",
            f"<b>Задание:</b> <code>{html.escape(chat_ref)}</code>",
            f"<b>Коротко:</b> {html.escape(short_reason)}",
            "<b>Что сделать:</b> Нажмите на одну из кнопок - текст подставится в сообщение админу."
        ]
        if err_display:
            pm_lines.append("")
            pm_lines.append("<b>Текст ошибки:</b>")
            pm_lines.append(f"<code>{html.escape(err_display)}</code>")
        pm_lines.append("")
        pm_lines.append("<b>📩 Превью сообщения, которое подставится:</b>")
        pm_lines.append(f"<code>{html.escape(preview)}</code>")
        pm_text = gc_html_replace_known("\n".join(pm_lines))
        if len(pm_text) > 3800:
            pm_text = pm_text[:3790].rstrip() + "\n\n… (текст обрезан)"

        admins = ["JerichoCute"]
        try:
            pref = urllib.parse.quote(sample_template_plain, safe="")
        except Exception:
            pref = urllib.parse.quote(str(sample_template_plain or ""), safe="")

        try:
            admin_buttons = []
            for uname in admins:
                url = f"https://t.me/{uname}?text={pref}"
                admin_buttons.append(InlineKeyboardButton(text=f"@{uname}", url=url))
            pm_kb = types.InlineKeyboardMarkup(inline_keyboard=[
                admin_buttons,
                [gc_btn("↩️ Назад", callback_data="qst:show_subs")],
            ])
        except Exception as e:
            _qdbg_exc("qst_broken_details_ref: build pm_kb failed", e)
            pm_kb = None

        pm_sent = False
        try:
            # send PM with details (commented out if you don't want spam) - we send best-effort
            #if pm_kb is not None:
            #    await bot1.send_message(chat_id=user_id, text=pm_text, parse_mode="HTML", disable_web_page_preview=True, reply_markup=pm_kb)
            #else:
            #    await bot1.send_message(chat_id=user_id, text=pm_text, parse_mode="HTML", disable_web_page_preview=True)
            pm_sent = True
            _qdbg("qst_broken_details_ref: full details + keyboard sent via PM")
        except Exception as e:
            _qdbg_exc("qst_broken_details_ref: send_message to user failed", e)
            pm_sent = False

        # Chat UI: delete original message then send sticker + compact keyboard
        try:
            if callback_query.message:
                try:
                    await bot1.delete_message(chat_id=callback_query.message.chat.id, message_id=callback_query.message.message_id)
                    _qdbg("qst_broken_details_ref: original message deleted")
                except Exception as e:
                    _qdbg_exc("qst_broken_details_ref: delete original message failed", e)

            top_row = [gc_btn("☁️ Сообщите об ошибке Админу", callback_data="noop")]
            compact_row = []
            for uname in admins:
                try:
                    url = f"https://t.me/{uname}?text={pref}"
                    compact_row.append(InlineKeyboardButton(text=f"@{uname}", url=url))
                except Exception:
                    compact_row.append(InlineKeyboardButton(text=f"@{uname}", url=f"https://t.me/{uname}"))
            back_row = [gc_btn("↩️ Назад", callback_data="qst:show_subs")]
            compact_kb = types.InlineKeyboardMarkup(inline_keyboard=[top_row, compact_row, back_row])

            replacement_sticker = "CAACAgIAAxkBAnnkmGkkxNhXY0BXJn7aZ8Q6M3Yh5iyhAAIbkwACOm0hSewZ8PtUH6P-NgQ"
            target_chat = callback_query.message.chat.id if callback_query.message else user_id
            try:
                await bot1.send_sticker(chat_id=target_chat, sticker=replacement_sticker, reply_markup=compact_kb)
                _qdbg("qst_broken_details_ref: replacement sticker sent (compact UI)")
            except Exception as e:
                _qdbg_exc("qst_broken_details_ref: send_sticker failed, fallback to text", e)
                try:
                    await bot1.send_message(
                        chat_id=target_chat,
                        text=gc_html_replace_known(
                            "⚠️ Проблема с заданием - используйте кнопки ниже, "
                            "чтобы связаться с админами."
                        ),
                        reply_markup=compact_kb,
                        parse_mode="HTML",
                    )
                except Exception as e2:
                    _qdbg_exc("qst_broken_details_ref: fallback send_message failed", e2)
                    if pm_sent:
                        await callback_query.answer("✅ Подробности отправлены в ЛС.", show_alert=True)
                    else:
                        await callback_query.answer("ℹ️ Подробности доступны - свяжитесь с админами.", show_alert=True)

        except Exception as e:
            _qdbg_exc("qst_broken_details_ref: chat UI update failed", e)
            try:
                if pm_sent:
                    await callback_query.answer("✅ Подробности отправлены в ЛС.", show_alert=True)
                else:
                    await callback_query.answer("ℹ️ Подробности доступны - свяжитесь с админами.", show_alert=True)
            except Exception:
                pass

    except Exception as e:
        _qdbg_exc("qst_broken_details_ref failed (outer)", e)
        try:
            await callback_query.answer("Ошибка при получении подробностей. Попробуйте позже. ⚠️", show_alert=True)
        except Exception:
            pass


@dp.callback_query(lambda c: c.data and c.data.startswith("qst:check:"))
async def qst_sub_check(callback_query: types.CallbackQuery):
    user = callback_query.from_user
    user_id = user.id

    # --------- маленький helper, чтобы не копировать try/except вокруг answer ----------
    async def _safe_answer(text: str = "", alert: bool = False):
        try:
            if text:
                await callback_query.answer(text, show_alert=alert)
            else:
                await callback_query.answer()
        except Exception:
            pass

    # 1) Разбор callback_data → chat_ref
    try:
        raw = callback_query.data.split(":", 2)[2]
    except Exception:
        raw = ""
    decoded = _decode_cb_ref(raw)
    cref = _norm_chat_ref(decoded)
    api_ref = _as_api_ref(cref)

    _qdbg(f"qst_sub_check user={user_id} raw={raw} decoded={decoded} norm={cref} api_ref={api_ref}")

    try:
        # 2) Проверяем, не закрыто ли задание ранее (sub/skip)
        done = await _try_db_call(["is_task_done", "has_done_task"], user_id, cref, default=False)
        if done:
            _qdbg("qst_sub_check: already done -> informing and moving on")
            await _safe_answer("Это задание уже закрыто ✅", alert=True)
            return await _show_next_task(callback_query.message, user_id)

        # 3) Пытаемся аккуратно получить саму задачу до проверки подписки
        task = await _try_db_call(["get_task_by_ref", "fetch_task_by_ref"], cref, default=None)
        if not task:
            _qdbg("qst_sub_check: task row not found in DB")
            await _safe_answer(
                "Это задание больше недоступно.\n"
                "Вероятно, оно было удалено или отключено.",
                alert=True
            )
            # просто возвращаем пользователя к списку/следующему
            return await _show_next_task(callback_query.message, user_id)

        reward = D(task.get("reward") or 0)
        # Доп. защита: если задание в БД помечено как неактивное - даже не проверяем подписку
        is_active = task.get("is_active", 1)
        if str(is_active) in ("0", "False", "false"):
            _qdbg("qst_sub_check: task is inactive in DB")
            await _safe_answer(
                "Это задание больше недоступно.\n"
                "Администратор отключил его.",
                alert=True
            )
            return await _show_next_task(callback_query.message, user_id)

        # 4) Определяем, подписан ли пользователь (membership)
        membership: Optional[bool] = None

        # 4.1. Пробуем общий helper check_user_subscriptions, если он есть
        use_check_fn = globals().get("check_user_subscriptions") is not None
        if use_check_fn:
            try:
                _qdbg(f"qst_sub_check: calling check_user_subscriptions for api_ref={api_ref}")
                subs = await check_user_subscriptions(bot1, user_id, [api_ref])
                _qdbg(f"qst_sub_check: check_user_subscriptions returned: {subs!r}")

                if subs is True:
                    membership = True
                elif subs is False:
                    membership = False
                elif isinstance(subs, dict) and len(subs) == 1:
                    # {chat_id: bool}
                    try:
                        v = list(subs.values())[0]
                        membership = bool(v)
                    except Exception:
                        pass
                elif isinstance(subs, list) and len(subs) == 1 and isinstance(subs[0], dict):
                    # [{'chat_id': ..., 'reason': 'not_member' / 'member', ...}]
                    item = subs[0]
                    reason = str(item.get("reason") or "").lower()
                    status = str(getattr(item.get("status"), "value", item.get("status") or "")).lower()
                    if reason in ("member", "ok") or status in ("member", "administrator", "creator"):
                        membership = True
                    elif reason in ("not_member", "kicked", "left") or status in ("left", "kicked"):
                        membership = False
            except Exception as e:
                _qdbg_exc("qst_sub_check: check_user_subscriptions call failed", e)
                membership = None

        # 4.2. Если после helper'а всё ещё неизвестно - делаем get_chat_member
        if membership is None:
            member_check_possible = True
            try:
                cm = await bot1.get_chat_member(chat_id=api_ref, user_id=user_id)
                status = (getattr(cm, "status", "") or "").lower()
                is_member = status in ("member", "creator", "administrator")
                membership = is_member
                _qdbg(f"qst_sub_check: get_chat_member status={status} -> membership={membership}")
            except Exception as e:
                _qdbg_exc("qst_sub_check: get_chat_member failed", e)
                member_check_possible = False
                membership = None

            if not member_check_possible:
                # Не получилось проверить вообще - честно говорим об этом
                await _safe_answer(
                    "Не удалось автоматически проверить подписку.\n"
                    "Убедитесь, что вы подписались на канал/группу и попробуйте ещё раз.",
                    alert=True
                )
                return

        # 4.3. На этом этапе membership либо True, либо False
        if membership is False:
            _qdbg("qst_sub_check: membership=False -> task NOT completed yet")
            await _safe_answer(
                "🙈 Вы ещё не выполнили задание!",
                alert=True
            )
            return

        if membership is not True:
            # Защитный fallback (какая-то непонятная форма ответа)
            _qdbg("qst_sub_check: membership is not True/False -> ambiguous")
            await _safe_answer(
                "Не удалось автоматически проверить членство.\n"
                "Убедитесь, что вы подписаны и повторите попытку.",
                alert=True
            )
            return

        # 5) Пользователь ДЕЙСТВИТЕЛЬНО подписан - пробуем зачесть награду
        # Сначала - основной «умный» путь с капами и TTL:
        if hasattr(db, "claim_task_reward_once_capped_expiry"):
            ok_code = await _try_db_call(
                ["claim_task_reward_once_capped_expiry"],
                user_id,
                cref,
                reward,
                default=(False, None)
            )

            if isinstance(ok_code, tuple):
                ok, code = ok_code
            else:
                ok = bool(ok_code)
                code = None

            _qdbg(f"qst_sub_check: claim_task_reward_once_capped_expiry -> ok={ok}, code={code}")

            if ok:
                # Успешное зачисление - запоминаем награду и показываем следующее лучшее задание
                if reward > 0:
                    _last_sub_reward[user_id] = reward

                await _show_best_task_for_user(callback_query.message, user_id)
                return

            # --- Обработка кодов, связанных с ограничениями/временем/повторным выполнением ---

            if code == "already":
                # В БД уже есть запись - просто сообщаем и ведём дальше
                await _safe_answer("Вы уже делали это задание ранее.", alert=True)
                return await _show_next_task(callback_query.message, user_id)

            if code == "not_active":
                await _safe_answer(
                    "Это задание больше недоступно.\n"
                    "Администратор отключил его.",
                    alert=True
                )
                return await _show_next_task(callback_query.message, user_id)

            if code == "expired":
                await _safe_answer(
                    "Срок действия этого задания истёк.\n"
                    "Выберите другое задание в списке.",
                    alert=True
                )
                return await _show_next_task(callback_query.message, user_id)

            if code == "cap_total":
                await _safe_answer(
                    "Лимит по количеству выполнений этого задания уже исчерпан.\n"
                    "Попробуйте другое задание.",
                    alert=True
                )
                return await _show_next_task(callback_query.message, user_id)

            # Если вернулся какой-то странный/неизвестный код - пробуем «вылечиться»:
            _qdbg(f"qst_sub_check: unknown code from claim_task_reward_once_capped_expiry: {code!r}")
            # Попробуем запасной путь - старый claim_task_reward_once, если он есть
            if hasattr(db, "claim_task_reward_once"):
                ok_fallback = await _try_db_call(
                    ["claim_task_reward_once"],
                    user_id,
                    cref,
                    reward,
                    default=False
                )
                _qdbg(f"qst_sub_check: fallback claim_task_reward_once -> {ok_fallback}")
                if ok_fallback:
                    if reward > 0:
                        _last_sub_reward[user_id] = reward

                    await _show_best_task_for_user(callback_query.message, user_id)
                    return

            # Если и fallback не помог - честно говорим, но не ломаемся
            await _safe_answer(
                "Не удалось зачислить награду.\n"
                "Вероятно, задание уже исчерпало лимит или было изменено.\n"
                "Попробуйте другое задание.",
                alert=True
            )
            return await _show_next_task(callback_query.message, user_id)

        # 5.2. Если «умного» метода нет - старый путь (без капа/ttl) + максимально мягкая обработка
        ok = await _try_db_call(["claim_task_reward_once"], user_id, cref, reward, default=False)
        _qdbg(f"qst_sub_check: simple claim_task_reward_once -> {ok}")
        if ok:
            if reward > 0:
                _last_sub_reward[user_id] = reward

            await _show_best_task_for_user(callback_query.message, user_id)
            return
        else:
            await _safe_answer(
                "Не удалось зачислить награду.\n"
                "Возможно, вы уже выполняли это задание раньше\n"
                "или оно больше недоступно.",
                alert=True
            )
            return await _show_next_task(callback_query.message, user_id)

    except Exception as e:
        _qdbg_exc("qst_sub_check unexpected", e)
        await _safe_answer("Ошибка при проверке. Попробуй ещё раз чуть позже.", alert=True)


# ---------- Skip handler ----------
@dp.callback_query(lambda c: c.data and c.data.startswith("qst:skip:"))
async def qst_sub_skip(callback_query: types.CallbackQuery):
    user_id = callback_query.from_user.id
    try:
        raw = callback_query.data.split(":", 2)[2]
    except Exception:
        raw = ""
    decoded = _decode_cb_ref(raw)
    cref = _norm_chat_ref(decoded)
    _qdbg(f"qst_sub_skip user={user_id} raw={raw} decoded={decoded} norm={cref}")

    # небольшой helper, чтобы не дублировать try/except
    async def _safe_answer(text: str = "", alert: bool = False):
        try:
            if text:
                await callback_query.answer(text, show_alert=alert)
            else:
                await callback_query.answer()
        except Exception:
            pass

    try:
        # сразу гасим "часики"
        try:
            await callback_query.answer()
        except Exception:
            pass

        # уже закрыто?
        done = await _try_db_call(["is_task_done", "has_done_task"], user_id, cref, default=False)
        if done:
            await _safe_answer("Задание уже закрыто ✅", alert=True)
            # показываем следующий/нет заданий
            if callback_query.message:
                await _show_next_task(callback_query.message, user_id)
            return

        # списываем SKIP_COST
        ok = await _try_db_call(
            ["skip_task_once", "skip_task", "mark_task_skipped"],
            user_id,
            cref,
            SKIP_COST,
            default=False
        )
        if not ok:
            queb = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
            queb = D(queb)
            if floor_int(queb) < floor_int(SKIP_COST):
                await _safe_answer("Недостаточно Virtual balance для пропуска.", alert=True)
            else:
                await _safe_answer("Не удалось пропустить задание (повторите позже).", alert=True)
            return

        # успешно пропущено → обновляем баланс
        queb = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
        queb = D(queb)

        # показываем небольшой тост, что всё ок
        try:
            await callback_query.answer(
                f"🕊 Задание пропущено. Virtual balance: {fmt_amt(queb)} кут.",
                show_alert=False
            )
        except Exception:
            pass

        # Проверяем, остались ли вообще задания
        pending_after = await get_pending_sub_tasks(user_id)
        sub_left = len(pending_after or [])

        # если вообще ничего не осталось (ни нормальных, ни проблемных) -
        # сразу показываем экран "заданий нет"
        if sub_left == 0:
            _qdbg(f"qst_sub_skip: last task skipped for user={user_id} -> no-tasks screen")
            if callback_query.message:
                await _show_no_tasks_screen(
                    chat_id=callback_query.message.chat.id,
                    message_id=callback_query.message.message_id,
                    queb=queb,
                )
            else:
                target = callback_query.from_user.id
                await _show_no_tasks_screen(
                    chat_id=target,
                    message_id=0,
                    queb=queb,
                )
            return

        # если задания ещё есть - СРАЗУ показываем следующий список/задание
        if callback_query.message:
            await _show_next_task(callback_query.message, user_id)
        else:
            # на всякий случай, если message отсутствует (редкий случай, inline и т.п.)
            try:
                await qst_show_subs(callback_query)
            except Exception as e:
                _qdbg_exc("qst_sub_skip: fallback qst_show_subs failed", e)

        return

    except Exception as e:
        _qdbg_exc("qst_sub_skip fail", e)
        await _safe_answer("Ошибка при пропуске.", alert=True)


# ---------- Withdraw ----------
@dp.callback_query(lambda c: c.data and c.data.startswith("qst:withdraw:"))
async def qst_withdraw_callback(callback_query: types.CallbackQuery):
    user_id = callback_query.from_user.id
    parts = callback_query.data.split(":")
    try:
        amount_raw = parts[2]
        amount = int(amount_raw)
    except Exception:
        await callback_query.answer("Неверная сумма.", show_alert=True)
        return

    if amount < 1:
        await callback_query.answer("Сумма должна быть не меньше 1.", show_alert=True)
        return

    _qdbg(f"qst_withdraw_callback: user={user_id} amount={amount}")

    try:
        queb = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
        queb = D(queb)
    except Exception as e:
        _qdbg_exc("qst_withdraw: get_que_balance fail", e)
        queb = D(0)

    if floor_int(queb) < amount:
        await callback_query.answer("Недостаточно Virtual balance для вывода.", show_alert=True)
        return

    await callback_query.answer()

    try:
        ok = await _try_db_call(["transfer_que_to_main", "transfer_queb_to_main", "transfer_que_balance_to_main"], user_id, amount, default=False)
        if ok:
            try:
                new_queb = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
            except Exception:
                new_queb = D(0)
            text = f"⛵️ <b>Вывод выполнен:</b> {amount} кут переведено на основной баланс.\n\n💰 Virtual balance : <b>{fmt_amt(new_queb)}</b> кут"
            try:
                await _safe_edit_message_text(chat_id=callback_query.message.chat.id, message_id=callback_query.message.message_id, text=text, reply_markup=await _build_after_take_kb(None), replacement_sticker=WITHDRAW_STICKER)
            except Exception as e:
                _qdbg_exc("qst_withdraw: update UI after atomic transfer failed", e)
            return
    except Exception as e:
        _qdbg_exc("qst_withdraw: atomic transfer attempt raised", e)

    deducted = False
    added = False
    try:
        deducted = await _try_db_call(["deduct_que_balance", "subtract_que_balance", "decrement_que_balance"], user_id, amount, default=False)
        if not deducted:
            _qdbg("qst_withdraw: deduct_que_balance returned falsy -> abort")
            await callback_query.answer("Не удалось списать Virtual balance (повторите позже).", show_alert=True)
            return

        # ВАЖНО: update_user_balance(uid, N) без знака - это SET (заменить баланс на N), а не ADD.
        # Раньше здесь был общий _try_db_call с "update_user_balance" в списке имён - если
        # add_user_balance/add_or_update_balance/credit_user_balance отсутствуют, срабатывал
        # fallback на update_user_balance(user_id, amount), который ЗАТИРАЛ основной баланс
        # суммой вывода вместо начисления к нему. Явно используем delta-режим ("+N").
        added = await _try_db_call(["add_user_balance", "add_or_update_balance", "credit_user_balance"], user_id, amount, default=None)
        if added is None:
            added = await db.update_user_balance(user_id, f"+{int(amount)}")
        added = bool(added is not None and added is not False)
        if not added:
            _qdbg("qst_withdraw: add to main balance failed -> trying to rollback virtual")
            try:
                await _try_db_call(["add_que_balance", "credit_que_balance"], user_id, amount, default=None)
            except Exception as e_rb:
                _qdbg_exc("qst_withdraw: rollback add_que_balance failed", e_rb)
            await callback_query.answer("Не удалось зачислить на основной баланс. Сумма возвращена в Virtual balance.", show_alert=True)
            return

        try:
            new_queb = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
        except Exception:
            new_queb = D(0)

        text = f"⛵️ <b>Вывод выполнен:</b> {amount} кут переведено на основной баланс.\n\n💰 Virtual balance : <b>{fmt_amt(new_queb)}</b> кут"
        try:
            await _safe_edit_message_text(chat_id=callback_query.message.chat.id, message_id=callback_query.message.message_id, text=text, reply_markup=await _build_after_take_kb(None), replacement_sticker=WITHDRAW_STICKER)
        except Exception as e_ui:
            _qdbg_exc("qst_withdraw: update UI after fallback transfer failed", e_ui)
        return

    except Exception as e:
        _qdbg_exc("qst_withdraw: fallback path exception", e)
        if deducted and not added:
            try:
                await _try_db_call(["add_que_balance", "credit_que_balance"], user_id, amount, default=None)
                _qdbg("qst_withdraw: rollback succeeded after exception")
            except Exception as e_rb2:
                _qdbg_exc("qst_withdraw: rollback failed after exception", e_rb2)
        await callback_query.answer("Ошибка при выводе. Попробуйте позже.", show_alert=True)
        return






































































