def _gc_task_cb_start(template_id: int) -> str:
    """Callback-данные для старта игрового задания (ТОЛЬКО GC)."""
    return f"qst:gcstart:{int(template_id)}"


async def _gc_safe_answer(callback_query: types.CallbackQuery, text: str = "", alert: bool = False) -> None:
    """Безопасный callback.answer с глушением ошибок.

    alert=False по умолчанию: полноэкранный alert только для реальных ошибок.
    """
    try:
        if text:
            await callback_query.answer(text, show_alert=alert)
        else:
            await callback_query.answer()
    except Exception:
        pass


def _gc_norm_id(x: Union[int, str]) -> Union[int, str]:
    """Нормализуем id/username для сравнения чатов."""
    try:
        return int(x)
    except Exception:
        return str(x).strip()
async def gc_get_active_assignment(user_id: int) -> Optional[Dict[str, Any]]:
    """
    Возвращает ТОЛЬКО реально активное игровое задание пользователя.

    Активное = status == 'active' (или пустой).
    Любые finish / failed / cancelled / deactive → считаем, что задания нет.
    """
    try:
        assignment = await _try_db_call(
            ["get_active_gc_assignment"],
            user_id,
            default=None,
        )
        _qdbg(f"[GC] gc_get_active_assignment: raw assignment={assignment!r}")

        if not isinstance(assignment, dict):
            return None

        status = str(assignment.get("status") or "").strip().lower()
        if status not in ("active", ""):
            _qdbg(
                f"[GC] gc_get_active_assignment: user={user_id}, "
                f"status={status!r} -> НЕ активное"
            )
            return None

        return assignment

    except Exception as e:
        _qdbg_exc("[GC] gc_get_active_assignment fail", e)
        return None

# -------------------------------------------------------------------------------------------------
#                                     ЗАГРУЗКА ШАБЛОНОВ GC
# -------------------------------------------------------------------------------------------------

# -------------------------------------------------------------------------------------------------
#          ПРАВА БОТА В ГРУППЕ ЗАДАНИЯ (admin check + cache)
# -------------------------------------------------------------------------------------------------
# Задание привязано к группе → бот обязан быть администратором, иначе игры
# не запустятся. Новичкам (онбординг) такие задания скрываем полностью.
# Во вкладке «Челленджи» показываем как «Неисправно».

_GC_BOT_VENUE_CACHE: Dict[str, Tuple[float, bool, str]] = {}
_GC_BOT_VENUE_TTL = 120.0
_GC_BOT_ID_CACHE: Optional[int] = None


def gc_clear_bot_venue_cache() -> None:
    _GC_BOT_VENUE_CACHE.clear()


async def _gc_bot_id() -> Optional[int]:
    global _GC_BOT_ID_CACHE
    if _GC_BOT_ID_CACHE:
        return _GC_BOT_ID_CACHE
    try:
        me = await bot1.get_me()
        _GC_BOT_ID_CACHE = int(me.id)
        return _GC_BOT_ID_CACHE
    except Exception as e:
        _qdbg_exc("[GC] _gc_bot_id: get_me fail", e)
        try:
            return int(getattr(bot1, "id", 0) or 0) or None
        except Exception:
            return None


def _gc_venue_cache_key(
    chat_id: Optional[int], chat_ref: Optional[str],
) -> str:
    if chat_id:
        try:
            return f"id:{int(chat_id)}"
        except Exception:
            pass
    ref = str(chat_ref or "").strip().lower()
    return f"ref:{ref}" if ref else "none"


def _gc_api_ref(
    chat_id: Optional[int], chat_ref: Optional[str],
) -> Optional[Union[int, str]]:
    if chat_id:
        try:
            return int(chat_id)
        except Exception:
            pass
    ref = str(chat_ref or "").strip()
    if not ref:
        return None
    if ref.lstrip("-").isdigit():
        try:
            return int(ref)
        except Exception:
            return ref
    return ref if ref.startswith("@") else f"@{ref}"


async def gc_bot_can_serve_venue(
    chat_id: Optional[int] = None,
    chat_ref: Optional[str] = None,
) -> Tuple[bool, str]:
    """Может ли бот проводить игры в целевой группе задания.

    Returns: (ok, reason)
      ok=True  - unrestricted / administrator / creator
      ok=False - нет бота, не админ, чат недоступен, ошибка проверки
    """
    api_ref = _gc_api_ref(chat_id, chat_ref)
    if api_ref is None:
        # Нет жёсткой привязки к группе - можно играть в клубе.
        return True, "unrestricted"

    key = _gc_venue_cache_key(chat_id, chat_ref)
    now = time.monotonic()
    cached = _GC_BOT_VENUE_CACHE.get(key)
    if cached and (now - cached[0]) < _GC_BOT_VENUE_TTL:
        return cached[1], cached[2]

    bot_id = await _gc_bot_id()
    if not bot_id:
        result = (False, "bot_id_unknown")
        _GC_BOT_VENUE_CACHE[key] = (now, result[0], result[1])
        return result

    try:
        member = await asyncio.wait_for(
            bot1.get_chat_member(api_ref, bot_id),
            timeout=5.0,
        )
        status = str(getattr(member, "status", "") or "").lower()
        if status in ("administrator", "creator"):
            result = (True, "admin")
        elif status in ("member", "restricted"):
            result = (False, "not_admin")
        elif status in ("left", "kicked"):
            result = (False, "missing")
        else:
            result = (False, f"status:{status or 'unknown'}")
    except Exception as e:
        err = str(e).lower()
        if any(
            x in err
            for x in (
                "forbidden",
                "kicked",
                "chat not found",
                "chat_not_found",
                "bot is not a member",
                "have no rights",
                "not enough rights",
            )
        ):
            result = (False, "unreachable")
            # Штатная ситуация (удалённый/неверный чат задания) —
            # без traceback, чтобы не пугать при «Открыть бонус» / списке заданий.
            _qdbg(f"[GC] venue unreachable ref={api_ref!r}: {e}")
        else:
            # На сомнении не отдаём новичкам - считаем неисправным.
            result = (False, f"error:{type(e).__name__}")
            _qdbg_exc(f"[GC] gc_bot_can_serve_venue fail ref={api_ref!r}", e)

    _GC_BOT_VENUE_CACHE[key] = (now, result[0], result[1])
    _qdbg(
        f"[GC] venue check ref={api_ref!r} -> ok={result[0]} reason={result[1]}"
    )
    return result


async def gc_bot_can_serve_template(tpl: Dict[str, Any]) -> Tuple[bool, str]:
    """Проверка шаблона челленджа по target_chat_*."""
    if not isinstance(tpl, dict):
        return False, "bad_template"
    raw_id = tpl.get("target_chat_id")
    chat_id: Optional[int] = None
    if raw_id not in (None, "", 0, "0"):
        try:
            chat_id = int(raw_id)
        except Exception:
            chat_id = None
    chat_ref = tpl.get("target_chat_ref") or tpl.get("chat_ref")
    return await gc_bot_can_serve_venue(chat_id, chat_ref)


async def gc_mark_templates_venue_status(
    templates: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """Помечает шаблоны: bot_venue_ok / bot_venue_broken / bot_venue_reason."""
    rows = [dict(t) for t in (templates or []) if isinstance(t, dict)]
    if not rows:
        return []

    venues: Dict[str, Tuple[Optional[int], Optional[str]]] = {}
    for t in rows:
        raw_id = t.get("target_chat_id")
        chat_id: Optional[int] = None
        if raw_id not in (None, "", 0, "0"):
            try:
                chat_id = int(raw_id)
            except Exception:
                chat_id = None
        chat_ref = t.get("target_chat_ref") or t.get("chat_ref")
        key = _gc_venue_cache_key(chat_id, chat_ref)
        venues[key] = (chat_id, chat_ref)

    async def _one(key: str, pair: Tuple[Optional[int], Optional[str]]):
        ok, reason = await gc_bot_can_serve_venue(pair[0], pair[1])
        return key, ok, reason

    checked = await asyncio.gather(
        *[_one(k, v) for k, v in venues.items()],
        return_exceptions=True,
    )
    by_key: Dict[str, Tuple[bool, str]] = {}
    for item in checked:
        if isinstance(item, Exception):
            _qdbg_exc("[GC] gc_mark_templates_venue_status gather item fail", item)
            continue
        key, ok, reason = item
        by_key[key] = (ok, reason)

    out: List[Dict[str, Any]] = []
    for t in rows:
        raw_id = t.get("target_chat_id")
        chat_id = None
        if raw_id not in (None, "", 0, "0"):
            try:
                chat_id = int(raw_id)
            except Exception:
                chat_id = None
        chat_ref = t.get("target_chat_ref") or t.get("chat_ref")
        key = _gc_venue_cache_key(chat_id, chat_ref)
        ok, reason = by_key.get(key, (True, "unrestricted"))
        t["bot_venue_ok"] = bool(ok)
        t["bot_venue_broken"] = not bool(ok)
        t["bot_venue_reason"] = reason
        out.append(t)
    return out


async def gc_load_templates_for_user(user_id: int) -> List[Dict[str, Any]]:
    """
    GC-список доступных шаблонов.

    Фильтруем:
      - доверяем active_only=True в list_gc_templates;
      - если max_users исчерпан - не показываем;
      - если у пользователя уже есть активный assignment по ЭТОМУ шаблону - не предлагаем;
      - если пользователь уже завершил/провалил ЭТОТ шаблон (finish/failed) -
        больше не показываем этот шаблон.
    """
    try:
        rows = await _try_db_call(
            ["list_gc_templates"],
            active_only=True,
            limit=50,
            default=[]
        )
    except Exception as e:
        _qdbg_exc("gc_load_templates_for_user: list_gc_templates fail", e)
        return []

    if not isinstance(rows, list):
        _qdbg(f"gc_load_templates_for_user: rows is not list -> {type(rows)}")
        rows = []

    _qdbg_list("GC raw templates from DB", rows, max_items=10)

    # реально активное задание (status == active)
    try:
        existing = await gc_get_active_assignment(user_id)
        existing_template_id = int(existing["template_id"]) if existing and existing.get("template_id") else None
    except Exception as e:
        _qdbg_exc("gc_load_templates_for_user: get_active_gc_assignment fail", e)
        existing_template_id = None

    if existing_template_id is not None:
        _qdbg(f"gc_load_templates_for_user: user {user_id} has active template_id={existing_template_id}")

    templates: List[Dict[str, Any]] = []

    for r in rows or []:
        try:
            if not isinstance(r, dict):
                _qdbg(f"gc_load_templates_for_user: skip non-dict row: {r}")
                continue

            # ID шаблона
            try:
                tid = int(r.get("id") or r.get("template_id") or 0)
            except Exception:
                _qdbg(f"gc_load_templates_for_user: skip row (bad id): {r}")
                continue

            if tid <= 0:
                _qdbg(f"gc_load_templates_for_user: skip row (tid <= 0): {r}")
                continue

            # не показываем шаблон, по которому уже есть АКТИВНОЕ задание
            if existing_template_id is not None and tid == existing_template_id:
                _qdbg(f"gc_load_templates_for_user: skip tid={tid} (already active for user)")
                continue

            # не показываем шаблон, который пользователь уже завершил/провалил
            already_done = False
            try:
                already_done = await _try_db_call(
                    ["has_user_gc_finished_template"],
                    user_id,
                    tid,
                    default=False,
                )
            except Exception as e:
                _qdbg_exc(
                    f"gc_load_templates_for_user: has_user_gc_finished_template fail for tid={tid}",
                    e,
                )

            if already_done:
                _qdbg(
                    f"gc_load_templates_for_user: skip tid={tid} "
                    f"(user {user_id} already finished/failed this template)"
                )
                continue

            # кап по пользователям
            max_users = r.get("max_users")
            completed_raw = r.get("completed_users") or 0
            try:
                completed = int(completed_raw)
            except Exception:
                completed = 0

            if max_users is not None:
                try:
                    max_users_int = int(max_users)
                except Exception:
                    _qdbg(
                        f"gc_load_templates_for_user: bad max_users for tid={tid}, "
                        f"value={max_users!r} (ignore cap)"
                    )
                    max_users_int = None

                if max_users_int is not None:
                    if max_users_int <= 0:
                        _qdbg(
                            f"gc_load_templates_for_user: skip tid={tid} "
                            f"(max_users={max_users_int} => no slots)"
                        )
                        continue
                    if completed >= max_users_int:
                        _qdbg(
                            f"gc_load_templates_for_user: skip tid={tid} "
                            f"(slots exhausted: {completed}/{max_users_int})"
                        )
                        continue

            # статус шаблона
            status = str(r.get("status") or "").strip().lower()
            if status and status not in ("active",):
                _qdbg(f"gc_load_templates_for_user: skip tid={tid} by status={status!r}")
                continue

            templates.append(dict(r))

        except Exception as e:
            _qdbg_exc("gc_load_templates_for_user: skip row on exception", e)
            continue

    # сортировка: по награде (DESC), затем по id
    def _sort_key(t: Dict[str, Any]):
        rw = t.get("reward_amount") or 0
        try:
            rwf = float(rw)
        except Exception:
            try:
                rwf = float(str(rw))
            except Exception:
                rwf = 0.0
        try:
            tid_v = int(t.get("id") or t.get("template_id") or 0)
        except Exception:
            tid_v = 0
        return (-rwf, tid_v)

    templates.sort(key=_sort_key)
    _qdbg_list("GC templates for user (sorted)", templates, max_items=10)
    return templates


