async def gc_render_empty_text(queb: Decimal) -> str:
    """
    Текст, когда НЕТ именно игровых челленджей.
    Не связан с текстом пустых подписочных заданий.
    """
    try:
        queb = D(queb)
    except Exception:
        queb = D(0)

    return gc_html_replace_known(
        "<b>🏜 Игровых челленджей сейчас нет.</b>\n\n"
        "Эти куты ты уже можешь вывести через кнопку вывода.\n\n"
        "Загляни позже или вернись в главное меню."
    )


async def gc_empty_kb(user_id: int, queb: Decimal) -> types.InlineKeyboardMarkup:
    """
    Клавиатура, когда НЕТ игровых челленджей.
    Отдельная клавиатура, но:
      - автоматически проверяет, есть ли у пользователя РЕАЛЬНО активное GC-задание;
      - если есть - добавляет кнопку «🎯 Моё задание».
    """
    rows: List[List[InlineKeyboardButton]] = []

    try:
        queb = D(queb)
    except Exception:
        queb = D(0)

    can_int = floor_int(queb)  # пока просто прогрев, пригодится, если добавишь кнопку вывода

    rows.append([gc_btn("Челленджей больше нет…", callback_data="noop_gc_empty")])

    has_active = False
    try:
        existing = await gc_get_active_assignment(user_id)
        has_active = bool(existing)
        _qdbg(f"gc_empty_kb: user={user_id}, has_active={has_active}")
    except Exception as e:
        _qdbg_exc("gc_empty_kb: get_active_gc_assignment fail", e)

    if has_active:
        rows.append([gc_btn("🎯 Моё задание", callback_data="qst:gc_my")])

    rows.append([gc_btn("🔙 Назад в меню", callback_data="qst:menu_back")])

    return types.InlineKeyboardMarkup(inline_keyboard=rows)


@dp.callback_query(lambda c: c.data == "noop_gc_empty")
async def gc_noop_empty(callback_query: types.CallbackQuery):
    """Инфо-кнопка ТОЛЬКО для GC пустого экрана."""
    await _gc_safe_answer(
        callback_query,
        "Игровых челленджей сейчас нет.\n"
        "Подожди немного или вернись в меню.",
        alert=True
    )


