async def gc_render_task_text(
    user_id: int,
    meta: Dict[str, Any],
    idx: int,
    total: int,
    queb: Decimal
) -> str:
    """
    Красивое описание ИГРОВОГО задания (по шаблону).
    Здесь пользователь ещё НЕ взял задание, показываем условия.
    """
    try:
        bar = _progress_bar(idx, total) if total > 0 else "──────────"

        tid_i = int(meta.get("id") or meta.get("template_id") or 0)
        start_i = int(meta.get("start_amount") or 0)
        target_i = int(meta.get("target_amount") or 0)
        reward_i = int(meta.get("reward_amount") or 0)
        max_users = meta.get("max_users")
        completed = int(meta.get("completed_users") or 0)
        created_pretty = meta.get("created_pretty") or "-"
        target_chat_ref = meta.get("target_chat_ref") or "-"
        betlimit = meta.get("betlimit")

        try:
            queb = D(queb)
        except Exception:
            queb = D(0)
        queb_s = fmt_amt(queb)

        cap_line = ""
        if max_users is not None:
            try:
                cap_line = f"\n• Слоты: <b>{completed}/{int(max_users)}</b>"
            except Exception:
                pass

        betlimit_line = "• Ограничение ставки: <b>нет, можно ставить любую сумму</b>"
        if betlimit:
            try:
                bl = int(betlimit)
                if bl > 0:
                    betlimit_line = f"• Ограничение ставки: <b>{_fmt_dot(bl)}</b> кут за одну игру"
            except Exception:
                pass

        lines = [
            f"<b>🦋 Игровой челлендж #{idx}/{total}</b>",
            bar,
            "",
            "📋 <b>Условия челленджа:</b>",
            f"• Стартовый виртуальный баланс: <b>{_fmt_dot(start_i)}</b> кут",
            f"• Цель по виртуальному балансу: <b>{_fmt_dot(target_i)}</b> кут",
            f"• Награда за выполнение: <b>{_fmt_dot(reward_i)}</b> кут",
            betlimit_line + cap_line,
            "",
            "📍 <b>Где играть:</b>",
            f"• Чат / канал: <code>{html.escape(str(target_chat_ref))}</code>",
            "",
            "💰 <b>Баланс наград за задания (выводимый):</b>",
            f"• Сейчас: <b>{queb_s}</b> кут",
            "",
            f"🧾 Шаблон: <b>ID {tid_i}</b>",
            f"📅 Создано: <b>{html.escape(created_pretty)}</b>",
            "",
            "Нажмите «🎮 Взять это задание», чтобы получить стартовый виртуальный баланс "
            "и начать путь к цели."
        ]
        return gc_html_replace_known("\n".join(lines))
    except Exception as e:
        _qdbg_exc("gc_render_task_text fail", e)
        return "<b>Игровое задание</b>\n\nОписание временно недоступно."


async def gc_render_my_assignment_text(
    user_id: int,
    assignment: Dict[str, Any],
) -> str:
    """
    Экран «Моё задание» для ИГРОВОГО челленджа.

    Показываем только информацию про само задание:
      - стартовый и текущий виртуальный баланс;
      - цель и сколько осталось;
      - прогресс в процентах;
      - награду;
      - ограничение на ставку (если есть);
      - дату выдачи;
      - группу для игры (если есть).

    НИКАКОГО quebalance здесь нет.
    """
    try:
        _qdbg(f"[GC] gc_render_my_assignment_text: user_id={user_id}, assignment={assignment!r}")

        assign_id = int(assignment.get("id") or 0)
        tpl_id = int(assignment.get("template_id") or 0)

        # виртуальный баланс челленджа
        two_balance = int(
            assignment.get("two_balance")
            or assignment.get("two_balance_initial")
            or 0
        )
        two_init = int(
            assignment.get("two_balance_initial")
            or two_balance
        )

        target_amount = int(assignment.get("target_amount") or 0)
        reward_amount = int(assignment.get("reward_amount") or 0)
        betlimit = assignment.get("betlimit")
        created_pretty = assignment.get("created_pretty") or "-"

        remaining = max(0, target_amount - two_balance) if target_amount > 0 else None

        if target_amount > 0:
            try:
                progress_pct = max(
                    0,
                    min(999, int(round((two_balance / target_amount) * 100)))
                )
            except Exception as e:
                _qdbg_exc(
                    "[GC] gc_render_my_assignment_text: ошибка расчёта процента прогресса",
                    e,
                )
                progress_pct = 0
        else:
            progress_pct = None

        # уже нормализованный username, если он есть
        target_chat_username = assignment.get("target_chat_username")

        lines: List[str] = []

        # шапка
        lines.append("🎮 <b>Твой активный игровой челлендж</b>")
        lines.append(f"ID задания: <b>{assign_id}</b> | Шаблон: <b>{tpl_id}</b>")
        lines.append("")

        # баланс
        lines.append(f"💼 Баланс челленджа: <b>{_fmt_dot(two_balance)}</b> кут")
        lines.append(f"   (старт: {_fmt_dot(two_init)} кут)")
        lines.append("")

        # цель + сколько осталось
        if target_amount > 0:
            lines.append(f"🎯 Цель: <b>{_fmt_dot(target_amount)}</b> кут")
            if remaining is not None:
                lines.append(f"🔥 Осталось до цели: <b>{_fmt_dot(remaining)}</b> кут")
            if progress_pct is not None:
                lines.append(f"📊 Прогресс: <b>{progress_pct}%</b>")
        else:
            lines.append("🎯 Цель по балансу не указана.")
        lines.append("")

        # награда
        lines.append(f"🏆 Награда за выполнение: <b>{_fmt_dot(reward_amount)}</b> кут")

        # лимит ставки - только если есть
        if betlimit:
            lines.append(f"🎲 Макс. ставка: <b>{_fmt_dot(betlimit)}</b> кут за игру")

        # группа - только если есть username
        if target_chat_username:
            lines.append("")
            lines.append(f"📍 Играть нужно в: <b>@{html.escape(str(target_chat_username))}</b>")

        lines.append("")
        lines.append(f"📅 Задание выдано: <b>{html.escape(str(created_pretty))}</b>")
        lines.append("")
        lines.append(
            "Играй в игры бота - каждая ставка меняет этот баланс и приближает тебя к цели."
        )

        text = gc_html_replace_known("\n".join(lines))
        _qdbg(f"[GC] gc_render_my_assignment_text: итоговый текст:\n{text}")
        return text

    except Exception as e:
        _qdbg_exc("[GC] gc_render_my_assignment_text: общая ошибка", e)
        return "<b>Ваш челлендж</b>\n\nОписание временно недоступно."

async def gc_build_my_assignment_kb(
    assignment: Dict[str, Any],
) -> types.InlineKeyboardMarkup:
    """
    Инлайн-клавиатура под экраном «Моё задание» в пляжном вайбе Лилу & Стича.

    Теперь:
      - кнопка типа задания (бесплатное / обычное) с пояснением через alert;
      - кнопка перехода в группу (если есть);
      - короткий прогресс (осталось / цель);
      - награда;
      - лимит ставки (если есть);
      - кнопка «Прервать челлендж» с подтверждением;
      - кнопка вернуться к списку.
    """
    try:
        _qdbg(f"[GC] gc_build_my_assignment_kb: assignment={assignment!r}")

        # ---- базовые числа по заданию ----
        try:
            target_amount = int(assignment.get("target_amount") or 0)
        except Exception:
            target_amount = 0

        try:
            two_balance = int(
                assignment.get("two_balance")
                or assignment.get("two_balance_initial")
                or 0
            )
        except Exception:
            two_balance = 0

        try:
            reward_amount = int(assignment.get("reward_amount") or 0)
        except Exception:
            reward_amount = 0

        betlimit = assignment.get("betlimit")

        remaining = max(0, target_amount - two_balance) if target_amount > 0 else None

        # ---- Определяем free-флаг через БД по template_id ----
        free_flag = "-"  # дефолт - обычное задание
        tpl_id = assignment.get("template_id")

        try:
            if tpl_id is not None:
                # нормализуем к int, если там строка
                try:
                    tpl_id_int = int(tpl_id)
                except Exception:
                    tpl_id_int = None

                if tpl_id_int is not None:
                    # основное: читаем из z_game_challenge_templates.free
                    free_flag = await db.get_gc_template_free_flag(tpl_id_int)
        except Exception as e:
            _qdbg_exc(
                "[GC] gc_build_my_assignment_kb: get_gc_template_free_flag fail",
                e,
            )
            # запасной план - смотри, что прилетело в assignment["free"]
            raw_local = (assignment.get("free") or "-").strip()
            free_flag = raw_local or "-"

        # нормализуем флаг: только '+' считается бесплатным, всё остальное - '-'
        if free_flag != "+":
            free_flag = "-"

        is_free = (free_flag == "+")
        type_label = "🍻 Бесплатное задание" if is_free else "💰 Обычное задание"
        # в callback передаём именно '+' или '-'
        type_cb = f"qst:gc_free_info:{free_flag}"

        rows: List[List[InlineKeyboardButton]] = []

        # ── Кнопка типа задания (самая верхняя) ─────────────────────────────
        rows.append([gc_btn(type_label, callback_data=type_cb)])

        # ── Кнопка «играть в чат» ───────────────────────────────────────────
        target_chat_username = assignment.get("target_chat_username")
        if target_chat_username:
            username_clean = str(target_chat_username).lstrip("@").strip()
            if username_clean:
                url = f"https://t.me/{username_clean}"
                label = f"🦋 Играть в @{username_clean}"
                _qdbg(
                    "[GC] gc_build_my_assignment_kb: добавляем кнопку группы -> "
                    f"text={label!r}, url={url!r}"
                )
                rows.append([gc_btn(label, url=url)])

        # ── Прогресс до цели (формат «осталось / цель») ─────────────────────
        if target_amount > 0 and remaining is not None:
            # формат «💦 Осталось: 9 / 10 кут»
            rows.append([
                gc_btn(
                    f"💦 Осталось: {_fmt_dot(remaining)} / {_fmt_dot(target_amount)} кут",
                    callback_data="noop",
                )
            ])

        # ── Награда ──────────────────────────────────────────────────────────
        rows.append([
            gc_btn(
                f"💎 Награда: {_fmt_dot(reward_amount)} кут",
                callback_data="noop",
            )
        ])

        # ── Лимит ставки ────────────────────────────────────────────────────
        if betlimit:
            try:
                betlimit_i = int(betlimit)
                if betlimit_i > 0:
                    rows.append([
                        gc_btn(
                            f"🐬 Макс. ставка: {_fmt_dot(betlimit_i)} кут",
                            callback_data="noop",
                        )
                    ])
            except Exception as e:
                _qdbg_exc(
                    "[GC] gc_build_my_assignment_kb: ошибка обработки betlimit",
                    e,
                )

        # ── Кнопка прерывания челленджа ─────────────────────────────────────
        # Отсюда уходим в подтверждение, а не сразу в удаление
        rows.append([
            gc_btn("🥀 Прервать челлендж", callback_data="qst:gc_abort_confirm")
        ])

        # ── Навигация (челленджи и обратно в меню) ──────────────────────────
        rows.append([
            gc_btn("🏕 Открыть список челленджей", callback_data="qst:show_gc")
        ])
        rows.append([
            gc_btn("🏝 В главное меню", callback_data="qst:menu_back")
        ])

        kb = types.InlineKeyboardMarkup(inline_keyboard=rows)
        _qdbg(
            "[GC] gc_build_my_assignment_kb: клавиатура сформирована: "
            f"{kb.inline_keyboard!r}"
        )
        return kb

    except Exception as e:
        _qdbg_exc("[GC] gc_build_my_assignment_kb fail", e)
        rows = [
            [gc_btn("🏕 Открыть список челленджей", callback_data="qst:show_gc")],
            [gc_btn("🏝 В главное меню", callback_data="qst:menu_back")],
        ]
        return types.InlineKeyboardMarkup(inline_keyboard=rows)

@dp.callback_query(lambda c: c.data.startswith("qst:gc_free_info:"))
async def gc_free_info_callback(callback_query: types.CallbackQuery):
    """
    Показывает краткое описание типа игрового задания.
    Укладывается в < 200 символов.
    """
    try:
        data = callback_query.data or ""
        parts = data.split(":")
        flag = parts[-1] if len(parts) >= 3 else None
        is_free = (flag == "+")

        if is_free:
            text = (
                "🍻 Бесплатное задание.\n"
                "Вы играете в одиночные игры на виртуальный баланс, не расходуя свои куты. "
                "Выполните цель и получите заслуженную награду, без вложений"
            )
        else:
            text = (
                "💰 Обычное задание.\n"
                "Ставки списываются с вашего основного и виртуального баланса челленджа. "
                "Достигните цели и получите дополнительную награду."
            )

        await callback_query.answer(text, show_alert=True)

    except Exception as e:
        _qdbg_exc("gc_free_info_callback fail", e)
        await callback_query.answer(
            "К сожалению, не удалось показать описание задания. Попробуйте позже.",
            show_alert=True,
        )


async def gc_build_after_take_kb(target_chat_ref: Optional[str]) -> types.InlineKeyboardMarkup:
    """
    Клавиатура ПОСЛЕ взятия игрового задания.
    Отдельная GC-версия, не используется системой подписок.
    """
    rows: List[List[InlineKeyboardButton]] = []

    if target_chat_ref:
        s = str(target_chat_ref).strip()
        if s.startswith("@"):
            uname = s[1:]
            url = f"https://t.me/{uname}"
            rows.append([InlineKeyboardButton(text=f"Перейти в {s}", url=url)])
        else:
            rows.append([
                InlineKeyboardButton(
                    text=f"Инфо: {s}",
                    callback_data=f"qst:group_info:{s}"
                )
            ])

    rows.append([gc_btn("🎯 Моё задание", callback_data="qst:gc_my")])
    rows.append([gc_btn("🏕 К списку челленджей", callback_data="qst:show_gc")])
    return types.InlineKeyboardMarkup(inline_keyboard=rows)


# -------------------------------------------------------------------------------------------------
#                          СПИСОК ЧЕЛЛЕНДЖЕЙ (СТРАНИЦЫ: СПИСОК ЗАДАНИЙ)
# -------------------------------------------------------------------------------------------------

async def gc_build_list_kb(
    templates: List[Dict[str, Any]],
    page: int,
    queb: Decimal,
    *,
    has_active: bool,
) -> types.InlineKeyboardMarkup:
    """
    Строит список игровых челленджей с пагинацией.
    Не использует код подписок.

    Формат строки челленджа:
      поднять с A → B кут [+reward] | мин betlimit

    Если слоты заняты - помечаем соответствующим префиксом и делаем кнопку неактивной.
    Если бот не админ в группе задания - «⚠️ Неисправно» (в конце списка).
    """
    # Проверяем права бота в целевых группах и сортируем:
    # рабочие сначала, неисправные внизу.
    try:
        templates = await gc_mark_templates_venue_status(list(templates or []))
    except Exception as e:
        _qdbg_exc("[GC] gc_build_list_kb: venue mark fail", e)
        templates = list(templates or [])

    def _tpl_sort_key(t: Dict[str, Any]):
        """
        Порядок в списке для игрока:
          1) рабочие / со слотами
          2) бесплатные (+) раньше платных
          3) самые большие награды
          4) прибыльность относительно пути (награда / путь)
          5) более простые (короткий путь, меньший старт)
        """
        broken = 1 if t.get("bot_venue_broken") else 0

        free_val = (t.get("free") or "-").strip()
        is_paid = 0 if free_val == "+" else 1

        try:
            start_amt = float(t.get("start_amount") or 0)
        except Exception:
            start_amt = 0.0
        try:
            target_amt = float(t.get("target_amount") or 0)
        except Exception:
            target_amt = 0.0
        try:
            reward = float(t.get("reward_amount") or 0)
        except Exception:
            reward = 0.0

        gap = target_amt - start_amt
        if gap <= 0:
            gap = 1.0
        profit_ratio = reward / gap

        full_slots = 0
        max_users = t.get("max_users")
        if max_users is not None:
            try:
                if int(t.get("completed_users") or 0) >= int(max_users):
                    full_slots = 1
            except Exception:
                full_slots = 0

        try:
            tid = int(t.get("id") or t.get("template_id") or 0)
        except Exception:
            tid = 0

        return (
            broken,          # неисправные вниз
            full_slots,      # занятые слоты вниз
            is_paid,         # бесплатные вверх
            -reward,         # самые большие награды вверх
            -profit_ratio,   # выгоднее относительно пути — выше
            gap,             # короче путь — выше
            start_amt,       # ниже старт — проще войти
            tid,
        )

    try:
        templates = sorted(templates, key=_tpl_sort_key)
    except Exception as e:
        _qdbg_exc("[GC] gc_build_list_kb: sort fail", e)

    total = len(templates or [])

    # --- расчёт страниц ---
    try:
        pages = max(1, math.ceil(total / GC_PAGE_SIZE)) if total > 0 else 1
    except Exception:
        pages = 1

    try:
        page = int(page)
    except Exception:
        page = 0

    if page < 0:
        page = 0
    if page >= pages:
        page = max(0, pages - 1)

    start = page * GC_PAGE_SIZE
    visible = templates[start:start + GC_PAGE_SIZE]

    rows: List[List[InlineKeyboardButton]] = []

    # --- заголовок ---
    header_label = f"🦋 Игровые челленджи - {page + 1}/{pages} стр."
    rows.append([gc_btn(header_label, callback_data="noop")])

    # помощь
    rows.append([gc_btn("❓ Что такое челлендж?", callback_data="qst:gc_help")])

    # разделитель сверху
    rows.append([InlineKeyboardButton(text="⎺⎺" * 19, callback_data="noop")])

    # --- сами челленджи ---
    for t in visible:
        try:
            # id шаблона
            tid = int(t.get("id") or t.get("template_id") or 0)
            if tid <= 0:
                _qdbg(f"gc_build_list_kb: skip row with bad id: {t}")
                continue

            # аккуратно парсим числа
            try:
                start_amt = int(t.get("start_amount") or 0)
            except Exception:
                start_amt = 0

            try:
                target_amt = int(t.get("target_amount") or 0)
            except Exception:
                target_amt = 0

            try:
                reward_amt = int(t.get("reward_amount") or 0)
            except Exception:
                reward_amt = 0

            max_users = t.get("max_users")
            try:
                completed = int(t.get("completed_users") or 0)
            except Exception:
                completed = 0

            # мин. ставка по тому же принципу, что в gc_build_task_kb
            betlimit_raw = t.get("betlimit")
            betlimit_int: Optional[int] = None
            if betlimit_raw not in (None, "", 0, "0"):
                try:
                    betlimit_int = int(betlimit_raw)
                    if betlimit_int <= 0:
                        betlimit_int = None
                except Exception:
                    betlimit_int = None

            # флаг "бесплатное / обычное"
            free_val = (t.get("free") or "-").strip()
            is_free = (free_val == "+")
            free_balance_emoji = "🍻 " if is_free else ""

            # проверка слотов
            full_slots = False
            if max_users is not None:
                try:
                    max_i = int(max_users)
                    if max_i <= 0:
                        full_slots = True
                    elif completed >= max_i:
                        full_slots = True
                except Exception:
                    pass

            # --- формируем краткую сводку ---
            summary_parts: List[str] = []

            # базовая часть: "поднять с A → B кут"
            if start_amt > 0 or target_amt > 0:
                summary_parts.append(
                    f"{free_balance_emoji}{_fmt_dot(start_amt)} → {_fmt_dot(target_amt)} кут"
                )

            # [+reward]
            if reward_amt > 0:
                summary_parts.append(f"[+{fmt_amt(reward_amt)}]")

            label = " ".join(summary_parts).strip()

            # " | мин X", если есть betlimit
            if betlimit_int is not None:
                if label:
                    label = f"{label} | мин {_fmt_dot(betlimit_int)}"
                else:
                    label = f"мин {_fmt_dot(betlimit_int)}"

            # если вообще не удалось собрать нормальную строку
            if not label:
                label = "Игровой челлендж"

            # учитываем занятость слотов и права бота в группе
            venue_broken = bool(t.get("bot_venue_broken"))
            if full_slots:
                label = f"⚠️ {label} (слоты заняты)"
                cb = "noop"
            elif venue_broken:
                # Коротко: новичок во вкладке заданий видит неисправность,
                # но не может взять такое задание.
                label = f"⚠️ Неисправно · {label}"
                if len(label) > 64:
                    label = label[:61] + "..."
                cb = f"qst:gc_broken:{tid}"
            else:
                cb = f"qst:gc_show:{tid}"

            rows.append([gc_btn(label, callback_data=cb)])

        except Exception as e:
            _qdbg_exc("gc_build_list_kb: add template button failed", e)
            rows.append(
                [gc_btn("⚠️ Неизвестный челлендж", callback_data="noop")]
            )

    # разделитель снизу
    rows.append([InlineKeyboardButton(text="⎽⎽" * 19, callback_data="noop")])

    # --- навигация по страницам ---
    try:
        nav_row: List[InlineKeyboardButton] = []
        if page > 0:
            nav_row.append(
                gc_btn("🔙 Назад", callback_data=f"qst:gc_page:{page - 1}")
            )
        if (start + GC_PAGE_SIZE) < total:
            nav_row.append(
                gc_btn("🔜 Вперёд", callback_data=f"qst:gc_page:{page + 1}")
            )
        if nav_row:
            rows.append(nav_row)
    except Exception as e:
        _qdbg_exc("gc_build_list_kb: nav row failed", e)

    # кнопка «Моё задание», если есть активный assignment
    if has_active:
        rows.append(
            [gc_btn("🎯 Моё задание", callback_data="qst:gc_my")]
        )

    rows.append(
        [gc_btn("♻️ Обновить список", callback_data="qst:gc_refresh")]
    )
    rows.append(
        [gc_btn("🏝 В главное меню", callback_data="qst:menu_back")]
    )

    try:
        return types.InlineKeyboardMarkup(inline_keyboard=rows)
    except Exception as e:
        _qdbg_exc("gc_build_list_kb: InlineKeyboardMarkup build failed", e)
        return types.InlineKeyboardMarkup(
            inline_keyboard=[
                [gc_btn("🏝 В главное меню", callback_data="qst:menu_back")]
            ]
        )


@dp.callback_query(lambda c: c.data and c.data.startswith("donate_info:"))
async def cb_donate_info(c: types.CallbackQuery):
    """
    Экран доната:
    - Разрешаем кликать ТОЛЬКО владельцу баланса.
    - Кнопка «Назад» ведёт обратно в cb_balance_refresh через callback_data balance:<owner_id>.
    - Привязываем сообщение к owner_id в balance_message_owner.
    """
    # -------- 0. Достаём owner_id из callback_data --------
    try:
        owner_id_from_cb = int(c.data.split(":", 1)[1])
    except Exception:
        print("⚠️ [DONATE_CB] Некорректный callback_data:", c.data)
        await c.answer("Ошибка данных.", show_alert=True)
        return

    chat_id = c.message.chat.id
    msg_id = c.message.message_id
    stop_timer_from_callback(c.message)
    # -------- 1. Определяем реального владельца сообщения --------
    real_owner_id = owner_id_from_cb
    try:
        # Если сообщение уже было привязано к владельцу - доверяем именно этой привязке
        stored_owner = balance_message_owner.get((chat_id, msg_id))
        if stored_owner:
            real_owner_id = int(stored_owner)
    except Exception as e:
        print(f"⚠️ [DONATE_CB] Ошибка чтения balance_message_owner: {e}")

    # -------- 2. Блокируем чужие клики --------
    if c.from_user.id != real_owner_id:
        await c.answer("Это чужое сообщение. Откройте своё, написав «баланс» в чат", show_alert=True)
        return

    # -------- 3. Строим клавиатуру --------
    kb = InlineKeyboardMarkup(inline_keyboard=[ ])

    # ✅ 1) сначала добавляем Донат
    try:
        kb.inline_keyboard.append(
            [ InlineKeyboardButton(
                text="Задонатить" , switch_inline_query_current_chat="донат 100", style="default" ,
                            icon_custom_emoji_id="6028338546736107668") ])
    except Exception:
        pass

    # ✅ 2) потом добавляем Назад
    kb.inline_keyboard.append(
        [ InlineKeyboardButton(
            text="Назад к балансу" , callback_data=f"balance:{real_owner_id}" , style="default" ,
            icon_custom_emoji_id="5960671702059848143") ])

    await c.message.edit_text(
        "<tg-emoji emoji-id='5296339823005557585'>🏜</tg-emoji>" , reply_markup=kb , parse_mode="HTML" ,
        disable_web_page_preview=True , )

    # Привязываем это сообщение к владельцу, чтобы другие хэндлеры (balance:, speedwithdrawal и т.п.)
    # тоже знали, кто хозяин.
    balance_message_owner[(chat_id, msg_id)] = real_owner_id
    print(
        f"🏜 [DONATE_CB] Экран доната. owner_id={real_owner_id}, "
        f"нажал uid={c.from_user.id}"
    )

# ─────────────────────────────────────────────────────────────────────────────
# ✅ ТВОЙ SPEED WITHDRAWAL CALLBACK (УЛУЧШЕННЫЙ, но по твоей структуре)
# ─────────────────────────────────────────────────────────────────────────────
@dp.callback_query(lambda c: isinstance(c.data , str) and c.data.startswith("speedwithdrawal"))
async def speed_withdrawal_callback(c: types.CallbackQuery):
    # ============================================================
    # 0) Парсим callback_data:
    #    - "speedwithdrawal:{remaining}"
    #    - "speedwithdrawal:{remaining}:{token}"  (extra token)
    # ============================================================
    available_amount = None
    has_extra_token = False
    raw_token = None
    stop_timer_from_callback(c.message)
    try:
        data = (c.data or "").strip()
        parts = data.split(":")
        print(f"🧩 [WITHDRAW][SPEED][PARSE] data={data!r} parts={parts}")

        if len(parts) >= 2:
            raw_amount = (parts [ 1 ] or "").strip()
            if raw_amount.isdigit():
                available_amount = int(raw_amount)

        if len(parts) >= 3:
            has_extra_token = True
            raw_token = (parts [ 2 ] or "").strip()

        print(
            f"🧾 [WITHDRAW][SPEED][PARSE] available_amount={available_amount} "
            f"has_extra_token={has_extra_token} token={raw_token!r}")
    except Exception as e:
        print(f"💥 [WITHDRAW][SPEED][PARSE][ERROR] {type(e).__name__}: {e}")
        available_amount = None
        has_extra_token = False
        raw_token = None

    # ============================================================
    # 1) Базовая информация
    # ============================================================
    user_id = int(getattr(c.from_user , "id" , 0) or 0)
    chat_id = int(getattr(getattr(c , "message" , None) , "chat" , None).id) if getattr(c , "message" , None) else 0
    msg_id = int(getattr(getattr(c , "message" , None) , "message_id" , 0) or 0)

    try:
        owner_id_for_back = int(balance_message_owner.get((chat_id , msg_id) , user_id))
    except Exception:
        owner_id_for_back = user_id

    print(
        f"🟦 [WITHDRAW][SPEED] uid={user_id} chat={chat_id} msg={msg_id} "
        f"owner={owner_id_for_back} avail={available_amount} extra={has_extra_token} data={c.data!r}")

    # ============================================================
    # 2) Защита: чужое сообщение
    # ============================================================
    if user_id != owner_id_for_back:
        print(f"🔒 [WITHDRAW][SPEED] ❌ чужое сообщение owner={owner_id_for_back} user={user_id}")
        try:
            await c.answer("Это чужое сообщение.\nОткройте своё, написав «баланс» в чат" , show_alert=True)
        except Exception:
            pass
        return

    # лёгкий ответ (не алерт)
    try:
        await c.answer("💭 Проверяем возможность вывода…" , show_alert=False)
    except Exception:
        pass

    # ============================================================
    # 3) Глобальный запрет вывода
    # ============================================================
    try:
        if withdraw_disabled:
            print("⛔ [WITHDRAW][SPEED] withdraw_disabled=True")
            try:
                await send_withdraw_disabled_message2(c)
            except Exception:
                pass
            return
    except Exception as e:
        print(f"🟨 [WITHDRAW][SPEED] withdraw_disabled check error: {type(e).__name__}: {e}")

    # ============================================================
    # 4) Username обязателен
    # ============================================================
    if not getattr(c.from_user , "username" , None):
        print("👤 [WITHDRAW][SPEED] ❌ нет username")
        try:
            await c.answer("❕ Для вывода необходимо установить username в Telegram." , show_alert=True)
        except Exception:
            pass
        return

    # ============================================================
    # 4.5) Активность в официальных группах (обязательное условие вывода)
    # ============================================================
    try:
        _msg_back_btn = InlineKeyboardButton(text="Назад", callback_data="balanceashudjwqkdq")
        ok_msgs = await ensure_daily_messages(c, user_id, back_btn=_msg_back_btn)
    except Exception as e:
        print(f"🟥 [WITHDRAW][SPEED][MSGCHK][ERROR] {type(e).__name__}: {e}")
        try:
            await c.answer("⚠️ Ошибка проверки активности", show_alert=True)
        except Exception:
            pass
        return
    if not ok_msgs:
        print(f"⛔ [WITHDRAW][SPEED][MSGCHK] uid={user_id} blocked")
        return

    # ============================================================
    # 5) Выбор back_flag (один раз)
    # - token есть -> назад STARS
    # - иначе -> назад BALANCE
    # ============================================================
    back_flag_for_ctx = WITHDRAW_BACK_BALANCE
    try:
        back_flag_for_ctx = WITHDRAW_BACK_STARS if has_extra_token else WITHDRAW_BACK_BALANCE
        print(
            f"🧭 [WITHDRAW][SPEED][BACK] has_extra_token={has_extra_token} -> back_flag_for_ctx={back_flag_for_ctx}")
    except Exception as e:
        print(f"💥 [WITHDRAW][SPEED][BACK][ERROR] {type(e).__name__}: {e}")
        back_flag_for_ctx = WITHDRAW_BACK_BALANCE

    # ============================================================
    # 6) ЖЕЛЕЗНОЕ ПРАВИЛО TON
    # ============================================================
    balance_ton = 0.0
    try:
        balance_ton = float(await get_balance_ton_fast(SEED_PHRASE))
        print(f"🟩 [WITHDRAW][SPEED][TON] balance_ton={balance_ton:.6f}")
    except Exception as e:
        print(f"💥 [WITHDRAW][SPEED][TON][ERROR] get_balance_ton_fast: {type(e).__name__}: {e}")
        balance_ton = 0.0

    # ============================================================
    # 7) TON <= 1 -> redirect to deep_conc_stars (обычный вывод)
    # ============================================================
    if balance_ton <= 1:
        print("🧱 [WITHDRAW][SPEED][TON] ❌ TON <= 1 -> redirect to deep_conc_stars")

        if c.message and c.message.chat.type != "private":
            try:
                bot_username = await get_bot_username_by_token(TOKEN)
                print(f"🤖 [WITHDRAW][SPEED][GROUP] bot_username={bot_username!r}")
            except Exception as e:
                print(f"💥 [WITHDRAW][SPEED][GROUP] get_bot_username_by_token: {type(e).__name__}: {e}")
                bot_username = None

            if not bot_username:
                try:
                    await c.answer("Ошибка определения бота." , show_alert=True)
                except Exception:
                    pass
                return

            try:
                pending_withdraw [ user_id ] = {"sent": False , "entry": "speedwithdrawal" ,
                                                "available_amount": available_amount}
                _pending_apply_back_meta(
                    pending_withdraw [ user_id ] , back_flag=WITHDRAW_BACK_BALANCE ,
                    owner_id_for_back=owner_id_for_back , )
                print("🧷 [WITHDRAW][SPEED][PENDING] сохранён pending (TON<=1) back=BALANCE")
            except Exception as e:
                print(f"💥 [WITHDRAW][SPEED][PENDING][ERROR] {type(e).__name__}: {e}")

            kb = InlineKeyboardMarkup(
                inline_keyboard=[ [ InlineKeyboardButton(
                    text="Открыть вывод в боте" , url=f"https://t.me/{bot_username}?start=deep_conc_stars" ,
                    style="default" , icon_custom_emoji_id="6028338546736107668") ] , [ InlineKeyboardButton(
                    text="Назад к балансу" , callback_data=f"balance:{owner_id_for_back}" , style="default" ,
                    icon_custom_emoji_id="5960671702059848143") ] , ])

            try:
                emoji_id = get_random_emoji_id()

                await c.message.edit_text(
                    f"<tg-emoji emoji-id='{emoji_id}'>💰</tg-emoji>" , reply_markup=kb , parse_mode="HTML")
                print("🧭 [WITHDRAW][SPEED][GROUP] redirected -> deep_conc_stars")
            except Exception as e:
                print(f"💥 [WITHDRAW][SPEED][GROUP] edit_text: {type(e).__name__}: {e}")
                try:
                    await c.message.edit_reply_markup(reply_markup=kb)
                except Exception:
                    pass

            try:
                await c.answer("⚠️ TON 0 - доступен обычный вывод." , show_alert=True)
            except Exception:
                pass
            return

        try:
            await render_conc_stars_screen(c.message , user_id , speed_flag="-")
        except Exception as e:
            print(f"💥 [WITHDRAW][SPEED][PRIVATE] render_conc_stars_screen: {type(e).__name__}: {e}")

        try:
            await c.answer("⚠️ TON 0 - открыт обычный вывод." , show_alert=True)
        except Exception:
            pass
        return

    # ============================================================
    # ✅ 8) TON есть -> speedwithdrawal
    # ============================================================

    # ======================================================================
    # 🌍 ГРУППА / КАНАЛ: ТОЛЬКО deep-link + pending. НЕТ авто-prompt в ЛС.
    # ======================================================================
    if c.message and c.message.chat.type != "private":
        try:
            bot_username = await get_bot_username_by_token(TOKEN)
            print(f"🤖 [WITHDRAW][SPEED][GROUP] bot_username={bot_username!r}")
        except Exception as e:
            print(f"💥 [WITHDRAW][SPEED][GROUP] get_bot_username_by_token: {type(e).__name__}: {e}")
            bot_username = None

        if not bot_username:
            try:
                await c.answer("Ошибка определения бота." , show_alert=True)
            except Exception:
                pass
            return

        try:
            pending_withdraw [ user_id ] = {"sent": False , "entry": "speedwithdrawal" ,
                                            "available_amount": available_amount}
            _pending_apply_back_meta(
                pending_withdraw [ user_id ] , back_flag=WITHDRAW_BACK_BALANCE ,
                owner_id_for_back=owner_id_for_back , )
            print(f"🧰 [WITHDRAW][SPEED][GROUP] pending сохранён uid={user_id} avail={available_amount}")
        except Exception as e:
            print(f"💥 [WITHDRAW][SPEED][GROUP] pending set: {type(e).__name__}: {e}")

        kb = InlineKeyboardMarkup(
            inline_keyboard=[ [ InlineKeyboardButton(
                text="Открыть вывод в боте" , url=f"https://t.me/{bot_username}?start=withdraw" , style="default" ,
                icon_custom_emoji_id="6028338546736107668") ] , [ InlineKeyboardButton(
                text="Назад к балансу" , callback_data=f"balance:{owner_id_for_back}" , style="default" ,
                icon_custom_emoji_id="5960671702059848143") ] , ])

        try:
            emoji_id = get_random_emoji_id()
            await c.message.edit_text(
                f"<tg-emoji emoji-id='{emoji_id}'>💰</tg-emoji>" , reply_markup=kb , parse_mode="HTML")
            try:
                balance_message_owner [ (chat_id , msg_id) ] = owner_id_for_back
            except Exception:
                pass
            print("🧭 [WITHDRAW][SPEED][GROUP] показан deeplink на /start withdraw (без auto prompt)")
        except Exception as e:
            print(f"💥 [WITHDRAW][SPEED][GROUP] edit_text: {type(e).__name__}: {e}")
            try:
                await c.message.edit_reply_markup(reply_markup=kb)
            except Exception:
                pass

        return

    # ======================================================================
    # 🔒 ЛИЧНЫЕ СООБЩЕНИЯ: отправляем prompt ОДИН раз, иначе "подожди N сек" (ОДНО сообщение)
    # ======================================================================

    pctx = None
    try:
        pctx = pending_withdraw.get(user_id)
    except Exception:
        pctx = None

    if isinstance(pctx , dict) and pctx.get("manual_message_id"):
        try:
            await c.bot.delete_message(user_id , int(pctx [ "manual_message_id" ]))
            print("🧹 [WITHDRAW][PRIVATE] удалил старый manual_message_id")
        except Exception:
            pass
        try:
            pending_withdraw.pop(user_id , None)
        except Exception:
            pass

    try:
        withdrawal_context [ user_id ] = {"awaiting_amount": True , "origin_chat_id": chat_id ,
            "origin_message_id": msg_id , }
    except Exception:
        withdrawal_context [ user_id ] = {"awaiting_amount": True}

    try:
        _ctx_apply_back_meta(
            withdrawal_context [ user_id ] , back_flag=back_flag_for_ctx , owner_id_for_back=owner_id_for_back , )
        print("🧷 [WITHDRAW][PRIVATE] meta(back_flag/owner) сохранена в ctx")
    except Exception as e:
        print(f"🟨 [WITHDRAW][PRIVATE] meta(back) warn: {type(e).__name__}: {e}")

    try:
        await c.message.delete()
    except Exception:
        pass

    prompt_msg = None
    try:
        prompt_msg = await send_withdraw_prompt_once(
            message_obj=c.message , user_id=user_id , text=build_withdraw_prompt_text(available_amount) ,
            available_amount=available_amount , back_flag=back_flag_for_ctx , owner_id_for_back=owner_id_for_back ,
            src="speedwithdrawal_private" , )
    except Exception as e:
        print(f"💥 [WITHDRAW][PRIVATE] send_withdraw_prompt_once error: {type(e).__name__}: {e}")
        try:
            await c.answer("Ошибка запуска вывода." , show_alert=True)
        except Exception:
            pass
        return

    # ✅ если prompt не отправили (guard/ctx/send_error) - показываем wait ОДИН раз (и дальше только edit)
    if prompt_msg is None:
        left = 0
        try:
            left = int(_guard_seconds_left(user_id))
        except Exception:
            left = 0

        print(f"🛡️ [WITHDRAW][PRIVATE] prompt не отправлен -> WAIT_NOTICE left={left}s")

        # toast
        try:
            await _withdraw_warn_wait_callback(c , user_id)
        except Exception:
            pass

        # ЛС wait-сообщение (ОДНО, дальше edit)
        try:
            await _send_or_edit_wait_notice(
                message_obj=c.message , user_id=user_id , left=left if left > 0 else 1 ,
                src="speedwithdrawal_private_wait" , )
        except Exception as e:
            print(f"💥 [WITHDRAW][PRIVATE][WAIT_NOTICE_ERROR] {type(e).__name__}: {e}")

        return

    try:
        await c.answer()
    except Exception:
        pass

