MAX_ALERT_LEN = 200


def _gc_build_task_info_text(
    start_amt: int,
    target_amt: int,
    reward_amt: int,
    betlimit: Optional[int],
    chat_place: Optional[str],
) -> str:
    """
    Текст для callback_query.answer(show_alert=True).
    Всегда <= MAX_ALERT_LEN символов.
    Формулировки максимально простые и понятные.
    """

    # --- 1) "человеческий" вариант ---
    lines: List[str] = []

    # Заголовок
    lines.append("🎮 Челлендж")

    # Старт и цель
    nums_parts: List[str] = []
    if start_amt > 0:
        nums_parts.append(f"старт {_fmt_dot(start_amt)}")
    if target_amt > 0:
        nums_parts.append(f"цель {_fmt_dot(target_amt)}")
    if nums_parts:
        lines.append(", ".join(nums_parts) + " кут.")

    # Награда
    if reward_amt > 0:
        lines.append(f"Награда: {fmt_amt(reward_amt)} кут.")

    # Минимальная ставка
    if betlimit is not None and betlimit > 0:
        lines.append(f"Мин. ставка: {_fmt_dot(betlimit)} кут.")

    # Где играть
    if chat_place:
        lines.append(f"Чат: {chat_place}.")

    # Короткое правило
    if target_amt > 0:
        lines.append("Подними баланс до цели - задание зачтётся.")

    text = "\n".join(lines).strip()
    _qdbg(
        f"[GC] _gc_build_task_info_text: human candidate "
        f"len={len(text)} -> {text!r}"
    )

    if len(text) <= MAX_ALERT_LEN:
        return text

    # --- 2) Компактный fallback-вариант ---
    parts: List[str] = ["🎮"]

    if start_amt > 0 and target_amt > 0:
        parts.append(f"{_fmt_dot(start_amt)}→{_fmt_dot(target_amt)}")
    elif target_amt > 0:
        parts.append(f"цель {_fmt_dot(target_amt)}")

    if reward_amt > 0:
        parts.append(f"+{fmt_amt(reward_amt)}")

    if betlimit is not None and betlimit > 0:
        parts.append(f"мин {_fmt_dot(betlimit)}")

    if chat_place:
        parts.append(f"чат {chat_place}")

    compact = " ".join(parts).strip()
    postfix = " Цель = выполнение."

    if len(compact) + len(postfix) <= MAX_ALERT_LEN:
        compact += postfix

    if len(compact) > MAX_ALERT_LEN:
        compact = compact[: MAX_ALERT_LEN - 1] + "…"

    _qdbg(
        f"[GC] _gc_build_task_info_text: compact result "
        f"len={len(compact)} -> {compact!r}"
    )
    return compact


async def gc_build_task_kb(
    template_id: int,
    meta: Dict[str, Any],
    queb: D,
    only_gc: bool = True,
) -> types.InlineKeyboardMarkup:
    """
    Клавиатура под КОНКРЕТНЫМ игровым заданием.

    Верхние элементы:
      - если есть целевой чат - кнопка "🦋 Играть в @username";
      - кнопка-сводка задания (по нажатию алерт с инфой);
      - кнопка «🎮 Взять это задание».
    """

    _qdbg(f"[GC] gc_build_task_kb: start, template_id={template_id}, meta={meta!r}")

    rows: List[List[InlineKeyboardButton]] = []

    # ---- Достаём числа из meta с защитой ----
    try:
        start_amt = int(meta.get("start_amount") or 0)
    except Exception:
        start_amt = 0

    try:
        target_amt = int(meta.get("target_amount") or 0)
    except Exception:
        target_amt = 0

    try:
        reward_amt = int(meta.get("reward_amount") or 0)
    except Exception:
        reward_amt = 0

    betlimit_raw = meta.get("betlimit")
    betlimit_int: Optional[int] = None
    if betlimit_raw not in (None, "", 0, "0"):
        try:
            betlimit_int = int(betlimit_raw)
            if betlimit_int <= 0:
                betlimit_int = None
        except Exception as e:
            betlimit_int = None
            _qdbg_exc("[GC] gc_build_task_kb: betlimit parse fail", e)

    # флаг "бесплатное / обычное"
    free_val = (meta.get("free") or "-").strip()
    is_free = (free_val == "+")
    free_balance_emoji = "🍻 " if is_free else ""

    _qdbg(
        "[GC] gc_build_task_kb: parsed params -> "
        f"start={start_amt}, target={target_amt}, "
        f"reward={reward_amt}, betlimit={betlimit_int!r}, free={free_val!r}"
    )

    # ---- Кнопка «Играть в чат», если есть целевой чат ----
    target_chat_username = meta.get("target_chat_username")
    if target_chat_username:
        username_clean = str(target_chat_username).lstrip("@").strip()
        if username_clean:
            url = f"https://t.me/{username_clean}"
            label = f"🦋 Играть в @{username_clean}"
            _qdbg(
                "[GC] gc_build_task_kb: добавляем кнопку группы -> "
                f"text={label!r}, url={url!r}"
            )
            rows.append([gc_btn(label, url=url)])

    # ---- Строим строку сводки ----
    summary_parts: List[str] = []

    # базовая часть: "поднять с A → B кут"
    if start_amt > 0 or target_amt > 0:
        summary_parts.append(
            f"{free_balance_emoji}{_fmt_dot(start_amt)} → {_fmt_dot(target_amt)} кут"
        )

    # [+reward]
    if reward_amt > 0:
        summary_parts.append(f"[+{fmt_amt(reward_amt)}]")

    summary = " ".join(summary_parts).strip()

    # " | мин X", если есть betlimit
    if betlimit_int is not None:
        if summary:
            summary = f"{summary} | мин {_fmt_dot(betlimit_int)}"
        else:
            summary = f"мин {_fmt_dot(betlimit_int)}"

    if not summary:
        summary = "🎮 Игровой челлендж"

    _qdbg(f"[GC] gc_build_task_kb: итоговая сводка -> {summary!r}")

    # ---- Кнопка сводки (по нажатию покажем alert с инфой) ----
    info_cb = f"qst:gc_info:{template_id}"
    _qdbg(f"[GC] gc_build_task_kb: info_cb={info_cb!r}")
    rows.append([gc_btn(summary, callback_data=info_cb)])

    # ---- Кнопка «🎮 Взять это задание» ----
    start_cb = _gc_task_cb_start(template_id)
    _qdbg(f"[GC] gc_build_task_kb: кнопка старта callback_data={start_cb!r}")
    rows.append([
        gc_btn("🎮 Взять это задание", callback_data=start_cb)
    ])

    # ---- (опционально) обработка queb, если нужна кнопка вывода ----
    if only_gc:
        try:
            queb = D(queb)
        except Exception:
            queb = D(0)
        # при желании сюда можно добавить кнопку вывода виртуального баланса

    # ---- Навигация ----
    rows.append([gc_btn("🏕 Вернуться к списку", callback_data="qst:show_gc")])

    kb = types.InlineKeyboardMarkup(inline_keyboard=rows)
    _qdbg("[GC] gc_build_task_kb: клавиатура сформирована")
    return kb


@dp.callback_query(lambda c: c.data and c.data.startswith("qst:gc_info:"))
async def gc_task_info_callback(callback_query: types.CallbackQuery) -> None:
    """
    Показывает короткое и понятное описание конкретного игрового челленджа
    через callback_query.answer(..., show_alert=True).

    Текст всегда ≤ MAX_ALERT_LEN символов, язык максимально простой.
    """

    data = callback_query.data or ""
    _qdbg(f"[GC] gc_task_info_callback: data={data!r}")

    # ---- 1. Парсим template_id ----
    try:
        _, _, tail = data.split(":", 2)
        template_id = int(tail)
        _qdbg(f"[GC] gc_task_info_callback: parsed template_id={template_id}")
    except Exception as e:
        _qdbg_exc("[GC] gc_task_info_callback: bad callback data", e)
        await callback_query.answer(
            "Не удалось загрузить информацию о задании.",
            show_alert=True,
        )
        return

    # ---- 2. Достаём шаблон из БД ----
    try:
        template = await db.get_gc_template_by_id(template_id)
        _qdbg(f"[GC] gc_task_info_callback: template={template!r}")
    except Exception as e:
        _qdbg_exc("[GC] gc_task_info_callback: DB error", e)
        await callback_query.answer(
            "Сейчас не получается получить данные по этому заданию.",
            show_alert=True,
        )
        return

    if not template:
        _qdbg("[GC] gc_task_info_callback: template not found")
        await callback_query.answer(
            "Это задание больше недоступно или было изменено.",
            show_alert=True,
        )
        return

    # ---- 3. Парсим числа ----
    try:
        start_amt = int(template.get("start_amount") or 0)
    except Exception:
        start_amt = 0

    try:
        target_amt = int(template.get("target_amount") or 0)
    except Exception:
        target_amt = 0

    try:
        reward_amt = int(template.get("reward_amount") or 0)
    except Exception:
        reward_amt = 0

    betlimit_raw = template.get("betlimit")
    betlimit_int: Optional[int] = None
    if betlimit_raw not in (None, "", 0, "0"):
        try:
            betlimit_int = int(betlimit_raw)
            if betlimit_int <= 0:
                betlimit_int = None
        except Exception:
            betlimit_int = None

    # ---- 4. Где играть (берём тот же принцип, что в gc_build_my_assignment_kb) ----
    chat_place: Optional[str] = None

    target_chat_username = template.get("target_chat_username")
    if target_chat_username:
        username_clean = str(target_chat_username).lstrip("@").strip()
        if username_clean:
            chat_place = f"@{username_clean}"

    # (если хочешь, сюда можно добавить fallback через chat_title/chat_link/chat_id)

    _qdbg(
        "[GC] gc_task_info_callback: parsed nums/chat -> "
        f"start={start_amt}, target={target_amt}, reward={reward_amt}, "
        f"betlimit={betlimit_int!r}, chat_place={chat_place!r}"
    )

    # ---- 5. Строим текст описания ----
    info_text = _gc_build_task_info_text(
        start_amt=start_amt,
        target_amt=target_amt,
        reward_amt=reward_amt,
        betlimit=betlimit_int,
        chat_place=chat_place,
    )

    # финальная страховка
    if len(info_text) > MAX_ALERT_LEN:
        info_text = info_text[: MAX_ALERT_LEN - 1] + "…"

    _qdbg(
        f"[GC] gc_task_info_callback: final info_text len={len(info_text)} -> "
        f"{info_text!r}"
    )

    # ---- 6. Отправляем alert ----
    try:
        await callback_query.answer(info_text, show_alert=True)
        _qdbg("[GC] gc_task_info_callback: alert sent successfully")
    except Exception as e:
        _qdbg_exc("[GC] gc_task_info_callback: callback_query.answer failed", e)
        try:
            await callback_query.answer(
                "Не удалось показать окно с описанием.",
                show_alert=False,
            )
        except Exception as e2:
            _qdbg_exc(
                "[GC] gc_task_info_callback: fallback callback_query.answer failed",
                e2,
            )

# -------------------------------------------------------------------------------------------------
#                              ПОКАЗ ОДНОГО СЛУЧАЙНОГО КАНДИДАТА (GC)
# -------------------------------------------------------------------------------------------------

async def gc_show_candidate_for_user(
    message: types.Message,
    user_id: int,
    *,
    only_gc: bool = True,
) -> bool:
    """
    Показывает ОДНО игровое задание (случайный шаблон).
    Используется для кнопки «Показать другой челлендж».
    Никак не трогает подписочную систему.
    """
    if not message:
        _qdbg("gc_show_candidate_for_user: no message")
        return False

    chat_id = message.chat.id
    msg_id = message.message_id

    queb = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
    queb = D(queb)

    gc_templates = await gc_load_templates_for_user(user_id)
    if not gc_templates:
        _qdbg(f"gc_show_candidate_for_user: no templates for user={user_id}")
        text = await gc_render_empty_text(queb)
        kb = await gc_empty_kb(user_id, queb)
        await _safe_edit_message_text(
            chat_id=chat_id,
            message_id=msg_id,
            text=text,
            reply_markup=kb,
            replacement_sticker=GC_STICKER_EMPTY,
        )
        return False

    tpl = random.choice(gc_templates)
    template_id = int(tpl.get("id") or tpl.get("template_id") or 0)
    total_gc = len(gc_templates)
    try:
        idx_gc = gc_templates.index(tpl) + 1
    except ValueError:
        idx_gc = 1

    gc_text = await gc_render_task_text(user_id, tpl, idx_gc, total_gc, queb)
    kb = await gc_build_task_kb(template_id, tpl, queb, only_gc=only_gc)

    await _safe_edit_message_text(
        chat_id=chat_id,
        message_id=msg_id,
        text=gc_text,
        reply_markup=kb,
        replacement_sticker=GC_STICKER111,
    )
    return True


