# ---------- ВСПОМОГАТЕЛЬНЫЙ ХЕЛПЕР ДЛЯ БАЛАНС-СООБЩЕНИЙ ----------

def _get_balance_owner_for_message(msg: types.Message) -> Optional[int]:
    """
    Возвращает owner_id, если сообщение является балансом,
    который мы ранее отправляли, иначе None.
    """
    try:
        key = (msg.chat.id, msg.message_id)
        return balance_message_owner.get(key)
    except Exception:
        return None


# ---------- ШАГ 1: КНОПКА "🌴 Завершить задание / челлендж" ----------

@dp.callback_query(lambda c: c.data == "qst:gc_abort_confirm")
async def gc_abort_confirm_callback(callback_query: types.CallbackQuery):
    """
    Универсальный обработчик "Завершить челлендж".

    Варианты:
    1) Сообщение баланса (💰) в НЕ приватном чате:
       -> короткое меню: "Завершить челлендж" / "Назад".
    2) Всё остальное (ЛС, другие экраны):
       -> старый подробный сценарий с описанием задания.
    """
    user_id = callback_query.from_user.id
    msg = callback_query.message
    chat = msg.chat if msg else None
    chat_type = getattr(chat, "type", None)

    _qdbg(f"[GC] gc_abort_confirm_callback: user={user_id}, chat_type={chat_type}")

    # Погасим крутилку
    try:
        await callback_query.answer()
    except Exception:
        _qdbg("[GC] gc_abort_confirm_callback: callback.answer() упал, продолжаем")

    # --- Проверка: является ли это сообщением баланса (💰) ---
    balance_owner_id = _get_balance_owner_for_message(msg) if msg else None
    is_private = (chat_type == "private")

    # Если это сообщение баланса, есть владелец и чат не приватный -> короткий режим
    if msg and (msg.text == "💰") and (balance_owner_id is not None) and not is_private:
        _qdbg(
            f"[GC] gc_abort_confirm_callback: баланс-контекст, owner={balance_owner_id}, "
            f"clicker={user_id}"
        )

        # Разрешаем клик только владельцу баланса
        if user_id != balance_owner_id:
            try:
                await callback_query.answer(
                    "Это не твой баланс. Открой свой командой «баланс».",
                    show_alert=True,
                )
            except Exception:
                pass
            return

        # Короткое меню: завершить челлендж / назад
        kb = types.InlineKeyboardMarkup(
            inline_keyboard=[
                [gc_btn("🌴 Завершить челлендж", callback_data="qst:gc_abort_do_bal")],
                [gc_btn("🏕 Назад", callback_data=f"balance:{balance_owner_id}")],
            ]
        )

        # В тексте оставляем premium 💰, просто меняем клавиатуру
        try:
            await _safe_edit_message_text(
                chat_id=msg.chat.id,
                message_id=msg.message_id,
                text=gc_tg("💰"),
                reply_markup=kb,
                replacement_sticker=None,
            )
        except Exception as e:
            _qdbg_exc("[GC] gc_abort_confirm_callback: ошибка _safe_edit_message_text (balance-mode)", e)

        return

    # ------------- ДАЛЬШЕ - СТАРЫЙ ПОДРОБНЫЙ СЦЕНАРИЙ -------------
    _qdbg("[GC] gc_abort_confirm_callback: используем подробный сценарий (не баланс или ЛС)")

    try:
        assignment = await gc_get_active_assignment(user_id)
        _qdbg(f"[GC] gc_abort_confirm_callback: assignment из БД -> {assignment!r}")

        if not assignment:
            _qdbg("[GC] gc_abort_confirm_callback: реально активного задания нет")
            await _gc_safe_answer(
                callback_query,
                "Сейчас у тебя нет активного игрового челленджа.",
                True,
            )
            return await gc_show_menu(callback_query)

        # ---- Подготовка краткой сводки по заданию (как у тебя было) ----
        try:
            tpl_id = int(assignment.get("template_id") or 0)
        except Exception:
            tpl_id = 0

        two_balance = int(
            assignment.get("two_balance")
            or assignment.get("two_balance_initial")
            or 0
        )
        target_amount = int(assignment.get("target_amount") or 0)
        reward_amount = int(assignment.get("reward_amount") or 0)

        remaining = max(0, target_amount - two_balance) if target_amount > 0 else None

        lines: List[str] = []
        lines.append("⚠️ <b>Прервать текущий челлендж?</b>")
        lines.append("")
        if tpl_id:
            lines.append(f"• ID шаблона: <b>{tpl_id}</b>")
        lines.append(f"• Текущий виртуальный баланс: <b>{_fmt_dot(two_balance)}</b> кут")
        if target_amount > 0:
            lines.append(f"• Цель: <b>{_fmt_dot(target_amount)}</b> кут")
            if remaining is not None:
                lines.append(f"• Осталось до цели: <b>{_fmt_dot(remaining)}</b> кут")
        lines.append(f"• Награда за выполнение: <b>{_fmt_dot(reward_amount)}</b> кут")
        lines.append("")
        lines.append(
            "Если прервёшь, прогресс по этому челленджу будет остановлен, "
            "а задание больше не будет активным."
        )

        text = gc_html_replace_known("\n".join(lines))

        kb = types.InlineKeyboardMarkup(
            inline_keyboard=[
                [gc_btn("🌴 Завершить челлендж", callback_data="qst:gc_abort_do")],
                [gc_btn("🏕 Назад", callback_data="qst:gc_my")],
            ]
        )

        if callback_query.message:
            await _safe_edit_message_text(
                chat_id=callback_query.message.chat.id,
                message_id=callback_query.message.message_id,
                text=text,
                reply_markup=kb,
                replacement_sticker=MY_ASSIGNMENT34,
            )

    except Exception as e:
        _qdbg_exc("[GC] gc_abort_confirm_callback: общая ошибка", e)
        await _gc_safe_answer(callback_query, "Ошибка при подготовке подтверждения.", True)
@dp.callback_query(lambda c: c.data == "qst:gc_abort_do_bal")
async def gc_abort_do_from_balance_callback(callback_query: types.CallbackQuery):
    """
    Подтверждение прерывания челленджа ИМЕННО из экрана баланса.

    - Разрешаем клик только владельцу баланса (balance_message_owner).
    - Завершаем челлендж через БД.
    - Сообщение: "💰" + кнопка "Вернуться назад" (ведёт в balance:).
    """
    user_id = callback_query.from_user.id
    msg = callback_query.message
    if not msg:
        return

    chat_id = msg.chat.id
    msg_id = msg.message_id

    _qdbg(f"[GC] gc_abort_do_from_balance_callback: user={user_id}, chat_id={chat_id}, msg_id={msg_id}")

    # Погасим крутилку
    try:
        await callback_query.answer()
    except Exception:
        _qdbg("[GC] gc_abort_do_from_balance_callback: callback.answer() упал, продолжаем")

    # -------- Проверяем владельца баланса --------
    owner_id = _get_balance_owner_for_message(msg)
    if owner_id is None:
        _qdbg("[GC] gc_abort_do_from_balance_callback: для сообщения нет owner_id -> игнор")
        try:
            await callback_query.answer("Ошибка привязки к балансу.", show_alert=True)
        except Exception:
            pass
        return

    if user_id != owner_id:
        _qdbg(
            f"[GC] gc_abort_do_from_balance_callback: чужой клик "
            f"(owner={owner_id}, clicker={user_id})"
        )
        try:
            await callback_query.answer(
                "Это не твой баланс. Открой свой командой «баланс».",
                show_alert=True,
            )
        except Exception:
            pass
        return

    # -------- Отмена задания в БД --------
    try:
        _qdbg("[GC] gc_abort_do_from_balance_callback: вызываем cancel_gc_assignment в БД")
        ok = await _try_db_call(
            ["cancel_gc_assignment"],
            user_id,
            default=False,
        )
        _qdbg(f"[GC] gc_abort_do_from_balance_callback: результат cancel_gc_assignment -> {ok!r}")
    except Exception as e:
        _qdbg_exc("[GC] gc_abort_do_from_balance_callback: ошибка при вызове cancel_gc_assignment", e)
        ok = False

    if not ok:
        await _gc_safe_answer(
            callback_query,
            "Не удалось прервать челлендж. Попробуй ещё раз позже.",
            True,
        )
        return

    # Успешно прервали
    await _gc_safe_answer(
        callback_query,
        "Челлендж прерван. Ты можешь выбрать новый челлендж в личных сообщениях.",
        False,
    )

    # Кнопка "Вернуться назад" → обратно к балансу
    kb = InlineKeyboardMarkup(
        inline_keyboard=[
            [gc_btn("🏕 Вернуться назад", callback_data=f"balance:{owner_id}")]
        ]
    )

    try:
        await _safe_edit_message_text(
            chat_id=chat_id,
            message_id=msg_id,
            text=gc_tg("💰"),
            reply_markup=kb,
            replacement_sticker=None,
        )
    except Exception as e:
        _qdbg_exc(
            "[GC] gc_abort_do_from_balance_callback: ошибка при обновлении сообщения после отмены",
            e,
        )

@dp.callback_query(lambda c: c.data == "qst:gc_abort_do")
async def gc_abort_do_callback(callback_query: types.CallbackQuery):
    """
    Шаг 2: пользователь подтвердил «Завершить челлендж».

    Делаем отмену в БД:
      - статус задания меняем с active на deactive;
      - корректно освобождаем слот в шаблоне (уменьшаем completed_users);
      - после успеха показываем пользователю, что челлендж прерван.
    """
    user_id = callback_query.from_user.id
    _qdbg(f"[GC] gc_abort_do_callback: пользователь={user_id}")

    async def _ans(text: str = "", alert: bool = False):
        await _gc_safe_answer(callback_query, text, alert)

    try:
        try:
            await callback_query.answer()
        except Exception:
            _qdbg("[GC] gc_abort_do_callback: callback.answer() упал, продолжаем")

        # Пытаемся отменить задание через БД
        _qdbg("[GC] gc_abort_do_callback: вызываем cancel_gc_assignment в БД")
        ok = await _try_db_call(
            ["cancel_gc_assignment"],
            user_id,
            default=False,
        )
        _qdbg(f"[GC] gc_abort_do_callback: результат cancel_gc_assignment -> {ok!r}")

        if not ok:
            await _ans("Не удалось прервать челлендж. Попробуй ещё раз позже.", True)
            # Попробуем вернуть пользователя к экрану задания (если вдруг оно ещё активно)
            try:
                return await gc_my_assignment_callback(callback_query)
            except Exception as e:
                _qdbg_exc("[GC] gc_abort_do_callback: gc_my_assignment_callback после ошибки отмены", e)
                return

        # Успешно прервали
        await _ans("Челлендж прерван. Ты можешь выбрать новый челлендж.", False)

        text = gc_html_replace_known(
            "⛱ <b>Челлендж остановлен.</b>\n\n"
            "Текущее игровое задание больше не активно.\n"
            "Когда будешь готов - выбери новый челлендж из списка."
        )

        kb = types.InlineKeyboardMarkup(
            inline_keyboard=[
                [gc_btn("🦋 К списку челленджей", callback_data="qst:show_gc")],
                [gc_btn("🏝 В главное меню", callback_data="qst:menu_back")],
            ]
        )

        if callback_query.message:
            _qdbg(
                "[GC] gc_abort_do_callback: показываем экран после отмены "
                f"chat_id={callback_query.message.chat.id}, "
                f"message_id={callback_query.message.message_id}"
            )
            await _safe_edit_message_text(
                chat_id=callback_query.message.chat.id,
                message_id=callback_query.message.message_id,
                text=text,
                reply_markup=kb,
                replacement_sticker=GC_STICKER_MY_ASSIGNMENT,
            )
        else:
            _qdbg("[GC] gc_abort_do_callback: callback_query.message == None (нечего редактировать)")

    except Exception as e:
        _qdbg_exc("[GC] gc_abort_do_callback: общая ошибка", e)
        await _ans("Ошибка при завершении челленджа. Попробуй позже.", True)

