async def _gc_resolve_group_username(assignment: Dict[str, Any]) -> Optional[str]:
    """
    Аккуратно достаём username группы, в которой нужно играть по текущему заданию.

    Данные приходят из:
      - assignment["target_chat_ref"]  (строка с username / @username / t.me/...)
      - assignment["target_chat_id"]   (числовой chat_id, по которому можно найти username в БД)

    Логика:
      1) Пробуем понять username из target_chat_ref.
      2) Если там ничего вменяемого нет, но есть target_chat_id - зовём db.get_group_username(chat_id).
      3) Всё нормализуем до чистого 'groupname' без '@'.
      4) При любой ошибке - возвращаем None, чтобы не показывать кнопку.
    """
    try:
        raw_ref = assignment.get("target_chat_ref")
        raw_id = assignment.get("target_chat_id")

        _qdbg(
            f"[GC] _gc_resolve_group_username: raw_ref={raw_ref!r} "
            f"(type={type(raw_ref)}), raw_id={raw_id!r}"
        )

        username: Optional[str] = None

        # ---------- 1) Пытаемся вытащить из target_chat_ref ----------
        if raw_ref is not None:
            try:
                s = str(raw_ref).strip()
                _qdbg(f"[GC] _gc_resolve_group_username: target_chat_ref после strip -> {s!r}")

                if s:
                    if s.startswith("@"):
                        # формат "@groupname"
                        username = s[1:].strip()
                        _qdbg(
                            "[GC] _gc_resolve_group_username: формат '@name', "
                            f"username={username!r}"
                        )
                    elif s.startswith("https://t.me/") or s.startswith("http://t.me/") or s.startswith("t.me/"):
                        # формат URL t.me/...
                        _qdbg(
                            "[GC] _gc_resolve_group_username: формат URL t.me, "
                            f"строка={s!r}"
                        )
                        m = re.search(r"t\.me/([^/?\s]+)", s)
                        if m:
                            username = m.group(1).strip()
                            _qdbg(
                                "[GC] _gc_resolve_group_username: username из URL -> "
                                f"{username!r}"
                            )
                        else:
                            _qdbg(
                                "[GC] _gc_resolve_group_username: не смогли вытащить "
                                "username из URL"
                            )
                    else:
                        # считаем, что это уже чистый username
                        username = s
                        _qdbg(
                            "[GC] _gc_resolve_group_username: считаем, что это уже "
                            f"чистый username -> {username!r}"
                        )
            except Exception as e:
                _qdbg_exc(
                    "[GC] _gc_resolve_group_username: ошибка парсинга target_chat_ref",
                    e,
                )
                username = None

        # ---------- 2) Если из ref ничего не достали - пробуем по target_chat_id через БД ----------
        if (username is None or not str(username).strip()) and raw_id is not None:
            try:
                chat_id_int = int(raw_id)
                _qdbg(
                    "[GC] _gc_resolve_group_username: пробуем найти username по "
                    f"chat_id={chat_id_int}"
                )
                uname_from_db = await _try_db_call(
                    ["get_group_username"],
                    chat_id_int,
                    default=None,
                )
                _qdbg(
                    "[GC] _gc_resolve_group_username: get_group_username вернул -> "
                    f"{uname_from_db!r}"
                )
                if uname_from_db:
                    username = str(uname_from_db).strip()
            except Exception as e:
                _qdbg_exc(
                    "[GC] _gc_resolve_group_username: ошибка поиска по chat_id",
                    e,
                )
                username = None

        # ---------- 3) Нормализация и финальная проверка ----------
        if username is None:
            _qdbg("[GC] _gc_resolve_group_username: username не найден -> вернём None")
            return None

        username = str(username).strip()
        if username.startswith("@"):
            username = username[1:]
        username = username.strip()

        if not username:
            _qdbg("[GC] _gc_resolve_group_username: username после нормализации пустой")
            return None

        _qdbg(f"[GC] _gc_resolve_group_username: финальный username -> {username!r}")
        return username

    except Exception as e:
        _qdbg_exc("[GC] _gc_resolve_group_username: неожиданная ошибка", e)
        return None

async def _gc_extract_group_username_from_ref(raw_ref: Any) -> Optional[str]:
    """
    Аккуратно достаём username группы из target_chat_ref.

    Поддерживаемые варианты:
      - "@groupname"
      - "groupname"
      - "https://t.me/groupname", "http://t.me/groupname", "t.me/groupname"
      - "-1001234567890" (chat_id) - ищем username через get_group_username(chat_id)

    На любой ошибке/мусоре - возвращаем None, чтобы просто не показывать кнопку.
    """
    try:
        _qdbg(f"[GC] _gc_extract_group_username_from_ref: raw_ref={raw_ref!r}, type={type(raw_ref)}")
        if raw_ref is None:
            _qdbg("[GC] _gc_extract_group_username_from_ref: raw_ref == None -> нет группы")
            return None

        s = str(raw_ref).strip()
        _qdbg(f"[GC] _gc_extract_group_username_from_ref: строка после strip -> {s!r}")
        if not s:
            _qdbg("[GC] _gc_extract_group_username_from_ref: пустая строка после strip -> нет группы")
            return None

        # @groupname
        if s.startswith("@"):
            uname = s[1:].strip()
            _qdbg(f"[GC] _gc_extract_group_username_from_ref: формат '@name', uname={uname!r}")
            return uname or None

        # URL t.me/...
        if s.startswith("https://t.me/") or s.startswith("http://t.me/") or s.startswith("t.me/"):
            _qdbg(f"[GC] _gc_extract_group_username_from_ref: формат URL t.me -> {s!r}")
            m = re.search(r"t\.me/([^/?\s]+)", s)
            if m:
                uname = m.group(1).strip()
                _qdbg(f"[GC] _gc_extract_group_username_from_ref: username из URL -> {uname!r}")
                return uname or None
            _qdbg("[GC] _gc_extract_group_username_from_ref: не смогли вытащить username из URL")
            return None

        # numeric chat_id -> пробуем добрать username через БД
        if re.fullmatch(r"-?\d+", s):
            _qdbg(f"[GC] _gc_extract_group_username_from_ref: похоже на chat_id -> {s!r}")
            try:
                chat_id_int = int(s)
                _qdbg(f"[GC] _gc_extract_group_username_from_ref: chat_id_int={chat_id_int}")
            except Exception as e:
                _qdbg(f"[GC] _gc_extract_group_username_from_ref: ошибка преобразования в int: {e}")
                return None

            try:
                uname = await _try_db_call(
                    ["get_group_username"],
                    chat_id_int,
                    default=None,
                )
                _qdbg(f"[GC] _gc_extract_group_username_from_ref: get_group_username вернул -> {uname!r}")
            except Exception as e:
                _qdbg_exc("[GC] _gc_extract_group_username_from_ref: get_group_username упал", e)
                return None

            if not uname:
                _qdbg("[GC] _gc_extract_group_username_from_ref: username из БД пустой/None")
                return None

            uname = str(uname).strip()
            if uname.startswith("@"):
                uname = uname[1:]
            uname = uname.strip()
            _qdbg(f"[GC] _gc_extract_group_username_from_ref: username после нормализации -> {uname!r}")
            return uname or None

        # иначе считаем, что это уже чистый username без @
        _qdbg(f"[GC] _gc_extract_group_username_from_ref: считаем, что это уже чистый username -> {s!r}")
        return s or None

    except Exception as e:
        _qdbg_exc("[GC] _gc_extract_group_username_from_ref: неожиданная ошибка", e)
        return None
@dp.callback_query(lambda c: c.data == "qst:gc_my")
async def gc_my_assignment_callback(callback_query: types.CallbackQuery):
    """
    Экран «Моё задание» - показывает текущее РЕАЛЬНО АКТИВНОЕ игровое задание.

    Если status уже finish/failed/etc - через gc_get_active_assignment оно
    просто не вернётся, и мы считаем, что активного задания нет.
    """
    user_id = callback_query.from_user.id
    _qdbg(f"[GC] gc_my_assignment_callback: пользователь={user_id}")

    try:
        try:
            await callback_query.answer()
        except Exception:
            _qdbg("[GC] gc_my_assignment_callback: callback.answer() упал, продолжаем без алерта")

        # Берём РЕАЛЬНО активное игровое задание
        assignment = await gc_get_active_assignment(user_id)
        _qdbg(f"[GC] gc_my_assignment_callback: assignment из БД -> {assignment!r}")

        if not assignment:
            _qdbg("[GC] gc_my_assignment_callback: реально активного задания нет")
            await _gc_safe_answer(
                callback_query,
                "У тебя сейчас нет активного игрового челленджа.",
                True
            )
            return await gc_show_menu(callback_query)

        # ---------- ищем username группы для игры ----------
        username = await _gc_resolve_group_username(assignment)
        if username:
            assignment["target_chat_username"] = username
            _qdbg(
                f"[GC] gc_my_assignment_callback: у задания есть группа -> @{username}"
            )
        else:
            _qdbg(
                "[GC] gc_my_assignment_callback: валидный username группы не найден, "
                f"target_chat_ref={assignment.get('target_chat_ref')!r}, "
                f"target_chat_id={assignment.get('target_chat_id')!r}"
            )

        # ---------- рендер ----------
        _qdbg("[GC] gc_my_assignment_callback: рендер текста задания")
        text = await gc_render_my_assignment_text(user_id, assignment)

        _qdbg("[GC] gc_my_assignment_callback: строим клавиатуру под задание")
        kb = await gc_build_my_assignment_kb(assignment)

        if callback_query.message:
            await _safe_edit_message_text(
                chat_id=callback_query.message.chat.id,
                message_id=callback_query.message.message_id,
                text=text,
                reply_markup=kb,
                replacement_sticker=GC_STICKER_MY_ASSIGNMENT,
            )
        else:
            _qdbg("[GC] gc_my_assignment_callback: callback_query.message == None, нечего редактировать")

    except Exception as e:
        _qdbg_exc("[GC] gc_my_assignment_callback: общая ошибка", e)
        await _gc_safe_answer(callback_query, "Ошибка.", True)


@dp.callback_query(lambda c: c.data == "qst:show_gc")
async def gc_show_menu(callback_query: types.CallbackQuery):
    """
    Вход в раздел игровых челленджей.

    Задания со статусом finish/failed НЕ считаются активными
    и не мешают брать новые.
    """
    user_id = callback_query.from_user.id
    _qdbg(f"gc_show_menu user={user_id}")

    try:
        try:
            await callback_query.answer()
        except Exception:
            pass

        queb_raw = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
        queb = D(queb_raw)

        templates = await gc_load_templates_for_user(user_id)

        # активный assignment (реально активный)
        existing = await gc_get_active_assignment(user_id)
        has_active = bool(existing)

        if not templates:
            text = await gc_render_empty_text(queb)
            kb = await gc_empty_kb(user_id, queb)
            if callback_query.message:
                await _safe_edit_message_text(
                    chat_id=callback_query.message.chat.id,
                    message_id=callback_query.message.message_id,
                    text=text,
                    reply_markup=kb,
                    replacement_sticker=GC_STICKER_EMPTY,
                )
            _qdbg(f"gc_show_menu: no templates for user={user_id} -> empty screen")
            return

        lines: List[str] = []
        if existing:
            cur_two = int(existing.get("two_balance") or existing.get("two_balance_initial") or 0)
            cur_init = int(existing.get("two_balance_initial") or cur_two)
            tpl_old = int(existing.get("template_id") or 0)
            target_old = int(existing.get("target_amount") or 0)
            reward_old = int(existing.get("reward_amount") or 0)

            def f(v):
                return _fmt_dot(v)

            remaining_old = max(0, target_old - cur_two) if target_old > 0 else 0
            lines.extend([
                "🦋 <b>У вас уже есть активный челлендж.</b>",
                "",
                f"📌 <b>Текущее задание (ID шаблона {tpl_old}):</b>",
                f"• Стартовая сумма: <b>{f(cur_init)}</b> кут",
                f"• Текущий виртуальный баланс: <b>{f(cur_two)}</b> кут",
                f"• Цель: <b>{f(target_old)}</b> кут",
                f"• До цели осталось: <b>{f(remaining_old)}</b> кут",
                f"• Награда: <b>{f(reward_old)}</b> кут",
                "",
                "",
                "Ниже - доступные челленджи.",
                "Вы можете продолжать текущее задание или взять новое (старое будет заменено).",
                "",
                "<b>Выберите челлендж из списка:</b>",
            ])
        else:
            lines.extend([
                "🦋 <b>Доступные игровые челленджи</b>",
                "",
                "",
                "Выберите челлендж из списка ниже.",
            ])

        header_text = gc_html_replace_known("\n".join(lines))
        kb = await gc_build_list_kb(templates, page=0, queb=queb, has_active=has_active)

        if callback_query.message:
            await _safe_edit_message_text(
                chat_id=callback_query.message.chat.id,
                message_id=callback_query.message.message_id,
                text=header_text,
                reply_markup=kb,
                replacement_sticker=GC_STICKER_LIST,
            )
        _qdbg(f"gc_show_menu: list shown for user={user_id}, templates={len(templates)}")

    except Exception as e:
        _qdbg_exc("gc_show_menu fail", e)
        await _gc_safe_answer(callback_query, "Ошибка.", True)


