@dp.callback_query(lambda c: c.data and c.data.startswith("qst:gc_broken:"))
async def gc_broken_callback(callback_query: types.CallbackQuery):
    """Карточка неисправного челленджа: бот не админ в целевой группе."""
    user_id = callback_query.from_user.id
    raw = (callback_query.data or "").split(":")
    try:
        template_id = int(raw[2]) if len(raw) > 2 else 0
    except Exception:
        template_id = 0

    try:
        await callback_query.answer()
    except Exception:
        pass

    try:
        tpl = await _try_db_call(["get_gc_template_by_id"], template_id, default=None)
        ok, reason = (False, "unknown")
        where = "целевой группе"
        if isinstance(tpl, dict):
            ok, reason = await gc_bot_can_serve_template(tpl)
            ref = str(tpl.get("target_chat_ref") or "").strip()
            if ref:
                where = ref if ref.startswith("@") else f"@{ref.lstrip('@')}"
            elif tpl.get("target_chat_id"):
                where = f"чате {tpl.get('target_chat_id')}"

        reason_human = {
            "not_admin": "бот есть в группе, но без прав администратора",
            "missing": "бот удалён из группы",
            "unreachable": "группа недоступна боту",
            "bot_id_unknown": "не удалось определить бота",
            "unrestricted": "привязки к группе нет",
            "admin": "бот - администратор",
        }.get(reason, reason)

        lines = [
            "⚠️ <b>Задание временно неисправно</b>",
            "",
            f"Группа: <b>{html.escape(str(where))}</b>",
            f"Причина: <b>{html.escape(str(reason_human))}</b>",
            "",
            "Чтобы задание снова заработало, бот должен быть "
            "<b>администратором</b> в этой группе.",
            "",
            "Напишите админу группы или выберите другое задание.",
        ]
        kb = types.InlineKeyboardMarkup(inline_keyboard=[
            [gc_btn("🏕 К списку челленджей", callback_data="qst:show_gc")],
            [gc_btn("🏝 В главное меню", callback_data="qst:menu_back")],
        ])
        if callback_query.message:
            await _safe_edit_message_text(
                chat_id=callback_query.message.chat.id,
                message_id=callback_query.message.message_id,
                text=gc_html_replace_known("\n".join(lines)),
                reply_markup=kb,
                replacement_sticker=GC_STICKER_LIST,
            )
        _qdbg(
            f"[GC] gc_broken_callback user={user_id} tid={template_id} "
            f"ok={ok} reason={reason}"
        )
    except Exception as e:
        _qdbg_exc("[GC] gc_broken_callback fail", e)
        await _gc_safe_answer(callback_query, "Ошибка.", True)


@dp.callback_query(lambda c: c.data and c.data.startswith("qst:gc_show:"))
async def gc_show_one_callback(callback_query: types.CallbackQuery):
    """
    Показать ОДИН конкретный челлендж по его ID (подробная карточка).

    Схема:
      список → qst:gc_show:<ID> → эта функция
        → проверяем, что шаблон ещё существует, активен и есть слоты
        → рендерим текст + клавиатуру
        → кнопка "🎮 Взять это задание" даёт callback qst:gcstart:<ID>,
          а дальше всё обрабатывает gc_start_callback (проверка активного задания и т.п.).
    """
    user_id = callback_query.from_user.id
    raw_data = callback_query.data or ""
    parts = raw_data.split(":", 2)
    raw_id = parts[2] if len(parts) > 2 else ""

    _qdbg(
        f"[GC] gc_show_one_callback: пользователь={user_id}, "
        f"callback_data={raw_data!r}, raw_id={raw_id!r}"
    )

    try:
        # --- парсим ID шаблона ---
        try:
            template_id = int(raw_id)
            _qdbg(f"[GC] gc_show_one_callback: распарсили template_id={template_id}")
        except Exception as e:
            _qdbg_exc("[GC] gc_show_one_callback: не удалось распарсить template_id", e)
            await _gc_safe_answer(callback_query, "Некорректное задание.", True)
            return

        # --- отвечаем на callback, чтобы убрать "часики" ---
        try:
            await callback_query.answer()
        except Exception as e:
            _qdbg_exc("[GC] gc_show_one_callback: callback.answer() упал", e)

        # --- берём баланс наград (он может понадобиться для кнопки вывода) ---
        try:
            queb_raw = await _try_db_call(
                ["get_que_balance", "get_virtual_balance"],
                user_id,
                default=D(0),
            )
            queb = D(queb_raw)
        except Exception as e:
            _qdbg_exc("[GC] gc_show_one_callback: не удалось получить quebalance", e)
            queb = D(0)

        _qdbg(f"[GC] gc_show_one_callback: quebalance пользователя={fmt_amt(queb)} кут")

        # --- грузим шаблон челленджа ---
        tpl = await _try_db_call(["get_gc_template_by_id"], template_id, default=None)
        _qdbg(f"[GC] gc_show_one_callback: шаблон из БД -> {tpl!r}")

        if not tpl or not isinstance(tpl, dict):
            _qdbg(
                f"[GC] gc_show_one_callback: шаблон id={template_id} "
                f"не найден или формат не dict"
            )
            await _gc_safe_answer(callback_query, "Это задание больше недоступно.", True)
            return await gc_show_menu(callback_query)

        # --- бот должен быть админом в группе задания ---
        venue_ok, venue_reason = await gc_bot_can_serve_template(tpl)
        if not venue_ok:
            _qdbg(
                f"[GC] gc_show_one_callback: venue broken tid={template_id} "
                f"reason={venue_reason}"
            )
            callback_query.data = f"qst:gc_broken:{template_id}"
            return await gc_broken_callback(callback_query)

        # --- проверка статуса ---
        status = str(tpl.get("status") or "active").strip().lower()
        _qdbg(f"[GC] gc_show_one_callback: статус шаблона -> {status!r}")

        if status not in ("active", ""):
            _qdbg(
                f"[GC] gc_show_one_callback: шаблон id={template_id} не активен (status={status!r})"
            )
            await _gc_safe_answer(callback_query, "Это задание отключено.", True)
            return await gc_show_menu(callback_query)

        # --- проверка слотов max_users / completed_users ---
        max_users = tpl.get("max_users")
        completed_raw = tpl.get("completed_users") or 0
        try:
            completed = int(completed_raw)
        except Exception:
            _qdbg(
                f"[GC] gc_show_one_callback: не смогли привести completed_users={completed_raw!r} к int, "
                "ставим 0"
            )
            completed = 0

        _qdbg(
            f"[GC] gc_show_one_callback: max_users={max_users!r}, "
            f"completed={completed}"
        )

        if max_users is not None:
            try:
                max_users_int = int(max_users)
            except Exception as e:
                _qdbg_exc(
                    f"[GC] gc_show_one_callback: не смогли привести max_users={max_users!r} к int",
                    e,
                )
                max_users_int = None

            if max_users_int is not None:
                if max_users_int <= 0:
                    _qdbg(
                        f"[GC] gc_show_one_callback: max_users_int={max_users_int} => слотов нет вообще"
                    )
                    await _gc_safe_answer(
                        callback_query,
                        "Это задание недоступно: слоты для участия не открыты.",
                        True,
                    )
                    return await gc_show_menu(callback_query)
                if completed >= max_users_int:
                    _qdbg(
                        f"[GC] gc_show_one_callback: слоты исчерпаны "
                        f"({completed}/{max_users_int})"
                    )
                    await _gc_safe_answer(
                        callback_query,
                        "Все слоты этого задания уже заняты.",
                        True,
                    )
                    return await gc_show_menu(callback_query)

        # --- рендер текста задания ---
        _qdbg("[GC] gc_show_one_callback: начинаем рендер текста челленджа")
        text = await gc_render_task_text(user_id, tpl, 1, 1, queb)
        _qdbg("[GC] gc_show_one_callback: текст челленджа успешно сформирован")

        # --- клавиатура с кнопкой '🎮 Взять это задание' (qst:gcstart:ID) ---
        _qdbg("[GC] gc_show_one_callback: строим клавиатуру под челлендж")
        kb = await gc_build_task_kb(template_id, tpl, queb, only_gc=True)
        _qdbg("[GC] gc_show_one_callback: клавиатура успешно сформирована")

        # --- редактируем сообщение ---
        if callback_query.message:
            chat_id = callback_query.message.chat.id
            msg_id = callback_query.message.message_id
            _qdbg(
                f"[GC] gc_show_one_callback: редактируем сообщение "
                f"chat_id={chat_id}, message_id={msg_id}"
            )
            await _safe_edit_message_text(
                chat_id=chat_id,
                message_id=msg_id,
                text=text,
                reply_markup=kb,
                replacement_sticker=GC_STICKER111,
            )
        else:
            _qdbg(
                "[GC] gc_show_one_callback: callback_query.message == None, "
                "редактировать нечего"
            )

    except Exception as e:
        _qdbg_exc("[GC] gc_show_one_callback: общая ошибка", e)
        await _gc_safe_answer(callback_query, "Ошибка.", True)


@dp.callback_query(lambda c: c.data == "qst:gc_refresh")
async def gc_refresh_callback(callback_query: types.CallbackQuery):
    """
    Обновить список игровых челленджей.
    """
    user_id = callback_query.from_user.id
    _qdbg(f"gc_refresh_callback called by user={user_id}")

    try:
        try:
            await callback_query.answer()
        except Exception:
            pass

        # Свежая проверка прав бота в группах заданий.
        try:
            gc_clear_bot_venue_cache()
        except Exception:
            pass

        if not callback_query.message:
            _qdbg("gc_refresh_callback: no message in callback")
            return

        target_chat_id = callback_query.message.chat.id
        target_msg_id = callback_query.message.message_id

        now = time.time()
        queb: Decimal = D(0)
        templates: List[Dict[str, Any]] = []

        cached = _gc_short_cache.get(user_id)
        if cached and (now - cached[0]) < _GC_CACHE_TTL:
            _, templates, queb = cached
            _qdbg(f"gc_refresh_callback: used short-cache for user={user_id}")
        else:
            queb_raw = await _try_db_call(["get_que_balance", "get_virtual_balance"], user_id, default=D(0))
            queb = D(queb_raw)
            templates = await gc_load_templates_for_user(user_id)
            _gc_short_cache[user_id] = (now, templates, queb)
            _qdbg(
                f"gc_refresh_callback: DB loaded for user={user_id}, "
                f"templates={len(templates)}, queb={fmt_amt(queb)}"
            )

        existing = await gc_get_active_assignment(user_id)
        has_active = bool(existing)

        if not templates:
            text = await gc_render_empty_text(queb)
            kb = await gc_empty_kb(user_id, queb)
            await _safe_edit_message_text(
                chat_id=target_chat_id,
                message_id=target_msg_id,
                text=text,
                reply_markup=kb,
                replacement_sticker=GC_STICKER_EMPTY,
            )
            _qdbg(f"gc_refresh_callback: no templates -> empty UI for user={user_id}")
            return

        text = gc_html_replace_known(
            "<b>🦋 Обновлён список игровых челленджей</b>\n"
            "Выберите задание ниже."
        )
        kb = await gc_build_list_kb(templates, page=0, queb=queb, has_active=has_active)

        await _safe_edit_message_text(
            chat_id=target_chat_id,
            message_id=target_msg_id,
            text=text,
            reply_markup=kb,
            replacement_sticker=GC_STICKER_LIST,
        )
        _qdbg(f"gc_refresh_callback: UI updated for user={user_id}")

    except Exception as e:
        _qdbg_exc("gc_refresh_callback fail", e)
        await _gc_safe_answer(
            callback_query,
            "Не удалось обновить челленджи - попробуйте ещё раз.",
            True,
        )


