@dp.callback_query(lambda c: c.data and c.data.startswith("qst:gcstart:"))
async def gc_start_callback(callback_query: types.CallbackQuery):
    """
    Взять выбранное игровое задание:
      - если этого задания уже нет в шаблонах / слоты закончились - говорим об этом;
      - если у пользователя уже есть ЭТО ЖЕ задание в активных - показываем «Моё задание»;
      - если у пользователя ДРУГОЕ активное задание - стикер + выбор: заменить или оставить;
      - если активного задания нет - резервируем слот и создаём assignment.
    """
    user_id = callback_query.from_user.id
    raw = (callback_query.data or "").split(":", 2)[2] if callback_query.data else ""
    _qdbg(f"gc_start_callback: user={user_id}, raw={raw}")

    async def _safe_answer(text: str = "", alert: bool = False):
        await _gc_safe_answer(callback_query, text, alert)

    try:
        try:
            template_id = int(raw)
        except Exception:
            return await _safe_answer("Неверное задание.", True)

        try:
            await callback_query.answer()
        except Exception:
            pass

        # --- грузим сам шаблон сразу, чтобы иметь данные и для проверки, и для красивого текста ---#
        tpl = await _try_db_call(["get_gc_template_by_id"], template_id, default=None)
        if not tpl:
            return await _safe_answer("Это задание больше недоступно.", True)

        status = str(tpl.get("status") or "active").lower()
        if status not in ("active", ""):
            return await _safe_answer("Это задание отключено.", True)

        # проверяем слоты по шаблону (до любых манипуляций)
        max_u = tpl.get("max_users")
        done_u = tpl.get("completed_users") or 0
        try:
            done_u = int(done_u)
        except Exception:
            done_u = 0

        def _slots_exhausted() -> bool:
            if max_u is None:
                return False
            try:
                max_u_int = int(max_u)
            except Exception:
                return False
            if max_u_int <= 0:
                return True
            return done_u >= max_u_int

        if _slots_exhausted():
            return await _safe_answer("Все слоты этого задания уже заняты.", True)

        # Бот должен быть администратором в группе задания.
        venue_ok, venue_reason = await gc_bot_can_serve_template(tpl)
        if not venue_ok:
            _qdbg(
                f"gc_start_callback: venue broken tid={template_id} reason={venue_reason}"
            )
            return await _safe_answer(
                "Это задание сейчас неисправно: бот должен быть администратором "
                "в группе задания. Выберите другое.",
                True,
            )

        # --- проверяем, есть ли уже активный assignment у пользователя ---#
        existing = await _try_db_call(["get_active_gc_assignment"], user_id, default=None)

        # 1) Есть активное задание И оно с ЭТИМ ЖЕ template_id
        if existing:
            try:
                existing_tid = int(existing.get("template_id") or 0)
            except Exception:
                existing_tid = 0

            if existing_tid == template_id:
                _qdbg(
                    f"gc_start_callback: user={user_id} already has this template_id={template_id} active -> show my assignment"
                )
                await _safe_answer("Этот челлендж уже у тебя активен. Показываю текущее задание 👇", True)
                try:
                    await gc_my_assignment_callback(callback_query)
                except Exception as e:
                    _qdbg_exc("gc_start_callback -> gc_my_assignment_callback fail", e)
                return

            # 2) Есть активное задание, но с ДРУГИМ шаблоном -> предлагаем заменить
            _qdbg(
                f"gc_start_callback: user={user_id} has another active template_id={existing_tid}, "
                f"new_template_id={template_id}"
            )

            cur_two = int(existing.get("two_balance") or existing.get("two_balance_initial") or 0)
            cur_init = int(existing.get("two_balance_initial") or cur_two)
            tpl_old = int(existing.get("template_id") or 0)
            target_old = int(existing.get("target_amount") or 0)
            reward_old = int(existing.get("reward_amount") or 0)

            # немного инфы о новом задании (которое хочет взять)
            new_start = int(tpl.get("start_amount") or 0)
            new_target = int(tpl.get("target_amount") or 0)
            new_reward = int(tpl.get("reward_amount") or 0)

            txt_lines = [
                "⚠️ <b>У вас уже есть активный челлендж.</b>",
                "",
                f"📌 <b>Текущее задание (ID шаблона {tpl_old}):</b>",
                f"• Стартовая сумма: <b>{_fmt_dot(cur_init)}</b> кут",
                f"• Текущий виртуальный баланс: <b>{_fmt_dot(cur_two)}</b> кут",
                f"• Цель: <b>{_fmt_dot(target_old)}</b> кут",
                f"• До цели осталось: <b>{_fmt_dot(max(0, target_old - cur_two))}</b> кут",
                f"• Награда: <b>{_fmt_dot(reward_old)}</b> кут",
                "",
                f"🆕 <b>Новое задание (ID шаблона {template_id}):</b>",
                f"• Стартовая сумма: <b>{_fmt_dot(new_start)}</b> кут",
                f"• Цель: <b>{_fmt_dot(new_target)}</b> кут",
                f"• Награда: <b>{_fmt_dot(new_reward)}</b> кут",
                "",
                "Выберите, что сделать:",
            ]
            txt = gc_html_replace_known("\n".join(txt_lines))

            kb = types.InlineKeyboardMarkup(
                inline_keyboard=[
                    [
                        InlineKeyboardButton(
                            text="✅ Заменить текущий челлендж",
                            callback_data=f"qst:gctake_force:{template_id}",
                        )
                    ],
                    [gc_btn("🏝 Показать текущее задание", callback_data="qst:gc_my")],
                    [gc_btn("🏕 Вернуться к списку", callback_data="qst:show_gc")],
                ]
            )

            if callback_query.message:
                try:
                    await _safe_edit_message_text(
                        chat_id=callback_query.message.chat.id,
                        message_id=callback_query.message.message_id,
                        text=txt,
                        reply_markup=kb,
                        replacement_sticker=GC_STICKER_DETAILS,
                    )
                except Exception as e:
                    _qdbg_exc("gc_start_callback: edit conflict UI fail", e)
            return

        # --- 3) Активного задания нет: пробуем нормально занять слот и создать assignment ---#

        # Перед окончательным резервированием слота перезагрузим счётчики слотов
        tpl_fresh = await _try_db_call(["get_gc_template_by_id"], template_id, default=None) or tpl
        max_u = tpl_fresh.get("max_users")
        done_u = tpl_fresh.get("completed_users") or 0
        try:
            done_u = int(done_u)
        except Exception:
            done_u = 0

        if max_u is not None:
            try:
                max_u_int = int(max_u)
            except Exception:
                max_u_int = None
            if max_u_int is not None and (max_u_int <= 0 or done_u >= max_u_int):
                return await _safe_answer("Все слоты этого задания уже заняты.", True)

        # резервируем слот (атомарная операция в БД)
        updated = await _try_db_call(["increment_gc_template_completed"], template_id, step=1, default=False)
        if not updated:
            return await _safe_answer("Не удалось занять слот задания (возможно, места уже закончились).", True)

        # защитная проверка: не появился ли активный assignment между моментом проверки и резервированием
        try:
            existing2 = await _try_db_call(["get_active_gc_assignment"], user_id, default=None)
        except Exception as e:
            _qdbg_exc("gc_start_callback: get_active_gc_assignment after increment fail", e)
            existing2 = None

        if existing2:
            # кто-то/что-то уже создало assignment в параллельном потоке - откатываем слот
            await _try_db_call(["decrement_gc_template_completed"], template_id, step=1)
            # если это именно этот шаблон - считаем, что челлендж уже взят
            try:
                existing2_tid = int(existing2.get("template_id") or 0)
            except Exception:
                existing2_tid = 0
            if existing2_tid == template_id:
                await _safe_answer("Этот челлендж уже у тебя активен.", True)
                try:
                    await gc_my_assignment_callback(callback_query)
                except Exception as e:
                    _qdbg_exc("gc_start_callback: gc_my_assignment_callback after race fail", e)
            else:
                await _safe_answer("У тебя уже есть активное задание.", True)
            return

        # --- создаём assignment ---#
        try:
            first_name = await _try_db_call(["get_firstname_by_user_id"], user_id, default=None)
            username = await _try_db_call(["get_username_by_user_id"], user_id, default=None)
        except Exception:
            first_name = None
            username = None

        two_init = int(tpl_fresh.get("start_amount") or 0)
        betlimit = tpl_fresh.get("betlimit")
        target_amount = int(tpl_fresh.get("target_amount") or 0)
        reward_amount = int(tpl_fresh.get("reward_amount") or 0)
        target_chat_ref = tpl_fresh.get("target_chat_ref")

        created = await _try_db_call(
            ["create_active_assignment"],
            user_id,
            template_id=template_id,
            first_name=first_name,
            username=username,
            two_balance_initial=two_init,
            betlimit=betlimit,
            target_amount=target_amount,
            reward_amount=reward_amount,
            default=False,
        )
        if not created:
            # откатываем слот, чтобы не сломать лимит
            await _try_db_call(["decrement_gc_template_completed"], template_id, step=1)
            return await _safe_answer("Не удалось взять задание. Попробуй ещё раз чуть позже.", True)

        # --- успех: показываем короткий экран успеха ---#
        await _safe_answer("Задание взято! Виртуальный баланс начислен.", True)

        short_lines = [
            "🎮 <b>Задание принято! Удачной игры.</b>",
            "",
            f"• Ваш стартовый виртуальный баланс: <b>{_fmt_dot(two_init)}</b> кут",
            f"• Цель по балансу: <b>{_fmt_dot(target_amount)}</b> кут",
            f"• Награда за выполнение: <b>{_fmt_dot(reward_amount)}</b> кут",
        ]
        if betlimit:
            short_lines.append(f"• Лимит ставки на игру: <b>{_fmt_dot(betlimit)}</b> кут")
        if target_chat_ref:
            short_lines.append(f"• Играть в: <code>{html.escape(str(target_chat_ref))}</code>")

        short_text = gc_html_replace_known("\n".join(short_lines))
        post_kb = await gc_build_after_take_kb(target_chat_ref)

        if callback_query.message:
            try:
                await _safe_edit_message_text(
                    chat_id=callback_query.message.chat.id,
                    message_id=callback_query.message.message_id,
                    text=short_text,
                    reply_markup=post_kb,
                    replacement_sticker=GC_STICKER34,
                )
            except Exception as e:
                _qdbg_exc("gc_start_callback: edit after take fail", e)

    except Exception as e:
        _qdbg_exc("gc_start_callback fail", e)
        await _safe_answer("Ошибка. Попробуй ещё раз.", True)


@dp.callback_query(lambda c: c.data and c.data.startswith("qst:gctake_force:"))
async def gc_take_force_callback(callback_query: types.CallbackQuery):
    """
    Форсированная замена активного игрового задания на новое.
    Тут тоже:
      - проверяем, что новое задание ещё активно и есть свободные слоты;
      - аккуратно снимаем старое задание (если есть) с возвратом слота;
      - резервируем слот на новое и создаём assignment;
      - при любой ошибке пытаемся «залечить» состояние.
    """
    user_id = callback_query.from_user.id
    parts = (callback_query.data or "").split(":")

    # форматы:
    #   qst:gctake_force:<new_template_id>
    #   qst:gctake_force:<new_template_id>:<old_assignment_id>  (старый формат, optional)
    if len(parts) < 3:
        await _gc_safe_answer(callback_query, "Неверные данные.", True)
        return

    async def _safe_answer(text: str = "", alert: bool = False):
        await _gc_safe_answer(callback_query, text, alert)

    try:
        new_template_id = int(parts[2])
    except Exception:
        return await _safe_answer("Неверное задание.", True)

    _qdbg(f"gc_take_force_callback: user={user_id}, new_template_id={new_template_id}")

    try:
        try:
            await callback_query.answer()
        except Exception:
            pass

        # грузим шаблон нового задания
        tpl = await _try_db_call(["get_gc_template_by_id"], new_template_id, default=None)
        if not tpl:
            return await _safe_answer("Шаблон нового задания недоступен.", True)

        status = str(tpl.get("status") or "active").lower()
        if status not in ("active", ""):
            return await _safe_answer("Это задание уже отключено.", True)

        # проверяем свободные слоты по новому шаблону ДО любых действий
        max_u = tpl.get("max_users")
        done_u = tpl.get("completed_users") or 0
        try:
            done_u = int(done_u)
        except Exception:
            done_u = 0

        def _slots_exhausted() -> bool:
            if max_u is None:
                return False
            try:
                max_u_int = int(max_u)
            except Exception:
                return False
            if max_u_int <= 0:
                return True
            return done_u >= max_u_int

        if _slots_exhausted():
            return await _safe_answer("Все слоты этого задания уже заняты.", True)

        # смотрим текущее активное задание
        existing = await _try_db_call(["get_active_gc_assignment"], user_id, default=None)
        if existing:
            try:
                existing_tid = int(existing.get("template_id") or 0)
            except Exception:
                existing_tid = 0

            # если по факту активное задание уже и так new_template_id -> просто показываем «Моё задание»
            if existing_tid == new_template_id:
                _qdbg(
                    f"gc_take_force_callback: user={user_id} already has new_template_id={new_template_id} active"
                )
                await _safe_answer("Этот челлендж уже у тебя активен.", True)
                try:
                    await gc_my_assignment_callback(callback_query)
                except Exception as e:
                    _qdbg_exc("gc_take_force_callback: gc_my_assignment_callback same-template fail", e)
                return

        # 1) снимаем текущее задание (если есть), возвращая слот старому шаблону
        removed = await _try_db_call(
            ["remove_assignment_by_user"],
            user_id,
            restore_slot=True,
            default=False
        )
        if removed:
            _qdbg(f"gc_take_force_callback: old assignment removed for user {user_id}")

        # 2) ещё раз проверим, что слоты нового задания не закончились (за время снятия старого)
        tpl_fresh = await _try_db_call(["get_gc_template_by_id"], new_template_id, default=None) or tpl
        max_u = tpl_fresh.get("max_users")
        done_u = tpl_fresh.get("completed_users") or 0
        try:
            done_u = int(done_u)
        except Exception:
            done_u = 0

        if _slots_exhausted():
            return await _safe_answer("Пока вы выбирали, слоты этого задания закончились.", True)

        # 3) резервируем слот под новое задание
        updated = await _try_db_call(
            ["increment_gc_template_completed"],
            new_template_id,
            step=1,
            default=False
        )
        if not updated:
            return await _safe_answer("Не удалось занять слот нового задания.", True)

        # 4) защитная проверка - вдруг уже появилось какое-то активное задание
        existing_after = await _try_db_call(["get_active_gc_assignment"], user_id, default=None)
        if existing_after:
            # странная ситуация - откатываем слот
            await _try_db_call(["decrement_gc_template_completed"], new_template_id, step=1)
            try:
                ex_tid = int(existing_after.get("template_id") or 0)
            except Exception:
                ex_tid = 0
            if ex_tid == new_template_id:
                await _safe_answer("Этот челлендж уже у тебя активен.", True)
                try:
                    await gc_my_assignment_callback(callback_query)
                except Exception as e:
                    _qdbg_exc("gc_take_force_callback: gc_my_assignment_callback after race fail", e)
            else:
                await _safe_answer("У тебя уже есть активное задание.", True)
            return

        # 5) создаём новое активное задание
        try:
            first_name = await _try_db_call(["get_firstname_by_user_id"], user_id, default=None)
            username = await _try_db_call(["get_username_by_user_id"], user_id, default=None)
        except Exception:
            first_name = None
            username = None

        two_init = int(tpl_fresh.get("start_amount") or 0)
        betlimit = tpl_fresh.get("betlimit")
        target_amount = int(tpl_fresh.get("target_amount") or 0)
        reward_amount = int(tpl_fresh.get("reward_amount") or 0)
        target_chat_ref = tpl_fresh.get("target_chat_ref")

        created = await _try_db_call(
            ["create_active_assignment"],
            user_id,
            template_id=new_template_id,
            first_name=first_name,
            username=username,
            two_balance_initial=two_init,
            betlimit=betlimit,
            target_amount=target_amount,
            reward_amount=reward_amount,
            default=False,
        )
        if not created:
            # откатываем занятый слот
            await _try_db_call(["decrement_gc_template_completed"], new_template_id, step=1)
            return await _safe_answer("Не удалось взять новое задание.", True)

        # успех - показываем короткий экран
        await _safe_answer("Вы переключились на новое задание ✅", True)

        short_lines = [
            "🎮 <b>Новое задание принято!</b>",
            "",
            f"• Ваш стартовый виртуальный баланс: <b>{_fmt_dot(two_init)}</b> кут",
            f"• Цель по балансу: <b>{_fmt_dot(target_amount)}</b> кут",
            f"• Награда за выполнение: <b>{_fmt_dot(reward_amount)}</b> кут",
        ]
        if betlimit:
            short_lines.append(f"• Лимит ставки на игру: <b>{_fmt_dot(betlimit)}</b> кут")
        if target_chat_ref:
            short_lines.append(f"• Играть в: <code>{html.escape(str(target_chat_ref))}</code>")

        short_text = gc_html_replace_known("\n".join(short_lines))
        post_kb = await gc_build_after_take_kb(target_chat_ref)

        if callback_query.message:
            try:
                await _safe_edit_message_text(
                    chat_id=callback_query.message.chat.id,
                    message_id=callback_query.message.message_id,
                    text=short_text,
                    reply_markup=post_kb,
                    replacement_sticker=GC_STICKER34,
                )
            except Exception as e:
                _qdbg_exc("gc_take_force_callback: edit fail", e)

    except Exception as e:
        _qdbg_exc("gc_take_force_callback unexpected fail", e)
        await _safe_answer("Ошибка при переключении задания. Попробуйте ещё раз.", True)


