# ✅ УТИЛИТЫ (один раз, без дублей)
# ============================================================
def _wd_safe_int(v, default: int = 0) -> int:
    try:
        return int(v)
    except Exception:
        return int(default)


def _wd_safe_str(v, default: str = "") -> str:
    try:
        if v is None:
            return default
        s = str(v).strip()
        return s if s else default
    except Exception:
        return default


def _wd_fmt_cd_mmss(seconds: int) -> str:
    try:
        seconds = max(0, int(seconds))
    except Exception:
        seconds = 0
    mm = seconds // 60
    ss = seconds % 60
    return f"{mm:02d}:{ss:02d}"


def _wd_fail(error: str, **extra) -> Dict[str, Any]:
    data = {
        "ok": False,
        "committed": False,
        "duplicate": False,
        "should_send_to_channel": False,
        "error": str(error),
        "status": str(error),
    }
    if extra:
        data.update(extra)
    return data
def _to_int(v: Any, default: int = 0) -> int:
    try:
        if v is None:
            return default
        if isinstance(v, str):
            v = v.strip().replace(" ", "").replace(".", "")
            if not v:
                return default
        return int(float(v))
    except Exception:
        return default


def _fmt_int(x: Any) -> str:
    """Формат 12.345 (как у тебя в UI)."""
    try:
        return "{:,.0f}".format(int(_to_int(x, 0))).replace(",", ".")
    except Exception:
        return "0"


def _fmt_hms(total_seconds: Any) -> str:
    """Формат секунд в HH:MM:SS или MM:SS."""
    s = max(0, _to_int(total_seconds, 0))
    h = s // 3600
    m = (s % 3600) // 60
    sec = s % 60
    return f"{h:02d}:{m:02d}:{sec:02d}" if h > 0 else f"{m:02d}:{sec:02d}"


async def _safe_edit_text(
    message: types.Message,
    text: str,
    *,
    reply_markup: Optional[InlineKeyboardMarkup] = None,
    parse_mode: str = "HTML",
    disable_web_page_preview: bool = True,
) -> None:
    """Безопасное edit_text: если нельзя отредактировать - отправим новое."""
    try:
        await message.edit_text(
            text,
            parse_mode=parse_mode,
            reply_markup=reply_markup,
            disable_web_page_preview=disable_web_page_preview,
        )
    except Exception as e:
        try:
            await message.answer(
                text,
                parse_mode=parse_mode,
                reply_markup=reply_markup,
                disable_web_page_preview=disable_web_page_preview,
            )
        except Exception as e2:
            print(f"[SAFE_EDIT][ERROR] edit_text failed={e!r}, answer failed={e2!r}")


