# ✅ КЛАВИАТУРЫ
# ============================================================

def _normalize_add_withdraw_result(raw: Any, *, strict_used: bool, rid: str) -> Dict[str, Any]:
    """
    Приводит ответ db.add_withdraw_strict / db.add_withdraw к одному формату.
    """

    if not raw:
        return {
            "ok": False,
            "committed": False,
            "duplicate": False,
            "should_send_to_channel": False,
            "error": "empty_response",
            "status": "empty_response",
            "request_id": rid,
        }

    if not isinstance(raw, dict):
        return {
            "ok": False,
            "committed": False,
            "duplicate": False,
            "should_send_to_channel": False,
            "error": "bad_db_response",
            "status": "bad_db_response",
            "request_id": rid,
            "raw_type": type(raw).__name__,
        }

    ok = bool(raw.get("ok"))
    duplicate = bool(raw.get("duplicate"))
    committed = bool(raw.get("committed"))
    status = _wd_safe_str(raw.get("status"), "")
    error = _wd_safe_str(raw.get("error"), "")

    if duplicate:
        committed = False

    if strict_used:
        if "should_send_to_channel" in raw:
            should_send = bool(raw.get("should_send_to_channel"))
        else:
            should_send = bool(ok and committed and not duplicate)

        if duplicate:
            should_send = False

        if not status:
            if duplicate:
                status = "duplicate"
            elif ok and committed:
                status = "committed"
            elif ok:
                status = "ok"
            else:
                status = error or "error"

        norm = dict(raw)
        norm["ok"] = ok
        norm["duplicate"] = duplicate
        norm["committed"] = committed
        norm["should_send_to_channel"] = should_send
        norm["status"] = status
        norm["request_id"] = _wd_safe_str(raw.get("request_id"), rid) or rid
        return norm

    if ok:
        committed = True
        duplicate = False
        should_send = True
        if not status:
            status = "committed"
    else:
        committed = False
        duplicate = False
        should_send = False
        if not status:
            status = error or "error"

    norm = dict(raw)
    norm["ok"] = ok
    norm["duplicate"] = duplicate
    norm["committed"] = committed
    norm["should_send_to_channel"] = should_send
    norm["status"] = status
    norm["request_id"] = _wd_safe_str(raw.get("request_id"), rid) or rid
    return norm


def _kb_info_back(left_seconds: int, back_callback: Optional[str] = None) -> InlineKeyboardMarkup:
    """
    Экран блокировки вывода: подождите обновления лимита + таймер.
    back_callback:
      - если пришли из баланса -> возвращаем туда
      - иначе закрываем/в меню (как у тебя было)
    """
    left_i = _to_int(left_seconds, 0)
    back_cd = str(back_callback) if back_callback else "9close_bonus"
    try:
        return _kb_withdraw_locked(
            left_i,
            reason="cooldown_active" if left_i > 0 else "unspendable_remainder",
            back_callback=back_cd,
        )
    except Exception:
        back_text = "Назад к балансу" if back_callback else "Назад"
        rows = [
            [InlineKeyboardButton(
                text="Вывод временно недоступен",
                callback_data="noop",
                style="danger",
                icon_custom_emoji_id="5449505950283078474",
            )],
            [InlineKeyboardButton(
                text="Дождитесь обновления лимита",
                callback_data="noop",
                style="default",
                icon_custom_emoji_id="5420542898452077602",
            )],
        ]
        if left_i > 0:
            rows.append([InlineKeyboardButton(
                text=f"Осталось : {_fmt_hms(left_i)}",
                callback_data="noop",
                style="default",
                icon_custom_emoji_id="5891211339170326418",
            )])
        rows.append([InlineKeyboardButton(
            text=back_text,
            callback_data=back_cd,
            style="default",
            icon_custom_emoji_id="5960671702059848143",
        )])
        return InlineKeyboardMarkup(inline_keyboard=rows)


