# ============================================================
def _resolve_db_or_none() -> Optional[Any]:
    """
    Пытается найти объект БД в globals() по популярным именам.
    Возвращает объект или None.
    """
    g = globals()

    candidates = [
        g.get("db"),
        g.get("database"),
        g.get("DB"),
        g.get("db1"),
    ]

    for obj in candidates:
        if obj is None:
            continue
        # главный маркер: должны существовать нужные методы
        if hasattr(obj, "refresh_withdraw_quota_if_needed") and hasattr(obj, "get_user_balance"):
            return obj

    return None


def _fmt_dot_int(v: int) -> str:
    try:
        return "{:,.0f}".format(int(v)).replace(",", ".")
    except Exception:
        return str(v)
async def ensure_has_referrals(
    cb: types.CallbackQuery,
    user_id: int,
    *,
    min_required: int = 0,
    db_obj: Optional[Any] = None,
) -> bool:
    """
    Возвращает True если рефералов хватает.
    НЕ падает, если db_obj=None - будет понятный лог и alert.
    """
    uid = int(user_id)
    need = int(min_required or 0)

    if need <= 0:
        print(f"[REF][CHECK] uid={uid} need=0 -> OK")
        return True

    dbx = db_obj or _resolve_db_or_none()
    if dbx is None:
        print(f"[REF][FATAL] db is None -> cannot check referrals uid={uid}")
        try:
            await cb.answer("⚠️ Ошибка системы: база данных не готова. Попробуйте позже.", show_alert=True)
        except Exception:
            pass
        return False

    # твой метод (с орфографией как у тебя)
    try:
        ref_count = await dbx.get_refferals_count(uid)  # <-- оставил твоё имя метода
        ref_count = int(ref_count or 0)
    except Exception as e:
        print(f"[REF][ERROR] get_refferals_count failed uid={uid}: {e!r}")
        ref_count = 0

    print(f"[REF][CHECK] uid={uid} ref_count={ref_count} need={need}")

    if ref_count < need:
        try:
            await cb.answer(f"⚠️ Нужно пригласить {need} друзей. Сейчас : {ref_count}\nНапишите 'хелп реф' в бот и отправьте пригласительную ссылку другу", show_alert=True)
        except Exception:
            pass
        return False

    return True



