async def get_all_gifts_minimal(bot1) -> List[Dict[str, Any]]:
    """
    Единый метод: получаем список подарков и приводим к стабильному формату.
    """
    try:
        resp = await bot1.get_available_gifts()
        gift_list = getattr(resp, "gifts", []) or []
    except Exception as e:
        print(f"[GIFTS][ERROR] get_available_gifts failed: {e!r}")
        return []

    result: List[Dict[str, Any]] = []
    for gift in gift_list:
        try:
            gid = getattr(gift, "id", None)
            if gid is None:
                continue

            sticker = getattr(gift, "sticker", None)
            emoji = getattr(sticker, "emoji", "🎁") if sticker else "🎁"

            price = _to_int(getattr(gift, "star_count", 0), 0)
            up = getattr(gift, "upgrade_star_count", None)
            upgrade_price = _to_int(up, 0) if up is not None else 0
            has_upgrade = bool(up is not None)

            # price должен быть >0 чтобы был “вывод”
            if price <= 0:
                continue

            result.append(
                {
                    "id": str(gid),
                    "emoji": emoji,
                    "price": int(price),
                    "upgrade_price": int(upgrade_price),
                    "has_upgrade": int(has_upgrade),
                }
            )
        except Exception as e:
            print(f"[GIFTS][WARN] parse gift failed: {e!r}")

    print(f"[GIFTS][OK] loaded={len(result)}")
    return result


async def build_affordable_gifts_keyboard(
    gifts: List[Dict[str, Any]],
    *,
    remaining: Optional[int] = None,
) -> InlineKeyboardMarkup:
    """
    Покажем кнопки подарков (по 2 в ряд) + моментальный вывод если remaining>=50.
    Формат callback_data оставил твоим: btnstars_{gift_id}_{price}_{upgrade_price}_0
    """
    rem = _to_int(remaining, 0)
    keyboard_buttons: List[List[InlineKeyboardButton]] = []
    row: List[InlineKeyboardButton] = []

    for g in gifts:
        try:
            gid = str(g.get("id") or "").strip()
            price = _to_int(g.get("price"), 0)
            up = _to_int(g.get("upgrade_price"), 0)
            has_up = bool(_to_int(g.get("has_upgrade"), 0))

            if not gid or price <= 0:
                continue
            if rem > 0 and price > rem:
                continue

            emoji = g.get("emoji") or "🎁"
            formatted_price = _fmt_int(price)

            text = f"{emoji} | {formatted_price} ⭐️ [ NFT ]" if has_up else f"{emoji} | {formatted_price} ⭐️"
            cd = f"btnstars_{gid}_{price}_{up}_0"

            row.append(InlineKeyboardButton(text=text, callback_data=cd))
            if len(row) == 2:
                keyboard_buttons.append(row)
                row = []

        except Exception as e:
            print(f"[GIFTS][WARN] build button failed: {e!r}")

    if row:
        keyboard_buttons.append(row)

    # ⚡ моментальный вывод (если >= 50)
    if rem >= 50:
        keyboard_buttons.append(
            [InlineKeyboardButton(text=f"Моментальный вывод ({_fmt_int(rem)})", callback_data=f"speedwithdrawal:{rem}", style="default" ,
                icon_custom_emoji_id="5397976749436842796")]
        )

    keyboard_buttons.append([InlineKeyboardButton(text=" ", callback_data="9close_bonus", style="default" ,
                icon_custom_emoji_id="5226660202035554522")])
    return InlineKeyboardMarkup(inline_keyboard=keyboard_buttons)


