async def ensure_can_withdraw(
    cb: types.CallbackQuery,
    user_id: int,
    *,
    amount: int,
    mode: Optional[str] = None,
    db_obj: Optional[Any] = None,
) -> bool:
    """
    Проверка лимитов вывода через db.refresh_withdraw_quota_if_needed().
    amount - сколько пользователь хочет вывести (в кут).
    """
    uid = int(user_id)
    amt = int(amount or 0)
    if amt <= 0:
        print(f"[WITHDRAW][CHECK] uid={uid} invalid amount={amt}")
        try:
            await cb.answer("⚠️ Неверная сумма.", show_alert=True)
        except Exception:
            pass
        return False

    dbx = db_obj or _resolve_db_or_none()
    if dbx is None:
        print(f"[WITHDRAW][FATAL] db is None -> cannot check limits uid={uid}")
        try:
            await cb.answer("⚠️ Ошибка системы: база данных не готова. Попробуйте позже.", show_alert=True)
        except Exception:
            pass
        return False

    try:
        min_w = int(await get_min_gift_price_now(bot1) or 0)
    except Exception:
        min_w = 0

    try:
        st = await dbx.refresh_withdraw_quota_if_needed(uid, min_withdraw_amount=int(min_w or 0))
    except Exception as e:
        print(f"[WITHDRAW][ERROR] refresh_withdraw_quota_if_needed failed uid={uid}: {e!r}")
        try:
            await cb.answer("⚠️ Ошибка лимитов. Попробуйте позже.", show_alert=True)
        except Exception:
            pass
        return False

    allowed = bool(st.get("allowed"))
    remaining = int(st.get("remaining") or 0)
    daily_limit = int(st.get("daily_limit") or 0)
    used = st.get("used")
    cooldown_left = int(st.get("cooldown_left") or 0)
    reason = str(st.get("reason") or "")
    if min_w > 0 and remaining > 0 and remaining < min_w:
        allowed = False
        reason = reason or "unspendable_remainder"

    print(f"🟦 Лимиты(UI-STATE): allowed={allowed} limit={daily_limit} used={used} remaining={remaining} cd_left={cooldown_left} cause='{reason}'")

    # кулдаун / крошки < мин. подарка / need_higher
    if not allowed:
        try:
            if cooldown_left > 0:
                await cb.answer(f"⏳ Кулдаун активен. Осталось: {cooldown_left} сек.", show_alert=True)
            elif cooldown_left > 0 or reason in (
                "unspendable_remainder",
                "unspendable_cap",
                "need_higher_limit",
                "min_withdraw_block",
            ) or (min_w > 0 and remaining < min_w):
                await cb.answer(
                    "⏳ Вывод временно недоступен. Дождитесь обновления лимита.",
                    show_alert=True,
                )
            else:
                await cb.answer("⚠️ Вывод временно недоступен. Дождитесь обновления лимита.", show_alert=True)
        except Exception:
            pass
        return False

    # лимит выбит (remaining=0)
    if remaining <= 0:
        try:
            await cb.answer("⚠️ Лимит вывода исчерпан. Подождите обновления лимита.", show_alert=True)
        except Exception:
            pass
        return False

    # сумма меньше самого дешёвого подарка
    if min_w > 0 and amt < min_w:
        try:
            await cb.answer(
                f"⚠️ Минимальный вывод: {_fmt_dot_int(min_w)} ⭐ (самый дешёвый подарок).",
                show_alert=True,
            )
        except Exception:
            pass
        return False

    # не хватает на сумму
    if amt > remaining:
        try:
            await cb.answer(
                f"⚠️ Доступно для вывода: {_fmt_dot_int(remaining)} кут.\n"
                f"Вы хотите: {_fmt_dot_int(amt)} кут.",
                show_alert=True
            )
        except Exception:
            pass
        return False

    return True


# ============================================================
# ✅ АКТИВНОСТЬ В ОФИЦИАЛЬНЫХ ГРУППАХ (условие вывода)
# ------------------------------------------------------------
# Игрок должен написать MESSAGE_CHECK_WITHDRAWAL сообщений за сегодня
# хотя бы в ОДНОЙ из официальных групп проекта (MuteConfig.STAFF_CHAT_IDS).
# Данные о группах (название + ссылка) берём напрямую из Telegram и кешируем.
# ============================================================

# Кеш ссылок на официальные группы:
#   chat_id -> (expires_ts, (title, url))  для успешного резолва
#   chat_id -> (expires_ts, None)          для временной "негативной" записи
# Негативный кеш нужен, чтобы не долбить Telegram повторными get_chat для чатов,
# где бот уже кикнут/недоступен (иначе логи зашумляются Forbidden-ошибками).
_staff_link_cache: Dict[int, Tuple[float, Optional[Tuple[str, str]]]] = LazyGameStore("_staff_link_cache")
_STAFF_LINK_TTL = 3600.0  # 1 час
_STAFF_LINK_NEGATIVE_TTL = 86400.0  # 24 часа


def _resolve_staff_link_from_config(chat_id: int) -> Optional[Tuple[str, str]]:
    """
    Быстрый fallback без Telegram API:
    берём ссылку на чат из bot.config.config, если chat_id совпадает.
    Это убирает лишние get_chat() для чатов, где бота кикнули.
    """
    try:
        from bot.config import config as _cfg

        cid = int(chat_id)
        cfg_chat_id = _wd_safe_int(getattr(_cfg, "chat_id", 0), 0)
        cfg_test_id = _wd_safe_int(getattr(_cfg, "test_id", 0), 0)
        cfg_chat_link = _wd_safe_str(getattr(_cfg, "chat_link", ""), "")
        cfg_chat_name = _wd_safe_str(getattr(_cfg, "target_chat_username", ""), "")

        if cid in {cfg_chat_id, cfg_test_id} and cfg_chat_link.startswith("https://t.me/"):
            title = cfg_chat_name or f"official chat {cid}"
            return title, cfg_chat_link
    except Exception:
        return None
    return None


async def _resolve_chat_link(bot_obj: Any, chat_id: int) -> Optional[Tuple[str, str]]:
    """
    Возвращает (название, ссылка) официальной группы, спрашивая сам Telegram.
    Публичные группы → https://t.me/username, приватные → invite_link
    (при необходимости запрашиваем/экспортируем ссылку-приглашение).
    Результат кешируется на _STAFF_LINK_TTL секунд. None — если ссылку не достать.
    """
    cid = int(chat_id)
    now = time.time()

    cached = _staff_link_cache.get(cid)
    if cached and cached[0] > now:
        return cached[1]

    cfg_fallback = _resolve_staff_link_from_config(cid)
    if cfg_fallback:
        _staff_link_cache[cid] = (now + _STAFF_LINK_TTL, cfg_fallback)
        return cfg_fallback

    try:
        chat = await bot_obj.get_chat(cid)
    except Exception as e:
        print(f"[STAFFLINK][WARN] get_chat({cid}) failed: {e!r}")
        if cached:
            return cached[1]
        _staff_link_cache[cid] = (now + _STAFF_LINK_NEGATIVE_TTL, None)
        return None

    title = str(getattr(chat, "title", None) or getattr(chat, "full_name", None) or cid)

    url: Optional[str] = None
    username = getattr(chat, "username", None)
    if username:
        url = f"https://t.me/{username}"
    else:
        invite = getattr(chat, "invite_link", None)
        if not invite:
            try:
                invite = await bot_obj.export_chat_invite_link(cid)
            except Exception as e:
                print(f"[STAFFLINK][WARN] export invite for {cid} failed: {e!r}")
                invite = None
        url = invite

    if not url:
        if cached:
            return cached[1]
        _staff_link_cache[cid] = (now + _STAFF_LINK_NEGATIVE_TTL, None)
        return None

    result = (title, url)
    _staff_link_cache[cid] = (now + _STAFF_LINK_TTL, result)
    return result


async def _build_staff_groups_keyboard(
    bot_obj: Any,
    *,
    back_btn: Optional[InlineKeyboardButton] = None,
) -> InlineKeyboardMarkup:
    """
    Клавиатура со ссылками на все официальные группы (STAFF_CHAT_IDS),
    по 2 кнопки в ряд, плюс кнопка «Назад» (если передана).
    """
    from bot.admins.mute import MuteConfig

    rows: List[List[InlineKeyboardButton]] = []
    temp: List[InlineKeyboardButton] = []

    for cid in MuteConfig.STAFF_CHAT_IDS:
        info = await _resolve_chat_link(bot_obj, int(cid))
        if not info:
            continue
        title, url = info
        temp.append(InlineKeyboardButton(text=f"{title}", url=url, style="default" ,
                icon_custom_emoji_id="5778208881301787450"))
        if len(temp) == 2:
            rows.append(temp)
            temp = []
    if temp:
        rows.append(temp)

    if back_btn is not None:
        rows.append([back_btn])

    return InlineKeyboardMarkup(inline_keyboard=rows)


async def ensure_daily_messages(
    cb: types.CallbackQuery,
    user_id: int,
    *,
    back_btn: Optional[InlineKeyboardButton] = None,
    bot_obj: Optional[Any] = None,
) -> bool:
    """
    Проверяет активность игрока в официальных группах как условие вывода.

    Возвращает True, если за сегодня написано не менее MESSAGE_CHECK_WITHDRAWAL
    сообщений хотя бы в одной официальной группе (через db.get_daily_messages9999).

    Политика «не мешать выводу из-за наших сбоев» (fail-open):
        • проверка отключена (порог <= 0) → True;
        • БД недоступна или запрос упал → True (не блокируем игрока);
    Блокируем (False) ТОЛЬКО когда БД точно ответила «сообщений не хватило» —
    тогда показываем сообщение с кнопками на официальные группы и «Назад».
    """
    uid = int(user_id)

    # Порог берём лениво, чтобы правка конфига не требовала перезапуска импорта.
    try:
        from bot.config.config import MESSAGE_CHECK_WITHDRAWAL as _MCW
    except Exception:
        _MCW = 250
    need = int(_MCW or 0)
    if need <= 0:
        return True  # проверка отключена глобально

    if db is None:
        print(f"[MSGCHK][FATAL] db is None uid={uid} → пропускаем (не блокируем)")
        return True

    try:
        ok = await db.get_daily_messages9999(uid)
    except Exception as e:
        print(f"[MSGCHK][ERROR] get_daily_messages9999 uid={uid}: {e!r} → пропускаем")
        return True

    if ok:
        return True

    print(f"⛔[MSGCHK] uid={uid} blocked (need>={need} in one staff group)")
    text, kb = await _build_staff_progress_ui(uid, need, back_btn=back_btn, bot_obj=bot_obj)
    await _safe_edit_or_alert(cb, text, kb=kb)
    return False


async def _build_staff_progress_ui(
    user_id: int,
    need: int,
    *,
    back_btn: Optional[InlineKeyboardButton] = None,
    bot_obj: Optional[Any] = None,
) -> Tuple[str, InlineKeyboardMarkup]:
    """
    Минималистичный экран прогресса активности для вывода:
      • правило (сообщения от N слов),
      • по каждой официальной группе: сколько написано и сколько осталось,
      • кнопки-ссылки на группы + «Назад».
    Данные о группах берём из Telegram (кеш), счётчики — из БД. Всё best-effort:
    любой сбой не роняет вывод, а даёт упрощённый вид.
    """
    from bot.admins.mute import MuteConfig

    botx = bot_obj or bot1

    try:
        from bot.config.config import MESSAGE_MIN_WORDS as _MMW
    except Exception:
        _MMW = 2
    min_words = int(_MMW or 2)

    try:
        counts = await db.get_staff_daily_counts(int(user_id))
    except Exception as e:
        print(f"[MSGCHK][COUNTS][WARN] uid={user_id}: {e!r}")
        counts = {}

    rows: List[List[InlineKeyboardButton]] = []
    temp: List[InlineKeyboardButton] = []
    lines: List[str] = []

    for cid in MuteConfig.STAFF_CHAT_IDS:
        cid_i = int(cid)
        cnt = int(counts.get(cid_i, 0))
        rem = max(0, need - cnt)

        info = await _resolve_chat_link(botx, cid_i)
        raw_title = info[0] if info else str(cid_i)
        title = escape(str(raw_title))
        url = info[1] if info else None

        if rem <= 0:
            lines.append(
                f"<tg-emoji emoji-id='5260463209562776385'>✅</tg-emoji> <b>{title} - <i>{_fmt_dot(cnt)}/{_fmt_dot(need)}</i></b>"
            )
        else:
            lines.append(
                f"<tg-emoji emoji-id='6019107055699236857'>💬</tg-emoji> <b>{title} - <i>{_fmt_dot(cnt)}/{_fmt_dot(need)}</i> · </b>"
                f"<b>осталось {_fmt_dot(rem)}</b>"
            )

        if url:
            temp.append(InlineKeyboardButton(text=f"{raw_title}", url=url, style="default" ,
                icon_custom_emoji_id="5778208881301787450"))
            if len(temp) == 2:
                rows.append(temp)
                temp = []

    if temp:
        rows.append(temp)
    kb = InlineKeyboardMarkup(inline_keyboard=rows)

    body = "\n".join(lines) if lines else "<i>Официальные группы не настроены.</i>"

    text = (
        f"<tg-emoji emoji-id='5353037965452943794'>🗽</tg-emoji> <b>Вывод откроется после написания {_fmt_dot(need)} сообщений за сегодня "
        f"в одной из официальных групп.</b>\n"
        f"<blockquote><b><i><tg-emoji emoji-id='5362082573872810652'>▪️</tg-emoji><tg-emoji emoji-id='5361951895197861262'>▪️</tg-emoji><tg-emoji emoji-id='5361807197749658770'>▪️</tg-emoji> Сообщения засчитываются от {min_words} слов "
        f"(например «привет как дела»). Короткие «привет» не в счёт.</i></b>  </blockquote>\n"
        f"{body}"
    )
    return text, kb


