# best-effort: тип исключения asyncpg
try:
    from asyncpg.exceptions import NumericValueOutOfRangeError
except Exception:
    NumericValueOutOfRangeError = Exception


def _is_numeric_overflow_exc(e: Exception) -> bool:
    """
    Узнаём overflow надёжно:
    - по типу (если asyncpg импортнулся)
    - по имени типа / тексту (fallback)
    """
    try:
        if isinstance(e, NumericValueOutOfRangeError):
            return True
    except Exception:
        pass

    name = str(type(e).__name__ or "")
    text = str(e or "")
    if "NumericValueOutOfRangeError" in name or "NumericValueOutOfRangeError" in text:
        return True
    if "переполнение" in text.lower():
        return True
    return False


async def ensure_add_withdraw(
    user_id: int,
    amount: int,
    *,
    db=None,
    reason: str = "user_payout",
    request_id: Optional[str] = None,
    chat_id: Optional[int] = None,
    chat_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    ЕДИНСТВЕННАЯ точка, где должен происходить атомарный учёт вывода.

    ВАЖНО:
    - здесь можно списывать баланс
    - здесь можно проверять лимит/кулдаун
    - здесь можно выставлять cooldown ТОЛЬКО после реального commit
    - НЕЛЬЗЯ вызывать логику, которая просто "смотрит UI", но пишет в БД

    Ожидается, что db.add_withdraw_strict(...) сам:
    - проверяет баланс
    - проверяет active cooldown
    - проверяет remaining daily/period limit
    - делает новый commit
    - и только если commit прошёл, обновляет used / cooldown
    """

    uid = _wd_safe_int(user_id, 0)
    amt = _wd_safe_int(amount, -1)

    if uid <= 0:
        print(f"🟥[WITHDRAW][ADD][ABORT] bad uid={user_id!r} -> uid={uid}")
        return _wd_fail("bad_user_id")

    if amt <= 0:
        print(f"🟥[WITHDRAW][ADD][ABORT] uid={uid} invalid amount={amount!r} -> amt={amt}")
        return _wd_fail("invalid_amount")

    if db is None:
        try:
            db = globals().get("db")
            print(f"🟨[WITHDRAW][ADD][DB] db=None -> globals()['db']={type(db).__name__}")
        except Exception as e:
            print(f"🟥[WITHDRAW][ADD][DB][ERROR] globals db resolve failed: {type(e).__name__}: {e!r}")
            db = None

    if db is None:
        print(f"🟥[WITHDRAW][ADD][ABORT] uid={uid} db=None")
        return _wd_fail("db_missing")

    try:
        if hasattr(db, "is_connected") and callable(getattr(db, "is_connected", None)):
            is_conn = await db.is_connected()
            if not is_conn and hasattr(db, "connect") and callable(getattr(db, "connect", None)):
                print(f"🟨[WITHDRAW][ADD][DB] not connected -> connect()")
                await db.connect()
                print(f"🟩[WITHDRAW][ADD][DB] connect OK")
    except Exception as e:
        print(f"🟧[WITHDRAW][ADD][DB][WARN] connect-check warn: {type(e).__name__}: {e!r}")

    rid = _wd_safe_str(request_id, "")
    if not rid:
        rid = uuid.uuid4().hex[:16]
    rid = rid[:64].strip() or uuid.uuid4().hex[:16]

    use_strict = hasattr(db, "add_withdraw_strict") and callable(getattr(db, "add_withdraw_strict", None))
    use_basic = hasattr(db, "add_withdraw") and callable(getattr(db, "add_withdraw", None))

    if not use_strict and not use_basic:
        print(f"🟥[WITHDRAW][ADD][ABORT] uid={uid} no add_withdraw_strict/add_withdraw")
        return _wd_fail("db_method_missing", request_id=rid)

    print(
        f"🟦[WITHDRAW][ADD] uid={uid} amount={amt} reason={reason!r} "
        f"rid={rid} chat_id={chat_id} chat_name={chat_name!r} strict={use_strict}"
    )

    try:
        if use_strict:
            print("🟦[WITHDRAW][ADD] -> db.add_withdraw_strict(...)")
            try:
                raw_res = await db.add_withdraw_strict(
                    user_id=uid,
                    amount=amt,
                    request_id=rid,
                    chat_id=chat_id,
                    chat_name=chat_name,
                    reason=reason,
                )
            except TypeError as e_sig:
                print(f"🟨[WITHDRAW][ADD][STRICT][SIG] kwargs mismatch: {e_sig!r} -> positional")
                raw_res = await db.add_withdraw_strict(
                    uid,
                    amt,
                    request_id=rid,
                    chat_id=chat_id,
                    chat_name=chat_name,
                    reason=reason,
                )
        else:
            print("🟦[WITHDRAW][ADD] -> db.add_withdraw(...)")
            try:
                raw_res = await db.add_withdraw(
                    user_id=uid,
                    amount=amt,
                    chat_id=chat_id,
                    chat_name=chat_name,
                    reason=reason,
                    request_id=rid,
                )
            except TypeError as e_sig:
                print(f"🟨[WITHDRAW][ADD][BASIC][SIG] kwargs mismatch: {e_sig!r} -> positional")
                raw_res = await db.add_withdraw(
                    uid,
                    amt,
                    chat_id,
                    chat_name,
                    reason,
                    request_id=rid,
                )

    except Exception as e:
        err_type = type(e).__name__
        err_text = _wd_safe_str(repr(e), "unknown_db_exception")

        if "_is_numeric_overflow_exc" in globals() and callable(globals().get("_is_numeric_overflow_exc")):
            try:
                if _is_numeric_overflow_exc(e):
                    print(f"🟥[WITHDRAW][ADD][OVERFLOW] uid={uid} amount={amt} rid={rid}")
                    return _wd_fail(
                        "db_overflow",
                        request_id=rid,
                        db_exception_type=err_type,
                        db_exception=err_text,
                    )
            except Exception:
                pass

        print(f"🟥[WITHDRAW][ADD][ERROR] db call failed: {err_type}: {e!r}")
        return _wd_fail(
            "db_error",
            request_id=rid,
            db_exception_type=err_type,
            db_exception=err_text,
        )

    res = _normalize_add_withdraw_result(raw_res, strict_used=use_strict, rid=rid)

    if not res.get("ok"):
        print(f"🟥[WITHDRAW][ADD][FAIL] uid={uid} res={res!r}")
        return res

    print(
        f"🟩[WITHDRAW][ADD][OK] uid={uid} "
        f"status={res.get('status')!r} "
        f"committed={res.get('committed')} "
        f"duplicate={res.get('duplicate')} "
        f"should_send={res.get('should_send_to_channel')} "
        f"res={res!r}"
    )
    return res


