async def show_available_gifts_under_limit(
    callback_query: types.CallbackQuery,
    user_id: int,
    *,
    remaining: int,
    cooldown_sec: int,
    db=None,
    bot1=None,
    process_gifts_list=None,
) -> bool:
    """
    Показывает подарки под remaining.
    Если подходящих нет (остаток < мин. подарка) — экран ожидания обновления лимита.
    """
    msg = callback_query.message
    uid = _to_int(user_id, 0)
    rem = _to_int(remaining, 0)

    print(f"[GIFTS][SHOW] uid={uid} remaining={rem}")

    gifts = await get_all_gifts_minimal(bot1)
    available = [g for g in gifts if _to_int(g.get("price"), 0) <= rem]

    if not available:
        print("[GIFTS][NONE] нет подарков под лимит -> ждём обновления лимита")

        left = 0
        reason = "unspendable_remainder"
        try:
            min_w = 0
            try:
                min_w = int(await get_min_gift_price_now(bot1) or 0)
            except Exception:
                min_w = 0
            if db is not None and hasattr(db, "refresh_withdraw_quota_if_needed"):
                st = await db.refresh_withdraw_quota_if_needed(
                    uid, min_withdraw_amount=int(min_w or 0)
                )
                left = _to_int(st.get("cooldown_left"), 0)
                reason = str(st.get("reason") or st.get("cause") or reason)
            if left <= 0:
                left = _to_int(await db.get_user_cooldown_left(uid), 0) if db is not None else 0
        except Exception as e:
            print(f"[GIFTS][NONE][WARN] refresh/cooldown: {e!r}")
            left = 0

        await _safe_edit_text(
            msg,
            "🧰",
            reply_markup=_kb_withdraw_locked(
                left,
                remaining=rem,
                reason=reason,
            ),
        )
        return False

    # keyboard
    if callable(process_gifts_list):
        kb = await process_gifts_list(available, remaining=rem, speed_allowed=(rem >= 50), owner_id=uid, back_callback=None)
    else:
        kb = await build_affordable_gifts_keyboard(available, remaining=rem)

    await _safe_edit_text(
        msg,
        (
            "<tg-emoji emoji-id='5269288899204640214'>🎁</tg-emoji> <b>Доступные подарки для вывода</b>\n"
            f"<tg-emoji emoji-id='5472404950673791399'>🧮</tg-emoji> Лимит доступного вывода : <b>{_fmt_int(rem)} <tg-emoji emoji-id='5897658922600240288'>⭐️</tg-emoji></b>\n\n"
            "Выберите подарок:"
        ),
        reply_markup=kb,
    )
    return True

