hide_requests: set[tuple[int, str]] = set()
pending_desc: set[int] = set()
# Включите тестовый режим, чтобы всегда показывать кнопку «Улучшить NFT»
TEST_MODE = False  #True  # → поменяйте на False для обычного режима
async def build_options_keyboard(session_id: str) -> InlineKeyboardMarkup:
    """
    Создаёт клавиатуру опций:
    • Переключатель скрытия имени отправителя
    • Кнопка ввода/изменения описания
    • Кнопка сброса описания
    • Переключатель улучшения NFT (если доступно или в тестовом режиме)
    • Кнопка отправки подарка
    • Кнопка отмены
    """
    session = session_data.get(session_id, {})
    hide = session.get("hide", False)
    desc = session.get("desc")
    real_upgrade_available = session.get("upgrade_available", False)
    upgrade_available = TEST_MODE or real_upgrade_available
    upgrade = session.get("upgrade", False)

    buttons = []

    # Текст для кнопки скрытия/показа имени
    hide_text = "Показать имя" if hide else "Скрыть имя"
    hide_text2 = "5454096630372379732" if hide else "5188216731453103384"
    # Текст для кнопки ввода или изменения описания
    desc_text = "Описание" if desc else "Описание"
    desc_text2 = "5334673106202010226" if desc else "5334673106202010226"

    # 1) Строка: переключатель скрытия имени + кнопка ввода/изменения описания
    buttons.append([
        InlineKeyboardButton(text=hide_text, callback_data=f"gift_hide|{session_id}", style="default" ,
                icon_custom_emoji_id=hide_text2),
        InlineKeyboardButton(text=desc_text, callback_data=f"gift_desc|{session_id}", style="default" ,
                icon_custom_emoji_id=desc_text2)
    ])

    # 2) Строка: сброс описания
    buttons.append([
        InlineKeyboardButton(
            text="Сбросить описание",
            callback_data=f"gift_reset_desc|{session_id}", style="default" ,
                icon_custom_emoji_id="5395325195542078574"
        )
    ])

    # 3) Строка: переключатель улучшения NFT (если доступно)
    if upgrade_available:
        up_text = "Улучшить NFT" if upgrade else "Улучшение NFT"


        up_text2 = "5197688912457245639" if upgrade else "5017058788604117831"
        buttons.append([
            InlineKeyboardButton(
                text=up_text,
                callback_data=f"gift_toggle_upgrade|{session_id}", style="default" ,
                icon_custom_emoji_id=up_text2
            )
        ])

    # 4) Строка: отправить подарок
    buttons.append([
        InlineKeyboardButton(
            text="Отправить подарок",
            callback_data=f"gift_confirm|{session_id}", style="success" ,
                icon_custom_emoji_id="5434121252874756456"
        )
    ])

    # 5) Строка: отмена
    buttons.append([
        InlineKeyboardButton(
            text="В главное меню",
            callback_data="9close_bonus", style="default" ,
                            icon_custom_emoji_id="5960671702059848143"
        )
    ])

    return InlineKeyboardMarkup(inline_keyboard=buttons)


@dp.callback_query(lambda c: c.data.startswith('gift_reset_desc|'))
async def gift_reset_desc_callback(c: types.CallbackQuery):
    session_id = c.data.split("|", 1)[1]
    session = session_data.get(session_id)
    if not session:
        return await c.answer("❌ Сессия не найдена.", show_alert=True)

    # Сбрасываем описание
    session['desc'] = None

    # Перерисовываем клавиатуру
    kb = await build_options_keyboard(session_id)

    # Формируем новый текст
    desc_text = session['desc'] or "«<tg-emoji emoji-id='5318959255385043017'>🎩</tg-emoji> <b>Элитный игровой бот на телеграмм звёзды! <tg-emoji emoji-id='5463289097336405244'>⭐️</tg-emoji></b>»"
    hide_text = "Да" if session['hide'] else "Нет"
    text = (
        f"<tg-emoji emoji-id='6028346797368283073'>🍹</tg-emoji> <b><i>Описание подарка :\n{desc_text}</i></b>"
    )

    # Редактируем сообщение, показывая обновлённый текст и клавиатуру
    from aiogram.exceptions import TelegramBadRequest
    try:
        await c.message.edit_text(
            text,
            reply_markup=kb,
            parse_mode="HTML"
        )
    except TelegramBadRequest as err:
        # Игнорируем, если текст/markup не изменился
        if 'not modified' not in str(err).lower():
            raise

    await c.answer("Описание сброшено")
@dp.callback_query(_cb_is_speedconc_request)
async def speedconc_request_callback(callback_query: types.CallbackQuery):
    """Вывод «От бота» / speedconc / spd: (имя отдельно от prep send_request_callback)."""
    user_id = callback_query.from_user.id
    raw_data = str(getattr(callback_query, "data", "") or "")

    # Таймаут между кликами
    now = time.time()
    if user_id in last_click_time:
        elapsed = now - last_click_time[user_id]
        if elapsed < timeoutourbot:
            mins = int((timeoutourbot - elapsed) // 60)
            secs = int((timeoutourbot - elapsed) % 60)
            return await callback_query.answer(
                f"⌚️ Подождите {mins} мин. {secs} сек.", show_alert=True
            )

    # Проверка username
    if not callback_query.from_user.username:
        return await callback_query.answer(
            "⚠️ Установите username в настройках Telegram.", show_alert=True
        )

    # Парсинг: speedconc_* | spd:* | skipcb:*→spd:*
    try:
        if raw_data.startswith("spd:") or raw_data.startswith("skipcb:"):
            resolved = _resolve_speedconc_request_data(raw_data)
            has_upgrade = int(resolved.get("has_upgrade") or 0)
            gift_name = str(resolved.get("gift_emoji") or "🎁")
            amount = int(resolved.get("used_base") or 0)
            upgrade_price = int(resolved.get("upgrade_price") or 0)
            gift_id = resolved.get("gift_id")
            user_gift_id = None
        else:
            parts = raw_data.split("_")
            user_gift_id = int(parts[6]) if len(parts) > 6 and parts[6].isdigit() else None
            has_upgrade = int(parts[1])
            gift_name = parts[2]
            amount = int(parts[3])
            upgrade_price = int(parts[4])
            gift_id = parts[5]
    except Exception as e:
        err_text = str(e).lower()
        if "expired" in err_text or "not found" in err_text:
            return await callback_query.answer(
                "⏳ Кнопка устарела после перезапуска бота.\n"
                "Откройте вывод заново из меню баланса.",
                show_alert=True,
            )
        return await callback_query.answer(
            "❌ Не удалось распознать параметры подарка.", show_alert=True
        )

    # Определяем, это NFT-апгрейд?
    is_nft = (has_upgrade != 0)
    # Итоговая сумма (с учётом апгрейда, если выбран)
    total_amount = amount + (upgrade_price if is_nft else 0)

    # Проверка баланса пользователя
    user_balance = await db.get_user_balance(user_id)
    if user_balance < total_amount:
        bal = "{:,.0f}".format(user_balance).replace(",", ".")
        req = "{:,.0f}".format(total_amount).replace(",", ".")
        return await callback_query.answer(
            f"💭 Недостаточно кут. Требуется: {req}. Баланс: {bal}",
            show_alert=True
        )

    # Проверка наличия подарка
    used, remaining, total = await extract_gift_counts(bot1, gift_id)
    if remaining is not None and remaining <= 0:
        kb = InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="💭 Написать создателю", url="https://t.me/JerichoCute")
        ],[
            InlineKeyboardButton(text="Закрыть", callback_data="back_to_stars_choice")
        ]])
        await callback_query.message.edit_text(
            "⚠️ <b>Выбранный подарок закончился 😔</b>",
            reply_markup=kb,
            parse_mode="HTML"
        )
        return

    # Создаём сессию для опций
    session_id = uuid.uuid4().hex[:8]
    session_data[session_id] = {
        "user_id": user_id,
        "original": callback_query.data,
        "hide": False,
        "desc": None,
        "upgrade_available": is_nft and upgrade_price > 0,
        "upgrade": False
    }
    user_to_session[user_id] = session_id

    # Подготовка и показ меню опций с текущими настройками
    kb = await build_options_keyboard(session_id)
    desc_text = session_data[session_id]['desc'] or "«<tg-emoji emoji-id='5318959255385043017'>🎩</tg-emoji> <b>Элитный игровой бот на телеграмм звёзды! <tg-emoji emoji-id='5463289097336405244'>⭐️</tg-emoji></b>»"
    hide_text = "Да" if session_data[session_id]['hide'] else "Нет"
    text = (
        f"<tg-emoji emoji-id='6028346797368283073'>🍹</tg-emoji> <b><i>Описание подарка :\n{desc_text}</i></b>"
    )

    await callback_query.message.edit_text(
        text,
        reply_markup=kb,
        parse_mode="HTML"
    )
    await callback_query.answer()

@dp.callback_query(lambda c: c.data.startswith('gift_toggle_upgrade|'))
async def toggle_upgrade_callback(c: types.CallbackQuery):
    session_id = c.data.split("|", 1)[1]
    session = session_data.get(session_id)
    if not session:
        return await c.answer("❌ Сессия не найдена.", show_alert=True)
    # Переключаем флаг улучшения NFT
    session['upgrade'] = not session['upgrade']
    kb = await build_options_keyboard(session_id)
    try:
        await c.message.edit_reply_markup(reply_markup=kb)
    except TelegramBadRequest as err:
        if 'not modified' not in str(err).lower():
            raise
    await c.answer(
        f"Улучшение NFT {'включено' if session['upgrade'] else 'отключено'}.",
    )

@dp.callback_query(lambda c: c.data.startswith('gift_hide|'))
async def gift_hide_callback(c: types.CallbackQuery):
    session_id = c.data.split("|", 1)[1]
    session = session_data.get(session_id)
    if not session:
        return await c.answer("❌ Сессия не найдена.", show_alert=True)
    # Переключаем флаг скрытия имени отправителя
    session['hide'] = not session['hide']
    kb = await build_options_keyboard(session_id)
    try:
        await c.message.edit_reply_markup(reply_markup=kb)
    except TelegramBadRequest as err:
        if 'not modified' not in str(err).lower():
            raise
    state = "скрыто" if session['hide'] else "показано"
    await c.answer(f"Имя отправителя {state}.")

@dp.callback_query(lambda c: c.data.startswith('gift_desc|'))
async def gift_desc_callback(c: types.CallbackQuery):
    session_id = c.data.split("|", 1)[1]
    session = session_data.get(session_id)
    if not session:
        return await c.answer("❌ Сессия не найдена.", show_alert=True)

    # Включаем режим ожидания описания
    session['awaiting_desc'] = True

    # Удаляем старое меню (если есть)
    try:
        await c.message.delete()
    except TelegramBadRequest:
        pass

    # Просим ввести описание, сохраняем ID вопроса
    prompt = await c.message.answer(
        "<tg-emoji emoji-id='6028346797368283073'>💭</tg-emoji> <b>Введите описание подарка (до 200 символов):</b>",
        reply_markup=ForceReply(selective=True),
        parse_mode="HTML"
    )
    session['prompt_chat_id'] = prompt.chat.id
    session['prompt_message_id'] = prompt.message_id

    await c.answer()




@dp.message(lambda m:
    m.reply_to_message
    and m.reply_to_message.message_id == session_data.get(user_to_session.get(m.from_user.id), {}).get('prompt_message_id')
    and session_data.get(user_to_session.get(m.from_user.id), {}).get('awaiting_desc')
)
async def process_description(message: types.Message):
    session_id = user_to_session.get(message.from_user.id)
    session = session_data.get(session_id)
    if not session:
        return

    text = message.text or ""

    # Проверяем длину
    if len(text) > 200:
        # Удаляем неверный ввод пользователя
        try:
            await message.delete()
        except TelegramBadRequest:
            pass

        # Удаляем предыдущее сообщение-приглашение
        try:
            await message.bot.delete_message(
                chat_id=session['prompt_chat_id'],
                message_id=session['prompt_message_id']
            )
        except TelegramBadRequest:
            pass

        # Шлём новый запрос с ошибкой
        prompt = await message.answer(
            f"<tg-emoji emoji-id='6028346797368283073'>🖐</tg-emoji> <b>Введите описание до 200 символов. (сейчас {len(text)}). </b>"
            "Попробуйте ещё раз",
            reply_markup=ForceReply(selective=True),
            parse_mode="HTML"
        )
        # Обновляем ID текущего запроса
        session['prompt_chat_id'] = prompt.chat.id
        session['prompt_message_id'] = prompt.message_id
        # awaiting_desc остаётся True
        return

    # Если всё в порядке - сохраняем описание и выходим из режима ожидания
    session['desc'] = text
    session['awaiting_desc'] = False

    # Удаляем подсказку-ForceReply
    try:
        await message.bot.delete_message(
            chat_id=session['prompt_chat_id'],
            message_id=session['prompt_message_id']
        )
    except TelegramBadRequest:
        pass

    # Собираем обновлённую клавиатуру
    kb = await build_options_keyboard(session_id)

    # Формируем и отправляем итоговый текст с меню
    desc_text = session.get('desc') or "-"
    hide_text = "Да" if session.get('hide') else "Нет"
    text = (
        f"<tg-emoji emoji-id='6028346797368283073'>🍹</tg-emoji> <b>Текущий текст описания подарка :</b>\n"
        f"«<i>{desc_text}</i>»\n\n"

    )
    await message.answer(
        text,
        reply_markup=kb,
        parse_mode="HTML"
    )

    # Удаляем сообщение пользователя
    try:
        await message.delete()
    except TelegramBadRequest:
        pass


