def _cleanup_gift_session(session_id: str, user_id: int) -> None:
    try:
        session_data.pop(session_id, None)
    except Exception:
        pass
    try:
        user_to_session.pop(int(user_id), None)
    except Exception:
        pass

# ============================================================
# ✅ helper: откат strict-вывода (баланс + withdraw_log + окно лимитов)
# ============================================================
async def _refund_failed_gift_strict(
    *,
    db,
    user_id: int,
    amount: int,
    rid: str,
    cooldown_set: bool = False,
) -> bool:
    """
    ✅ Откат, если add_withdraw_strict уже списал, но send_gift упал:
    - возвращаем баланс пользователю
    - удаляем withdraw_log по request_id
    - пересчитываем withdraw_quota_window по truth
    - best-effort удаляем свежий cooldown, включая cause='daily_limit:{rid}'
    - идемпотентно

    ВАЖНО:
    - если withdraw_log уже нет, повторный вызов ничего не ломает
    """
    uid = int(user_id)
    amt = int(amount or 0)
    rid0 = str(rid or "").strip()

    if amt <= 0 or not rid0:
        print(f"[REFUND][ABORT] uid={uid} bad amt={amount!r} rid={rid!r}")
        return False

    if not getattr(db, "pool", None):
        print("[REFUND][ABORT] db.pool is None")
        return False

    t0 = time.time()
    print(f"[REFUND][START] uid={uid} amt={amt} rid='{rid0}' cooldown_set={bool(cooldown_set)}")

    try:
        async with db.pool.acquire() as conn:
            async with conn.transaction():
                await conn.execute("SELECT pg_advisory_xact_lock($1::bigint)", int(uid))

                row_exists = await conn.fetchrow(
                    """
                    SELECT amount
                    FROM withdraw_log
                    WHERE user_id=$1 AND request_id=$2
                    LIMIT 1
                    """,
                    int(uid),
                    str(rid0),
                )

                if not row_exists:
                    print(f"[REFUND][SKIP] no withdraw_log for rid='{rid0}' (already refunded or never charged)")
                    try:
                        await _recalc_withdraw_window(conn, db, int(uid))
                    except Exception as e:
                        print(f"[REFUND][WARN] recalc after skip: {e!r}")
                    return True

                # 1) вернуть баланс
                row_bal = await conn.fetchrow(
                    """
                    UPDATE users
                    SET balance = balance + $2
                    WHERE user_id=$1
                    RETURNING balance
                    """,
                    int(uid),
                    int(amt),
                )
                if not row_bal:
                    print(f"[REFUND][FAIL] balance update returned no row uid={uid}")
                    return False

                new_bal = int(row_bal["balance"] or 0)

                # 2) удалить withdraw_log по rid
                try:
                    res = await conn.execute(
                        """
                        DELETE FROM withdraw_log
                        WHERE user_id=$1 AND request_id=$2
                        """,
                        int(uid),
                        str(rid0),
                    )
                    deleted = int(str(res).split()[-1]) if res else 0
                except Exception as e:
                    print(f"[REFUND][LOG][ERROR] delete withdraw_log err={e!r}")
                    deleted = 0

                print(f"[REFUND][LOG] uid={uid} rid='{rid0}' deleted withdraw_log rows={deleted}")

                # 3) снять свежий cooldown, если он был поставлен этим выводом
                if cooldown_set:
                    try:
                        await conn.execute(
                            """
                            DELETE FROM withdraw_cooldown
                            WHERE user_id=$1
                              AND until_at > NOW()
                              AND (
                                    cause = $2
                                 OR cause = 'daily_limit'
                                 OR cause = 'limit_reached'
                                 OR cause = 'manual_withdraw'
                                 OR cause = 'min_withdraw_block'
                                 OR cause = 'fast_withdraw_gift'
                              )
                            """,
                            int(uid),
                            f"daily_limit:{rid0}",
                        )
                        print(f"[REFUND][COOLDOWN] delete attempted uid={uid} exact_cause={f'daily_limit:{rid0}'}")
                    except Exception as e:
                        print(f"[REFUND][COOLDOWN][WARN] {e!r}")

                # 4) пересчёт окна лимита
                await _recalc_withdraw_window(conn, db, int(uid))

                # 5) sync cache after refund
                try:
                    if hasattr(db, "sync_user_balance_cache"):
                        await db.sync_user_balance_cache(int(uid), int(new_bal))
                except Exception as e:
                    print(f"[REFUND][CACHE][WARN] {e!r}")

                dt = time.time() - t0
                print(f"[REFUND][DONE] uid={uid} refunded={amt} new_bal={new_bal} dt={dt:.4f}s")
                return True

    except Exception as e:
        print(f"[REFUND][ERROR] uid={uid} err={type(e).__name__}: {e!r}")
        return False



async def _update_withdraw_quota_window_safe(
    conn,
    *,
    uid: int,
    daily_limit: int,
    used_value: int,
    status: str,
    cooldown_left_sec: int = 0,
    cooldown_until=None,
) -> None:
    """
    Безопасное обновление withdraw_quota_window.
    Всегда:
    - used_in_window = INT >= 0 и не больше daily_limit
    - remaining = INT >= 0
    - used_percent = INT 0..100
    """
    def _safe_int(v, default: int = 0) -> int:
        try:
            return int(v)
        except Exception:
            return int(default)

    def _safe_non_negative(v, default: int = 0) -> int:
        x = _safe_int(v, default)
        return x if x >= 0 else 0

    def _safe_used_percent(used_value: int, limit_value: int) -> int:
        used_i = _safe_non_negative(used_value, 0)
        limit_i = _safe_non_negative(limit_value, 0)

        if limit_i <= 0:
            return 100 if used_i > 0 else 0

        pct = int((used_i * 100) / limit_i)

        if pct < 0:
            return 0
        if pct > 100:
            return 100
        return pct

    uid = int(uid)
    dl = _safe_non_negative(daily_limit, 0)
    used_raw = _safe_non_negative(used_value, 0)

    if dl <= 0:
        dl = 100

    used_store = min(int(used_raw), int(dl))
    remaining = max(0, int(dl) - int(used_store))
    used_percent = _safe_used_percent(int(used_store), int(dl))
    cooldown_left_sec = _safe_non_negative(cooldown_left_sec, 0)

    await conn.execute(
        """
        UPDATE withdraw_quota_window
        SET used_in_window     = $2,
            daily_limit        = $3,
            remaining          = $4,
            used_percent       = $5,
            status             = $6,
            cooldown_left_sec  = $7,
            cooldown_until     = $8,
            updated_at         = NOW()
        WHERE user_id = $1
        """,
        uid,
        int(used_store),
        int(dl),
        int(remaining),
        int(used_percent),
        str(status),
        int(cooldown_left_sec),
        cooldown_until,
    )
# ============================================================
# ✅ helper: пересчитать окно лимитов (истина по SUM)
# ============================================================
async def _recalc_withdraw_window(conn, db, uid: int) -> None:
    """
    Пересчитывает withdraw_quota_window по факту withdraw_log.

    ВАЖНО:
    - не создаёт новый cooldown
    - не продлевает cooldown
    - не ломает активный cooldown
    - used_percent всегда INT 0..100
    """

    def _safe_int(v, default: int = 0) -> int:
        try:
            return int(v)
        except Exception:
            return int(default)

    def _safe_non_negative(v, default: int = 0) -> int:
        x = _safe_int(v, default)
        return x if x >= 0 else 0

    uid = int(uid)

    # ---------------------------------------------------
    # 1) ensure row exists
    # ---------------------------------------------------
    await conn.execute(
        """
        INSERT INTO withdraw_quota_window(
            user_id,
            window_started_at,
            used_in_window,
            daily_limit,
            remaining,
            used_percent,
            status,
            cooldown_left_sec,
            cooldown_until,
            updated_at
        )
        VALUES ($1, NOW(), 0, 0, 0, 0, 'OK', 0, NULL, NOW())
        ON CONFLICT (user_id) DO NOTHING
        """,
        uid,
    )

    # ---------------------------------------------------
    # 2) lock quota row
    # ---------------------------------------------------
    q = await conn.fetchrow(
        """
        SELECT
            window_started_at,
            daily_limit,
            used_in_window,
            remaining,
            used_percent,
            status,
            cooldown_left_sec,
            cooldown_until
        FROM withdraw_quota_window
        WHERE user_id=$1
        FOR UPDATE
        """,
        uid,
    )

    ws = q["window_started_at"] if q else None
    dl = _safe_non_negative(q["daily_limit"], 0) if q else 0

    if not ws:
        ws = await conn.fetchval("SELECT NOW()")
        await conn.execute(
            """
            UPDATE withdraw_quota_window
            SET window_started_at=$2,
                updated_at=NOW()
            WHERE user_id=$1
            """,
            uid,
            ws,
        )

    # ---------------------------------------------------
    # 3) восстанавливаем daily_limit
    #    приоритет:
    #    1. users.canwithdrawal (источник истины)
    #    2. текущий daily_limit из quota row
    #    3. withdraw_limits.daily_amount_limit (legacy fallback)
    #    4. Default_WITHDRAW_DEFAULT_DAILY_LIMIT
    # ---------------------------------------------------
    try:
        if hasattr(db, "get_canwithdrawal"):
            canw = _safe_non_negative(await db.get_canwithdrawal(uid) or 0, 0)
            if canw > 0:
                dl = int(canw)
    except Exception as e:
        print(f"[REFUND][WINDOW][WARN] get_canwithdrawal uid={uid} err={e!r}")

    if dl <= 0:
        dl = _safe_non_negative(dl, 0)

    if dl <= 0:
        try:
            row_lim = await conn.fetchrow(
                """
                SELECT daily_amount_limit
                FROM withdraw_limits
                WHERE user_id=$1
                """,
                uid,
            )
            dl = _safe_non_negative(row_lim["daily_amount_limit"], 0) if row_lim else 0
        except Exception as e:
            print(f"[REFUND][WINDOW][WARN] withdraw_limits uid={uid} err={e!r}")
            dl = 0

    if dl <= 0:
        try:
            dl = _safe_non_negative(Default_WITHDRAW_DEFAULT_DAILY_LIMIT, 0)
        except Exception:
            dl = 100

    if dl <= 0:
        dl = 100

    # ---------------------------------------------------
    # 4) считаем truth used по withdraw_log
    # ---------------------------------------------------
    used_truth = _safe_non_negative(
        await conn.fetchval(
            """
            SELECT COALESCE(SUM(amount), 0)::BIGINT
            FROM withdraw_log
            WHERE user_id=$1 AND created_at >= $2
            """,
            uid,
            ws,
        ) or 0,
        0,
    )

    # ---------------------------------------------------
    # 5) проверяем активный cooldown
    # ---------------------------------------------------
    cd_row = await conn.fetchrow(
        """
        SELECT
            until_at,
            GREATEST(0, EXTRACT(EPOCH FROM (until_at - NOW()))::BIGINT) AS left_sec
        FROM withdraw_cooldown
        WHERE user_id=$1 AND until_at > NOW()
        """,
        uid,
    )

    cooldown_until = None
    cooldown_left_sec = 0

    if cd_row:
        cooldown_until = cd_row["until_at"]
        cooldown_left_sec = _safe_non_negative(cd_row["left_sec"], 0)
        status = "COOLDOWN"
    else:
        used_store_preview = min(int(used_truth), int(dl))
        remaining_preview = max(0, int(dl) - int(used_store_preview))
        status = "OK" if remaining_preview > 0 else "LIMIT_REACHED"

    # ---------------------------------------------------
    # 6) безопасный update через helper
    # ---------------------------------------------------
    await _update_withdraw_quota_window_safe(
        conn,
        uid=int(uid),
        daily_limit=int(dl),
        used_value=int(used_truth),
        status=str(status),
        cooldown_left_sec=int(cooldown_left_sec),
        cooldown_until=cooldown_until,
    )

    used_store_final = min(int(used_truth), int(dl))
    remaining_final = max(0, int(dl) - int(used_store_final))

    print(
        f"[REFUND][WINDOW] uid={uid} ws={ws} "
        f"limit={dl} used_truth={used_truth} used_store={used_store_final} "
        f"remaining={remaining_final} status={status} cd_left={cooldown_left_sec}"
    )


async def _withdraw_fail_ui(*, bot1, chat_id: int, text: str) -> None:
    try:
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="Закрыть", callback_data="9close_bonus")]
        ])
        await bot1.send_message(chat_id=chat_id, text=text, reply_markup=kb, parse_mode="HTML")
    except Exception as e:
        print(f"[WITHDRAW][UI][WARN] cannot send fail ui: {e!r}")
def _mk_gift_rid(*parts) -> str:
    """
    Детерминированный request_id (idempotent):
    повторный клик -> тот же rid -> add_withdraw_strict не спишет второй раз.
    """
    s = "|".join([str(x) for x in parts if x is not None])
    h = hashlib.md5(s.encode("utf-8")).hexdigest()  # 32 hex
    return h[:16]  # короткий, как ты любишь
