test_gift_mode = False  # ✅ True = тест (вместо настоящего подарка шлём красивое сообщение), False = реальный gift

# token -> payload
# token -> payload



# Persistent store — тот же ключ, что уже используется выводами игроков.
# НЕ переопределяем ADMIN_WITHDRAW_ACTIONS / registry ниже в файле.
# pending-заявки живут до нажатия кнопки (см. _cleanup_admin_withdraw_actions выше).


def _build_withdraw_channel_keyboard(
    *,
    request_id: str,
    sender_user_id: int,
    sender_username: Optional[str],
    sender_first_name: Optional[str],
    recipient_user_id: Optional[int],
    recipient_username: Optional[str],
    recipient_first_name: Optional[str],
    amount: int,
    result_flag: str,
    is_friend: bool,
    channel_message_id_hint: int = 0,
    gift_id: int = 0,
    gift_emoji: str = "",
    has_upgrade: int = 0,
    extra: Optional[dict] = None,
) -> InlineKeyboardMarkup:
    """
    ✅ Короткие callback_data
    ✅ Полный payload в registry
    ✅ gift_id проходит до approve/refund/reject
    ✅ extra — доп. поля (is_salary, star_payout_id, …)
    """

    sender_username = str(sender_username or "None")
    sender_first_name = str(sender_first_name or "")
    recipient_username = str(recipient_username or "None")
    recipient_first_name = str(recipient_first_name or "")

    base_payload = {
        "request_id": str(request_id),
        "sender_user_id": int(sender_user_id),
        "sender_username": sender_username,
        "sender_first_name": sender_first_name,
        "recipient_user_id": int(recipient_user_id or 0),
        "recipient_username": recipient_username,
        "recipient_first_name": recipient_first_name,
        "amount": int(amount),
        "result_flag": str(result_flag or "-"),
        "is_friend": bool(is_friend),
        "channel_message_id_hint": int(channel_message_id_hint or 0),

        "gift_id": int(gift_id or 0),
        "gift_emoji": str(gift_emoji or ""),
        "has_upgrade": int(has_upgrade or 0),
    }
    if extra and isinstance(extra, dict):
        base_payload.update(extra)

    approve_token = _register_admin_withdraw_action({
        **base_payload,
        "kind": "approve",
    })

    refund_token = _register_admin_withdraw_action({
        **base_payload,
        "kind": "refund",
    })

    reject_token = _register_admin_withdraw_action({
        **base_payload,
        "kind": "reject",
    })

    # Обычные выводы игроков:
    # 👎 reject  — отказ, куты НЕ возвращаются
    # 🥂 refund  — отказ, куты возвращаются отправителю
    # 👍 approve — вывод одобрен
    # Зарплатные/админские выводы (staff_stars) собирают клавиатуру отдельно
    # и намеренно без 🥂 — их не трогаем.
    return InlineKeyboardMarkup(
        inline_keyboard=[[
            InlineKeyboardButton(text="👎", callback_data=f"wdact:{reject_token}"),
            InlineKeyboardButton(text="🥂", callback_data=f"wdact:{refund_token}"),
            InlineKeyboardButton(text="👍", callback_data=f"wdact:{approve_token}"),
        ]]
    )


def _gift_confirm_fmt_cd_mmss(sec: int) -> str:
    try:
        sec = int(sec or 0)
    except Exception:
        sec = 0

    if sec <= 0:
        return "0:00"

    m = sec // 60
    s = sec % 60
    return f"{m}:{s:02d}"


def _gift_confirm_safe_int(v, default: int = 0) -> int:
    try:
        return int(v)
    except Exception:
        return int(default)


def _gift_confirm_safe_str(v, default: str = "") -> str:
    try:
        if v is None:
            return default
        s = str(v).strip()
        return s if s else default
    except Exception:
        return default


def _gift_confirm_get_inflight_store() -> set:
    g = globals()
    if "gift_confirm_inflight" not in g or not isinstance(g.get("gift_confirm_inflight"), set):
        g["gift_confirm_inflight"] = set()
    return g["gift_confirm_inflight"]


def _gift_confirm_parse_session_payload(original: str) -> Dict[str, Any]:
    """
    Ожидаемый формат original:
    что-то_{{has_upgrade}}_что-то_{{amount}}_{{upgrade_price}}_{{gift_id}}_{{user_gift_id?}}
    """
    parts = str(original or "").split("_")

    if len(parts) < 6:
        raise ValueError(f"original has too few parts: len={len(parts)} original={original!r}")

    has_upgrade = _gift_confirm_safe_int(parts[1], 0)
    amount = _gift_confirm_safe_int(parts[3], 0)
    upgrade_price = _gift_confirm_safe_int(parts[4], 0)
    gift_id = _gift_confirm_safe_str(parts[5], "")
    user_gift_id = None

    if len(parts) > 6:
        raw_uid = _gift_confirm_safe_str(parts[6], "")
        if raw_uid.isdigit():
            user_gift_id = int(raw_uid)

    return {
        "has_upgrade": has_upgrade,
        "amount": amount,
        "upgrade_price": upgrade_price,
        "gift_id": gift_id,
        "user_gift_id": user_gift_id,
    }


async def _gift_confirm_safe_answer(c: types.CallbackQuery, text: str = "", show_alert: bool = False):
    try:
        await c.answer(text, show_alert=show_alert)
    except Exception:
        pass


async def _gift_confirm_send_pretty_lock_ui(
    *,
    chat_id: Optional[int],
    title: str,
    lines: list,
    back_cb: str = "9close_bonus",
):
    """
    Единый UI для блокировок/ошибок gift-вывода.
    """
    if chat_id is None:
        return

    try:
        rows = []
        rows.append([InlineKeyboardButton(text=str(title), callback_data="noop")])

        for ln in (lines or []):
            rows.append([InlineKeyboardButton(text=str(ln), callback_data="noop")])

        rows.append([InlineKeyboardButton(text="Закрыть", callback_data=str(back_cb or "9close_bonus"))])

        kb = InlineKeyboardMarkup(inline_keyboard=rows)

        await bot1.send_message(
            chat_id=chat_id,
            text="🧰",
            reply_markup=kb,
            parse_mode="HTML",
            disable_web_page_preview=True,
        )
    except Exception as e:
        print(f"🟥 [GIFT_CONFIRM][LOCK_UI][ERROR] {type(e).__name__}: {e!r}")


async def _gift_confirm_process_withdraw_result(
    *,
    strict_res: Dict[str, Any],
    session_id: str,
    user_id: int,
    chat_id_int: Optional[int],
) -> Optional[Dict[str, Any]]:
    """
    Возвращает нормализованный результат, если можно продолжать.
    Иначе сам показывает UI, чистит сессию и возвращает None.
    """
    if not isinstance(strict_res, dict):
        strict_res = {"ok": False, "error": "bad_response", "status": "bad_response"}

    if strict_res.get("duplicate"):
        print(f"🟨 [GIFT_CONFIRM] duplicate strict_res={strict_res!r}")
        await _gift_confirm_send_pretty_lock_ui(
            chat_id=chat_id_int,
            title="📌 Заявка уже обработана",
            lines=["Повторно оформлять этот вывод не нужно."],
            back_cb="9close_bonus",
        )
        _cleanup_gift_session(session_id, user_id)
        return None

    if not strict_res.get("ok"):
        err = _gift_confirm_safe_str(strict_res.get("error"), "unknown")
        print(f"🟥 [GIFT_CONFIRM] WITHDRAW failed err={err} payload={strict_res!r}")

        if err == "cooldown_active":
            left = _gift_confirm_safe_int(strict_res.get("cooldown_left"), 0)
            await _gift_confirm_send_pretty_lock_ui(
                chat_id=chat_id_int,
                title="⛔ Лимит",
                lines=[f"⏳ Кулдаун : {_gift_confirm_fmt_cd_mmss(left)}"],
                back_cb="9close_bonus",
            )

        elif err == "exceeds_remaining":
            rem = _gift_confirm_safe_int(strict_res.get("remaining"), 0)
            dl = _gift_confirm_safe_int(strict_res.get("daily_limit"), 0)
            used = _gift_confirm_safe_int(strict_res.get("used"), 0)
            await _gift_confirm_send_pretty_lock_ui(
                chat_id=chat_id_int,
                title="⛔ Лимит вывода",
                lines=[
                    f"📌 Лимит : {_fmt_int(dl)}",
                    f"💋 Доступно : {_fmt_int(rem)}",
                    f"🥀 Использовано : {_fmt_int(used)}",
                ],
                back_cb="9close_bonus",
            )

        elif err == "insufficient_funds":
            bal = _gift_confirm_safe_int(strict_res.get("balance"), 0)
            await _gift_confirm_send_pretty_lock_ui(
                chat_id=chat_id_int,
                title="💭 Недостаточно кут",
                lines=[f"🌵 Баланс : {_fmt_int(bal)} кут"],
                back_cb="9close_bonus",
            )

        else:
            await _gift_confirm_send_pretty_lock_ui(
                chat_id=chat_id_int,
                title="⚠️ Ошибка оформления вывода",
                lines=["Попробуйте позже."],
                back_cb="9close_bonus",
            )

        _cleanup_gift_session(session_id, user_id)
        return None

    if not strict_res.get("committed"):
        print(f"🟥 [GIFT_CONFIRM] ok=True but committed=False -> stop strict_res={strict_res!r}")
        await _gift_confirm_send_pretty_lock_ui(
            chat_id=chat_id_int,
            title="⚠️ Вывод не был зафиксирован",
            lines=["Попробуйте ещё раз позже."],
            back_cb="9close_bonus",
        )
        _cleanup_gift_session(session_id, user_id)
        return None

    if not strict_res.get("should_send_to_channel", True):
        print(f"🟥 [GIFT_CONFIRM] should_send_to_channel=False -> stop strict_res={strict_res!r}")
        await _gift_confirm_send_pretty_lock_ui(
            chat_id=chat_id_int,
            title="📌 Заявка уже обработана",
            lines=["Повторная отправка не требуется."],
            back_cb="9close_bonus",
        )
        _cleanup_gift_session(session_id, user_id)
        return None

    return strict_res


async def _gift_confirm_preflight_target(
    *,
    target_id: int,
) -> bool:
    """
    Проверяем, что получатель открыл диалог с ботом.
    """
    try:
        print("🛰️ [GIFT_CONFIRM] preflight ping target")
        ping_msg = await bot1.send_message(chat_id=target_id, text="🤙")
        try:
            await bot1.delete_message(chat_id=target_id, message_id=ping_msg.message_id)
        except Exception:
            pass
        print("🆗 [GIFT_CONFIRM] preflight OK")
        return True
    except Exception as e:
        print(f"⛔ [GIFT_CONFIRM] preflight FAILED: {type(e).__name__}: {e!r}")
        return False


async def _gift_confirm_send_gift_and_log(
    *,
    target_id: int,
    gift_id: str,
    upgrade: bool,
    desc: Optional[str],
    amount_text: str,
    strict_res: Dict[str, Any],
    total_amount: int,
    c: types.CallbackQuery,
):
    """
    Отправка подарка + публикация в канал + запись истории.
    Бросает exception наверх, если send_gift не удался.
    """
    receiver_name = "Пользователь"
    try:
        receiver_name = await db.get_firstname_by_user_id(target_id)
    except Exception as e:
        print(f"🟠 [GIFT_CONFIRM] receiver_name warn: {e!r}")

    try:
        receiver_username = None
        if hasattr(db, "get_username_by_id"):
            receiver_username = await db.get_username_by_id(target_id)
        name_link = await create_user_link(target_id, receiver_name, receiver_username)
    except Exception as e:
        print(f"🟠 [GIFT_CONFIRM] name_link warn: {e!r}")
        name_link = receiver_name

    now_str = datetime.now().strftime("%d.%m.%Y %H:%M")

    print(
        f"🎁 [GIFT_CONFIRM] send_gift start target={target_id} gift_id={gift_id} "
        f"pay_for_upgrade={upgrade} test_mode={bool(test_gift_mode)}"
    )

    if bool(test_gift_mode):
        test_text = (
            "<b><tg-emoji emoji-id='5269288899204640214'>🎁</tg-emoji> Тестовая отправка подарка</b>\n"
            f"<tg-emoji emoji-id='5440911110838425969'>🌹</tg-emoji> Подарок: <b>{str(gift_id)}</b>\n"
            f"<tg-emoji emoji-id='5848259999763011021'>⭐️</tg-emoji> Сумма: <b>{amount_text}</b>\n"
            f"🕒 {now_str}\n\n"
            "<i>Это тестовый режим. Реальный подарок не отправлен.</i>"
        )
        await bot1.send_message(
            chat_id=target_id,
            text=test_text,
            parse_mode="HTML",
            disable_web_page_preview=True,
        )
    else:
        await bot1.send_gift(
            chat_id=target_id,
            gift_id=gift_id,
            pay_for_upgrade=upgrade,
            text=desc or "<tg-emoji emoji-id='5318959255385043017'>🎩</tg-emoji> <b>Элитный игровой бот на телеграмм звёзды! <tg-emoji emoji-id='5463289097336405244'>⭐️</tg-emoji></b>",
            text_parse_mode="HTML",
        )

    print("✅ [GIFT_CONFIRM] send_gift OK")

    try:
        if strict_res.get("should_send_to_channel"):
            await bot1.send_message(
                chat_id="@CurrencyCute",
                text=(
                    f"<b><tg-emoji emoji-id='5897658922600240288'>⭐️</tg-emoji> {amount_text} TgStars отправлены лично ботом</b>\n"
                    f"<tg-emoji emoji-id='5188322825735267247'>⛵️</tg-emoji> <b>Получатель : {name_link}</b>\n"
                    f"<i><tg-emoji emoji-id='5465143921912846619'>💭</tg-emoji> {now_str}</i>\n\n"
                    f"<blockquote><b>@CuteGamingbot</b></blockquote>"
                ),
                parse_mode="HTML",
                disable_web_page_preview=True,
            )
        else:
            print(f"🟨 [GIFT_CONFIRM] channel publish skipped strict_res={strict_res!r}")
    except Exception as e:
        print(f"🟠 [GIFT_CONFIRM] @CurrencyCute warn: {e!r}")

    try:
        if hasattr(db, "save_withdrawal_record"):
            await db.save_withdrawal_record(
                user_id=c.from_user.id,
                amount=total_amount,
                withdrawal_text="🦾 вывод через бот (fast)",
            )
    except Exception as e:
        print(f"🟠 [GIFT_CONFIRM] save_withdrawal_record warn: {e!r}")

    return name_link


