@dp.callback_query(lambda c: isinstance(c.data, str) and c.data.startswith("gift_confirm|"))
async def gift_confirm_callback(c: types.CallbackQuery):
    print("📦 [GIFT_CONFIRM] ▶️ start")

    session_id = ""
    user_id = 0
    inflight_store = _gift_confirm_get_inflight_store()

    try:
        try:
            chat_id_int = int(c.message.chat.id)
        except Exception:
            chat_id_int = None

        try:
            session_id = str(c.data.split("|", 1)[1]).strip()
        except Exception:
            print(f"❌ [GIFT_CONFIRM] bad callback_data={c.data!r}")
            return await _gift_confirm_safe_answer(c, "❌ Ошибка данных.", show_alert=True)

        if not session_id:
            print("❌ [GIFT_CONFIRM] empty session_id")
            return await _gift_confirm_safe_answer(c, "❌ Ошибка сессии.", show_alert=True)

        if session_id in inflight_store:
            print(f"🟨 [GIFT_CONFIRM] session already inflight session_id={session_id}")
            return await _gift_confirm_safe_answer(c, "⏳ Операция уже обрабатывается", show_alert=True)

        inflight_store.add(session_id)

        session = session_data.get(session_id)
        if not session:
            print(f"❌ [GIFT_CONFIRM] session not found: {session_id}")
            return await _gift_confirm_safe_answer(c, "❌ Сессия не найдена.", show_alert=True)

        user_id = _gift_confirm_safe_int(session.get("user_id"), 0)
        original = _gift_confirm_safe_str(session.get("original"), "")
        hide = bool(session.get("hide", False))
        desc = session.get("desc")
        upgrade = bool(session.get("upgrade", False))

        print(f"📋 [GIFT_CONFIRM] session: uid={user_id} hide={hide} upgrade={upgrade} original_len={len(original)}")

        if user_id <= 0:
            print(f"❌ [GIFT_CONFIRM] bad user_id in session: {session!r}")
            _cleanup_gift_session(session_id, user_id)
            return await _gift_confirm_safe_answer(c, "❌ Ошибка пользователя.", show_alert=True)

        clicker_id = _gift_confirm_safe_int(getattr(getattr(c, "from_user", None), "id", 0), 0)
        if clicker_id != user_id:
            print(f"🟥 [GIFT_CONFIRM] security: clicker_id={clicker_id} session_user_id={user_id}")
            return await _gift_confirm_safe_answer(c, "⚠️ Эта кнопка не для вас.", show_alert=True)

        try:
            parsed = _gift_confirm_parse_session_payload(original)
        except Exception as err:
            print(f"❗️ [GIFT_CONFIRM] parse error: {err!r} original={original!r}")
            _cleanup_gift_session(session_id, user_id)
            return await _gift_confirm_safe_answer(c, "❌ Невозможно разобрать параметры.", show_alert=True)

        has_upgrade = _gift_confirm_safe_int(parsed.get("has_upgrade"), 0)
        amount = _gift_confirm_safe_int(parsed.get("amount"), 0)
        upgrade_price = _gift_confirm_safe_int(parsed.get("upgrade_price"), 0)
        gift_id = _gift_confirm_safe_str(parsed.get("gift_id"), "")
        user_gift_id = parsed.get("user_gift_id")

        print(
            f"🔧 [GIFT_CONFIRM] parsed: has_upg={has_upgrade} amount={amount} "
            f"upg_price={upgrade_price} gift_id={gift_id} user_gift_id={user_gift_id}"
        )

        if amount <= 0:
            _cleanup_gift_session(session_id, user_id)
            return await _gift_confirm_safe_answer(c, "❌ Неверная сумма.", show_alert=True)

        if not gift_id:
            _cleanup_gift_session(session_id, user_id)
            return await _gift_confirm_safe_answer(c, "❌ Не найден gift_id.", show_alert=True)

        total_amount = int(amount) + (int(upgrade_price) if upgrade else 0)
        total_amount = int(total_amount)

        if total_amount <= 0:
            _cleanup_gift_session(session_id, user_id)
            return await _gift_confirm_safe_answer(c, "❌ Неверная итоговая сумма.", show_alert=True)

        target_id = int(user_gift_id or user_id)
        amount_text = _fmt_int(total_amount)

        print(
            f"💰 [GIFT_CONFIRM] total={total_amount} base={amount} "
            f"upg_add={(upgrade_price if upgrade else 0)} target_id={target_id}"
        )

        try:
            current_time = time.time()
            if user_id in last_click_time:
                elapsed = current_time - last_click_time[user_id]
                if elapsed < timeoutourbot:
                    left = timeoutourbot - elapsed
                    minutes = int(left // 60)
                    seconds = int(left % 60)
                    print(f"⌛ [GIFT_CONFIRM] spam block uid={user_id} left={minutes}:{seconds:02d}")
                    return await _gift_confirm_safe_answer(
                        c,
                        f"⌚️ Подождите {minutes} мин. {seconds} сек\n\nНельзя так часто оформлять вывод",
                        show_alert=True,
                    )
        except Exception as e:
            print(f"🟠 [GIFT_CONFIRM] spam-check warn: {e!r}")

        # Активность в официальных группах — обязательное условие вывода.
        # Проверяем ДО удаления меню, чтобы можно было показать кнопки на группы.
        try:
            _msg_back_btn = InlineKeyboardButton(text="Назад", callback_data="9close_bonus")
            ok_msgs = await ensure_daily_messages(c, user_id, back_btn=_msg_back_btn)
        except Exception as e:
            print(f"🟥 [GIFT_CONFIRM] MSGCHK error: {type(e).__name__}: {e!r}")
            return await _gift_confirm_safe_answer(c, "⚠️ Ошибка проверки активности", show_alert=True)
        if not ok_msgs:
            print(f"⛔ [GIFT_CONFIRM] MSGCHK blocked uid={user_id}")
            return

        rid = _mk_gift_rid("gift_confirm", session_id, user_id, target_id, total_amount, gift_id, int(upgrade))
        print(f"🧷 [GIFT_CONFIRM] rid={rid}")

        try:
            await c.message.delete()
            print("🗑️ [GIFT_CONFIRM] menu deleted")
        except Exception as e:
            print(f"🟠 [GIFT_CONFIRM] menu delete warn: {type(e).__name__}: {e!r}")

        cooldown_set_now = False
        committed_now = False
        new_balance_after = 0

        try:
            print(f"🧾 [GIFT_CONFIRM] WITHDRAW start uid={user_id} amount={total_amount}")
            strict_res = await ensure_add_withdraw(
                user_id=user_id,
                amount=total_amount,
                db=db,
                reason="fast_withdraw_gift",
                request_id=rid,
                chat_id=chat_id_int,
                chat_name=None,
            )
            print(f"🧾 [GIFT_CONFIRM] WITHDRAW result: {strict_res!r}")
        except Exception as e:
            print(f"🟥 [GIFT_CONFIRM] WITHDRAW exception: {type(e).__name__}: {e!r}")
            await _gift_confirm_send_pretty_lock_ui(
                chat_id=chat_id_int,
                title="⚠️ Ошибка оформления вывода",
                lines=["Попробуйте позже."],
                back_cb="9close_bonus",
            )
            _cleanup_gift_session(session_id, user_id)
            return

        strict_res = await _gift_confirm_process_withdraw_result(
            strict_res=strict_res,
            session_id=session_id,
            user_id=user_id,
            chat_id_int=chat_id_int,
        )
        if strict_res is None:
            return

        committed_now = True
        cooldown_set_now = bool(strict_res.get("cooldown_set"))
        new_balance_after = _gift_confirm_safe_int(strict_res.get("user_balance_after"), 0)

        print(
            f"✅ [GIFT_CONFIRM] WITHDRAW COMMITTED uid={user_id} "
            f"new_bal={new_balance_after} cooldown_set={cooldown_set_now}"
        )

        preflight_ok = await _gift_confirm_preflight_target(target_id=target_id)
        if not preflight_ok:
            if committed_now:
                refunded = await _refund_failed_gift_strict(
                    db=db,
                    user_id=user_id,
                    amount=total_amount,
                    rid=rid,
                    cooldown_set=cooldown_set_now,
                )
                print(f"🧯 [GIFT_CONFIRM] refund result={refunded}")

            await _gift_confirm_send_pretty_lock_ui(
                chat_id=chat_id_int,
                title="<tg-emoji emoji-id='5269288899204640214'>🎁</tg-emoji> Получатель не открыл бота",
                lines=["Попросите его написать боту и попробуйте снова."],
                back_cb="9close_bonus",
            )

            _cleanup_gift_session(session_id, user_id)
            return

        try:
            await _gift_confirm_send_gift_and_log(
                target_id=target_id,
                gift_id=gift_id,
                upgrade=upgrade,
                desc=desc,
                amount_text=amount_text,
                strict_res=strict_res,
                total_amount=total_amount,
                c=c,
            )
        except Exception as e:
            err = str(e)
            print(f"⚠️ [GIFT_CONFIRM] send_gift ERROR: {type(e).__name__}: {err}")

            if committed_now:
                refunded = await _refund_failed_gift_strict(
                    db=db,
                    user_id=user_id,
                    amount=total_amount,
                    rid=rid,
                    cooldown_set=cooldown_set_now,
                )
                print(f"🧯 [GIFT_CONFIRM] refund after gift-fail result={refunded}")
            else:
                print("🟨 [GIFT_CONFIRM] refund skipped because committed_now=False")

            if "BALANCE_TOO_LOW" in err:
                if chat_id_int is not None:
                    await bot1.send_message(
                        chat_id=chat_id_int,
                        text="🧰",
                        reply_markup=InlineKeyboardMarkup(
                            inline_keyboard=[
                                [InlineKeyboardButton(text="У бота недостаточно звёзд", callback_data="noop")],
                                [InlineKeyboardButton(text="Списание отменено", callback_data="noop")],
                                [InlineKeyboardButton(text="Связь", url="https://t.me/JerichoCute")],
                                [InlineKeyboardButton(text="Назад", callback_data="9close_bonus")],
                            ]
                        ),
                        parse_mode="HTML",
                        disable_web_page_preview=True,
                    )
                _cleanup_gift_session(session_id, user_id)
                return

            if "STARGIFT_UPGRADE_UNAVAILABLE" in err:
                await _gift_confirm_send_pretty_lock_ui(
                    chat_id=chat_id_int,
                    title="🔄 Улучшение недоступно",
                    lines=["✅ Списание отменено, лимит восстановлен.", "Попробуйте без улучшения."],
                    back_cb="9close_bonus",
                )
                _cleanup_gift_session(session_id, user_id)
                return

            await _gift_confirm_send_pretty_lock_ui(
                chat_id=chat_id_int,
                title="⚠️ Ошибка при отправке подарка",
                lines=["✅ Списание отменено, лимит восстановлен.", "Попробуйте позже."],
                back_cb="9close_bonus",
            )
            _cleanup_gift_session(session_id, user_id)
            return

        await _gift_confirm_notify_receiver(
            sender_user_id=user_id,
            receiver_user_id=user_gift_id,
            hide=hide,
        )

        try:
            print("📊 [GIFT_CONFIRM] success history step")
            try:
                if hasattr(db, "cutehistory_minus"):
                    await db.cutehistory_minus(user_id, total_amount, "Быстрый вывод кут в звезды (gift)")
            except Exception as e:
                print(f"🟠 [GIFT_CONFIRM] cutehistory_minus warn: {e!r}")

            await _gift_confirm_send_success_ui(
                chat_id_int=chat_id_int,
                total_amount=total_amount,
                new_balance_after=new_balance_after,
            )

            last_click_time[user_id] = time.time()
            print(f"✅ [GIFT_CONFIRM] DONE uid={user_id} total={total_amount} new_bal={new_balance_after}")
        except Exception as e:
            print(f"❗️ [GIFT_CONFIRM] post-success warn: {e!r}")

        _cleanup_gift_session(session_id, user_id)
        print(f"🧹 [GIFT_CONFIRM] session cleaned session_id={session_id}")

        await _gift_confirm_safe_answer(c, "Подарок отправлен!")

    finally:
        try:
            if session_id:
                inflight_store.discard(session_id)
        except Exception:
            pass










def _mk_withdraw_rid(*parts) -> str:
    """
    ✅ Детерминированный request_id (16 символов).
    Повторный клик по той же кнопке -> тот же rid -> add_withdraw_strict вернёт duplicate, НЕ спишет повторно.
    """
    try:
        s = "|".join(str(p) for p in parts)
        rid = hashlib.md5(s.encode("utf-8")).hexdigest()[:16]
        print(f"[WITHDRAW][RID] ✅ make rid={rid} parts={parts}")
        return rid
    except Exception as e:
        # fallback, но детерминированность хуже
        rid = hashlib.md5(str(time.time()).encode("utf-8")).hexdigest()[:16]
        print(f"[WITHDRAW][RID][WARN] fallback rid={rid} err={e!r}")
        return rid

async def _handle_withdraw_gate_failure(
    callback_query: types.CallbackQuery,
    res: Dict[str, Any],
) -> Dict[str, Any]:
    """
    Красиво показывает alert по результату ensure_add_withdraw / _withdraw_strict_or_alert.
    """
    err = _wd_safe_str(res.get("error"), "unknown")

    async def _safe_alert(text: str):
        try:
            await callback_query.answer(text, show_alert=True)
        except Exception as e:
            print(f"[WITHDRAW][ALERT][WARN] {type(e).__name__}: {e!r}")

    if err == "cooldown_active":
        left = _wd_safe_int(res.get("cooldown_left"), 0)
        await _safe_alert(f"📌 Кулдаун. Подождите {left} сек")
        return res

    if err == "exceeds_remaining":
        rem = _wd_safe_int(res.get("remaining"), 0)
        left = _wd_safe_int(res.get("cooldown_left"), 0)

        if rem <= 0 and left > 0:
            await _safe_alert(f"📌 Лимит исчерпан.\nКулдаун: {left} сек")
        elif rem > 0:
            if "_fmt_int" in globals() and callable(globals().get("_fmt_int")):
                await _safe_alert(f"📌 Превышен лимит.\nДоступно: {_fmt_int(rem)}")
            else:
                await _safe_alert(f"📌 Превышен лимит.\nДоступно: {rem}")
        else:
            await _safe_alert("📌 Превышен лимит вывода")
        return res

    if err == "insufficient_funds":
        bal = _wd_safe_int(res.get("balance"), 0)
        if "_fmt_int" in globals() and callable(globals().get("_fmt_int")):
            await _safe_alert(f"💭 Недостаточно кут.\nБаланс: {_fmt_int(bal)}")
        else:
            await _safe_alert(f"💭 Недостаточно кут.\nБаланс: {bal}")
        return res

    if err == "db_overflow":
        await _safe_alert("❌ Внутренняя ошибка лимитов/баланса")
        return res

    if err in ("db_missing", "db_method_missing", "db_error", "wrapper_exception", "bad_response"):
        await _safe_alert("❌ Ошибка вывода. Попробуйте позже")
        return res

    await _safe_alert("❌ Ошибка вывода")
    return res

async def _withdraw_strict_or_alert(
    callback_query: types.CallbackQuery,
    *,
    payer_id: int,
    amount: int,
    rid: str,
    reason: str = "manual_withdraw",
) -> Dict[str, Any]:
    """
    Единая железная точка вывода.

    ВАЖНО:
    - здесь не режем повторы вручную
    - duplicate не должен блокировать отправку сам по себе
    - если нужен повторный вывод, вызывающий код обязан давать новый rid
    """

    print("────────────────────────────────────────────")
    print(f"[WITHDRAW][STRICT] ▶️ start payer_id={payer_id} amount={amount} rid={rid!r} reason={reason!r}")

    async def _safe_alert(text: str):
        try:
            await callback_query.answer(text, show_alert=True)
        except Exception as e:
            print(f"[WITHDRAW][STRICT][ALERT][WARN] {type(e).__name__}: {e!r}")

    try:
        payer_id = int(payer_id)
        amount = int(amount)
        rid = _wd_safe_str(rid)
        reason = _wd_safe_str(reason, "manual_withdraw")
    except Exception as e:
        print(f"[WITHDRAW][STRICT][ABORT] 🟥 bad args err={e!r}")
        await _safe_alert("❌ Ошибка параметров вывода")
        return _wd_fail("bad_args")

    if payer_id <= 0:
        await _safe_alert("❌ Ошибка пользователя")
        return _wd_fail("invalid_user")

    if amount <= 0:
        await _safe_alert("❌ Неверная сумма")
        return _wd_fail("invalid_amount")

    if not rid:
        await _safe_alert("❌ Не найден идентификатор запроса")
        return _wd_fail("empty_request_id")

    chat_id = None
    chat_name = None
    msg_id = None

    try:
        msg_obj = getattr(callback_query, "message", None)
        if msg_obj is not None:
            msg_id = _wd_safe_int(getattr(msg_obj, "message_id", 0), 0) or None
            chat_obj = getattr(msg_obj, "chat", None)
            if chat_obj is not None:
                chat_id = _wd_safe_int(getattr(chat_obj, "id", 0), 0) or None
                chat_name = (
                    getattr(chat_obj, "title", None)
                    or getattr(chat_obj, "full_name", None)
                    or getattr(chat_obj, "username", None)
                )
    except Exception as e:
        print(f"[WITHDRAW][STRICT][WARN] read chat/meta failed: {e!r}")

    print(
        f"[WITHDRAW][STRICT][META] payer_id={payer_id} chat_id={chat_id} "
        f"msg_id={msg_id} chat_name={chat_name!r}"
    )

    try:
        res = await ensure_add_withdraw(
            user_id=int(payer_id),
            amount=int(amount),
            db=db,
            reason=str(reason or "manual_withdraw"),
            request_id=str(rid),
            chat_id=chat_id,
            chat_name=chat_name,
        )
    except Exception as e:
        print(f"[WITHDRAW][STRICT][ERROR] ensure_add_withdraw exception: {type(e).__name__}: {e!r}")
        await _safe_alert("❌ Ошибка вывода")
        return _wd_fail("wrapper_exception", db_exception_type=type(e).__name__, db_exception=repr(e))

    if not isinstance(res, dict):
        print(f"[WITHDRAW][STRICT][ERROR] bad response type={type(res).__name__} res={res!r}")
        await _safe_alert("❌ Ошибка вывода")
        return _wd_fail("bad_response", raw_type=type(res).__name__)

    ok = bool(res.get("ok"))
    committed = bool(res.get("committed"))
    duplicate = bool(res.get("duplicate"))
    should_send = bool(res.get("should_send_to_channel"))
    status = _wd_safe_str(res.get("status"), "")
    err = _wd_safe_str(res.get("error"), "unknown")

    print(
        f"[WITHDRAW][STRICT] ◀️ result ok={ok} committed={committed} "
        f"duplicate={duplicate} should_send={should_send} status={status!r} res={res!r}"
    )

    if ok and committed:
        return {
            **res,
            "committed": True,
            "duplicate": bool(duplicate),
            "should_send_to_channel": bool(res.get("should_send_to_channel", True)),
        }

    # Если wrapper вернул ok=True, но committed=False,
    # не режем это как "дубль" здесь автоматически.
    # Просто возвращаем как есть, чтобы внешний код сам решал, что делать.
    if ok and not committed:
        print(
            f"[WITHDRAW][STRICT][WARN] ok=True but committed=False "
            f"status={status!r} rid={rid} duplicate={duplicate}"
        )
        return {
            **res,
            "committed": False,
            "duplicate": bool(duplicate),
            "should_send_to_channel": bool(res.get("should_send_to_channel", False)),
        }

    print(f"[WITHDRAW][STRICT][FAIL] err={err!r} status={status!r}")
    return await _handle_withdraw_gate_failure(callback_query, res)

def _safe_ascii_token(value: str, default: str = "x") -> str:
    try:
        s = str(value or "").strip()
    except Exception:
        s = ""

    if not s:
        return default

    out = []
    for ch in s:
        if ch.isascii() and (ch.isalnum() or ch in ("-", "_")):
            out.append(ch)

    cleaned = "".join(out).strip("-_")
    return cleaned or default


def _short_hash(*parts: object, size: int = 10) -> str:
    raw = "|".join(str(x) for x in parts)
    return hashlib.sha256(raw.encode("utf-8", errors="ignore")).hexdigest()[:size]


def _mk_click_rid_from_callback(
    prefix: str,
    callback_query: types.CallbackQuery,
    *,
    user_id: int,
    amount: int,
    gift_emoji: str = "",
    extra: str = "",
) -> str:
    """
    ✅ Каждый новый физический клик -> новый RID.
    ✅ Даже если подарок один и тот же, сообщение то же самое и сумма та же.
    ✅ RID короткий и безопасный для БД.
    """
    try:
        cbid = str(getattr(callback_query, "id", "") or "").strip()
    except Exception:
        cbid = ""

    try:
        msg = getattr(callback_query, "message", None)
        msg_id = int(getattr(msg, "message_id", 0) or 0) if msg else 0
        chat_obj = getattr(msg, "chat", None) if msg else None
        chat_id = int(getattr(chat_obj, "id", 0) or 0) if chat_obj else 0
    except Exception:
        msg_id = 0
        chat_id = 0

    prefix_safe = _safe_ascii_token(prefix, "req")[:10]
    extra_safe = _safe_ascii_token(extra, "x")[:8]

    # хэш emoji вместо сырого emoji
    emoji_hash = _short_hash(gift_emoji or "", size=6)

    # уникальная часть именно на клик
    unique_part = _short_hash(
        cbid or uuid.uuid4().hex,
        time.time_ns(),
        uuid.uuid4().hex,
        size=16
    )

    rid = (
        f"{prefix_safe}_"
        f"u{int(user_id)}_"
        f"c{int(chat_id)}_"
        f"m{int(msg_id)}_"
        f"a{int(amount)}_"
        f"e{emoji_hash}_"
        f"x{extra_safe}_"
        f"{unique_part}"
    )

    # жёсткий лимит для БД
    rid = rid[:64].strip("_")
    return rid or uuid.uuid4().hex[:16]










































#
def _fmt0(v) -> str:
    try:
        return "{:,.0f}".format(int(v)).replace(",", ".")
    except Exception:
        return str(v)


def _mk_rid(*parts) -> str:
    """
    ✅ Детерминированный request_id (16 символов).
    Повторный клик по той же кнопке -> тот же rid -> строгая БД-операция вернёт duplicate, НЕ спишет повторно.
    """
    s = "|".join(str(p) for p in parts)
    return hashlib.md5(s.encode("utf-8")).hexdigest()[:16]



