def _fmt_sec_to_mmss(seconds: int) -> str:
    try:
        s = int(seconds or 0)
    except Exception:
        s = 0
    if s < 0:
        s = 0
    m = s // 60
    ss = s % 60
    if m <= 0:
        return f"{ss} сек"
    return f"{m} мин {ss:02d} сек"


def _kb_toolbox_limit(
    *,
    cooldown_left: int = 0,
    remaining: int = 0,
    daily_limit: int = 0,
    used: int = 0,
    back_cb: str = "9close_bonus",
) -> InlineKeyboardMarkup:
    # 1) информативные строки (noop)
    rows: List[List[InlineKeyboardButton]] = []

    try:
        cd = int(cooldown_left or 0)
    except Exception:
        cd = 0

    try:
        rem = int(remaining or 0)
    except Exception:
        rem = 0

    try:
        dl = int(daily_limit or 0)
    except Exception:
        dl = 0

    try:
        us = int(used or 0)
    except Exception:
        us = 0

    if cd > 0:
        rows.append([InlineKeyboardButton(text=f"⏳ Кулдаун: {_fmt_sec_to_mmss(cd)}", callback_data="noop")])

    # лимит/остаток - показываем, если знаем
    if dl > 0:
        # форматируй как любишь: _fmt0 или _fmt_int - оставлю _fmt0 (у тебя есть)
        rows.append([InlineKeyboardButton(text=f"📌 Лимит: {_fmt0(dl)} кут", callback_data="noop")])
        rows.append([InlineKeyboardButton(text=f"🧾 Использовано: {_fmt0(us)} кут", callback_data="noop")])

    # remaining - показываем тоже
    rows.append([InlineKeyboardButton(text=f"🏄 Доступно сейчас: {_fmt0(rem)} кут", callback_data="noop")])

    # 2) управляющие
    rows.append([InlineKeyboardButton(text="Обновить", callback_data="back_to_stars_choice", style="default" ,
                icon_custom_emoji_id="5318781800221273738")])
    rows.append([InlineKeyboardButton(text="✖️ Закрыть", callback_data=back_cb)])

    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _show_toolbox_limit_screen(
    callback_query: types.CallbackQuery,
    *,
    cooldown_left: int = 0,
    remaining: int = 0,
    daily_limit: int = 0,
    used: int = 0,
    back_cb: str = "9close_bonus",
) -> None:
    """
    Показывает 1 emoji '🧰' и инлайн-кнопки статуса.
    Без текста "Вывод недоступен", как ты хочешь.
    """
    # 0) гасим крутилку
    try:
        await callback_query.answer()
    except Exception:
        pass

    kb = _kb_toolbox_limit(
        cooldown_left=int(cooldown_left or 0),
        remaining=int(remaining or 0),
        daily_limit=int(daily_limit or 0),
        used=int(used or 0),
        back_cb=str(back_cb or "9close_bonus"),
    )

    msg = getattr(callback_query, "message", None)
    if msg is None:
        # если вдруг нет message - fallback в alert (не ломаемся)
        try:
            await callback_query.answer("🧰 Ограничение на вывод.", show_alert=True)
        except Exception:
            pass
        return

    try:
        await msg.edit_text("🧰", reply_markup=kb, parse_mode="HTML", disable_web_page_preview=True)
    except Exception as e:
        print(f"🟨[GIFTGIFT][TOOLBOX][WARN] edit_text failed: {type(e).__name__}: {e!r}")
        # fallback: просто сообщением
        try:
            await msg.answer("🧰", reply_markup=kb)
        except Exception as e2:
            print(f"🟥[GIFTGIFT][TOOLBOX][ERROR] answer failed: {type(e2).__name__}: {e2!r}")


# =========================================================
# GIFTGIFT SEND REQUEST ACTION REGISTRY
# =========================================================




def _cleanup_giftgift_send_request_actions() -> None:
    now_ts = time.time()
    expired_tokens = []

    for token, payload in list(GIFTGIFT_SEND_REQUEST_ACTIONS.items()):
        try:
            ts = float(payload.get("ts", 0) or 0)
        except Exception:
            ts = 0.0

        if ts <= 0 or (now_ts - ts) > GIFTGIFT_SEND_REQUEST_ACTION_TTL:
            expired_tokens.append(token)

    for token in expired_tokens:
        GIFTGIFT_SEND_REQUEST_ACTIONS.pop(token, None)


def _register_giftgift_send_request_action(payload: Dict[str, Any]) -> str:
    _cleanup_giftgift_send_request_actions()
    token = uuid.uuid4().hex[:12]
    row = {
        **dict(payload or {}),
        "ts": time.time(),
    }
    GIFTGIFT_SEND_REQUEST_ACTIONS[token] = row
    try:
        from bot.runtime.button_lifecycle import bind_registered_token
        bind_registered_token(GIFTGIFT_SEND_REQUEST_ACTIONS, token, row, prefix="ggsr")
    except Exception:
        pass
    return token


def _get_giftgift_send_request_action(token: str) -> Optional[Dict[str, Any]]:
    _cleanup_giftgift_send_request_actions()
    return GIFTGIFT_SEND_REQUEST_ACTIONS.get(str(token or "").strip())


def _pop_giftgift_send_request_action(token: str) -> Optional[Dict[str, Any]]:
    _cleanup_giftgift_send_request_actions()
    return GIFTGIFT_SEND_REQUEST_ACTIONS.pop(str(token or "").strip(), None)


def build_giftgift_send_request_callback(
    *,
    amount: int,
    receiver_user_id: int,
    payer_user_id: int,
    gift_emoji: str,
    has_upgrade: int,
    gift_id: int = 0,
) -> str:
    """
    Возвращает безопасный callback_data <= 64 байт.

    Форматы:
      1) legacy:
         giftgift_send_request_<amount>_<receiver>_<payer>_<emoji>_<has_upgrade>_<gift_id>

      2) short:
         ggsr:<token>
    """
    amount_i = int(amount or 0)
    receiver_i = int(receiver_user_id or 0)
    payer_i = int(payer_user_id or 0)
    has_upgrade_i = 1 if int(has_upgrade or 0) else 0
    gift_id_i = int(gift_id or 0)
    gift_emoji_s = str(gift_emoji or "🎁")

    legacy = (
        f"giftgift_send_request_"
        f"{amount_i}_{receiver_i}_{payer_i}_{gift_emoji_s}_{has_upgrade_i}_{gift_id_i}"
    )

    # Если влезает - используем прямой формат
    if len(legacy.encode("utf-8")) <= 64:
        print(
            f"🧩[GIFTGIFT][CBUILD] legacy ok "
            f"len={len(legacy.encode('utf-8'))} gift_id={gift_id_i} cb={legacy!r}"
        )
        return legacy

    # Если не влезает - используем короткий токен
    token = _register_giftgift_send_request_action({
        "amount": amount_i,
        "receiver_user_id": receiver_i,
        "payer_user_id": payer_i,
        "gift_emoji": gift_emoji_s,
        "has_upgrade": has_upgrade_i,
        "gift_id": gift_id_i,
    })
    short_cb = f"ggsr:{token}"

    print(
        f"🧩[GIFTGIFT][CBUILD] short token "
        f"len={len(short_cb.encode('utf-8'))} gift_id={gift_id_i} cb={short_cb!r}"
    )
    return short_cb









