# CONFIG
# =========================================================
WITHDRAW_HELP_USERNAME = "jerichocute"
WITHDRAW_HELP_TEXT = "Привет, это сообщение для вывода валюты"

WITHDRAW_RECIPIENT_OK_TTL = 300
WITHDRAW_RECIPIENT_FAIL_TTL = 20
WITHDRAW_DIALOG_SCAN_LIMIT = 300

WITHDRAW_RECIPIENT_CHECK_CACHE: Dict[str, Dict[str, Any]] = {}

_WITHDRAW_ME_CACHE: Dict[str, Any] = {
    "ts": 0.0,
    "id": 0,
    "username": "",
    "phone": "",
}


# =========================================================
# SAFE HELPERS
# =========================================================
def _wdchk_safe_int(v, default: int = 0) -> int:
    try:
        return int(v)
    except Exception:
        return int(default)


def _wdchk_safe_str(v, default: str = "") -> str:
    try:
        if v is None:
            return default
        s = str(v).strip()
        return s if s else default
    except Exception:
        return default


def _normalize_username_for_check(value: Optional[str]) -> str:
    try:
        raw = str(value or "").strip().lstrip("@")
        if raw and re.fullmatch(r"[A-Za-z0-9_]{5,32}", raw):
            return raw
    except Exception:
        pass
    return ""


def _build_withdraw_help_url() -> str:
    text = quote(WITHDRAW_HELP_TEXT)
    return f"https://t.me/{WITHDRAW_HELP_USERNAME}?text={text}"


def _make_withdraw_check_cache_key(
    recipient_user_id: int,
    recipient_username: str,
    *,
    must_have_dialog: bool,
) -> str:
    return (
        f"{_wdchk_safe_int(recipient_user_id, 0)}:"
        f"{_normalize_username_for_check(recipient_username).lower()}:"
        f"dialog={1 if must_have_dialog else 0}"
    )

def _get_cached_withdraw_check(
    recipient_user_id: int,
    recipient_username: str,
    *,
    must_have_dialog: bool,
) -> Optional[Dict[str, Any]]:
    try:
        key = _make_withdraw_check_cache_key(
            recipient_user_id,
            recipient_username,
            must_have_dialog=must_have_dialog,
        )
        row = WITHDRAW_RECIPIENT_CHECK_CACHE.get(key)
        if not row:
            return None

        ts = float(row.get("ts") or 0.0)
        ok = bool(row.get("ok"))
        ttl = WITHDRAW_RECIPIENT_OK_TTL if ok else WITHDRAW_RECIPIENT_FAIL_TTL

        age = time.time() - ts
        if age <= ttl:
            print(
                f"🧠[WITHDRAW][CHECK][CACHE] hit key={key} "
                f"ok={ok} age={age:.2f}s ttl={ttl}s"
            )
            return dict(row)

        WITHDRAW_RECIPIENT_CHECK_CACHE.pop(key, None)

    except Exception as e:
        print(f"🟨[WITHDRAW][CHECK][CACHE][WARN] get err={type(e).__name__}: {e!r}")

    return None


def _put_cached_withdraw_check(
    recipient_user_id: int,
    recipient_username: str,
    payload: Dict[str, Any],
    *,
    must_have_dialog: bool,
) -> None:
    try:
        key = _make_withdraw_check_cache_key(
            recipient_user_id,
            recipient_username,
            must_have_dialog=must_have_dialog,
        )
        WITHDRAW_RECIPIENT_CHECK_CACHE[key] = {
            **dict(payload or {}),
            "ts": time.time(),
        }
        print(f"💾[WITHDRAW][CHECK][CACHE] save key={key} payload={WITHDRAW_RECIPIENT_CHECK_CACHE[key]!r}")
    except Exception as e:
        print(f"🟨[WITHDRAW][CHECK][CACHE][WARN] put err={type(e).__name__}: {e!r}")


def _strip_tg_emoji_tags(text: str) -> str:
    try:
        s = str(text or "")
        s = re.sub(r"</?tg-emoji[^>]*>", "", s, flags=re.IGNORECASE)
        return s
    except Exception:
        return str(text or "")


def _strip_html_tags_soft(text: str) -> str:
    try:
        s = str(text or "")
        s = re.sub(r"</?tg-emoji[^>]*>", "", s, flags=re.IGNORECASE)
        s = re.sub(r"</?(?:b|i|u|s|code|pre|blockquote)>", "", s, flags=re.IGNORECASE)
        s = s.replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&")
        return s
    except Exception:
        return str(text or "")


def _looks_like_document_invalid_error(err: Exception) -> bool:
    try:
        msg = str(err or "")
        return "DOCUMENT_INVALID" in msg.upper()
    except Exception:
        return False


# =========================================================
# USERBOT ACCESS
# =========================================================
async def _try_call_maybe_async(func, *args, **kwargs):
    try:
        res = func(*args, **kwargs)
        if hasattr(res, "__await__"):
            return await res
        return res
    except TypeError:
        res = func()
        if hasattr(res, "__await__"):
            return await res
        return res


_CLIENT_ATTR_NAMES = (
    "_WITHDRAW_USERBOT_CLIENT",
    "withdraw_userbot_client",
    "withdraw_client",
    "WITHDRAW_USERBOT_CLIENT",
)


def _client_attr_from_mapping(mapping) -> Any:
    """Достаёт уже созданный client из dict/module attrs. Без вызова getter'ов."""
    if mapping is None:
        return None
    getter = mapping.get if hasattr(mapping, "get") else None
    for attr_name in _CLIENT_ATTR_NAMES:
        try:
            if getter is not None:
                client = getter(attr_name)
            else:
                client = getattr(mapping, attr_name, None)
            if client is not None and hasattr(client, "is_connected"):
                return client
        except Exception:
            continue
    return None


async def _get_registered_withdraw_userbot_client_silent():
    """
    Ищет УЖЕ созданный withdraw-client только по атрибутам registry.

    ВАЖНО: НИКОГДА не вызывать get_withdraw_userbot_client() отсюда —
    он сам зовёт этот silent-lookup → RecursionError.
    """
    client = _client_attr_from_mapping(globals())
    if client is not None:
        return client

    for mod_name in ("__main__", "main"):
        mod = sys.modules.get(mod_name)
        client = _client_attr_from_mapping(mod)
        if client is not None:
            return client

    for mod_name in (
        "withdraw_userbot_runtime",
        "withdraw_runtime",
        "withdraw_service",
        "gift_executor",
    ):
        mod = sys.modules.get(mod_name)
        if mod is None:
            continue
        client = _client_attr_from_mapping(mod)
        if client is not None:
            return client
        runtime_obj = getattr(mod, "withdraw_userbot_runtime", None)
        if runtime_obj is not None:
            cached = getattr(runtime_obj, "client", None) or getattr(runtime_obj, "_client", None)
            if cached is not None and hasattr(cached, "is_connected"):
                return cached

    try:
        for mod_name, mod in list(sys.modules.items()):
            if mod is None:
                continue
            mod_name_l = str(mod_name).lower()
            if not any(key in mod_name_l for key in ("withdraw", "main", "run_bot")):
                continue
            client = _client_attr_from_mapping(mod)
            if client is not None:
                return client
    except Exception as e:
        print(f"🟨[WITHDRAW][CHECK] sys.modules scan err={type(e).__name__}: {e!r}")

    return None


async def _ensure_withdraw_userbot_connected_for_check():
    """
    Только connect + auth-check.
    НЕ start()
    НЕ login()
    НЕ создаёт нового клиента
    """
    client = await _get_registered_withdraw_userbot_client_silent()
    if client is None:
        return None, "client_missing"

    for attr in ("connect", "is_connected", "is_user_authorized"):
        if not hasattr(client, attr):
            print(f"🟥[WITHDRAW][CHECK] найденный объект не похож на TelegramClient: missing attr={attr}")
            return None, "client_invalid_object"

    try:
        if not client.is_connected():
            print("🔌[WITHDRAW][CHECK] client disconnected -> connect()")
            await client.connect()
    except Exception as e:
        print(f"🟥[WITHDRAW][CHECK] connect error: {type(e).__name__}: {e!r}")
        return None, "client_connect_error"

    try:
        is_auth = await client.is_user_authorized()
        print(f"🧪[WITHDRAW][CHECK] is_user_authorized={is_auth}")
        if not is_auth:
            print("🟥[WITHDRAW][CHECK] session not authorized")
            return None, "client_not_authorized"
    except Exception as e:
        print(f"🟥[WITHDRAW][CHECK] auth check error: {type(e).__name__}: {e!r}")
        return None, "client_auth_check_error"

    try:
        validator = globals().get("_validate_withdraw_userbot_identity")
        if callable(validator):
            await validator(client)
            print("🟩[WITHDRAW][CHECK] identity validation passed")
    except Exception as e:
        print(f"🟥[WITHDRAW][CHECK] identity validation error: {type(e).__name__}: {e!r}")
        if _is_auth_key_duplicated_error(e) or "AuthKeyDuplicated" in str(e):
            global WITHDRAW_USERBOT_READY
            WITHDRAW_USERBOT_READY = False
            try:
                await _wd_alert_userbot_unauthorized(
                    reason="AuthKeyDuplicatedError: session killed (two IPs / rolling deploy)"
                )
            except Exception as alert_err:
                print(f"🟨[WITHDRAW][CHECK] alert failed: {alert_err!r}")
            return None, "client_auth_key_duplicated"
        return None, "client_identity_invalid"

    return client, ""


async def _get_withdraw_me_cached(client) -> Dict[str, Any]:
    now = time.time()

    try:
        if (_WITHDRAW_ME_CACHE.get("id") or 0) > 0 and (now - float(_WITHDRAW_ME_CACHE.get("ts") or 0.0)) <= 300:
            return {
                "id": int(_WITHDRAW_ME_CACHE.get("id") or 0),
                "username": str(_WITHDRAW_ME_CACHE.get("username") or ""),
                "phone": str(_WITHDRAW_ME_CACHE.get("phone") or ""),
            }
    except Exception:
        pass

    me = await client.get_me()
    uid = int(getattr(me, "id", 0) or 0)
    uname = str(getattr(me, "username", "") or "")
    phone = str(getattr(me, "phone", "") or "")

    _WITHDRAW_ME_CACHE["ts"] = now
    _WITHDRAW_ME_CACHE["id"] = uid
    _WITHDRAW_ME_CACHE["username"] = uname
    _WITHDRAW_ME_CACHE["phone"] = phone

    print(f"👤[WITHDRAW][CHECK][ME] id={uid} username={uname!r} phone={phone!r}")

    return {
        "id": uid,
        "username": uname,
        "phone": phone,
    }


# =========================================================
# MAIN CHECK
# =========================================================
async def _check_withdraw_userbot_can_resolve_recipient(
    recipient_user_id: int,
    recipient_username: Optional[str] = None,
    *,
    must_have_dialog: bool = True,
) -> Dict[str, Any]:
    """
    Строгая пред-проверка для выводного юзербота.

    Если must_have_dialog=True:
    Успехом считается ТОЛЬКО наличие реального личного диалога
    между выводным юзерботом и получателем.

    Возвращает:
    {
        "ok": bool,
        "reason": str,
        "method": str,
        "human": str,
        "recipient_user_id": int,
        "recipient_username": str,
        "resolved_as": str,
        "has_dialog": bool,
        "can_resolve": bool,
    }
    """
    recipient_user_id = _wdchk_safe_int(recipient_user_id, 0)
    recipient_username = _normalize_username_for_check(recipient_username)

    cached = _get_cached_withdraw_check(
        recipient_user_id,
        recipient_username,
        must_have_dialog=must_have_dialog,
    )
    if cached is not None:
        cached.setdefault("has_dialog", False)
        cached.setdefault("can_resolve", bool(cached.get("ok")))
        return cached

    result = {
        "ok": False,
        "reason": "unknown",
        "method": "",
        "human": "",
        "recipient_user_id": recipient_user_id,
        "recipient_username": recipient_username,
        "resolved_as": "",
        "has_dialog": False,
        "can_resolve": False,
    }

    if recipient_user_id <= 0:
        result["reason"] = "bad_recipient_id"
        result["human"] = "Некорректный user_id получателя"
        _put_cached_withdraw_check(
            recipient_user_id,
            recipient_username,
            result,
            must_have_dialog=must_have_dialog,
        )
        return result

    client, client_err = await _ensure_withdraw_userbot_connected_for_check()
    if client is None:
        result["reason"] = client_err or "client_unavailable"

        if result["reason"] == "client_missing":
            result["human"] = "Технический юзербот для выводов не зарегистрирован"
        elif result["reason"] == "client_connect_error":
            result["human"] = "Не удалось подключить технический юзербот для выводов"
        elif result["reason"] == "client_not_authorized":
            result["human"] = "Технический юзербот для выводов не авторизован"
        elif result["reason"] == "client_auth_check_error":
            result["human"] = "Не удалось проверить авторизацию технического юзербота"
        elif result["reason"] == "client_auth_key_duplicated":
            result["human"] = (
                "Session выводного юзербота убита (AuthKeyDuplicated): "
                "один ключ открыли с двух IP. Нужен reauth-withdraw.bat --fresh"
            )
        elif result["reason"] == "client_identity_invalid":
            result["human"] = "Открыта неверная session технического юзербота"
        elif result["reason"] == "client_invalid_object":
            result["human"] = "Найденный объект выводного юзербота имеет неверный тип"
        else:
            result["human"] = "Технический юзербот для выводов недоступен"

        _put_cached_withdraw_check(
            recipient_user_id,
            recipient_username,
            result,
            must_have_dialog=must_have_dialog,
        )
        return result

    # -----------------------------------------------------
    # 0) self
    # -----------------------------------------------------
    try:
        me = await _get_withdraw_me_cached(client)
        if int(me.get("id") or 0) == recipient_user_id:
            result["ok"] = True
            result["reason"] = "self"
            result["method"] = "me"
            result["resolved_as"] = "self"
            result["human"] = ""
            result["has_dialog"] = True
            result["can_resolve"] = True
            _put_cached_withdraw_check(
                recipient_user_id,
                recipient_username,
                result,
                must_have_dialog=must_have_dialog,
            )
            return result
    except Exception as e:
        print(f"🟨[WITHDRAW][CHECK][ME][WARN] {type(e).__name__}: {e!r}")

    # -----------------------------------------------------
    # 1) СТРОГАЯ ПРОВЕРКА:
    # ИЩЕМ ИМЕННО ЛИЧНЫЙ ДИАЛОГ
    # -----------------------------------------------------
    try:
        scanned = 0

        async for dialog in client.iter_dialogs(limit=WITHDRAW_DIALOG_SCAN_LIMIT):
            scanned += 1

            ent = getattr(dialog, "entity", None)
            if ent is None:
                continue

            dialog_uid = _wdchk_safe_int(getattr(ent, "id", 0), 0)
            dialog_username = _normalize_username_for_check(getattr(ent, "username", ""))

            # Можно дополнительно отфильтровать только user-диалоги
            # если хочешь ещё жёстче:
            # if not getattr(dialog, "is_user", False):
            #     continue

            if dialog_uid == recipient_user_id:
                result["ok"] = True
                result["reason"] = "ok"
                result["method"] = "dialogs_by_id"
                result["resolved_as"] = str(recipient_user_id)
                result["human"] = ""
                result["has_dialog"] = True
                result["can_resolve"] = True
                print(f"🟩[WITHDRAW][CHECK] recipient found in dialogs by id={recipient_user_id} scanned={scanned}")
                _put_cached_withdraw_check(
                    recipient_user_id,
                    recipient_username,
                    result,
                    must_have_dialog=must_have_dialog,
                )
                return result

            if recipient_username and dialog_username and dialog_username.lower() == recipient_username.lower():
                result["ok"] = True
                result["reason"] = "ok"
                result["method"] = "dialogs_by_username"
                result["resolved_as"] = f"@{recipient_username}"
                result["human"] = ""
                result["has_dialog"] = True
                result["can_resolve"] = True
                print(f"🟩[WITHDRAW][CHECK] recipient found in dialogs by username=@{recipient_username} scanned={scanned}")
                _put_cached_withdraw_check(
                    recipient_user_id,
                    recipient_username,
                    result,
                    must_have_dialog=must_have_dialog,
                )
                return result

        print(f"🟨[WITHDRAW][CHECK] dialog scan finished scanned={scanned}")

    except Exception as e:
        print(f"🟨[WITHDRAW][CHECK] iter_dialogs failed: {type(e).__name__}: {e!r}")

    # -----------------------------------------------------
    # 2) МЯГКАЯ ПРОВЕРКА:
    # МОЖЕТ ЛИ ЮЗЕРБОТ ХОТЯ БЫ ЗАРЕЗОЛВИТЬ ENTITY
    # -----------------------------------------------------
    if recipient_username:
        for candidate in (recipient_username, f"@{recipient_username}"):
            try:
                ent = await client.get_input_entity(candidate)
                if ent is not None:
                    result["can_resolve"] = True
                    result["resolved_as"] = f"@{recipient_username}"
                    result["method"] = "username_input_entity"
                    print(f"🟨[WITHDRAW][CHECK] recipient resolved only by username_input_entity={candidate!r}")
                    break
            except Exception as e:
                print(f"🟨[WITHDRAW][CHECK] get_input_entity({candidate!r}) failed: {type(e).__name__}: {e!r}")

    if not result["can_resolve"] and recipient_username:
        for candidate in (recipient_username, f"@{recipient_username}"):
            try:
                full_entity = await client.get_entity(candidate)

                resolved_id = _wdchk_safe_int(getattr(full_entity, "id", 0), 0)
                resolved_username = _normalize_username_for_check(getattr(full_entity, "username", ""))

                if resolved_id > 0 and resolved_id != recipient_user_id:
                    result["ok"] = False
                    result["reason"] = "username_points_to_other_user"
                    result["method"] = "username_get_entity_mismatch"
                    result["resolved_as"] = f"@{resolved_username or recipient_username}"
                    result["human"] = (
                        f"Username @{recipient_username} сейчас ведёт не на того пользователя. "
                        f"Ожидался user_id={recipient_user_id}, а Telegram вернул user_id={resolved_id}"
                    )
                    print(
                        f"🟥[WITHDRAW][CHECK] username mismatch "
                        f"expected_uid={recipient_user_id} actual_uid={resolved_id}"
                    )
                    _put_cached_withdraw_check(
                        recipient_user_id,
                        recipient_username,
                        result,
                        must_have_dialog=must_have_dialog,
                    )
                    return result

                ent = await client.get_input_entity(full_entity)
                if ent is not None:
                    result["can_resolve"] = True
                    result["resolved_as"] = f"@{resolved_username or recipient_username}"
                    result["method"] = "username_get_entity"
                    print(f"🟨[WITHDRAW][CHECK] recipient resolved only by username_get_entity={candidate!r}")
                    break

            except Exception as e:
                print(f"🟨[WITHDRAW][CHECK] get_entity({candidate!r}) failed: {type(e).__name__}: {e!r}")

    if not result["can_resolve"]:
        try:
            ent = await client.get_input_entity(int(recipient_user_id))
            if ent is not None:
                result["can_resolve"] = True
                result["resolved_as"] = str(recipient_user_id)
                result["method"] = "user_id"
                print(f"🟨[WITHDRAW][CHECK] recipient resolved only by user_id={recipient_user_id}")
        except Exception as e:
            print(f"🟨[WITHDRAW][CHECK] get_input_entity(user_id={recipient_user_id}) failed: {type(e).__name__}: {e!r}")

    if not result["can_resolve"] and PeerUser is not None:
        try:
            ent = await client.get_input_entity(PeerUser(user_id=int(recipient_user_id)))
            if ent is not None:
                result["can_resolve"] = True
                result["resolved_as"] = str(recipient_user_id)
                result["method"] = "peer_user"
                print(f"🟨[WITHDRAW][CHECK] recipient resolved only by PeerUser id={recipient_user_id}")
        except Exception as e:
            print(f"🟨[WITHDRAW][CHECK] get_input_entity(PeerUser({recipient_user_id})) failed: {type(e).__name__}: {e!r}")

    # -----------------------------------------------------
    # 3) ФИНАЛЬНАЯ ЛОГИКА
    # -----------------------------------------------------
    if must_have_dialog:
        result["ok"] = False
        result["reason"] = "recipient_has_no_dialog_with_withdraw_userbot"
        result["has_dialog"] = False

        if recipient_username:
            result["human"] = (
                f"Технический аккаунт для выводов пока не имеет личного диалога с @{recipient_username}. "
                f"Попросите получателя написать в личные сообщения с @{WITHDRAW_HELP_USERNAME}, "
                f"после этого нажмите «Проверить снова»."
            )
        else:
            result["human"] = (
                "Технический аккаунт для выводов пока не имеет личного диалога с получателем. "
                "Попросите получателя написать в личные сообщения с tech userbot, после этого можно повторить проверку."
            )

        print(
            f"🟥[WITHDRAW][CHECK] strict fail: no dialog with withdraw userbot "
            f"user_id={recipient_user_id} username=@{recipient_username or ''} "
            f"can_resolve={result['can_resolve']}"
        )

        _put_cached_withdraw_check(
            recipient_user_id,
            recipient_username,
            result,
            must_have_dialog=must_have_dialog,
        )
        return result

    # мягкий режим
    if result["can_resolve"]:
        result["ok"] = True
        result["reason"] = "ok_soft_resolve"
        result["human"] = ""
        _put_cached_withdraw_check(
            recipient_user_id,
            recipient_username,
            result,
            must_have_dialog=must_have_dialog,
        )
        return result

    result["ok"] = False
    result["reason"] = "recipient_not_visible_for_withdraw_userbot"
    result["method"] = ""
    result["resolved_as"] = ""
    result["has_dialog"] = False
    result["can_resolve"] = False

    if recipient_username:
        result["human"] = (
            f"Технический аккаунт для выводов пока не видит получателя @{recipient_username}. "
            f"Попросите получателя написать в личные сообщения с @{WITHDRAW_HELP_USERNAME}, "
            f"после этого можно нажать «Проверить снова»."
        )
    else:
        result["human"] = (
            "Технический аккаунт для выводов пока не видит получателя. "
            "Желательно, чтобы у получателя был username и чтобы он сначала написал tech userbot."
        )

    print(
        f"🟥[WITHDRAW][CHECK] recipient NOT visible for withdraw userbot "
        f"user_id={recipient_user_id} username=@{recipient_username or ''}"
    )

    _put_cached_withdraw_check(
        recipient_user_id,
        recipient_username,
        result,
        must_have_dialog=must_have_dialog,
    )
    return result


