async def _safe_render_withdraw_check_message(
    callback_query,
    *,
    text: str,
    reply_markup: Optional[InlineKeyboardMarkup] = None,
) -> bool:
    msg = getattr(callback_query, "message", None)
    user_id = _wdchk_safe_int(getattr(getattr(callback_query, "from_user", None), "id", 0), 0)

    if msg is not None:
        try:
            current_text = _wd_safe_str(getattr(msg, "text", ""), "")
            target_plain = _strip_html_tags_soft(text)
            if current_text and target_plain and current_text == target_plain:
                print("🟦[WITHDRAW][UI][SAFE] edit_text skipped: same visible text")
                return True
        except Exception:
            pass

        try:
            await msg.edit_text(
                text=text,
                reply_markup=reply_markup,
                parse_mode="HTML",
                disable_web_page_preview=True,
            )
            print("🟩[WITHDRAW][UI][SAFE] rendered via edit_text HTML")
            return True
        except Exception as e:
            s = str(e).lower()
            if "message is not modified" in s:
                print("🟦[WITHDRAW][UI][SAFE] edit_text skipped: message is not modified")
                return True
            print(f"🟨[WITHDRAW][UI][SAFE] edit_text HTML err={type(e).__name__}: {e!r}")
            if _looks_like_document_invalid_error(e):
                try:
                    await msg.edit_text(
                        text=_strip_tg_emoji_tags(text),
                        reply_markup=reply_markup,
                        parse_mode="HTML",
                        disable_web_page_preview=True,
                    )
                    print("🟩[WITHDRAW][UI][SAFE] rendered via edit_text HTML without tg-emoji")
                    return True
                except Exception as e2:
                    print(f"🟨[WITHDRAW][UI][SAFE] edit_text HTML no-tg-emoji err={type(e2).__name__}: {e2!r}")

    if msg is not None:
        try:
            await msg.edit_caption(
                caption=text,
                reply_markup=reply_markup,
                parse_mode="HTML",
            )
            print("🟩[WITHDRAW][UI][SAFE] rendered via edit_caption HTML")
            return True
        except Exception as e:
            s = str(e).lower()
            if "message is not modified" in s:
                print("🟦[WITHDRAW][UI][SAFE] edit_caption skipped: message is not modified")
                return True
            if "there is no caption" in s:
                print("🟦[WITHDRAW][UI][SAFE] edit_caption skipped: message has no caption")
            else:
                print(f"🟨[WITHDRAW][UI][SAFE] edit_caption HTML err={type(e).__name__}: {e!r}")
            if _looks_like_document_invalid_error(e):
                try:
                    await msg.edit_caption(
                        caption=_strip_tg_emoji_tags(text),
                        reply_markup=reply_markup,
                        parse_mode="HTML",
                    )
                    print("🟩[WITHDRAW][UI][SAFE] rendered via edit_caption HTML without tg-emoji")
                    return True
                except Exception as e2:
                    print(f"🟨[WITHDRAW][UI][SAFE] edit_caption HTML no-tg-emoji err={type(e2).__name__}: {e2!r}")

    if user_id > 0:
        try:
            await bot1.send_message(
                chat_id=user_id,
                text=text,
                reply_markup=reply_markup,
                parse_mode="HTML",
                disable_web_page_preview=True,
            )
            print("🟩[WITHDRAW][UI][SAFE] rendered via fallback send_message HTML")
            return True
        except Exception as e:
            print(f"🟥[WITHDRAW][UI][SAFE] fallback send_message HTML err={type(e).__name__}: {e!r}")
            if _looks_like_document_invalid_error(e):
                try:
                    await bot1.send_message(
                        chat_id=user_id,
                        text=_strip_tg_emoji_tags(text),
                        reply_markup=reply_markup,
                        parse_mode="HTML",
                        disable_web_page_preview=True,
                    )
                    print("🟩[WITHDRAW][UI][SAFE] rendered via fallback send_message HTML without tg-emoji")
                    return True
                except Exception as e2:
                    print(f"🟥[WITHDRAW][UI][SAFE] fallback send_message HTML no-tg-emoji err={type(e2).__name__}: {e2!r}")

        ok_plain = await _send_plain_message_fallback(user_id, text, reply_markup=reply_markup)
        if ok_plain:
            return True

    return False


