async def _ensure_withdraw_recipient_visible_or_show_ui(
    callback_query,
    *,
    retry_callback_data: str,
    recipient_user_id: int,
    recipient_username: str,
    is_friend_flow: bool,
) -> bool:
    """
    Главная точка строгой проверки перед выводом.
    Для подарков у нас обязательно нужен личный диалог с выводным юзерботом.
    """
    check = await _check_withdraw_userbot_can_resolve_recipient(
        recipient_user_id=_wdchk_safe_int(recipient_user_id, 0),
        recipient_username=recipient_username,
        must_have_dialog=True,
    )

    ok = bool(check.get("ok"))
    reason = _wdchk_safe_str(check.get("reason"), "")
    method = _wdchk_safe_str(check.get("method"), "")
    human = _wdchk_safe_str(check.get("human"), "")
    has_dialog = bool(check.get("has_dialog"))
    can_resolve = bool(check.get("can_resolve"))

    print(
        f"🔎[WITHDRAW][CHECK] recipient_user_id={recipient_user_id} "
        f"recipient_username=@{_normalize_username_for_check(recipient_username) or ''} "
        f"ok={ok} reason={reason!r} method={method!r} "
        f"has_dialog={has_dialog} can_resolve={can_resolve}"
    )

    if ok:
        return True

    # -----------------------------------------------------
    # SYSTEM PROBLEM
    # -----------------------------------------------------
    if reason in {
        "client_missing",
        "client_connect_error",
        "client_not_authorized",
        "client_auth_check_error",
        "client_identity_invalid",
        "client_unavailable",
        "client_invalid_object",
    }:
        return await _show_withdraw_service_problem(
            callback_query,
            retry_callback_data=retry_callback_data,
            human_reason=human,
        )

    # -----------------------------------------------------
    # NO DIALOG / NOT VISIBLE
    # -----------------------------------------------------
    return await _show_withdraw_visibility_problem(
        callback_query,
        retry_callback_data=retry_callback_data,
        recipient_user_id=_wdchk_safe_int(recipient_user_id, 0),
        recipient_username=recipient_username,
        is_friend_flow=bool(is_friend_flow),
        human_reason=human,
    )




WITHDRAW_BUTTON_COOLDOWN_SEC = 5.0

withdraw_button_click_guard = LazyGameStore("withdraw_button_click_guard")
giftgift_button_click_guard = LazyGameStore("giftgift_button_click_guard")


def _wd_btn_now() -> float:
    try:
        return float(time.time())
    except Exception:
        return 0.0


def _wd_btn_safe_int(v, default: int = 0) -> int:
    try:
        return int(v)
    except Exception:
        return int(default)


def _wd_btn_cleanup_guard(storage: dict, max_age: float = 3600.0) -> None:
    try:
        now = _wd_btn_now()
        to_delete = []

        for key, ts in list(storage.items()):
            try:
                if (now - float(ts)) > float(max_age):
                    to_delete.append(key)
            except Exception:
                to_delete.append(key)

        for key in to_delete:
            storage.pop(key, None)

    except Exception as e:
        print(f"🟨[WITHDRAW][BTN_GUARD][CLEANUP][WARN] {type(e).__name__}: {e!r}")


async def _check_button_cooldown_or_answer(
    callback_query: types.CallbackQuery,
    *,
    storage: dict,
    action_name: str,
    cooldown_sec: float = WITHDRAW_BUTTON_COOLDOWN_SEC,
) -> bool:
    """
    Возвращает:
    - True  -> можно продолжать
    - False -> пользователь нажал слишком рано, показан callback.answer
    """
    try:
        user_id = _wd_btn_safe_int(getattr(getattr(callback_query, "from_user", None), "id", 0), 0)
        if user_id <= 0:
            return True

        _wd_btn_cleanup_guard(storage)

        now = _wd_btn_now()
        last_ts = float(storage.get(user_id, 0.0) or 0.0)
        elapsed = now - last_ts

        if last_ts > 0 and elapsed < float(cooldown_sec):
            left = max(1, int((float(cooldown_sec) - elapsed) + 0.999))
            text = f"⌚️ Подождите {left} сек. перед следующим нажатием"

            print(
                f"⏳[WITHDRAW][BTN_GUARD] block action={action_name} "
                f"user_id={user_id} elapsed={elapsed:.3f}s left={left}s"
            )

            try:
                await callback_query.answer(text, show_alert=False)
            except Exception as e:
                print(f"🟨[WITHDRAW][BTN_GUARD][ANSWER][WARN] {type(e).__name__}: {e!r}")

            return False

        storage[user_id] = now

        print(
            f"🟩[WITHDRAW][BTN_GUARD] pass action={action_name} "
            f"user_id={user_id} cooldown={cooldown_sec}s"
        )
        return True

    except Exception as e:
        print(f"🟨[WITHDRAW][BTN_GUARD][WARN] action={action_name} err={type(e).__name__}: {e!r}")
        return True


def _withdraw_auto_gift_enabled() -> bool:
    # Ручной режим выплат:
    # подарок отправляется ТОЛЬКО когда администратор нажмёт 👍.
    return False


async def _wd_try_auto_gift_delivery_after_strict(
    *,
    request_id: str,
    sender_user_id: int,
    sender_username: str,
    sender_first_name: str,
    recipient_user_id: int,
    recipient_username: str,
    recipient_first_name: str,
    amount: int,
    is_friend: bool,
    gift_id: int = 0,
    has_upgrade: int = 0,
) -> Dict[str, Any]:
    request_id = _wd_safe_str(request_id, "")
    sender_user_id = _wd_safe_int(sender_user_id, 0)
    recipient_user_id = _wd_safe_int(recipient_user_id, 0)
    amount = _wd_safe_int(amount, 0)
    gift_id = _wd_safe_int(gift_id, 0)
    has_upgrade = _wd_safe_int(has_upgrade, 0)
    is_friend = bool(is_friend)
    is_self_withdraw = sender_user_id > 0 and sender_user_id == recipient_user_id

    if not _withdraw_auto_gift_enabled():
        return {
            "attempted": False,
            "ok": False,
            "error": "auto disabled",
            "gift_result": {},
        }

    print(
        f"[WITHDRAW][AUTO] ▶️ start rid={request_id!r} "
        f"sender={sender_user_id} recipient={recipient_user_id} "
        f"amount={amount} gift_id={gift_id} has_upgrade={has_upgrade} "
        f"is_friend={is_friend}"
    )

    gift_result = await _execute_gift_delivery(
        request_id=request_id,
        sender_user_id=sender_user_id,
        sender_username=sender_username,
        sender_first_name=sender_first_name,
        recipient_user_id=recipient_user_id,
        recipient_username=recipient_username,
        recipient_first_name=recipient_first_name,
        amount=amount,
        is_friend=is_friend,
        is_self_withdraw=is_self_withdraw,
        gift_id=gift_id,
        has_upgrade=has_upgrade,
    )

    gift_ok = bool(gift_result.get("ok"))
    provider = _wd_safe_str(gift_result.get("provider"), "userbot")
    provider_result = gift_result.get("provider_result") or {}
    gift_error = _wd_safe_str(gift_result.get("error"), "Не удалось отправить подарок автоматически")
    message_used = bool(gift_result.get("message_used"))
    message_mode = _wd_safe_str(gift_result.get("message_mode"), "")

    if not gift_ok:
        print(
            f"[WITHDRAW][AUTO] ❌ fail rid={request_id!r} "
            f"provider={provider!r} error={gift_error!r}"
        )
        return {
            "attempted": True,
            "ok": False,
            "error": gift_error,
            "gift_result": gift_result,
        }

    await _wd_mark_request_completed_safe(
        request_id=request_id,
        admin_id=0,
        provider=f"{provider}:auto",
        provider_result=provider_result,
    )

    fallback_description_sent = False
    if not message_used:
        fallback_description_sent = await _wd_send_gift_description_message_safe(recipient_user_id)

    print(
        f"[WITHDRAW][AUTO] ✅ success rid={request_id!r} "
        f"provider={provider!r} message_used={message_used} "
        f"message_mode={message_mode!r} "
        f"fallback_description_sent={fallback_description_sent}"
    )

    return {
        "attempted": True,
        "ok": True,
        "error": "",
        "gift_result": gift_result,
        "fallback_description_sent": fallback_description_sent,
    }

@dp.callback_query(lambda c: c.data and (c.data.startswith("send_request_") or c.data.startswith("srq:")))
async def send_request_callback_self(callback_query: types.CallbackQuery):
    user_id = int(callback_query.from_user.id)
    current_time = time.time()

    async def _safe_answer(text: str = "", show_alert: bool = False):
        try:
            await callback_query.answer(text, show_alert=show_alert)
        except Exception:
            pass

    # =====================================================
    # ЖЁСТКАЯ защита от повторного нажатия по одной кнопке
    # =====================================================
    can_press = await _check_button_cooldown_or_answer(
        callback_query,
        storage=withdraw_button_click_guard,
        action_name="send_request_self",
        cooldown_sec=5.0,
    )
    if not can_press:
        return

    # =====================================================
    # МЯГКАЯ защита только от мгновенного двойного тапа
    # =====================================================
    can_repeat = await _check_light_repeat_or_answer(
        callback_query,
        storage=last_click_time,
        user_id=int(user_id),
        action_name="send_request_self_light_gap",
        min_gap_sec=WITHDRAW_DOUBLE_TAP_GAP_SEC,
    )
    if not can_repeat:
        return

    g = globals()
    if "send_request_inflight" not in g or not isinstance(g.get("send_request_inflight"), set):
        g["send_request_inflight"] = set()
    send_request_inflight = g["send_request_inflight"]

    username = callback_query.from_user.username
    if not username:
        await _safe_answer("⚠️ Установите username для получения подарка", show_alert=True)
        return

    has_upgrade = 0
    gift_emoji = "🎁"
    amount = 0
    amountupgreat = 0
    gift_id = 0

    try:
        data = str(callback_query.data or "")

        if data.startswith("srq:"):
            token = str(data.split(":", 1)[1]).strip()
            payload = _get_send_request_action(token)

            if not payload:
                print(f"[WITHDRAW][HANDLER][ERROR] srq token expired/not found token={token!r}")
                await _safe_answer("❌ Кнопка устарела. Откройте меню заново", show_alert=True)
                return

            owner_user_id = int(payload.get("owner_user_id") or 0)
            if owner_user_id > 0 and owner_user_id != user_id:
                print(f"[WITHDRAW][HANDLER][BLOCK] чужой srq token={token!r} owner={owner_user_id} clicker={user_id}")
                await _safe_answer("⚠️ Эта кнопка не для вас", show_alert=True)
                return

            has_upgrade = int(payload.get("has_upgrade") or 0)
            gift_emoji = str(payload.get("gift_emoji") or "🎁")
            amount = int(payload.get("used_base") or 0)
            amountupgreat = int(payload.get("upgrade_price") or 0)
            gift_id = int(payload.get("gift_id") or 0)

            print(
                f"[WITHDRAW][HANDLER][PARSE] srq token={token!r} "
                f"uid={user_id} amount={amount} upg={amountupgreat} gift_id={gift_id} has_upgrade={has_upgrade}"
            )

        else:
            parts = callback_query.data.split("_")
            has_upgrade = int(parts[2])
            gift_emoji = parts[3]
            amount = int(parts[4])
            amountupgreat = int(parts[5])

            try:
                gift_id = int(parts[6])
            except Exception:
                gift_id = 0

            print(
                f"[WITHDRAW][HANDLER][PARSE] legacy uid={user_id} "
                f"amount={amount} upg={amountupgreat} gift_id={gift_id} has_upgrade={has_upgrade}"
            )

    except Exception as e:
        print(f"[WITHDRAW][HANDLER][ERROR] parse send request err={e!r} data={callback_query.data!r}")
        await _safe_answer("❌ Ошибка данных", show_alert=True)
        return

    is_nft = False if has_upgrade == 0 else True
    if is_nft and int(amountupgreat or 0) > 0:
        amount = int(amount) + int(amountupgreat)

    if amount <= 0:
        await _safe_answer("❌ Неверная сумма.", show_alert=True)
        return

    # Активность в официальных группах — обязательное условие вывода.
    try:
        _msg_back_btn = InlineKeyboardButton(text="Назад", callback_data="9close_bonus")
        ok_msgs = await ensure_daily_messages(callback_query, int(user_id), back_btn=_msg_back_btn)
    except Exception as e:
        print(f"[WITHDRAW][HANDLER][MSGCHK][ERROR] uid={user_id} err={e!r}")
        await _safe_answer("⚠️ Ошибка проверки активности", show_alert=True)
        return
    if not ok_msgs:
        print(f"⛔[WITHDRAW][HANDLER][MSGCHK] uid={user_id} blocked")
        return

    # =====================================================
    # НОВЫЙ rid ДЛЯ КАЖДОЙ НОВОЙ ПОКУПКИ
    # =====================================================
    rid = _mk_unique_withdraw_rid(
        "send_request" , user_id=int(user_id) , amount=int(amount) , gift_emoji=str(gift_emoji or "🎁") ,
        extra=f"{int(has_upgrade)}:{int(gift_id)}" , )

    print(f"[WITHDRAW][HANDLER][RID] ✅ rid={rid} gift_id={gift_id}")

    inflight_key = str(getattr(callback_query, "id", "") or "") or rid
    if inflight_key in send_request_inflight:
        print(f"[WITHDRAW][HANDLER][INFLIGHT] duplicate inflight rid={rid}")
        await _safe_answer("⏳ Заявка уже обрабатывается", show_alert=True)
        return

    send_request_inflight.add(inflight_key)

    try:
        can_continue = await _ensure_withdraw_recipient_visible_or_show_ui(
            callback_query,
            retry_callback_data=str(callback_query.data or ""),
            recipient_user_id=int(user_id),
            recipient_username=str(username or ""),
            is_friend_flow=False,
        )
        if not can_continue:
            print(f"[WITHDRAW][HANDLER][PRECHECK] stop before strict withdraw uid={user_id}")
            return

        res = await _withdraw_strict_or_alert(
            callback_query,
            payer_id=user_id,
            amount=amount,
            rid=rid,
        )

        if not isinstance(res, dict):
            print(f"[WITHDRAW][HANDLER][BAD] res is not dict -> {type(res).__name__}: {res!r}")
            return

        ok = bool(res.get("ok"))
        committed = bool(res.get("committed"))
        duplicate = bool(res.get("duplicate"))
        should_send = bool(res.get("should_send_to_channel"))

        if duplicate:
            print(f"[WITHDRAW][HANDLER] 🟨 duplicate rid={rid} -> stop")
            return

        if not ok:
            print(f"[WITHDRAW][HANDLER] 🟥 fail rid={rid} res={res!r}")
            return

        if not committed:
            print(f"[WITHDRAW][HANDLER] 🟥 ok=True but committed=False rid={rid} -> stop")
            return

        if not should_send:
            print(f"[WITHDRAW][HANDLER] 🟥 should_send_to_channel=False rid={rid} -> stop")
            return

        new_balance = int(res.get("user_balance_after") or 0)

        try:
            SAFE_CUTEHISTORY_AFTER_STRICT = False
            if hasattr(db, "cutehistory_minus"):
                if SAFE_CUTEHISTORY_AFTER_STRICT:
                    await db.cutehistory_minus(user_id, int(amount), "вывод кут в звезды")
                else:
                    print("[WITHDRAW][HANDLER][HISTORY] skip cutehistory_minus after strict (anti double-spend)")
        except Exception as e:
            print(f"[WITHDRAW][HANDLER][WARN] cutehistory_minus err={e!r}")

        amount_str = _fmt_int(amount)
        new_balance_str = _fmt_int(new_balance)
        formatted_time = datetime.now().strftime("%d.%m.%Y %H:%M")

        auto_delivery = await _wd_try_auto_gift_delivery_after_strict(
            request_id=rid,
            sender_user_id=int(user_id),
            sender_username=str(username or ""),
            sender_first_name="",
            recipient_user_id=int(user_id),
            recipient_username=str(username or ""),
            recipient_first_name="",
            amount=int(amount),
            is_friend=False,
            gift_id=int(gift_id),
            has_upgrade=int(has_upgrade),
        )

        auto_ok = bool(auto_delivery.get("ok"))
        auto_attempted = bool(auto_delivery.get("attempted"))
        auto_fail_reason = _wd_safe_str(auto_delivery.get("error"), "")

        first_name = ""
        username_db = _wd_normalize_username(username)

        try:
            if hasattr(db, "get_firstname_by_user_id"):
                first_name = _wd_safe_str(await db.get_firstname_by_user_id(user_id), "")
        except Exception as e:
            print(f"[WITHDRAW][HANDLER][WARN] get_firstname_by_user_id err={e!r}")

        try:
            if hasattr(db, "get_username_by_user_id"):
                username_db = _wd_normalize_username(await db.get_username_by_user_id(user_id)) or username_db
        except Exception as e:
            print(f"[WITHDRAW][HANDLER][WARN] get_username_by_user_id err={e!r}")

        name_link = f"@{username_db}" if username_db else f"user_id {user_id}"
        if first_name:
            try:
                name_link = await create_user_link(user_id, first_name, username_db or None)
            except Exception as e:
                print(f"[WITHDRAW][HANDLER][WARN] create_user_link err={e!r}")

        if auto_ok:
            success_text = (
                f"<b><tg-emoji emoji-id='5924701179157156993'>⭐️</tg-emoji> Подарок отправлен автоматически\n"
                f"<tg-emoji emoji-id='5449372007432985754'>🌴</tg-emoji> {amount_str} кут\n"
                f"<tg-emoji emoji-id='5238108342873762772'>🦎</tg-emoji> {formatted_time}\n"
                f"<tg-emoji emoji-id='5449820402018688838'>🌵</tg-emoji> Баланс : {new_balance_str} кут\n\n"
                f"<blockquote>Выплата выполнена через tech userbot.</blockquote></b>"
            )

            try:
                await callback_query.message.edit_text(
                    success_text,
                    reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                        [InlineKeyboardButton(text="В главное меню", callback_data="9close_bonus")]
                    ]),
                    parse_mode="HTML",
                    disable_web_page_preview=True,
                )
            except Exception as e:
                print(f"[WITHDRAW][HANDLER][UI][AUTO][WARN] edit_text err={e!r}")
                try:
                    await bot1.send_message(
                        chat_id=user_id,
                        text=success_text,
                        parse_mode="HTML",
                        disable_web_page_preview=True,
                    )
                except Exception as e2:
                    print(f"[WITHDRAW][HANDLER][UI][AUTO][ERROR] fallback send_message err={e2!r}")

            try:
                channel_auto_text = await _wd_render_final_channel_text(
                    kind="approve",
                    result_flag="-",
                    amount=int(amount),
                    sender_display=name_link,
                    recipient_display=name_link,
                    sender_user_id=int(user_id),
                    recipient_user_id=int(user_id),
                    is_friend=False,
                )
                channel_auto_text += (
                    "\n\n<blockquote><b>⚡️ Автовыплата через tech userbot</b></blockquote>"
                )
                msg = await bot1.send_message(
                    chat_id="@CurrencyCute",
                    text=channel_auto_text,
                    parse_mode="HTML",
                    disable_web_page_preview=True,
                )
                print(
                    f"[WITHDRAW][HANDLER][CHANNEL][AUTO] ✅ sent channel_msg_id={getattr(msg, 'message_id', None)} "
                    f"rid={rid} gift_id={gift_id}"
                )
            except Exception as e:
                print(f"[WITHDRAW][HANDLER][CHANNEL][AUTO][WARN] err={e!r}")

            last_click_time[user_id] = current_time
            print(
                f"[WITHDRAW][HANDLER] 🟩 AUTO DONE send_request uid={user_id} "
                f"amount={amount} new_bal={new_balance} gift_id={gift_id}"
            )
            return

        if auto_attempted:
            print(
                f"[WITHDRAW][HANDLER][AUTO][FALLBACK] rid={rid} "
                f"reason={auto_fail_reason!r} -> manual channel review"
            )

        auto_fail_note = (
            "\n<blockquote>⚠️ Автовыплата сейчас недоступна, заявка передана администратору.</blockquote>"
            if auto_attempted
            else ""
        )

        try:
            await callback_query.message.edit_text(
                f"<b><tg-emoji emoji-id='5449850741667668411'>🌿</tg-emoji> Заявка создана | {amount_str} кут\n"
                f"<tg-emoji emoji-id='5238108342873762772'>🦎</tg-emoji> {formatted_time}\n"
                f"<tg-emoji emoji-id='5449820402018688838'>🌵</tg-emoji> Баланс : {new_balance_str} кут\n\n"
                f"<blockquote>Админ скоро с вами свяжется\n"
                f"Не меняйте username - иначе выплаты не будет</blockquote>"
                f"{auto_fail_note}</b>",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(
                        text="Канал с выводами",
                        url="https://t.me/CurrencyCute",
                        style="default",
                        icon_custom_emoji_id="5796440171364749940"
                    )],
                    [InlineKeyboardButton(text="В главное меню", callback_data="9close_bonus")]
                ]),
                parse_mode="HTML",
                disable_web_page_preview=True
            )
        except Exception as e:
            print(f"[WITHDRAW][HANDLER][UI][WARN] edit_text err={e!r}")
            try:
                await bot1.send_message(
                    chat_id=user_id,
                    text=(
                        f"<b><tg-emoji emoji-id='5449850741667668411'>🌿</tg-emoji> Заявка создана | {amount_str} кут\n"
                        f"<tg-emoji emoji-id='5238108342873762772'>🦎</tg-emoji> {formatted_time}\n"
                        f"<tg-emoji emoji-id='5449820402018688838'>🌵</tg-emoji> Баланс : {new_balance_str} кут</b>"
                    ),
                    parse_mode="HTML",
                    disable_web_page_preview=True
                )
            except Exception as e2:
                print(f"[WITHDRAW][HANDLER][UI][ERROR] fallback send_message err={e2!r}")

        if is_nft:
            channel_message = (
                f"<code>{gift_emoji}</code> <b>{amount_str} кут [ NFT ]</b>\n"
                f"<b><tg-emoji emoji-id='5294026527850132517'>🍬</tg-emoji> Для <i>{name_link}</i></b>\n\n"
                f"<blockquote><b>@CuteGamingBot</b></blockquote>"
            )
        else:
            channel_message = (
                f"<code>{gift_emoji}</code> <b>{amount_str} кут в stars <tg-emoji emoji-id='5897658922600240288'>⭐️</tg-emoji></b>\n"
                f"<b><tg-emoji emoji-id='5294026527850132517'>🍬</tg-emoji> Для <i>{name_link}</i></b>\n\n"
                f"<blockquote><b>@CuteGamingBot</b></blockquote>"
            )

        if auto_attempted and auto_fail_reason:
            channel_message = (
                f"<b>⚠️ Автовыплата не удалась:</b> "
                f"<code>{escape(auto_fail_reason)[:220]}</code>\n\n"
                f"{channel_message}"
            )

        sender_first_name = first_name or None

        keyboard = _build_withdraw_channel_keyboard(
            request_id=rid,
            sender_user_id=int(user_id),
            sender_username=username_db,
            sender_first_name=sender_first_name,
            recipient_user_id=int(user_id),
            recipient_username=username_db,
            recipient_first_name=sender_first_name,
            amount=int(amount),
            result_flag="-",
            is_friend=False,
            channel_message_id_hint=int(callback_query.message.message_id),
            gift_id=int(gift_id),
            gift_emoji=str(gift_emoji or ""),
            has_upgrade=int(has_upgrade),
        )

        last_click_time[user_id] = current_time

        try:
            msg = await bot1.send_message(
                chat_id="@CurrencyCute",
                text=channel_message,
                reply_markup=keyboard,
                parse_mode="HTML",
                disable_web_page_preview=True
            )
            print(
                f"[WITHDRAW][HANDLER][CHANNEL] ✅ sent channel_msg_id={getattr(msg, 'message_id', None)} "
                f"rid={rid} gift_id={gift_id}"
            )
        except Exception as e:
            print(f"[WITHDRAW][HANDLER][CHANNEL][ERROR] err={e!r}")

        print(f"[WITHDRAW][HANDLER] 🟩 DONE send_request uid={user_id} amount={amount} new_bal={new_balance} gift_id={gift_id}")

    finally:
        send_request_inflight.discard(inflight_key)

