@dp.callback_query(lambda call: isinstance(call.data, str) and call.data.startswith("outrefunddelete_"))
async def delete_messagedw1d1wd1dw1(call: types.CallbackQuery):
    if call.from_user.id not in ADMIN_IDS:
        await _adm_safe_answer(call, "👎", show_alert=True)
        return

    inflight = _get_admin_inflight_store()
    inflight_key = f"refund:{getattr(call, 'id', '') or call.data}"

    if inflight_key in inflight:
        await _adm_safe_answer(call, "⏳ Уже обрабатывается", show_alert=True)
        return

    inflight.add(inflight_key)

    try:
        await _adm_safe_answer(call)

        try:
            # новый формат:
            # outrefunddelete_{amount}_{message_id}_{user_id}_{rid}
            parts = call.data.split("_", maxsplit=4)

            if len(parts) >= 5:
                _, amount, message_id, user_id, rid = parts
            else:
                # fallback старый формат без rid
                _, amount, message_id, user_id = call.data.split("_", maxsplit=3)
                rid = ""

            amount = _adm_safe_int(amount, 0)
            message_id = _adm_safe_int(message_id, 0)
            user_id = _adm_safe_int(user_id, 0)
            rid = _adm_safe_str(rid, "")
        except Exception:
            await _adm_safe_answer(call, "Ошибка данных!", show_alert=True)
            return

        if user_id <= 0 or amount <= 0:
            await _adm_safe_answer(call, "Ошибка данных заявки!", show_alert=True)
            return

        rollback_done = False
        fallback_refund_done = False

        # --------------------------------------------------------
        # 1) правильный rollback по rid
        # --------------------------------------------------------
        if rid and hasattr(db, "rollback_withdraw_strict"):
            try:
                rb = await db.rollback_withdraw_strict(user_id=user_id, request_id=rid)
                print(f"[ADMIN][REFUND] rollback_withdraw_strict -> {rb!r}")

                if isinstance(rb, dict) and rb.get("ok"):
                    rollback_done = True
            except Exception as e:
                print(f"[ADMIN][REFUND][WARN] rollback_withdraw_strict err={e!r}")

        # --------------------------------------------------------
        # 2) fallback-возврат (хуже, но план Б)
        # --------------------------------------------------------
        if not rollback_done:
            try:
                balance = await db.get_user_balance(user_id)
                balance = _adm_safe_int(balance, 0)
                new_balance = balance + amount
                await db.update_user_balance(user_id, new_balance)

                try:
                    if hasattr(db, "cutehistory_plus"):
                        await db.cutehistory_plus(
                            user_id,
                            amount,
                            "возврат кут с заявки на вывод (fallback)"
                        )
                except Exception as e:
                    print(f"[ADMIN][REFUND][HISTORY][WARN] err={e!r}")

                fallback_refund_done = True
                print(f"[ADMIN][REFUND][FALLBACK] uid={user_id} amount={amount} new_balance={new_balance}")
            except Exception as e:
                print(f"[ADMIN][REFUND][ERROR] fallback refund err={e!r}")
                await _adm_safe_answer(call, "❌ Не удалось вернуть куты", show_alert=True)
                return

        # --------------------------------------------------------
        # 3) уведомление пользователю
        # --------------------------------------------------------
        emoj = "<tg-emoji emoji-id='5440911110838425969'>🌹</tg-emoji>"
        if rollback_done:
            user_text = f"<b>{emoj} Ваша заявка на вывод кут отклонена! Куты возвращены\n\n@CuteGamingBot</b>"
        else:
            user_text = f"<b>{emoj} Ваша заявка на вывод отклонена! Куты возвращены (fallback)\n\n@CuteGamingBot</b>"

        await _adm_safe_notify_user(
            user_id,
            user_text,
            effect_id="5159385139981059251",
        )

        # --------------------------------------------------------
        # 4) удалить сообщение из канала
        # --------------------------------------------------------
        await _adm_safe_delete_channel_message(call)

        if rollback_done:
            await _adm_safe_answer(call, "🍃 Заявка отклонена, куты возвращены", show_alert=True)
        elif fallback_refund_done:
            await _adm_safe_answer(call, "🍃 Заявка отклонена, куты возвращены (fallback)", show_alert=True)
        else:
            await _adm_safe_answer(call, "⚠️ Заявка отклонена", show_alert=True)

    finally:
        inflight.discard(inflight_key)



