# ─────────────────────────────────────────────────────────────────────────────
# ✅ Back flag (коротко: "+" или "-")
# ─────────────────────────────────────────────────────────────────────────────
WITHDRAW_BACK_STARS = "-"     # обычный "Назад"
WITHDRAW_BACK_BALANCE = "+"   # "Назад к балансу"


def _ctx_apply_back_meta(
    ctx: dict,
    *,
    back_flag: Optional[str],
    owner_id_for_back: Optional[int],
):
    """
    Аккуратно прокидывает meta в withdrawal_context.
    Совместимо с Python 3.9.
    """
    if not isinstance(ctx, dict):
        return

    if back_flag in (WITHDRAW_BACK_STARS, WITHDRAW_BACK_BALANCE):
        ctx["back_flag"] = back_flag
    else:
        ctx.setdefault("back_flag", WITHDRAW_BACK_STARS)

    if owner_id_for_back is not None:
        try:
            ctx["owner_id_for_back"] = int(owner_id_for_back)
        except Exception:
            pass


def _pending_apply_back_meta(
    pending: dict,
    *,
    back_flag: Optional[str],
    owner_id_for_back: Optional[int],
):
    """
    То же самое, но для pending_withdraw[user_id],
    чтобы deep-link переносил контекст.
    """
    if not isinstance(pending, dict):
        return

    if back_flag in (WITHDRAW_BACK_STARS, WITHDRAW_BACK_BALANCE):
        pending["back_flag"] = back_flag
    else:
        pending.setdefault("back_flag", WITHDRAW_BACK_STARS)

    if owner_id_for_back is not None:
        try:
            pending["owner_id_for_back"] = int(owner_id_for_back)
        except Exception:
            pass


def _apply_single_back_button(
    keyboard: InlineKeyboardMarkup,
    *,
    ctx: dict,
    user_id: int,
):
    """
    Делает РОВНО ОДНУ правильную кнопку "назад" - без дублей.

    Если ctx.back_flag == "+":
        - находим кнопку "Назад" с callback_data="back_to_stars_choice"
        - заменяем её на "← Назад к балансу" (balance:{owner_id})
    Если ctx.back_flag == "-":
        - ничего не делаем (остаётся обычная "Назад")

    Fallback:
        - если кнопку "Назад" не нашли, добавляем ОДНУ кнопку "← Назад к балансу"
    """
    try:
        back_flag = (ctx or {}).get("back_flag", WITHDRAW_BACK_STARS)
        if back_flag != WITHDRAW_BACK_BALANCE:
            return

        owner_id_for_back = int((ctx or {}).get("owner_id_for_back") or user_id)

        rows = getattr(keyboard, "inline_keyboard", None) or []
        replaced = False

        for r_i, row in enumerate(rows):
            for b_i, btn in enumerate(row):
                # строго ищем твою кнопку "Назад"
                if getattr(btn, "callback_data", None) == "back_to_stars_choice":
                    text = (getattr(btn, "text", "") or "").strip().lower()
                    # чтобы не задеть кнопку суммы, если она тоже на back_to_stars_choice
                    # (у тебя там "{amount} кут" с таким же callback)
                    if text == "назад" or "назад" in text:
                        rows[r_i][b_i] = InlineKeyboardButton(
                            text="Назад к балансу",
                            callback_data=f"balance:{owner_id_for_back}", style="default" ,
                            icon_custom_emoji_id="5960671702059848143",
                        )
                        replaced = True
                        break
            if replaced:
                break

        if not replaced:
            rows.append([
                InlineKeyboardButton(
                    text="Назад к балансу",
                    callback_data=f"balance:{owner_id_for_back}", style="default" ,
                            icon_custom_emoji_id="5960671702059848143",
                )
            ])

    except Exception as e:
        print(f"[WITHDRAW][BACK][ERROR] _apply_single_back_button: {e}")


