# ✅ 3) Обработчик ForceReply суммы + ТОЧНАЯ ОТЛАДКА С ЭМОДЗИ
# ─────────────────────────────────────────────────────────────────────────────
def _extract_amount_candidate(text: str) -> Optional[str]:
    """
    Достаёт из текста наиболее "похожий на сумму" кусок.
    Примеры:
      "вывести 1.000 кут" -> "1.000"
      "сумма: 1 000 000"  -> "1 000 000"
    """
    t = (text or "").strip()
    if not t:
        return None

    cands = re.findall(r"\d(?:[\d\s._,]*\d)?", t)
    if not cands:
        return None

    cands_sorted = sorted(cands, key=lambda s: len(s), reverse=True)
    return cands_sorted[0].strip() if cands_sorted else None


def _parse_human_int(candidate: str) -> Tuple[Optional[int], str]:
    """
    Возвращает (value, reason).
    value=None если не распарсилось.

    Правила:
      - допускаем пробелы и "_" как разделители тысяч
      - допускаем "." и "," как разделители тысяч (группы по 3)
      - дроби запрещены (например 10.5 / 10,50)
    """
    raw = (candidate or "").strip()
    if not raw:
        return None, "пусто"

    # Уберём пробелы и подчёркивания
    s = raw.replace(" ", "").replace("_", "")

    # Допускаем только цифры, точки и запятые после нормализации
    if not re.fullmatch(r"[\d.,]+", s):
        return None, "лишние символы"

    # Если нет разделителей - обычное число
    if "." not in s and "," not in s:
        if not s.isdigit():
            return None, "не цифры"
        try:
            return int(s), "ok"
        except Exception:
            return None, "int() failed"

    # Есть "." и/или "," → проверим что это именно тысячи, а НЕ дробь.
    # Разбиваем по любым . или ,
    parts = re.split(r"[.,]", s)

    # Все части должны быть цифрами
    if any((not p.isdigit()) for p in parts):
        return None, "части не цифры"

    # Признак дроби: всего 2 части и длина хвоста НЕ 3
    # Пример: "10.5" -> ["10","5"] (хвост 1) => дробь
    # Пример: "10,50" -> хвост 2 => дробь
    if len(parts) == 2 and len(parts[1]) != 3:
        return None, "похоже на дробь"

    # Для тысячных разделителей:
    # - первая группа: 1..3 цифры
    # - все последующие: строго 3 цифры
    if not (1 <= len(parts[0]) <= 3):
        return None, "первая группа не 1..3 цифры"

    if any(len(p) != 3 for p in parts[1:]):
        return None, "группы тысяч не по 3 цифры"

    # Всё ок - склеиваем и парсим
    try:
        return int("".join(parts)), "ok"
    except Exception:
        return None, "int() failed after join"


