async def _retry_invalid_amount(message: types.Message, ctx: dict, prompt_text: str):
    # Удаляем некорректный ввод
    try:
        await message.delete()
    except TelegramBadRequest:
        pass
    # Удаляем старый prompt
    try:
        await message.bot.delete_message(
            ctx['prompt_chat_id'], ctx['prompt_message_id']
        )
    except TelegramBadRequest:
        pass
    # Отправляем новый prompt
    retry = await message.answer(
        prompt_text,
        reply_markup=ForceReply(selective=True),
        parse_mode="HTML"
    )
    ctx['prompt_chat_id'] = retry.chat.id
    ctx['prompt_message_id'] = retry.message_id





# Декоратор для регистрации команд с ускорением
def register_command(*aliases):
    """Декоратор для регистрации команды с оптимизацией."""
    def decorator(func):
        # Регистрация команды с приведения к нижнему регистру
        for alias in aliases:
            COMMANDS[alias.lower()] = func
        return func
    return decorator


# Пример асинхронной функции для обработки команды "баланс"



# Обрабатываем сообщение от пользователя


async def process_command(text: str, message: Message, bot1, chat_id, db):
    """Обрабатывает команды, если они зарегистрированы."""
    start_time = time.time()  # Засекаем время начала работы функции

    text_lower = text.lower()  # Приводим текст команды к нижнему регистру
    handler = COMMANDS.get(text_lower)  # Получаем обработчик по тексту

    if handler:
        try:
            # Логирование перед выполнением команды
            print(f"🧩 Начинаем обработку команды: {text_lower}")
            end_time = time.time()
            print(f"🧩 Время до начала обработки команды {text_lower}: {end_time - start_time:.4f} секунд.")

            # Выполнение обработчика, передавая в него db
            result = await handler(message, db)

            end_time = time.time()  # Засекаем время после выполнения команды
            print(f"🧩 Обработка команды {text_lower} заняла: {end_time - start_time:.4f} секунд.")

            if result is not None:  # Если результат не None
                await asyncio.gather(
                    measure_time(result, text_lower),  # Измеряем время выполнения result
                    update(bot1, chat_id, db)
                )

        except Exception as e:
            end_time = time.time()
            print(f"🧩 Ошибка при обработке команды {text_lower}: {e}")
            print(f"🧩 Время до ошибки: {end_time - start_time:.4f} секунд.")
    else:
        pass  # команда не зарегистрирована — без лишнего print на каждое сообщение
async def on_message(message: Message, bot1, chat_id, db):
    """Обработчик входящих сообщений, передаем подключение к базе данных."""
    text = message.text
    if not text:
        return
    handler = COMMANDS.get(text.lower())
    if handler:
        await process_command(text, message, bot1, chat_id, db)









