def _is_target_channel(msg: types.Message) -> bool:
    """Принадлежность нужному каналу (приоритет ID → username)."""
    try:
        if REVIEWS_CHANNEL_ID is not None:
            return msg.chat.id == REVIEWS_CHANNEL_ID
        username = (msg.chat.username or "").lower()
        return username == (REVIEWS_USERNAME or "").lower()
    except Exception:
        return False

def _check_save_dir_ready() -> bool:
    """НЕ создаём папку. Проверяем наличие/права/свободное место."""
    if SAVE_DIR is None:
        print("[ERROR] Папка не найдена. Создай вручную 'reviews' или 'rewiews', либо укажи ENV REVIEWS_DIR.")
        return False
    if not os.access(SAVE_DIR, os.W_OK):
        print(f"[ERROR] Нет прав на запись: {SAVE_DIR}")
        return False
    try:
        total, used, free = shutil.disk_usage(SAVE_DIR)
        if free < MIN_FREE_BYTES:
            print(f"[ERROR] Мало места: {free} < {MIN_FREE_BYTES}")
            return False
    except Exception as e:
        print(f"[WARN] Не удалось проверить свободное место: {e!r}")
    return True

def _unique_review_number(chat_id: int, msg_id: int) -> str:
    """
    Детерминированный псевдослучайный десятичный номер на основе chat_id:msg_id.
    Стабильно одинаковый для одного сообщения → идемпотентность/самоисцеление.
    """
    seed = f"{chat_id}:{msg_id}".encode("utf-8")
    h = hashlib.sha256(seed).digest()
    # Возьмём первые 8 байт → int → 14-значное число (без лидирующих нулей)
    num = int.from_bytes(h[:8], "big")
    return str(num).rjust(14, "0")  # выровняем до 14 цифр (красиво и одинаково длинно)

def _format_review_filename(chat_id: int, message_id: int, dt: datetime) -> str:
    """
    "<УНИКАЛЬНЫЙ НОМЕР> ｜ <мм.чч> ｜ <дд.мм.гггг>"
    Время берём ЛОКАЛЬНОЕ: datetime.now()
    По ТЗ: «мм.чч» (минуты.часы).
    """
    unique_no = _unique_review_number(chat_id, message_id)
    mm = f"{dt.minute:02d}"
    hh = f"{dt.hour:02d}"
    dd = f"{dt.day:02d}"
    mon = f"{dt.month:02d}"
    yyyy = f"{dt.year:04d}"
    base = f"{unique_no} {SAFE_BAR} {mm}.{hh} {SAFE_BAR} {dd}.{mon}.{yyyy}"
    return _safe_filename(base)

def _ensure_unique_path(base_path: Path) -> Path:
    """Если имя занято - добавляем _dupN, затем _dupTS<timestamp> в крайнем случае."""
    if not base_path.exists():
        return base_path
    stem, suffix = base_path.stem, base_path.suffix
    for i in range(1, 9999):
        cand = base_path.with_name(f"{stem}_dup{i}{suffix}")
        if not cand.exists():
            return cand
    return base_path.with_name(f"{stem}_dupTS{int(datetime.now().timestamp())}{suffix}")

async def _atomic_download(bot: Bot, file_id: str, final_path: Path) -> bool:
    """
    Атомарная запись: скачиваем во временный файл *.part, затем rename → *.jpg.
    С ретраями и бэкоффом.
    """
    part_path = final_path.with_suffix(final_path.suffix + ".part")
    for attempt, delay in enumerate((0.0,) + RETRY_BACKOFFS, start=1):
        try:
            if delay:
                await asyncio.sleep(delay)
            # удалим .part, если остался с прошлых попыток
            try:
                if part_path.exists():
                    part_path.unlink()
            except Exception:
                pass

            await bot.download(file_id, destination=part_path)

            # ФС-барьер: убедимся, что файл реально на диске, затем атомарный rename
            if not part_path.exists() or part_path.stat().st_size == 0:
                raise IOError("Временный файл отсутствует или пуст.")

            # Если итоговый уже существует - автоуникализируем (самоисцеление)
            target = final_path if not final_path.exists() else _ensure_unique_path(final_path)

            part_path.replace(target)  # атомарно в пределах одного раздела
            return True

        except Exception as e:
            print(f"[WARN] Попытка {attempt}/{1+len(RETRY_BACKOFFS)} скачать {final_path.name} не удалась: {e!r}")
            # следующая попытка по backoff
    # если все попытки исчерпаны
    try:
        if part_path.exists():
            part_path.unlink()
    except Exception:
        pass
    return False

def _is_jpeg_document(doc: types.Document) -> bool:
    mime = (doc.mime_type or "").lower()
    fname = (doc.file_name or "").lower()
    return ("image/jpeg" in mime) or fname.endswith(".jpg") or fname.endswith(".jpeg")

