@dp.channel_post(F.photo)
async def handle_channel_photo(message: types.Message, bot: Bot):
    """
    Фото из канала: сохраняем как JPEG.
    Имя: "<УНИКАЛЬНЫЙ НОМЕР> ｜ <мм.чч> ｜ <дд.мм.гггг>.jpg"
    """
    if not _is_target_channel(message):
        return
    if not message.photo or not _check_save_dir_ready():
        return

    photo = message.photo[-1]
    if photo.file_size and photo.file_size > MAX_DOC_BYTES:
        print(f"[SKIP] Photo слишком большой ({photo.file_size}) msg_id={message.message_id}")
        return

    # ЛОКАЛЬНОЕ системное время
    dt_now = datetime.now()
    base_name = _format_review_filename(message.chat.id, message.message_id, dt_now)
    final_path = _ensure_unique_path((SAVE_DIR / f"{base_name}.jpg"))

    print(f"[INFO] Сохраняю фото → {final_path.name}")
    if await _atomic_download(bot, photo.file_id, final_path):
        print(f"[OK] Фото сохранено: {final_path.resolve()}")
    else:
        print(f"[FAIL] Фото не сохранено: {final_path.name}")

@dp.channel_post(F.document)
async def handle_channel_document(message: types.Message, bot: Bot):
    """
    Документ из канала: сохраняем только JPEG (image/jpeg или .jpg/.jpeg).
    Имя: "<УНИКАЛЬНЫЙ НОМЕР> ｜ <мм.чч> ｜ <дд.мм.гггг>.jpg/.jpeg"
    """
    if not _is_target_channel(message):
        return
    doc = message.document
    if not doc or not _check_save_dir_ready():
        return

    if not _is_jpeg_document(doc):
        print(f"[SKIP] Документ не JPEG: mime={doc.mime_type}, name={doc.file_name!r}")
        return
    if doc.file_size and doc.file_size > MAX_DOC_BYTES:
        print(f"[SKIP] Документ слишком большой ({doc.file_size})")
        return

    fname = (doc.file_name or "").lower()
    ext = ".jpg" if fname.endswith(".jpg") else ".jpeg"

    # ЛОКАЛЬНОЕ системное время
    dt_now = datetime.now()
    base_name = _format_review_filename(message.chat.id, message.message_id, dt_now)
    final_path = _ensure_unique_path((SAVE_DIR / f"{base_name}{ext}"))

    print(f"[INFO] Сохраняю JPEG-документ → {final_path.name}")
    if await _atomic_download(bot, doc.file_id, final_path):
        print(f"[OK] Документ сохранён: {final_path.resolve()}")
    else:
        print(f"[FAIL] Документ не сохранён: {final_path.name}")

