    # ----------------------------
    # Project root detection (search CuteUpdate1)
    # ----------------------------
    def _find_project_root_dir() -> str:
        candidates = [ os.getcwd() ]
        try:
            candidates.append(os.path.abspath(os.path.dirname(__file__)))
        except Exception:
            pass

        seen = set()
        for start in candidates:
            cur = os.path.abspath(start)
            while True:
                if cur in seen:
                    break
                seen.add(cur)
                if os.path.basename(cur) == "CuteUpdate1":
                    return cur
                parent = os.path.dirname(cur)
                if parent == cur:
                    break
                cur = parent

        for start in candidates:
            for root , dirs , _ in os.walk(start):
                if "CuteUpdate1" in dirs:
                    return os.path.join(root , "CuteUpdate1")

        return os.getcwd()

    _PROJECT_ROOT = _find_project_root_dir()

    # Filename timestamp uses milliseconds
    def _oslo_now_filename_ts() -> str:
        try:
            if _OSLO_TZ is not None:
                now = datetime.now(_OSLO_TZ)
            else:
                now = datetime.now()
            return now.strftime("%Y-%m-%d_%H-%M-%S_%f") [ :-3 ]
        except Exception:
            return datetime.now().strftime("%Y-%m-%d_%H-%M-%S_%f") [ :-3 ]

    PRIMARY_RUNTIME_LOGFILE_ABS_PATH = os.path.join(_PROJECT_ROOT , "log.txt")
