        def _safe_balance(value) -> int:
            """
            Безопасно приводит любое значение баланса к int.
            Поддерживает: int, float, Decimal, str, None.
            """
            try:
                if value is None:
                    return 0

                if isinstance(value , bool):
                    return 0

                if isinstance(value , (int , float)):
                    return int(value)

                if isinstance(value , Decimal):
                    return int(value)

                s = str(value).strip().replace(" " , "")
                if not s:
                    return 0

                # если вдруг число пришло как "1234.00"
                return int(float(s))
            except Exception:
                return 0

        def _format_balance(value) -> str:
            """
            Красивое форматирование числа: 1234567 -> 1.234.567
            """
            try:
                return "{:,.0f}".format(_safe_balance(value)).replace("," , ".")
            except Exception:
                return "0"

