        async def _get_user_id_by_info(info: str) -> int | None:
            """Возвращает user_id по строке (ID, @username или ссылка t.me/...)"""
            info = info.strip()
            if info.isdigit():
                return int(info)
            if info.startswith("@"):
                username = info.lstrip("@")
                return await db.get_user_id_by_username(username)
            if info.startswith("https://t.me/"):
                username = info.split("/") [ -1 ]
                return await db.get_user_id_by_username(username)
            return None

        def _parse_amount_and_rest(text: str) -> tuple [ int | None , str ]:
            """Извлекает целое число из начала строки, возвращает (сумма, остаток)"""
            parts = text.strip().split(maxsplit=1)
            if not parts:
                return None , ""
            amt_str = parts [ 0 ].replace("." , "")
            try:
                amount = int(amt_str)
                rest = parts [ 1 ] if len(parts) > 1 else ""
                return amount , rest
            except ValueError:
                return None , text

