        async def _process_sypher_command(message: types.Message , mode: str):
            """
            Универсальная функция для обработки любой sypher‑команды.
            mode: 'demo_add', '0demo_add', 'demo_sub', '0demo_sub'
            """
            text = message.text.strip()
            parts = text.split(maxsplit=2)

            receiver_id = None
            amount = None

            # 1. Получатель из ответа на сообщение
            if message.reply_to_message:
                receiver_id = message.reply_to_message.from_user.id
                receiver_name = await db.get_firstname_by_user_id(receiver_id) or "Пользователь"
                if len(parts) >= 2:
                    amount_str = " ".join(parts [ 1: ])
                else:
                    amount_str = ""
                amount , _ = _parse_amount_and_rest(amount_str)
            else:
                # 2. Получатель указан в теле команды
                if len(parts) < 2:
                    await message.reply("⚠️ Укажите пользователя или ответьте на его сообщение.")
                    return
                candidate = parts [ 1 ].strip()
                uid = await _get_user_id_by_info(candidate)
                if uid is not None:
                    receiver_id = uid
                    if len(parts) >= 3:
                        amount_str = parts [ 2 ]
                    else:
                        amount_str = ""
                    amount , _ = _parse_amount_and_rest(amount_str) if amount_str else (0 , "")
                else:
                    await message.reply("❓ Пользователь не найден. Укажите @username, ID или ответьте на сообщение.")
                    return

            receiver_name = await db.get_firstname_by_user_id(receiver_id) or "Пользователь"

            # Если сумма нулевая или не указана → показать балансы demo и 0demo
            if amount is None or amount <= 0:
                demo = await db.get_user_demo(receiver_id) or 0
                zero_demo = await db.get_user_0demo(receiver_id) or 0
                info_text = (f"<b>🎮 Информация о демо-балансах</b>\n"
                             f"<i>Пользователь: {receiver_name}</i>\n"
                             f"<blockquote>💚 demo:   {demo}\n🖤 0demo: {zero_demo}</blockquote>")
                await message.reply(info_text , parse_mode="HTML")
                return

            # Выполнение операции
