        async def show_users_with_positive_balance(message: types.Message , balance_type: str):
            """
            Выводит список пользователей с положительным demo или 0demo,
            а затем короткую сводку: общее количество пользователей и сумму баланса.
            balance_type = 'demo' или '0demo'
            """
            # Только админ
            if message.from_user.id != ADMIN_ID:
                await message.reply("⛔ Эта команда доступна только администратору.")
                return

            # Данные из базы
            if balance_type == "demo":
                users = await db.get_all_users_with_positive_demo()
                bal_key = "demo"
                title = "💚 demo-балансом"
            else:
                users = await db.get_all_users_with_positive_0demo()
                bal_key = "0demo"
                title = "🖤 0demo-балансом"

            if not users:
                await message.reply(f"📭 Нет пользователей с положительным {title}.")
                return

            # Формируем список
            lines = [ ]
            total_balance = 0
            for u in users:
                uid = u [ "user_id" ]
                bal = u.get(bal_key , 0)
                total_balance += bal
                name = await db.get_firstname_by_user_id(uid) or str(uid)
                user_link = await create_user_link(uid , name , name)
                lines.append(f"• {user_link} - {bal}")

            total_users = len(users)

            # Собираем итоговое сообщение
            header = f"<b>📊 Пользователи с {title}:</b>\n"
            body = "\n".join(lines)
            summary = (f"\n\n<b>📋 Сводка:</b>\n"
                       f"👥 Всего пользователей: {total_users}\n"
                       f"💰 Общая сумма {bal_key}: {total_balance}")

            await message.reply(header + body + summary , parse_mode="HTML")

