    async def _words_close_game_and_edit(bot , chat_id: int , game: Dict [ str , Any ] , winner_id: Optional [ int ] ,
            winner_name: Optional [ str ] , ) -> None:
        """
        Редактирует «шапку» игры как завершённую, переводит ставку (если есть), снимает игру из словаря.
        """
        msg_id = game.get("msg_id")
        bet = int(game.get("bet" , 0))
        creator_id = int(game.get("creator_id"))
        word_original = game.get("word" , "")

        # Денежки: если была ставка - победителю +bet, у создателя −bet
        if winner_id is not None and bet > 0:
            try:
                # Безопасно, коротко и понятно. Заменишь на свои методы при желании.
                await db.add_user_balance(winner_id , bet)
                await db.add_user_balance(creator_id , -bet)
                print(f"[WORDS][PAY] +{bet} → {winner_id} | -{bet} ← {creator_id}")
            except Exception as e:
                print(f"[WORDS][PAY][ERR] {e!r}")

        # Текст финала
        if winner_id is None:
            final_text = (f"⭐️ <b>Игра «Слова» завершена</b>\n"
                          f"🔤 Слово: <b>{word_original}</b>\n"
                          f"🏁 Победителя нет.")
        else:
            win_line = f"👑 Победитель: <a href='tg://user?id={winner_id}'>{winner_name or 'Игрок'}</a>"
            bet_line = f"\n💰 Выигрыш: +{bet} кут" if bet > 0 else ""
            final_text = (f"⭐️ <b>Игра «Слова» завершена</b>\n"
                          f"🔤 Слово: <b>{word_original}</b>\n"
                          f"{win_line}{bet_line}")

        # Правим «шапку»
        try:
            await bot.edit_message_text(
                chat_id=chat_id , message_id=msg_id , text=final_text , reply_markup=words_build_closed_kb() ,
                parse_mode="HTML" , disable_web_page_preview=True , )
            print(f"[WORDS][CLOSE] chat={chat_id} msg={msg_id} winner={winner_id}")
        except Exception as e:
            print(f"[WORDS][CLOSE][EDIT_ERR] {e!r}")

        # Снимаем флаг и чистим словарь
        game [ "open" ] = False
        if chat_id in words_games:
            del words_games [ chat_id ]

    def words_normalize(raw: str) -> str:
        """
        Нормализует слово для игры:
        - защищается от None
        - чистит с помощью words_clean
        - убирает пробелы
        - срезает ведущие/завершающие знаки пунктуации (.,!? и т.п.)
        - приводит к casefold() для честного сравнения без учёта регистра
        """
        if not raw:
            return ""

        # базовая очистка
        cleaned = words_clean(raw)

        # набор символов, которые мы считаем «мусорными» по краям слова
        # можно расширять при желании
        strip_chars = " \t\r\n" + ".,!?;:…--*()[]{}\"'«»„“№"

        cleaned = cleaned.strip(strip_chars)

        # ещё раз на всякий случай обрежем пробелы
        cleaned = cleaned.strip()

        if not cleaned:
            return ""

        return cleaned.casefold()

    # ───────── ОСНОВНОЙ ОБРАБОТЧИК: вызывать из твоего @dp.message(...) ПОСЛЕ остальных системных действий ─────────
    # ───────────────── ПОМОЩНИК: ссылка на сообщение игры ─────────────────
    async def _build_game_link(_chat_id: int , _msg_id: int) -> Optional [ str ]:
        try:
            chat = await bot1.get_chat(_chat_id)
        except Exception as ce:
            print(f"[WORDS][LINK][GET_CHAT_ERR] {ce!r}")
            chat = None

        # публичные чаты с username
        if chat and getattr(chat , "username" , None):
            return f"https://t.me/{chat.username}/{_msg_id}"

        # приватные супер-группы/каналы: t.me/c/<id без -100>/<msg_id>
        s = str(_chat_id)
        if s.startswith("-100"):
            return f"https://t.me/c/{s [ 4: ]}/{_msg_id}"

        # обычные группы без username - прямой ссылки нет
        return None

    # ───────── основной обработчик угадывания ─────────
    async def words_try_process_message(message: Message):
        try:
            # 0) не реагируем на ботов
            if getattr(message , "from_user" , None) and message.from_user.is_bot:
                return

            # 1) регистрируем «шапку», если это инлайн-игра
            try:
                await _words_inline_bootstrap_if_needed(message)
            except Exception as e_boot:
                print(f"[WORDS][BOOTSTRAP_CALL_ERR] {e_boot!r}")

            # 2) получаем попытку
            guess_raw = (message.text or message.caption or "").strip()
            if not guess_raw:
                return

            # 🔥 единая нормализация попытки (регистр и пунктуация по краям игнорируются)
            guess_norm = words_normalize(guess_raw)
            if not guess_norm:
                return

            chat_id = message.chat.id
            uid = message.from_user.id

            _vdbg(f"[WORDS][DEBUG] guess_raw={guess_raw!r} guess_norm={guess_norm!r} chat={chat_id} user={uid}")

            if not WORDS_STORE:
                return

            # 3) ищем подходящие открытые игры в этом чате
            candidates: List [ Tuple [ str , Dict ] ] = [ ]
            for gid , g in WORDS_STORE.items():
                if not g or g.get("closed"):
                    continue
                if g.get("chat_id") != chat_id:
                    continue

                target_norm = words_normalize(g.get("word_norm") or g.get("word_orig") or "")
                if not target_norm:
                    continue

                _vdbg(f"[WORDS][DEBUG] gid={gid} target_norm={target_norm!r}")

                if guess_norm == target_norm:
                    candidates.append((gid , g))

            if not candidates:
                return

            # берём самую раннюю
            gid , g = min(candidates , key=lambda kv: kv [ 1 ].get("created_ts" , 0.0))

            # создатель не участвует
            if uid == int(g.get("creator_id" , 0)):
                print(f"[WORDS][GUESS][CREATOR_SKIP] chat={chat_id} user={uid}")
                return

            # мягкий лок
            if not _try_soft_lock(g):
                return

            # финальная проверка от гонки - ещё раз нормализуем загаданное слово
            target_norm_final = words_normalize(g.get("word_norm") or g.get("word_orig") or "")
            _vdbg(f"[WORDS][DEBUG] FINAL_CHECK guess_norm={guess_norm!r} target_norm_final={target_norm_final!r}")
            if guess_norm != target_norm_final:
                _soft_unlock(g)
                return

            # 4) победа
            g [ "winner_id" ] = uid
            g [ "closed" ] = True
            bet_val = int(g.get("bet" , 0))
            creator_id = int(g.get("creator_id" , 0))
            header_mid = int(g.get("message_id"))

            # 5) выплаты
            try:
                if bet_val > 0:
                    winner_balance = await db.get_user_balance(uid)
                    loser_balance = await db.get_user_balance(creator_id)

                    await db.update_user_balance(uid , winner_balance + bet_val)
                    await db.touch_balance_last_active(uid , set_active_status=True)
                    await db.update_user_wins(uid , 1 , bot1 , ref_coin)
                    await db.update_user_winamount(uid , bet_val)#
                    await db.update_game_last_activity(uid)
                    from main import check_bet_and_set_item
                    await check_bet_and_set_item(uid , bet_val)

                    await db.update_user_balance(creator_id , max(0 , loser_balance - bet_val))
                    await db.touch_balance_last_active(creator_id , set_active_status=True)
                    await db.cutehistory_plus(uid , bet_val , "+ слова")
                    await db.cutehistory_minus(creator_id , bet_val , "- слова")
                g [ "payout_done" ] = True
            except Exception as pay_err:
                print(f"[WORDS][PAYOUT_ERR] {pay_err!r}")

                # 6) редактируем «шапку» - победитель, создатель, ставка, слово, подсказка
            try:
                win_name = (await db.get_firstname_by_user_id(uid)) or (
                        message.from_user.first_name or "Победитель")
                creator_name = (await db.get_firstname_by_user_id(creator_id)) or "Создатель"
                hint_text = g.get("hint") or ""
                user_message_count_f123124ormatted = "{:,.0f}".format(bet_val).replace("," , ".")
                word_orig_clean = words_clean(g.get("word_orig") or "")

                end_text = ("<tg-emoji emoji-id='5463289097336405244'>⭐️</tg-emoji> <b>Игра в слова закончена!</b> <tg-emoji emoji-id='5463289097336405244'>⭐️</tg-emoji>\n\n"
                            f"<tg-emoji emoji-id='5188344996356448758'>🏆</tg-emoji> <b>Победитель : <i><a href='tg://user?id={uid}'>{words_clean(win_name)}</a></i></b>")
                end_text += f"\n<tg-emoji emoji-id='5361684086807076580'>🍹</tg-emoji> <b>Создатель : <i><a href='tg://user?id={creator_id}'>{words_clean(creator_name)}</a></i></b>"

                if bet_val > 0:
                    end_text += f"\n\n<tg-emoji emoji-id='5375296873982604963'>💰</tg-emoji> <b>Выигрыш {user_message_count_f123124ormatted} кут</b>"

                end_text += f"\n<tg-emoji emoji-id='5454172415070315962'>🎗</tg-emoji> <b>Загаданное слово : «{word_orig_clean}»</b>"

                if hint_text:
                    end_text += f"\n\n<blockquote><b><tg-emoji emoji-id='5237799019329105246'>🧠</tg-emoji> Подсказка :\n<tg-emoji emoji-id='5472273030753295910'>🎀</tg-emoji> «{words_clean(hint_text)}»</b></blockquote>"

                await bot1.edit_message_text(
                    end_text , chat_id=chat_id , message_id=header_mid , parse_mode="HTML" ,
                    reply_markup=words_build_closed_kb() , disable_web_page_preview=True , )
            except Exception as e:
                print(f"[WORDS][HEADER_EDIT_ERR] {e!r}")

            # 7) отдельное сообщение победителю + кнопка «Перейти к игре»
            try:
                game_link = await _build_game_link(chat_id , header_mid)

                # ─── финальное сообщение ───
                if bet_val > 0:
                    win_msg = "<tg-emoji emoji-id='5458612419116933783'>🏆</tg-emoji>"
                    user_message_count_formatted = "{:,.0f}".format(bet_val).replace("," , ".")
                    btn_texts = [ ("🥇 Правильный ответ! 🥇" , "wordswin_ok") ,
                                  (f"{user_message_count_formatted} кут" , f"wordswin_amount_{bet_val}") ]
                else:
                    win_msg = "<tg-emoji emoji-id='5458612419116933783'>🏆</tg-emoji>"
                    btn_texts = [ ("🥇 Правильный ответ! 🥇" , "wordswin_ok") ]

                # создаём кнопки
                buttons = [ InlineKeyboardButton(text=text , callback_data=data) for text , data in btn_texts ]

                # если есть ссылка на игру - добавляем
                if game_link:
                    buttons.append(InlineKeyboardButton(text=" " , url=game_link, style="default" ,
                    icon_custom_emoji_id="6028171274939797252"))

                # размещаем кнопки построчно
                button_rows = [ [ btn ] for btn in buttons ]
                kb = InlineKeyboardMarkup(inline_keyboard=button_rows)

                # отправляем сообщение
                await message.reply(
                    text=win_msg , parse_mode="HTML" , reply_markup=kb , disable_web_page_preview=True , )
            except Exception as link_err:
                print(f"[WORDS][WINNER_MSG_ERR] {link_err!r}")

            _soft_unlock(g)
            print(f"[WORDS][GUESS][OK] chat={chat_id} user={uid} word='{g.get('word_norm')}'")

        except Exception as e:
            print(f"[WORDS][GUESS_ERR] {e!r}")

    await words_try_process_message(message)

