            # Разделите сообщение на части
            all_symb = message.text.lower().split()
            if len(all_symb) >= 3 and all_symb [ 0 ] in ['снять','Снять']:
                parts = message.text.split()
                # Извлекаем целевого пользователя и сумму для снятия
                target = parts [ 1 ]
                try:
                    amount_to_withdraw = float(parts [ 2 ])
                except ValueError:
                    await message.reply("⚠️ Некорректное количество для снятия. Пожалуйста, введите число.")
                    return

                # Извлечение username из URL или @username
                if target.startswith('https://t.me/'):
                    username = target.replace('https://t.me/' , '')
                elif target.startswith('@'):
                    username = target [ 1: ]  # Удаляем символ '@'
                else:
                    await message.reply(
                        "⚠️ Некорректный формат имени пользователя. Используйте 'снять [@username пользователя] [количество денег для снятия]'")
                    return

                # Получение текущего баланса пользователя
                current_balance = await db.retrieve_user_balance(username)

                # Проверка существования пользователя и достаточности баланса
                if current_balance is None:
                    await message.reply(f"⚠️ Пользователь @{username} не найден.")
                elif current_balance >= amount_to_withdraw:
                    # Обновление баланса пользователя после снятия
                    new_balance = current_balance - amount_to_withdraw
                    await db.modify_user_balance(username , new_balance)

                    # Форматирование суммы снятия и нового баланса с разделителем разрядов в виде точки без десятичных знаков
                    formatted_amount_to_withdraw = f"{amount_to_withdraw:,.0f}".replace("," , ".")
                    formatted_new_balance = f"{new_balance:,.0f}".replace("," , ".")

                    # Сообщение об успешной операции
                    await message.reply(
                        f"✅ {formatted_amount_to_withdraw} успешно снято с баланса @{username}.\n"
                        f"🍏 Новый баланс пользователя: {formatted_new_balance}.")
                else:
                    await message.reply(
                        f"⚠️ У пользователя @{username} недостаточно средств для снятия {amount_to_withdraw}.")


