async def preload_all_games():
    folder = "pkl"
    print("[🔁] Запуск предзагрузки игровых данных...")

    if not os.path.exists(folder):
        print(f"[📂] Папка '{folder}' не найдена. Создаю...")
        os.makedirs(folder)

    files = [f for f in os.listdir(folder) if f.endswith(".pkl")]
    print(f"[📄] Найдено {len(files)} .pkl файлов: {[f for f in files]}")

    if not files:
        print("[ℹ️] Нет файлов для загрузки.")
        return

    tasks = [load_game_data(filename[:-4]) for filename in files]
    await asyncio.gather(*tasks)
    print("\n[✅] Все игровые данные успешно предзагружены.\n")



async def get_star_prices(client, channel_url: str) -> dict:
    from telethon import functions, types

    try:
        # Получаем объект канала
        channel = await client.get_entity(channel_url)
        print(f"📡 Канал найден: {channel.title} (id={channel.id})")

        # Создаем InputPeerChannel
        peer = types.InputPeerChannel(channel_id=channel.id, access_hash=channel.access_hash)

        # Получаем доходность
        result = await client(functions.payments.GetStarsRevenueStatsRequest(peer=peer))
        usd_rate = result.usd_rate
        print(f"💰 Доход за 1 звезду: ${usd_rate:.4f}")

        # Расчёт цены, которую платит пользователь
        user_price = 0.015
        print(f"👛 Пользователь платит: ${user_price:.4f}")

        return {
            "SELL_PRICE_PER_STAR": round(usd_rate, 4),
            "BUY_PRICE_PER_STAR": round(user_price, 4),
        }

    except Exception as e:
        print(f"❌ Ошибка при получении курса: {e}")
        return None
async def calculate_stars_to_pay(kuts: int, sell_price: float, buy_price: float, min_profit: float = 0.01) -> dict:
    step = 1
    min_stars = kuts
    max_stars = kuts * 2

    for stars in range(min_stars, max_stars + 1, step):
        cost = stars * buy_price
        income = stars * sell_price
        profit = income - cost

        if profit >= min_profit:
            return {
                "kuts": kuts,
                "stars_to_pay": stars,
                "commission_percent": round((stars / kuts - 1) * 100, 2),
                "profit_uah": round(profit, 2),
                "user_pays_uah": round(cost, 2),
                "you_receive_uah": round(income, 2)
            }

    # fallback если не удалось найти подходящий вариант
    stars = max_stars
    cost = stars * buy_price
    income = stars * sell_price
    profit = income - cost
    return {
        "kuts": kuts,
        "stars_to_pay": stars,
        "commission_percent": round((stars / kuts - 1) * 100, 2),
        "profit_uah": round(profit, 2),
        "user_pays_uah": round(cost, 2),
        "you_receive_uah": round(income, 2)
    }

