# ✅ HEARTBEAT: максимально лёгкая проверка "жив ли бот"
HEARTBEAT_FILE = "/tmp/cutebot.heartbeat"

def start_heartbeat_task(*, interval: int = 15, debug: bool = True):
    """
    Бот сам пишет heartbeat раз в interval секунд.
    Если бот упал/завис - файл перестанет обновляться, watchdog это увидит.
    """
    async def _heartbeat_loop():
        print(f"[HEARTBEAT][START] file={HEARTBEAT_FILE} interval={interval}s")
        while True:
            try:
                ts = int(time.time())
                with open(HEARTBEAT_FILE, "w") as f:
                    f.write(str(ts))

                if debug:
                    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    print(f"[HEARTBEAT][OK] {now} ts={ts}")
            except Exception as e:
                if debug:
                    print(f"[HEARTBEAT][ERR] {e}")

            await asyncio.sleep(interval)

    asyncio.create_task(_heartbeat_loop())












class BalanceEngineWatcher:
    def __init__(self, db):
        self.db = db
        self._next_check_at: Dict[int, float] = {}
        self._locks: Dict[int, asyncio.Lock] = {}
        self._last_seen: Dict[int, float] = {}
        self.HARD_MIN_GAP_SEC = 45.0
        # Чтобы карты не росли бесконечно за сутки аптайма
        self._TRIM_IDLE_SEC = 6 * 3600
        self._TRIM_MAX_ENTRIES = 5000

    def _lock(self, uid: int) -> asyncio.Lock:
        lk = self._locks.get(uid)
        if lk is None:
            lk = asyncio.Lock()
            self._locks[uid] = lk
        return lk

    def trim(self) -> Dict[str, int]:
        """Удаляет устаревшие uid-записи (самолечение кнопок/пула БД)."""
        now = time.monotonic()
        idle_before = now - float(self._TRIM_IDLE_SEC)
        removed = 0

        for uid, ts in list(self._last_seen.items()):
            lk = self._locks.get(uid)
            if lk is not None and lk.locked():
                continue
            if ts < idle_before:
                self._last_seen.pop(uid, None)
                self._next_check_at.pop(uid, None)
                self._locks.pop(uid, None)
                removed += 1

        # Жёсткий потолок на случай огромного трафика
        if len(self._last_seen) > self._TRIM_MAX_ENTRIES:
            oldest = sorted(self._last_seen.items(), key=lambda x: x[1])
            overflow = len(self._last_seen) - self._TRIM_MAX_ENTRIES
            for uid, _ in oldest[:overflow]:
                lk = self._locks.get(uid)
                if lk is not None and lk.locked():
                    continue
                self._last_seen.pop(uid, None)
                self._next_check_at.pop(uid, None)
                self._locks.pop(uid, None)
                removed += 1

        return {
            "removed": removed,
            "seen": len(self._last_seen),
            "locks": len(self._locks),
            "next": len(self._next_check_at),
        }

    async def tick(self, user_id: int) -> None:
        uid = int(user_id)
        now = time.monotonic()

        prev = self._last_seen.get(uid)
        if prev is not None and (now - prev) < self.HARD_MIN_GAP_SEC:
            return
        self._last_seen[uid] = now

        nxt = self._next_check_at.get(uid)
        if nxt is not None and now < nxt:
            return

        lk = self._lock(uid)
        if lk.locked():
            return

        async with lk:
            now2 = time.monotonic()
            nxt2 = self._next_check_at.get(uid)
            if nxt2 is not None and now2 < nxt2:
                return

            # ensure_balance_status_engine → 8 значений (последнее burned_now)
            (
                st,
                last_active,
                elapsed,
                remaining,
                played,
                needed,
                next_after,
                burned_now,
            ) = await self.db.ensure_balance_status_engine(uid)
            _ = (st, last_active, elapsed, remaining, played, needed, burned_now)
            self._next_check_at[uid] = time.monotonic() + float(next_after)


from aiogram import BaseMiddleware
class BalanceEngineMiddleware(BaseMiddleware):
    def __init__(self, watcher: BalanceEngineWatcher):
        super().__init__()
        self.watcher = watcher

    async def _run_tick(self, uid: int) -> None:
        try:
            await self.watcher.tick(uid)
        except Exception as e:
            print(f"❌ [BALANCE][MW] tick err: {e!r}")

    async def __call__(self, handler, event, data):
        try:
            # НЕ тикаем на callback_query: кнопки должны оставаться лёгкими.
            # Движок баланса достаточно гонять по приватным сообщениям.
            uid = None
            if isinstance(event, Message) and event.from_user:
                if event.chat and getattr(event.chat, "type", None) == ChatType.PRIVATE:
                    uid = event.from_user.id

            if uid:
                asyncio.create_task(self._run_tick(int(uid)))
        except Exception as e:
            print(f"❌ [BALANCE][MW] err: {e!r}")

        return await handler(event, data)

